/**
 * The engine's own stylesheet. Web-only, and deliberately TINY.
 *
 * Everything that can be said as a theme param is said in `theme.ts`, not here. This file only
 * carries what the Theming API has no param for: per-column alignment classes, the no-rows
 * overlay, the cell's line box, the child-row tint and rail, the column-group strip, the density
 * padding knob, and the DS-built column filters. Every colour and number in here is a
 * `--nds-grid-*` token from `tokens/grid.ts` — if a rule starts naming a ramp step or a bare
 * pixel, it belongs in the token table instead. Two places to change a row height is how the
 * five-engine mess started.
 *
 * Not registered in `design-system/styles/`, and not imported by `layout.tsx`: it is imported by
 * the engine component, so it only ships on routes that actually mount a grid. It has no
 * counterpart in apps/factory (factory renders no AG grid) — the grid TOKENS are mirrored there,
 * this sheet is not.
 */

/* `.nds-wsgrid th.num, .nds-wsgrid td.num { text-align: right }` — plus the tabular figures the
   DS learned to set the hard way: a money column that loses proportional-digit alignment is the
   one defect a grid cannot afford. */
.nds-ag-num {
  justify-content: flex-end;
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.nds-ag-head-num .ag-header-cell-label {
  justify-content: flex-end;
}

.nds-ag-ed {
  justify-content: flex-start;
  text-align: left;
}

.nds-ag-ctr {
  justify-content: center;
  text-align: center;
}

/* The identity column: AG already centres its cell content, so only the gap and the ellipsis
   are restated. */
.nds-ag-cell-first {
  gap: 7px;
}

.nds-ag-cell-first > * {
  min-width: 0;
}

/* The empty state. SGX parity: the sentence must WRAP. The hand-rolled grid shipped this bug to
   prod — a long empty state painted straight out of its cell and under the frozen column —
   because the empty cell inherited `white-space: nowrap`. AG Grid's overlay does not inherit that,
   but the wrap is stated anyway so the fix cannot be lost a second time. */
.nds-ag-empty {
  display: block;
  max-width: 320px;
  padding: 28px;
  color: var(--nds-grid-empty-fg);
  text-align: center;
  white-space: normal;
}

/* AG.3 — the bulk-action bay, shown only while rows are selected. Geometry only, deliberately:
   every control inside is the caller's and is already a DS primitive. */
.nds-ag-selbar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  padding: 8px 0;
}

/* A row that opens something must look like it does. Only the cursor: the hover tint is a theme
   param and lives in theme.ts. */
.nds-ag-clickable {
  cursor: pointer;
}

/* AG.3 — the row rule.
 *
 * `theme.ts` asks for this with the `rowBorder` param and AG Grid 36.1.0 emits NOTHING for it:
 * measured, `--ag-row-border-color` is empty in both the object form and the `true` form, and
 * rows render `1px solid rgba(0, 0, 0, 0)` — a rule that is present, sized, and invisible.
 *
 * AG's own base CSS reads a SHORTHAND: `border-bottom: var(--ag-row-border)`, applied to the cell
 * CONTAINERS (`.ag-grid-scrolling-cells`, `.ag-grid-pinned-*-cells`), not to `.ag-cell`. Setting
 * that one variable is therefore not a hand-rolled border — it is supplying the value AG is
 * already asking for, and it stays a token, so dark mode still costs nothing. */
.nds-ag-wrap {
  --ag-row-border: 1px solid var(--nds-grid-row-rule);
}

/* PN.1 — the cell is a flex row with a NORMAL line box, like the DS `td` it replaces.
 *
 * AG sets `line-height: calc(row-height − 3px)` on every cell so a single line of plain text
 * centres itself. Every renderer this product puts in a cell inherits that: a two-line product
 * cell became 82px of content inside a 43px row (measured — thumbnail pushed 22px down and
 * clipped 19px off the bottom), and pills, tag chips and channel labels each sat on a 40px line
 * box, so nothing shared a vertical centre. The Theming API has no param for this, which is the
 * one condition under which a rule belongs in this file.
 *
 * Centring is done the way the DS grid does it — the cell is the flex container — so a renderer
 * needs no knowledge of the row height to sit in the middle of it. */
.nds-ag-wrap .ag-cell,
.nds-ag-wrap .ag-cell-value {
  line-height: normal;
}

.nds-ag-wrap .ag-cell {
  display: flex;
  align-items: center;
}

/* The group cell (the tree column) wraps its chevron and value in `.ag-cell-wrapper`; give the
   value the remaining width so the product cell's ellipsis has a box to work in. */
.nds-ag-wrap .ag-cell .ag-cell-wrapper {
  align-items: center;
  width: 100%;
  min-width: 0;
}

.nds-ag-wrap .ag-cell .ag-group-value {
  flex: 1 1 auto;
  min-width: 0;
}

/* PN.1 — DS tooltips inside cells.
 *
 * The DS `Tooltip` is CSS-only: an absolutely positioned bubble that pops above its trigger on
 * hover, INSIDE the trigger's box. AG clips every cell (`overflow: hidden`) so the bubble was cut
 * at the cell's top edge — measured on the Channels column, and worse at Cozy/Compact where the
 * row is shorter than the bubble. Unclipping every cell would let long plain values spill into
 * their neighbours, so only cells that actually contain a DS tooltip are opened up; everything
 * else keeps AG's ellipsis. `:has()` is what makes that precise.
 *
 * What this cannot fix: a bubble on the FIRST row pops into the scroll viewport's clip, and no
 * cell rule reaches that. That is the case the portal-rendered `InfoTip` exists for (W6). */
.nds-ag-wrap .ag-cell:has(.nds-tooltip),
.nds-ag-wrap .ag-cell:has(.nds-tooltip) .ag-cell-value,
.nds-ag-wrap .ag-cell:has(.nds-tooltip) .ag-cell-wrapper {
  overflow: visible;
}

/* AG rows are absolutely positioned siblings whose DOM order is not their visual order, so a
   bubble rising out of one row can paint BEHIND the row above it. The hovered row wins. */
.nds-ag-wrap .ag-row:hover,
.nds-ag-wrap .ag-row.ag-row-focus {
  z-index: 1;
}

/* PN.1 — `flatTree` (see NexusGrid): the DS says "child" with a tint and a 3px rail, never with an
   indent. A page whose children must line up under their parent owns the tree column's cell
   (`autoGroupColumnDef.cellRenderer`) — AG then renders no chevron slot and no level step, and
   nothing here has to undo them. A full-width row below the top level (the family footer) takes
   the same tint. */
.nds-ag-flat-tree .ag-row:not(.ag-row-level-0) {
  background-color: var(--nds-grid-child-bg);
}

/* On the ROW, not the first cell: a cell is 1px shorter than its row, which left a gap in the
   rail at every row boundary. The DS drew it on the `td`, whose box includes the row rule, so the
   rail ran continuously down the family — the row is AG's equivalent box.
 *
 * ...and it has to PAINT above the cells, which is why this is a pseudo-element and no longer the
 * `inset` box-shadow it was. AG draws the row rule as `border-bottom: var(--ag-row-border)` on
 * `.ag-grid-scrolling-cells` — a `position: relative; z-index: 0` child that spans the row's full
 * height from `left: 0`. A positioned descendant paints ABOVE its parent's box-shadow, so that
 * 1px of the LIGHTER `--nds-grid-row-rule` overwrote the rail's bottom pixel at every boundary
 * and broke the stroke into per-row segments. Measured on prod: consecutive child rows are exactly
 * contiguous (…867.8 | 867.8…) with no border on the row itself — the row BOX was never the
 * problem, the paint ORDER was. The row is `position: absolute`, so `::after` anchors to it. */
.nds-ag-flat-tree .ag-row:not(.ag-row-level-0):not(.ag-full-width-row)::after {
  content: '';
  position: absolute;
  inset-block: 0;
  left: 0;
  width: 3px;
  background-color: var(--nds-grid-child-rail);
  z-index: 1;
  pointer-events: none;
}

.nds-ag-flat-tree .ag-row:not(.ag-row-level-0).ag-row-hover {
  background-color: var(--nds-grid-child-hover-bg);
}

/* PN.1 — a grid inside a `.nds-gridcard` does not draw its own frame.
 *
 * The theme's `wrapperBorder` / `wrapperBorderRadius` frame a STANDALONE grid. /products/next
 * puts the grid inside the DS grid card, which already draws the same 1px border and radius —
 * measured: two identical borders one pixel apart, and a rounded top corner on the header inside
 * a card whose own corner is where the rounding belongs. AG sets these variables on its root
 * wrapper, so the override has to land on that element, not on an ancestor. */
.nds-gridcard .nds-ag-wrap .ag-root-wrapper {
  --ag-wrapper-border: none;
  --ag-wrapper-border-radius: 0;
  border: none;
  border-radius: 0;
}

/* IE.4 — a column-group row is a slim STRIP above the header, not a second header.
 *
 * AG draws group headers in the header's own style, so a grid with groups showed two header rows
 * of full height (93px at the Spacious tier) — against the products page's single 46px header
 * over 85px rows. The Owner: the group labels belong "in the strip above the actual header".
 * Every NexusGrid with column groups gets this band: the height is the grid's `groupHeaderHeight`
 * (`gridGeometry.stripH`), the ground is the sunken surface, labels are the DS eyebrow, and the
 * partitions run the strip's FULL height so it reads as parts of one band rather than as header
 * cells. */
.nds-ag-nexus .ag-header-row-group {
  background: var(--nds-grid-strip-bg);
  box-shadow: inset 0 -1px 0 var(--nds-grid-strip-rule);
}
.nds-ag-nexus .ag-header-group-cell {
  --ag-header-column-border-height: 100%;
  font-size: var(--nds-grid-strip-size);
  font-weight: var(--nds-grid-strip-weight);
  letter-spacing: var(--nds-grid-strip-tracking);
  text-transform: uppercase;
  color: var(--nds-grid-strip-fg);
}
.nds-ag-nexus .ag-header-group-cell .ag-header-group-cell-label {
  justify-content: center;
}

/* PN.1 — compact density tightens the cell's horizontal padding too. The theme sets cell padding
   once, so the density-specific value lands here, keyed off the wrapper's `data-density`. AG sets
   this variable on its root wrapper, hence the selector. (AG renders the padding one pixel under
   the variable — measured 13 at 14, 9 at 10 — so the token states what the DS grid measured +1.) */
.nds-ag-wrap[data-density='compact'] .ag-root-wrapper {
  --ag-cell-horizontal-padding: var(--nds-grid-cell-pad-x-compact);
}

/* ── Column filters: DS-built components inside AG's column menu ───────────────────────────
   The list reuses the MultiSelect option rows (`.nds-ms-opt`) and its search box, so a filter in
   the header menu reads exactly like the same filter in the accordion. These are DS controls, so
   they speak the DS control tokens, not the grid's. */
.nds-ag-filter {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 240px;
  max-width: 320px;
  padding: 8px;
  font-size: 13px;
  color: var(--nds-text);
}
.nds-ag-filter-list {
  display: flex;
  flex-direction: column;
  max-height: 260px;
  overflow-y: auto;
}
.nds-ag-filter-range {
  display: flex;
  gap: 8px;
  align-items: end;
}
.nds-ag-filter-range label {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 4px;
  font-size: 12px;
  color: var(--nds-text-2);
}
.nds-ag-filter-foot {
  display: flex;
  justify-content: flex-end;
  padding-top: 4px;
  border-top: 1px solid var(--nds-border);
}

/* PES.2 — the FLOATING filter row (`filters/gridFloatingFilters.tsx`). It lives INSIDE the header
   block, so it must not add its own frame: AG already draws the row's bottom rule, and a second
   border here reads as a doubled header. The controls are shrunk to the row, not the row grown to
   the controls — the sheet's whole argument is rows on screen. */
.nds-ag-wrap .ag-floating-filter { padding: 0 var(--nds-grid-cell-pad-x-compact); }
.nds-ag-floating { display: flex; align-items: center; gap: 4px; width: 100%; }
.nds-ag-floating-range { gap: 4px; }
/* The DS Input at floating-filter size. Height is the row minus its padding, so a density change
   moves it with everything else instead of leaving a control floating in a taller box. */
.nds-ag-floating .nds-ag-floating-input,
.nds-ag-floating .nds-ag-floating-input input {
  height: 22px;
  min-height: 22px;
  font-size: 11.5px;
  width: 100%;
  min-width: 0;
}
.nds-ag-floating-range .nds-ag-floating-input { flex: 1 1 0; }
/* The set filter's read-out: a control that opens the real list. Styled as a quiet field so it
   reads as the same kind of thing as the inputs beside it, and marked when a filter is on —
   the count is the mark, not the colour. */
.nds-ag-floating-set {
  width: 100%; height: 22px; padding: 0 6px; text-align: left; cursor: pointer;
  font: inherit; font-size: 11.5px; color: var(--nds-grid-muted-fg);
  background: var(--nds-surface); border: 1px solid var(--nds-border);
  border-radius: var(--nds-grid-radius);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.nds-ag-floating-set:hover { border-color: var(--nds-border-strong); }
/* 🔴 `box-shadow`, NOT `outline`. `--nds-grid-focus-ring` aliases `--nds-focus-ring`, which is a
   box-SHADOW value (`0 0 0 2px rgb(… / .12)`) — so `outline: 2px solid var(…)` expanded to
   `outline: 2px solid 0 0 0 2px rgb(…)`, invalid, and the whole declaration was dropped. Measured
   by DS.1 with a positive control: `outlineStyle: none` AND `boxShadow: none` here, while a
   `2px solid red` control on the same probe painted correctly — so the nothing was the page, not a
   blind instrument.

   **This was an accessibility defect, not a cosmetic one**: a keyboard user got no focus indicator
   on this control at all, silently, with no error anywhere.

   The tell worth keeping: the SAME token is used in two properties in this file — dead here, correct
   at `.nds-cell-expand` below — and the working one sitting 60 lines away is exactly what made the
   dead one look verified. A token whose name does not say which property it belongs to will be used
   in the wrong one eventually. */
.nds-ag-floating-set:focus-visible { outline: 2px solid var(--nds-primary); outline-offset: -1px; }
/* `.nds-cell-expand:focus-visible` below carried the SAME weakness in its milder form — it painted,
   but only a 12%-alpha shadow, measured at 1.17:1. FIXED below (DS.1 ruling #296), after DS.1
   enumerated the token and found 9 of 22 rules using that shadow as their ONLY focus signal. Kept
   here as the record of why it was flagged and not silently assumed correct: it was scoped OUT of
   the defect above deliberately, so that it could not be read as verified by proximity — which is
   the exact mistake that hid the dead rule above. */
.nds-ag-floating-set-on { color: var(--nds-text); border-color: var(--nds-grid-accent); font-weight: var(--nds-font-weight-semibold); }

/* ══ GDS cell library (`../renderers`, `../editors`) ══════════════════════════════════════════
   Geometry lifted verbatim from /products/next's page stylesheet (measured there); colours are the
   grid tokens. A page composes these cells; it does not restyle them. */

/* the dash — muted; the title (a measured zero) is on the element, the colour is here */
.nds-cell-empty { color: var(--nds-grid-muted-fg); }
.nds-cell-muted { color: var(--nds-grid-muted-fg); }
.nds-cell-strong { font-weight: var(--nds-font-weight-semibold); }
.nds-cell-date { font-size: var(--nds-font-size-sm); white-space: nowrap; }

/* identity: leading (expander) · thumb · meta (title row + sub-line) */
.nds-cell-identity { display: flex; align-items: center; gap: 11px; min-width: 0; }
.nds-cell-identity-meta { min-width: 0; }
.nds-cell-title-row { display: flex; align-items: center; gap: 6px; min-width: 0; max-width: 330px; }
.nds-cell-title-link {
  font-weight: var(--nds-font-weight-semibold); font-size: var(--nds-font-size-base); color: var(--nds-primary);
  text-decoration: none; cursor: pointer; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; min-width: 0;
}
.nds-cell-title-link:hover { text-decoration: underline; }
/* the hover-revealed "Open in new tab" pill (the ads manager's `.h10-open`, tokenised) */
.nds-cell-open {
  display: none; align-items: center; gap: 4px; font-size: var(--nds-font-size-xs); font-weight: var(--nds-font-weight-semibold);
  color: var(--nds-text-inverse); background: var(--nds-primary); border-radius: var(--nds-radius-sm); padding: 3px 8px;
  text-decoration: none; flex-shrink: 0; white-space: nowrap; line-height: 1.2;
}
.nds-cell-identity:hover .nds-cell-open, .nds-cell-title-row:hover .nds-cell-open { display: inline-flex; }
.nds-cell-open:hover { background: var(--nds-primary-hover); }
.nds-cell-sub { font-size: var(--nds-font-size-xs); color: var(--nds-grid-muted-fg); margin-top: 2px; display: flex; gap: 8px; align-items: center; flex-wrap: nowrap; }
/* `--nds-font-mono` exists as of 2026-09-01 and resolves to JetBrains Mono, which the app already
   loads; this line inlined the OS stack and so every SKU in the sheet rendered in the wrong face.
   The fallback is kept deliberately — it keeps the cell readable if the token is ever removed, and
   it is the reason no guard caught this (`check-css-token-definitions.mjs` only flags a `var()`
   WITHOUT one, so the careful call sites bought the silence). DS.1's DS1-1. */
.nds-cell-sku { font-family: var(--nds-font-mono, ui-monospace, SFMono-Regular, Menlo, monospace); font-size: var(--nds-font-size-xs); color: var(--nds-grid-muted-fg); }

/* ══ the identity band (`renderers/IdentityBand.tsx`) ═════════════════════════════════════════
   ONE row shape for master and every channel scope (#710). Content-derived width: the band is
   `width: max-content` inside its cell so the column can be sized FROM it, which is the thing three
   separate pinned columns could not do — each was sized on its own and the chip ended up overlapping
   the thumbnail (#709a).
   🔴 `min-width: 0` on the text block is load-bearing: without it the flex item's automatic minimum
   is its content width, the SKU refuses to shrink, and the trailing pill is pushed out of the cell —
   the same floor that held the `?` button 2px wide (#684) and the media tile's picture at 80px
   (#688). The SKU truncates; the state pill never moves. */
.nds-identity-band {
  display: flex; align-items: center; gap: 8px; width: 100%; min-width: 0;
}
/* The picture and the mark about it travel together, so the mark cannot be separated from the
   photograph it describes by a later layout change. */
.nds-identity-band-pic { display: inline-flex; align-items: center; gap: 4px; flex: none; }
.nds-identity-band-text {
  display: flex; flex-direction: column; justify-content: center; gap: 1px; min-width: 0; flex: 1 1 auto;
}
.nds-identity-band-sku {
  font-family: var(--nds-font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-size: var(--nds-font-size-xs); color: var(--nds-text-strong); font-weight: 600;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap; min-width: 0;
}
/* The second line is context, not the key: quieter, and it is the one that gives way first. */
.nds-identity-band-sub {
  font-size: var(--nds-font-size-xs); color: var(--nds-text-2); line-height: 1.25;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap; min-width: 0;
}
/* Pinned right and never shrinking — a readiness reading that truncates is worse than absent. */
.nds-identity-band-trail { display: inline-flex; align-items: center; gap: 6px; flex: none; margin-left: auto; }

.nds-readypill { display: inline-flex; align-items: center; gap: 6px; flex: none; }
.nds-readypill-track {
  width: 34px; height: 4px; flex: none; border-radius: var(--nds-radius-pill);
  background: var(--nds-surface-sunken); overflow: hidden;
}
.nds-readypill-fill { display: block; height: 100%; background: var(--nds-grid-muted-fg); }
/* 🔴 A FIXED slot, not a shrink-to-fit one (#739). The band's width is derived from its fixed
   slots, so a pill that is narrower at "9%" than at "100%" gives the same family a different derived
   width on two scopes — which is the one thing #710 exists to prevent. `tabular-nums` makes every
   digit the same width; `min-width` makes every VALUE the same width. Sized for the widest string
   the pill can hold ("100%") and right-aligned so the digits line up down a column. */
.nds-readypill-num {
  font-size: var(--nds-font-size-xs); font-variant-numeric: tabular-nums; color: var(--nds-text-2);
  flex: none; min-width: 30px; text-align: right;
}
/* 🔴 Tone is carried by the NUMBER as well as the bar. A bar-only signal fails anyone who cannot
   separate the two fills, and this is a readiness reading an operator acts on.
   🔴 The tone names are the READINESS vocabulary, not `full`/`low` — they come from
   `readinessMeta(state).tone`, never from the percentage (#43/#727). A pill at 84% in state
   `errors` is DANGER; a pill at 40% in state `ready` is not a warning. */
.nds-readypill-success .nds-readypill-fill { background: var(--nds-success); }
.nds-readypill-success .nds-readypill-num { color: var(--nds-text-strong); font-weight: 600; }
.nds-readypill-warning .nds-readypill-fill { background: var(--nds-warning); }
.nds-readypill-warning .nds-readypill-num { color: var(--nds-warning-text); }
.nds-readypill-danger .nds-readypill-fill { background: var(--nds-danger); }
.nds-readypill-danger .nds-readypill-num { color: var(--nds-danger-text); }
.nds-readypill-info .nds-readypill-fill { background: var(--nds-info-strong); }

/* the 20×20 chips beside a name — targeting A/M (filled), programme SP/SB/SD (outlined), an accent */
.nds-cell-chip {
  display: inline-flex; align-items: center; justify-content: center; flex: none; box-sizing: border-box;
  width: 20px; height: 20px; padding: 0; border-radius: var(--nds-radius-sm); line-height: 1; font-weight: 800;
  font-size: 11px; color: var(--nds-text-inverse);
}
.nds-cell-chip-auto { background: var(--nds-targeting-auto); }
.nds-cell-chip-manual { background: var(--nds-targeting-manual); }
.nds-cell-chip-accent { background: var(--nds-rail-text); }
.nds-cell-chip-program { font-size: 9px; letter-spacing: -0.3px; color: var(--nds-grid-muted-fg); background: var(--nds-grid-bg); border: 1px solid var(--nds-grid-frame); }
.nds-cell-chip-neutral { color: var(--nds-text-2); background: var(--nds-surface-sunken); }
/* Both containers on purpose: `.nds-cell-identity` is the older identity cell (products/next, the
   channel's own rows) and `.nds-identity-band` is the band (#710). The rules below were written for
   the first and silently stopped applying when master moved to the second — C lost its pill and the
   chip overlapped the thumbnail again, inside one build. A scoped rule is only as good as the list
   of scopes it names.
   a chip's tooltip wrapper must not add a line box of its own — nor SHRINK below the chip it wraps.
   🔴 `flex: none` is the half that was missing (#709a): at the default `flex: 0 1 auto` this wrapper
   was squeezed to **4px** while the chip inside went on painting at 20px, so the P chip overlapped
   the thumbnail by 5px and the Owner saw a picture with no parent/child pill. Nothing declared a
   width for the chip to lose — it lost one to flex-shrink, the same automatic-sizing family as the
   `?` button's `min-width: auto` floor (#684). Read the USED size, never the declared one. */
.nds-cell-identity .h10-tipwrap,
.nds-identity-band .h10-tipwrap { display: inline-flex; align-items: center; line-height: 0; flex: none; }

/* 🔴 THE IDENTITY ROLE PILL (#709a, Owner 15:53: "the chip is still dropped slightly, and we need to
   fix it and make it a bit wider"). Scoped to the identity cell ON PURPOSE: `.nds-cell-chip` is
   shared with the Ad Manager's targeting (A/M) and programme (SP/SB/SD) chips, and widening the base
   would resize those surfaces without anyone asking. Here it becomes a real pill — content width
   with horizontal padding, a 20px floor so a single character is still a pill and not a letter —
   and `align-self: center` puts it on the thumbnail's centre line rather than the flex line's
   baseline, which is what "dropped slightly" was.
   `neutral` (the C of a child row) also gains a border: on `--nds-surface-sunken` against a white
   row its fill is nearly invisible, which is why C read as a bare grey glyph while P read as a chip.
   One component, one size, two tones — the Owner's "P and C the same pill". */
.nds-cell-identity .nds-cell-chip,
.nds-identity-band .nds-cell-chip {
  width: auto; min-width: 24px; padding: 0 6px; align-self: center; border-radius: var(--nds-radius-sm);
  /* 🔴 A TRANSPARENT border on every tone, not just the bordered one. Measured: with the border on
     `neutral` alone, C came out 22.2px and P 20px — one pill, two sizes, which is the inconsistency
     the Owner would see before anyone measured it. `width: auto` puts a border OUTSIDE the padding
     box whatever `box-sizing` says, so the only way both tones share a size is for both to carry the
     same border and for `min-width` to sit above their content width. */
  border: 1px solid transparent;
}
.nds-cell-identity .nds-cell-chip-neutral,
.nds-identity-band .nds-cell-chip-neutral { border-color: var(--nds-grid-frame); }

/* the 20px expander and the slot that keeps a leaf aligned under its siblings */
.nds-cell-expand {
  width: 20px; height: 20px; flex: none; display: inline-flex; align-items: center; justify-content: center;
  border-radius: var(--nds-radius-pill); border: none; background: none; color: var(--nds-text-3); cursor: pointer; padding: 0;
  transition: background 0.1s ease, color 0.1s ease;
}
.nds-cell-expand:hover { background: var(--nds-surface-hover); color: var(--nds-grid-cell-fg); }
/* 1.17:1 as the only focus signal is not a focus indicator — see the note at `.nds-ag-floating-set`
   above for how this rule came to be flagged, and why `outline` is written literally here rather
   than through `--nds-grid-focus-ring` (that token is a box-SHADOW value).

   `outline-offset` is NEGATIVE, like its sibling: AG clips every cell with `overflow: hidden` (the
   same fact that cut the hover bubble at `:131`), so an outward ring on a 20px control sitting at a
   cell edge would be the second invisible focus indicator on this control in a row. */
.nds-cell-expand:focus-visible { outline: 2px solid var(--nds-primary); outline-offset: -1px; }
.nds-cell-expand-slot { width: 20px; flex: none; }

/* actions: Edit + ⋯, right-aligned */
.nds-cell-actions { display: flex; gap: 6px; justify-content: flex-end; align-items: center; }

/* tags: one named chip, or up to N glyph chips and a +N */
.nds-cell-tags { display: flex; align-items: center; gap: 5px; flex-wrap: nowrap; overflow: hidden; }
.nds-cell-tagchip {
  display: inline-flex; align-items: center; gap: 5px; padding: 1px 8px; border-radius: var(--nds-radius-round);
  background: var(--nds-surface-sunken); color: var(--nds-text-2); font-size: var(--nds-font-size-xs); white-space: nowrap;
  max-width: 110px; overflow: hidden; text-overflow: ellipsis;
}
.nds-cell-tagchip-name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; min-width: 0; }
.nds-cell-tagglyph { display: inline-flex; align-items: center; justify-content: center; flex: none; width: 18px; height: 18px; border-radius: var(--nds-radius-sm); background: var(--nds-surface-sunken); }
.nds-cell-tagmore { font-size: var(--nds-font-size-xs); color: var(--nds-grid-muted-fg); flex: none; }

/* group row: label + count */
.nds-cell-group { display: inline-flex; align-items: baseline; gap: 8px; min-width: 0; }
.nds-cell-group strong { font-weight: var(--nds-font-weight-semibold); color: var(--nds-grid-header-fg); }
.nds-cell-group-count { font-size: 12px; color: var(--nds-text-2); white-space: nowrap; }

/* stock levels */
.nds-cell-stock-out { color: var(--nds-danger); font-weight: var(--nds-font-weight-semibold); }
.nds-cell-stock-low { color: var(--nds-warning); font-weight: var(--nds-font-weight-semibold); }
.nds-cell-stock-ok { color: var(--nds-success); font-weight: var(--nds-font-weight-semibold); }

/* locked — the cell (a whole read-only column) and the value (a lock glyph beside it) */
.nds-ag-wrap .ag-cell.nds-cell-is-locked { color: var(--nds-grid-locked-fg); }
.nds-cell-locked { color: var(--nds-grid-locked-fg); display: inline-flex; align-items: center; gap: 6px; }
.nds-cell-lock-glyph { font-size: 10px; }

/* the delta chip on a pending edit */
.nds-cell-delta {
  position: absolute; right: 6px; top: 3px; font-family: var(--nds-font-mono, ui-monospace, monospace); font-size: 10px; font-weight: 700;
  line-height: 14px; padding: 0 5px; border-radius: var(--nds-radius-full); background: var(--nds-grid-delta-bg); color: var(--nds-grid-delta-fg);
}
.nds-cell-delta-neg { background: var(--nds-grid-delta-neg-bg); }

/* editing states — batch (pending / refused) and per-cell round trip (saving / saved / refused) */
.nds-ag-wrap .ag-cell.nds-cell-is-editable { cursor: text; }
.nds-ag-wrap .ag-cell.nds-cell-is-editable:hover { box-shadow: inset 0 0 0 1px var(--nds-grid-editable-ring); }

/* ── Closed-list cells (D13) ───────────────────────────────────────────────────────────────
   🔴 DISCLOSED EDIT under PES.2's claim (hub #442). The Owner: the status cell "should really be a
   dropdown". It already IS a select editor — what was missing is that nothing said so. Measured
   2026-09-02 on GALE-JACKET at innerWidth 1728: the closed-list `status` cell and the free-text
   `name` cell were identical in EVERY signal — same `nds-cell-is-editable` class, same single
   child span, no glyph, and the same `cursor: text`.

   The cursor is the half worth naming separately, because it is not missing information but WRONG
   information: `cursor: text` on a closed list invites the operator to type where typing is not
   possible. A cell that cannot accept text should not claim it can, which is why this rule comes
   before the glyph rather than after it.

   The chevron is a flex item, not an absolutely-positioned one: the cell is already
   `display: flex; align-items: center`, so `margin-left: auto` parks the glyph on the right edge
   and the value KEEPS ITS LEFT EDGE — the Owner's "does not move the value". It also means the
   icon is a flex item rather than a block in a line box, which is the trap that put the Pill's
   icon on its own line an hour ago. `pointer-events: none` so it can never swallow the click that
   opens the editor, and it is a chevron in a CELL, where AG draws no sort indicator; sort lives in
   the header, so the two cannot be confused.

   `--nds-grid-muted-fg` is an existing token and no new one was minted: the DS already had the
   glyph convention too (`.chev` on Select, Listbox, Combobox and the nav rail), so PES.2 renders
   the same lucide ChevronDown every other select in the app uses. */
.nds-ag-wrap .ag-cell.nds-cell-is-select { cursor: pointer; }
/* 🔴 NO resting opacity, and that is a contrast decision rather than a taste one. The first draft
   dimmed the glyph to `opacity: 0.5` so it would sit quietly in every row; composited against the
   cell that measured **2.05:1**, under the 3:1 floor a non-text indicator owes. This chevron is not
   decoration — it is the only thing distinguishing a closed list from free text, which is the
   "decorative by category, informative in fact" shape that has cost this DS an Input placeholder at
   2.04 and a Listbox hint at 3.10. An informative glyph is not dimmed; if it is too loud at full
   strength the answer is a quieter TOKEN, not a lower alpha. `--nds-grid-muted-fg` measures 5.32:1
   light and 7.38:1 dark, and matches how every other DS select shows its chevron — always on. */
.nds-ag-chev {
  margin-left: auto;
  flex: none;
  color: var(--nds-grid-muted-fg);
  pointer-events: none;
}
.nds-ag-wrap .ag-cell.nds-cell-is-pending { background: var(--nds-grid-pending-bg) !important; }
.nds-ag-wrap .ag-cell.nds-cell-is-saving { background: var(--nds-grid-saving-bg) !important; }
.nds-ag-wrap .ag-cell.nds-cell-is-saved { box-shadow: inset 0 0 0 1px var(--nds-success); transition: box-shadow 400ms ease; }
.nds-ag-wrap .ag-cell.nds-cell-is-refused { background: var(--nds-grid-refused-bg) !important; box-shadow: inset 0 0 0 1px var(--nds-grid-refused-ring); }
/* 🔴 "We do not know", in warning tone — NOT the danger tone a refusal wears. `waiting` is a flight
   still open past the patience window; `unknown` is a fetch that rejected and may or may not have
   applied. Both are honest ignorance, and painting either as a refusal is what told an operator a
   34-second write had failed when it had in fact saved. */
.nds-ag-wrap .ag-cell.nds-cell-is-waiting { background: color-mix(in srgb, var(--nds-warning) 8%, transparent) !important; }
.nds-ag-wrap .ag-cell.nds-cell-is-unknown { background: color-mix(in srgb, var(--nds-warning) 8%, transparent) !important; box-shadow: inset 0 0 0 1px var(--nds-warning); }
.nds-cell-select-editor { width: 100%; padding: 0 4px; }

/* sheet validation — a tint AND a corner triangle (never colour alone); the reason is the cell's title */
/* #780 — a cell whose formula was refused carries the same tint as an invalid one: the operator's
   next action is the same (open it and fix what produced it), and inventing a third tint for a
   fourth state would multiply the vocabulary without changing where the click lands (§9.6b).
   🔴 Its own CLASS though: `nds-cell-is-refused` already belongs to `roundTripClassRules`, where it
   means a rejected SAVE. Sharing the tint is a design choice; sharing the class name was a bug that
   let a later spread silently win. */
.nds-ag-wrap .ag-cell.nds-cell-is-formula-refused { background: var(--nds-grid-refused-bg) !important; }
.nds-ag-wrap .ag-cell.nds-cell-is-invalid { background: var(--nds-grid-refused-bg) !important; }
.nds-ag-wrap .ag-cell.nds-cell-is-invalid::after, .nds-ag-wrap .ag-cell.nds-cell-is-warned::after { content: ''; position: absolute; top: 0; right: 0; border-style: solid; border-width: 0 7px 7px 0; border-color: transparent var(--nds-danger) transparent transparent; }
.nds-ag-wrap .ag-cell.nds-cell-is-warned { background: var(--nds-grid-pending-bg) !important; }
.nds-ag-wrap .ag-cell.nds-cell-is-warned::after { border-color: transparent var(--nds-warning) transparent transparent; }
/* a value inherited from the parent: readable, and quietly not the row's own */
.nds-ag-wrap .ag-cell.nds-cell-is-inherited { color: var(--nds-grid-muted-fg); background: color-mix(in srgb, var(--nds-info) 6%, transparent); }
/* PES.2 — cell PROVENANCE. A tint AND a glyph (renderers/provenance.tsx); never colour alone.
   Every colour here is a declared token used at the USE site, not aliased into a new `:root`
   custom property — so the dark-alias scope trap (scripts/check-dark-alias-scope.mjs) does not
   apply and `.dark` resolves each one itself. Measured in tokens.css 2026-09-01: --nds-primary
   IS re-declared inside .dark; --nds-info / --nds-purple-600 are theme-invariant, exactly
   like the --nds-info the inherited rule above already rides on. The tints are low-percentage
   mixes over the cell's own ground, which does flip, and the glyph carries the meaning either
   way.

   🔴 This comment used to end "Contrast is verified in BOTH themes, in the browser, before this
   ships." **It was not.** Nobody measured it, and the sentence read as a record of work done — so
   it did the opposite of its job, discouraging the check it claimed to describe. `64` measured the
   marks in the browser afterwards and found three shipped ones under the 3:1 a meaningful glyph
   owes: `ai` 2.07:1 in both themes, `inherited` 2.38, `pinned` 2.83 light.
   What this rests on now: `64`'s browser measurement of every provenance mark, both themes,
   composited over the real cell ground — and the acceptance for the fix below is their re-measure,
   not a re-reading of this comment. **A comment must state what WAS measured, never what should
   be.** */
.nds-ag-wrap .ag-cell.nds-cell-is-pinned { background: color-mix(in srgb, var(--nds-primary) 7%, transparent); }
.nds-ag-wrap .ag-cell.nds-cell-is-ai-draft { background: var(--nds-grid-ai-draft-bg); font-style: italic; }
/* italic overhang — see `.nds-cell-required` */
.nds-ag-wrap .ag-cell.nds-cell-is-ai-draft .nds-cell-value-text { padding-inline-end: 2px; }
/* A STALE draft (PES.8): still a draft, plus the warn triangle the validation states already use,
   so "this would overwrite an edit" reads in the idiom an operator has already learned. */
.nds-ag-wrap .ag-cell.nds-cell-is-ai-draft-stale::after { content: ''; position: absolute; top: 0; right: 0; border-style: solid; border-width: 0 7px 7px 0; border-color: transparent var(--nds-warning) transparent transparent; }
/* The mark sits before the value and never steals width from it: it is `flex: none`, and the
   value beside it is what ellipsises. */
/* 🔴 NO `opacity`. It was 0.75, and that alone put `inherited` at 2.38:1 and `pinned` at 2.83:1 —
   under the 3:1 a non-text indicator owes. My own note on `.nds-ag-chev` states the rule this
   broke: **an informative glyph is not dimmed; if it is too loud at full strength the answer is a
   quieter TOKEN, not a lower alpha.** These marks are the only thing distinguishing an inherited
   value from a typed one, so they are informative by definition. Removing the alpha is what makes
   `inherited` and `pinned` pass on the tokens they already ride. */
.nds-cell-prov { flex: none; display: inline-flex; align-items: center; margin-right: 5px; vertical-align: middle; }
/* DS.2's semantic token (FX.1's measurement: dark 2.55 → 8.44 / 2.67 → 8.85 / 2.28 → 7.55). */
.nds-cell-prov-inherited { color: var(--nds-prov-inherited-fg, var(--nds-info-strong)); }
/* Inherited VIA a layer that itself overrides the master (ruling #16): the same family as plain
   inheritance, distinguished by its own glyph rather than by a shade of the same one. */
.nds-cell-prov-via { color: var(--nds-primary); }
.nds-ag-wrap .ag-cell.nds-cell-is-inherited-override { background: color-mix(in srgb, var(--nds-primary) 5%, transparent); }
.nds-cell-prov-pinned { color: var(--nds-primary); }
/* 🔴 `--nds-prov-ai-fg` with a FALLBACK, deliberately. DS.2 is landing that token now and it does
   not exist yet — and an undefined custom property in a `color` computes to `rgba(0,0,0,0)`, i.e.
   the mark disappears, silently, with no guard in the repo that catches it. Writing it bare would
   have "fixed" a 2.07:1 contrast by making the glyph invisible. The fallback keeps today's colour
   until the token lands, at which point it takes over with no further edit. */
.nds-cell-prov-ai { color: var(--nds-prov-ai-fg, var(--nds-purple-700)); }
.nds-cell-prov-ai-stale { color: var(--nds-warning-strong); }
/* §9.6's derived-value marks. `provenanceMark.tsx` has emitted these classes since the union was
   widened and `grid.css` had NO rule for either — the tests assert the class is APPLIED, never that
   it does anything, so both marks inherited the cell's own colour and said nothing by their tint.
   `--nds-grid-muted-fg` is chosen because it is already measured (5.32:1 light, 7.38:1 dark) and
   because a derived value is informative rather than alarming: it is not a warning, it is a
   statement about where the value came from. If DS.2 would rather mint a semantic token for
   provenance-derived, this is the line to change. */
.nds-cell-prov-mapped { color: var(--nds-grid-muted-fg); }
/* Product-grain: the same family, distinguished by its own glyph (Share2), not by a shade. */
.nds-cell-prov-mapped-shared { color: var(--nds-grid-muted-fg); }
/* §9.6's ninth member: a cell whose value is produced by a stored `CellFormula` (D16, hub #730).
   The token is DS.2's, landed in BOTH themes and measured there — light `#0e7490` (surface 5.36 ·
   ai-tint 4.43 · pinned 4.88), dark `#22d3ee` (8.43 · 8.36 · 7.87). No fallback here, unlike
   `--nds-prov-ai-fg` above: that one was written with one because the token did not exist yet and
   an undefined custom property in a `color` computes to `rgba(0,0,0,0)` — the mark vanishing
   silently. This token exists (`tokens/css-vars.ts:287,574`), verified before the rule was written
   rather than after. */
.nds-cell-prov-formula { color: var(--nds-prov-formula-fg); }

/* 🔴 #780 — a REFUSED formula's mark. It replaces the ƒ rather than joining it, so this is the only
   thing in the cell saying where the value came from, and it has to read as a WARNING at 11px.
   `--nds-warning` rather than `--nds-danger`: the cell still holds its previous value and nothing is
   broken — the formula simply produced nothing — and reserving danger for a cell that is actually
   invalid keeps the two distinguishable on a sheet showing both. Not `opacity`: an informative glyph
   is never dimmed (the banked contrast rule). */
.nds-cell-prov-refused { color: var(--nds-warning); font-weight: 700; }
/* Only the typography is local — italic and weight are what make a `ƒ` read as a function rather
   than an `f`, and they are not what was ruled into the engine. */
.nds-formula-glyph { font-style: italic; font-weight: 700; line-height: 1; font-size: var(--nds-font-size-sm); }

/* ── the `=` formula editor (D16 / §1.3) ───────────────────────────────────────────────────────
   The editor is an AG POPUP, so it is free of the cell's box and grows downward: field, then the
   `$` autocomplete IN FLOW, then the signature hint, then the preview line. The autocomplete is in
   flow rather than floating because floating it covered the preview — the one thing §1.3 step 2
   exists to show, at exactly the moment an operator is choosing what to read. */
.nds-formula-editor {
  display: flex; flex-direction: column;
  background: var(--nds-surface); color: var(--nds-text);
  border: 1px solid var(--nds-border); border-radius: var(--nds-radius-lg);
  /* 🔴 `--nds-shadow-pop`, the DEFINED token (`styles/tokens.css:203`). I first wrote
     `--nds-shadow-md`, which exists nowhere in this repo — and an undefined custom property in a
     `box-shadow` makes the whole declaration invalid at computed-value time, so the popup would
     have rendered with NO shadow and nothing would have said so. Checked every token in this block
     against its definition before shipping, which is how this one was found. */
  box-shadow: var(--nds-shadow-pop);
}
/* The overlay stacks ON the input, so the wrapper is the positioning context. `display: grid`
   stretches `.nds-field` — it is `inline-flex` and would otherwise size to the input's default
   ~20-character width and clip a formula inside a much wider editor (measured in the lab: 231px
   inside a 420px box). */
.nds-formula-fieldwrap { position: relative; display: grid; }
/* 🔴 The input's own text goes TRANSPARENT and the overlay carries the colour, but the CARET stays
   visible and inherits the text colour — a transparent caret is an editor with no cursor, which is
   the kind of defect that only shows up once someone types. Selection still paints natively. */
/* 🔴 MONO, and it is not decoration. `.nds-fx-errmark` positions the error tick in `ch` units, and
   a `ch` in a proportional face is the width of a `0` — which is not the width of the character it
   is meant to sit under. Measured before this line existed: the overlay computed
   `11.5px Inter`, inherited from the field, so every mark landed at a plausible wrong offset. The
   overlay copies the input's resolved face, so setting it here sets both and they cannot drift. */
/* 🔴 `.nds-formula-editor .nds-field input`, not `.nds-formula-input`. The class alone is (0,1,0)
   and the DS's own `.nds-field input` is (0,1,1), so it won and the overlay — which copies the
   input's RESOLVED face — computed `11.5px Inter`. Measured on the live editor after the first
   attempt: `overlayFont: "Inter, Inter Fallback, …"`. This is the banked page-sheet-beats-DS shape
   with the roles reversed, and the tell was that the declaration was present and simply not in
   effect. */
.nds-formula-editor .nds-field input.nds-formula-input,
.nds-formula-composer .nds-field input.nds-formula-input {
  caret-color: var(--nds-text);
  font-family: var(--nds-font-mono);
  font-variant-ligatures: none;
}
.nds-formula-editor .nds-field input.nds-formula-input.highlighted { color: transparent; }
.nds-formula-overlay {
  position: absolute; pointer-events: none;
  display: flex; align-items: center;
  white-space: pre; overflow: hidden;
  box-sizing: border-box;
  /* 🔴 ABOVE the field, and this was a real defect rather than a precaution. `.nds-field` paints an
     opaque white background and the overlay is its previous sibling, so with `z-index: auto` the
     field painted over it and the formula was INVISIBLE — the input's own text being transparent by
     design, the cell looked empty while holding text. Found on screen; the DOM said `overlayText:
     "="` while the screenshot showed nothing, which is the only reason it was caught at all. */
  z-index: 1;
  /* `left` and `padding-left` are set by the component from the INPUT's measured rect — the `ƒ`
     rides as the field's `leadingIcon` inside the border, so the text starts 20px right of the
     field's edge (measured: field 517, input 537). Positioning from the wrapper would put every
     character 20px left of the one it describes. */
}
.nds-formula-overlay-line { position: relative; flex: none; }
.nds-formula-input, .nds-formula-overlay, .nds-formula-help code,
.nds-formula-help-panel code, .nds-formula-hint code { font-variant-ligatures: none; }
.nds-fx-eq { color: var(--nds-text-muted); }
.nds-fx-str { color: var(--nds-success-text); }
.nds-fx-num { color: var(--nds-text); }
.nds-fx-ident { color: var(--nds-primary); }
.nds-fx-op, .nds-fx-punc { color: var(--nds-text-muted); }
.nds-fx-error { color: var(--nds-danger-text); text-decoration: underline wavy; }
/* A reference wears the hue `formulaPalette` assigned it — set inline, because the assignment is
   per-formula and per-edit and there is no class to carry seven rotating hues. */
.nds-fx-ref { font-weight: 600; }
/* 🔴 An UNKNOWN reference is red and underlined, never merely uncoloured. The engine's own failure
   mode for one is to warn and resolve to nothing, and an operator reading a blank cell cannot tell
   a typo from an empty source — which is the whole reason `unknownRefs` was added to the route
   (#723). Red plus a wavy underline, so it does not depend on colour alone. */
.nds-fx-ref.bad { color: var(--nds-danger-text); text-decoration: underline wavy; font-weight: 600; }
.nds-fx-errmark {
  position: absolute; bottom: 0; width: 1ch; height: 2px;
  background: var(--nds-danger-text);
}
/* In flow inside the editor, so it cannot cover the preview line below it. */
.nds-formula-pop { position: static; box-shadow: none; border: 1px solid var(--nds-border-subtle); }
.nds-formula-hint { display: flex; gap: var(--nds-space-2); align-items: baseline; font-size: var(--nds-font-size-xs); color: var(--nds-text-muted); }
.nds-formula-hint code { font-family: var(--nds-font-mono); color: var(--nds-text); }
/* The argument the caret is in. Weight AND colour: emphasis by weight alone is invisible at 11px
   in a monospace face, and by colour alone it fails for an operator who cannot separate the hues. */
.nds-formula-hint code .on { font-weight: 700; color: var(--nds-primary); }
.nds-formula-hint-sum { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.nds-formula-preview {
  font-family: var(--nds-font-mono); font-size: var(--nds-font-size-xs);
  color: var(--nds-text); overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  border-top: 1px solid var(--nds-border-subtle); padding-top: var(--nds-space-1);
}
.nds-formula-preview.muted { color: var(--nds-text-muted); }
.nds-formula-preview.bad { color: var(--nds-danger-text); white-space: normal; }
/* 🔴 A cell being edited by an OVER popup does not paint its own value (#769).
   AG 36's reactive editors report every keystroke through `onValueChange`, which updates the proxy's
   value and repaints the cell UNDERNEATH the popup — so a half-typed formula appeared in the cell as
   though it were the value, which is exactly what (a2) exists to prevent. The editor is the truth
   while it is open; the cell has nothing to add and its text is a stale draft.
   `visibility`, not `display`: the cell keeps its box, so nothing reflows when the edit ends.

   🔴 `:not(.nds-cell-is-select)` — SCOPED TO `over` POPUPS, 2026-09-03 (Owner's Phase 1).
   Unscoped, this also blanked the cell under an `under` popup, and MEASURED that is what happened:
   with the Status list open, the Status cell read `"ACTIVE"` before the gesture and `""` while the
   list was showing — an empty blue box with the options beneath it, so the operator chose a new
   value with the current one hidden. Every other row still read ACTIVE. The reason #769 gives holds
   only where the popup COVERS the cell; where it sits below, the cell is the only place the current
   value appears and hiding it is a defect of its own.
   Keyed on the select class because `cellEditorPopupPosition: 'under'` is set by `selectEditor()`
   alone and nothing else in the product is positioned `under`. It is a PROXY and it is safe in both
   directions: a select cell opened by the `=` editor is an `over` popup that keeps its value
   painted, which the popup then covers anyway — visually identical, nothing leaks. */
.nds-ag-wrap .ag-cell.ag-cell-popup-editing:not(.nds-cell-is-select) .nds-cell-value { visibility: hidden; }

/* 🔴 THE ORIGIN CELL IS OUTLINED WHILE IT IS BEING EDITED (Owner's Phase 1, 2026-09-03).
   "The cell being edited is always the one you are looking at, outlined" — the constant across
   Excel, Sheets and Airtable. It matters most exactly when the geometry cannot be perfect: if a
   column is scrolled so far right that even the room-capped editor cannot sit flush, this outline is
   the only thing still tying the editor to the cell it came from.
   Same `outline` / `outline-offset: -2px` idiom as the formula reference above, and for the same
   reason: a border would change the cell's box and shift every column beside it the moment an
   editor opened. */
.nds-ag-wrap .ag-cell.ag-cell-popup-editing {
  outline: 2px solid var(--nds-primary);
  outline-offset: -2px;
}

/* 🔴 THE EDITOR'S BOX, computed per cell by `editors/editorBox.ts` and published as custom
   properties by `publishEditorBox()` BEFORE AG creates and positions the popup.
   `agLargeTextCellEditor` takes only `rows`/`cols` — character counts — so pixels have to arrive
   this way. The old constant was 488×158 for every cell whatever the content, which AG then slid up
   to 202px sideways to keep it in the window. The fallback values are the previous constants, so a
   failure to publish degrades to the old behaviour rather than to nothing.
   The properties live on `:root` because AG parents editor popups to `document.body`; exactly one
   cell editor is open at a time, so one slot is enough. */
/* 🔴 ONE BOX, AND THE TEXTAREA IS THE THING THAT IS SIZED — Owner item 52(a), 2026-09-04.
   The first version of this rule set a fixed `height` on `.ag-large-text` and `.ag-large-text-input`
   and `resize: none` on the same two, and BOTH halves were wrong in the same way: neither selector
   is the textarea. Measured in the live DOM — `textarea.ag-input-field-input.ag-text-area-input`
   inside `div.ag-large-text-input` (AG's AgInputTextArea WRAPPER) inside `div.ag-large-text` (which
   carries the white background). So `resize: none` bound to nothing, computed `resize` on the real
   textarea stayed `vertical`, and AG only kills it under `.ag-rtl` — in LTR the handle is theirs by
   design and has always been there.
   What my fixed height then added was the TEAR the Owner photographed: AG sets `height: auto` on the
   wrapper precisely so it follows the textarea, I overrode it with a pixel value, and dragging grew
   the textarea while the background stayed put. Reproduced before fixing: textarea 368×250 against
   an outer box frozen at 396×158.
   So the container is no longer sized at all — AG's `auto` stands and it follows its content — and
   the height, the cap, the scroll and the resize lock all live on the textarea, which is the element
   that actually holds the text. One box, because only one of them has a height. */
.ag-popup-editor .ag-large-text {
  width: var(--nds-editor-w, 488px);
  max-width: 100vw;
  box-sizing: border-box;
}
.ag-popup-editor .ag-large-text-input { width: 100%; box-sizing: border-box; }
.ag-popup-editor .ag-text-area-input {
  /* No manual resize handle: the approved rule is that height follows content to a cap, and a drag
     handle offers a second, conflicting way to size the same box. */
  resize: none;
  height: var(--nds-editor-h, 158px);
  max-height: var(--nds-editor-h, 158px);
  overflow-y: auto;
  box-sizing: border-box;
}

/* 🔴 The same-row OUTLINE, in the reference's own hue — Excel's affordance and the Owner's ask.
   `outline`, not `border`: a border would change the cell's box and shift every column beside it by
   2px the moment an operator typed a `$`. `outline-offset: -2px` keeps it inside the cell so
   adjacent outlines do not overlap into a 4px seam. */
.nds-ag-wrap .ag-cell.nds-formula-ref-cell {
  outline: 2px solid var(--nds-formula-ref, var(--nds-primary));
  outline-offset: -2px;
}
/* A cell that carries a mark lays out as a row so the glyph and the text share the line. */
.nds-cell-value { display: inline-flex; align-items: center; min-width: 0; width: 100%; }
.nds-cell-value-text { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; min-width: 0; }
/* 🔴 ITALIC OVERHANG (Owner, 2026-09-05: "required … is cropped a bit at the end"). The clip box is
   `.nds-cell-value-text`'s padding box, sized to the text's ADVANCE width; an italic glyph paints past
   its advance, so the last letter's tail was cut off. Every italic run inside a clipped cell carries
   an end padding of its own (the ai-draft cell does the same, below its rule) so the tail can paint.
   Guarded by `renderers/listChipAndItalicClip.vitest.test.ts`: a new italic needs its padding. */
.nds-cell-required { color: var(--nds-danger-text); font-style: italic; font-size: var(--nds-font-size-xs); padding-inline-end: 2px; }
/* A cell the ACTIVE view chip counted (PES.3's need, hoisted into the engine — grid chrome belongs
   here, never in a page stylesheet, and the import-boundary guard enforces exactly that). Filtering
   to the matching ROWS alone leaves the operator hunting for which of a hundred columns was the
   reason, so the cells themselves are marked. A ring, not a fill, so it composes with the
   provenance tints instead of hiding them. */
.nds-ag-wrap .ag-cell.nds-cell-chip-hit { box-shadow: inset 0 0 0 2px var(--nds-warning); }

/* ══ media cells (`renderers/MediaCellView.tsx`) ══════════════════════════════════════════════
   A grid whose CELL IS A PICTURE — the Amazon Colour × Slot matrix, the eBay bucket grid.
   🔴 Nothing here is `position: absolute`: an absolutely positioned child ESCAPES an AG cell
   (ruling #12), so the marks are laid-out flex children and the tile is a flex container. */
.nds-media-cell {
  display: flex; align-items: center; gap: 6px;
  width: var(--nds-media-size, 96px); height: var(--nds-media-size, 96px);
  border: 1px solid var(--nds-border); border-radius: var(--nds-grid-radius);
  background: var(--nds-surface-sunken); overflow: hidden; position: relative;
}
/* 🔴 THE PICTURE YIELDS; THE MARK NEVER CLIPS (#688, ruled by the hub on PES.7's measurement).
   `.nds-media-cell` is `overflow: hidden` and lays out image + 6px gap + marks in ONE row. With
   the image at `width: 100%` that row is 80 + 6 + 22 = 108px inside an 84px box, so the marks
   rendered OUTSIDE the clip rect and the provenance glyph was simply not painted — measured live
   on the Amazon·IT matrix: tile right edge 568, marks 571→593, i.e. 25px out, on BOTH real
   `pinned` marks of 30 media cells. A tile that wears no glyph has only its border to say where
   its picture came from, which is why the `-ai`/`-ai-stale` split two rules below matters.
   `flex: 1 1 0` + `min-width: 0` makes the image the item that gives way — `min-width: auto` is a
   flex item's automatic floor and would otherwise hold it at its content width, which is the same
   mechanism that held the `?` button 2px too wide (#684). `object-fit: cover` keeps the crop
   centred as the box narrows.
   Measured by UX.1 on both arms of one build: `overflow: hidden` clips at the PADDING box (567),
   not the border box (568), so the marks' right edge at 567 sits EXACTLY flush with the clip rect
   — not one pixel inside, as a border-box reading suggests. The pre-fix overhang was +26 against
   that rect (not the +25 a border-box reading gives), and it ran on 14 of 30 tiles: unmarked image
   tiles overhung by 10px each, with no glyph to lose.
   FLUSH IS NOT FRAGILE — the bound, measured by UX.1 across four in-page arms on this build:
   the image ABSORBS growth in the strip or the gap, down to 0 width, so the mark cannot re-clip
   while `marks + gap <= 82px` (the tile's CONTENT box). Arms: marks 30 → image 46, flush ·
   marks 76 → image 0, flush (the boundary) · marks 90 → 14px over, clipped · gap 20 → image 40,
   flush. At a 6px gap that is a 76px strip, roughly three and a half more glyphs of headroom.
   An earlier version of this comment said any growth re-clips immediately; that was wrong, and so
   was the opposite claim that it never can.
   ⚠ The acceptance is that the GLYPH is reachable, not that the strip fits: at the 90px arm the
   strip overhangs and the first glyph still hit-tests. */
.nds-media-img { flex: 1 1 0; min-width: 0; width: 100%; height: 100%; object-fit: cover; display: block; }
/* 🔴 The empty placeholder NEVER HAD THIS BUG, and the reason is worth keeping because the obvious
   analogy is wrong. "Same box, same row" predicts it clipped like the image; measured, it is 70px in
   BOTH arms, and under an identical forced squeeze the image stayed floored at 80 while this box
   yielded to 54 on its own. `min-width: auto` resolves differently by element: on an `<img>` the
   automatic minimum is the INTRINSIC width, on a `<span>` flex container it is min-content — an
   icon. So this line fixes nothing today. It is kept only so both boxes state the same intent, and
   it starts mattering the day this span gains intrinsic content. (UX.1, one build, both arms.) */
.nds-media-empty { display: flex; align-items: center; justify-content: center; flex: 1 1 0; min-width: 0; width: 100%; height: 100%; color: var(--nds-grid-muted-fg); }
/* The marks sit in their own strip so they never cover the picture they describe. */
.nds-media-marks { display: inline-flex; align-items: center; gap: 3px; flex: none; padding: 0 3px; }
.nds-media-count { font-size: 10px; font-weight: 700; color: var(--nds-text-2); font-variant-numeric: tabular-nums; }

.nds-media-is-empty { border-style: dashed; }
.nds-media-is-locked { opacity: 0.75; }
.nds-media-is-pending { box-shadow: inset 0 0 0 2px var(--nds-grid-saving-bg); }
.nds-media-is-warned { box-shadow: inset 0 0 0 2px var(--nds-warning); }
.nds-media-is-refused { box-shadow: inset 0 0 0 2px var(--nds-grid-refused-ring); background: var(--nds-grid-refused-bg); }
/* Provenance reuses the CELL vocabulary — one idea, one set of names. */
.nds-media-prov-inherited { border-color: var(--nds-prov-inherited-fg, var(--nds-info-strong)); }
.nds-media-prov-inherited-override { border-color: var(--nds-primary); }
.nds-media-prov-pinned { border-color: var(--nds-primary); }
/* 🔴 `ai` and `ai-stale` are DIFFERENT states and must not share a border (#684(a), PES.7's
   measurement). They were byte-identical here — contrast 1.00 — while the cell forms at :535/:536
   already paint them apart. On a TILE the border is doing more work than it looks: PES.7 measured
   `.nds-media-marks` (22px, `flex:0 0 auto`) overflowing `.nds-media-cell` (84px, `overflow:hidden`)
   on tiles whose image cannot shrink, so the provenance GLYPH is clipped away and the border is the
   only channel left. `--nds-warning-strong` is pinned in both themes (tokens.css:104 / :464), so
   unlike the `ai` line it needs no fallback. ⚠ The clipping itself is a separate, unruled defect in
   `.nds-media-cell`/`.nds-media-marks` geometry — not fixed here. */
.nds-media-prov-ai { border-color: var(--nds-prov-ai-fg, var(--nds-purple-700)); }
.nds-media-prov-ai-stale { border-color: var(--nds-warning-strong); }
/* The channel's own answer, as a rule along the bottom rather than a floating dot. */
.nds-media-publish-live { border-bottom: 3px solid var(--nds-success); }
.nds-media-publish-queued { border-bottom: 3px solid var(--nds-warning); }
.nds-media-publish-failed { border-bottom: 3px solid var(--nds-danger); }
/* long text: the text ellipsises, the counter keeps its place */
.nds-cell-longtext { display: inline-flex; align-items: center; gap: 8px; min-width: 0; width: 100%; }
.nds-cell-longtext-text { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; min-width: 0; flex: 1 1 auto; }
/* §9.3a — the length as a MARK, not a counter. "127/200" beside one line of text was most of a
   110px cell, so the figures moved to the tooltip and the state stays on screen.
   🔴 The GLYPH carries the distinction (● filled · ◆ near · ▲ over) and the tone reinforces it:
   amber and red read identically to a large minority of operators, so colour alone would make
   "you have room left" and "this will be refused" the same mark. `unchecked` renders nothing —
   see LongTextCell for why that is only honest while `filled` is visible. */
.nds-cell-longtext-mark { flex: none; font-size: 9px; line-height: 1; color: var(--nds-grid-muted-fg); }
.nds-cell-longtext-mark-near { color: var(--nds-warning-strong); font-size: 10px; }
.nds-cell-longtext-mark-over { color: var(--nds-danger-text); font-size: 10px; }
/* follows-master control */
.nds-cell-follows { font-size: var(--nds-font-size-xs); color: var(--nds-grid-muted-fg); white-space: nowrap; }
.nds-cell-follows-pinned { color: var(--nds-text-2); font-weight: 600; }

/* overlays */
/* AG wraps React overlays in a shrink-to-content flex item. Give the skeleton the grid width. */
.nds-ag-wrap .ag-overlay-loading-wrapper > .ag-react-container:has(> .nds-grid-skel) { width: 100%; }
/* 16px, matching the footstrip and the toolbar. The SKELETON's inset matters more than it looks:
   at 14px the first paint sat 2px left of where the real content lands, so every sheet load ended
   with a 2px jump. DS.2's four-edge measurement. */
.nds-grid-skel { display: flex; flex-direction: column; width: 100%; padding: 0 16px; }
.nds-grid-skel-row { display: flex; align-items: center; gap: 12px; border-bottom: 1px solid var(--nds-grid-row-rule); }
.nds-grid-skel-thumb { flex: none; border-radius: var(--nds-radius-sm); background: var(--nds-grid-skeleton-bg); }
.nds-grid-skel-text { display: flex; flex-direction: column; gap: 7px; flex: 1; }
.nds-grid-skel-line { display: block; height: 11px; border-radius: 6px; background: linear-gradient(90deg, var(--nds-grid-skeleton-bg) 25%, var(--nds-grid-skeleton-shine) 37%, var(--nds-grid-skeleton-bg) 63%); background-size: 400% 100%; animation: nds-grid-shimmer 1.3s ease infinite; }
.nds-grid-skel-line-sub { height: 8px; }
@keyframes nds-grid-shimmer { 0% { background-position: 100% 0; } 100% { background-position: 0 0; } }
@media (prefers-reduced-motion: reduce) { .nds-grid-skel-line { animation: none; } }
.nds-grid-noRows { display: flex; flex-direction: column; align-items: center; gap: 8px; }
.nds-grid-noRows-title { font-weight: var(--nds-font-weight-semibold); color: var(--nds-grid-cell-fg); }
.nds-grid-noRows-msg { color: var(--nds-grid-empty-fg); }

/* ══ hosts and toolbars (`../hosts`, `../toolbars`) ═══════════════════════════════════════════
   Lifted from /products/next (`.pager`, `.rpp`, `.grow`, `.ieFootStrip`, `.gridCard`), measured. */
/* the page host is a size container, so a toolbar's selection cluster adapts to the CARD's width */
.nds-grid-card { container-type: inline-size; }
/* the pager: pages left of the control, rows-per-page on the right (the Ad Manager's arrangement) */
/* 16px — same value, same reason as the footstrip above. I fixed the footstrip alone earlier and
   left this and the skeleton at 14, so the engine's own three chrome bands disagreed with each
   other. Enumerating one consumer and calling it the set is the mistake, not the number. */
.nds-grid-pager { display: flex; align-items: center; gap: 16px; padding: 10px 16px; border-top: 1px solid var(--nds-border); }
.nds-grid-pager-grow { flex: 1; }
.nds-grid-pager-rpp { display: flex; align-items: center; gap: 8px; font-size: 13px; color: var(--nds-text-2); white-space: nowrap; }
/* the editor's footer strip inside the card */
/* 🔴 16px horizontal, not 14 — the studio's gutter. DS.1 measured the three stacked text runs
   inside one sheet card starting at x = 81 / 83 / 81: the footstrip rendered TWICE at the time
   (family band on top, status strip at the bottom) and the toolbar between them at 16px is what
   read as misaligned. The family band has since been folded into the toolbar (§2.1c), so only the
   status strip is left — the 16px stands on its own evidence, not on the pair. `.nds-detailhdr`, `.nds-scopebar`, the tab strip and `.nds-gridcard .nds-toolbar` all
   compute `0 16px`, so the footstrip was the lone outlier. Changed on the BASE rather than added as
   a studio modifier: nothing evidenced the 14 as deliberate, and one consumer at a different inset
   is how a design system grows two gutters for one idea. */
.nds-grid-footstrip { display: flex; align-items: center; gap: 10px; padding: 10px 16px; border-top: 1px solid var(--nds-border); }
.nds-grid-footstrip-grow { flex: 1; }

/* the toolbar's swapping halves (`../toolbars/GridSelectionActions`). The search field is 36px, an
   `sm` button 28: the cluster holds the toolbar's height on the first tick and never wraps —
   labels hide under 1320px and the reach note under 1100px of the CARD (`GridCard` is the container). */
.nds-grid-selbar { display: inline-flex; align-items: center; gap: 7px; flex-wrap: nowrap; white-space: nowrap; min-width: 0; min-height: var(--nds-grid-toolbar-slot-h); }
.nds-grid-selbar-note { color: var(--nds-grid-muted-fg); }
.nds-grid-search { flex: 1; min-width: 220px; max-width: 340px; }
/* The two halves share ONE height. A DS field is a 1px border + padding + a 19.5px line box = 35.5px;
   the cluster's floor was 36 — a half-pixel step on every tick (measured 64.5 → 65 on both surfaces).
   Both sides now sit on the same floor, so the swap is exact by construction. */
.nds-grid-search .nds-field { min-height: var(--nds-grid-toolbar-slot-h); box-sizing: border-box; }
.nds-ag-wrap, .nds-gridcard { --nds-grid-toolbar-slot-h: 36px; }
@container (max-width: 1320px) { .nds-grid-selbar-lbl { display: none; } }
@container (max-width: 1100px) { .nds-grid-selbar-note { display: none; } }

/* ══ the SHEET host (`../hosts/GridSheet`) ═══════════════════════════════════════════════════
   The one page-level grid that is bounded and virtualised: it fills the viewport below its own top
   edge (measured, stamped as --nds-grid-sheet-top) and the grid inside scrolls both ways. */
/* The gutter is 8px, not 24. §2.2 wants 74.8% of the viewport in ROWS, and a full-bleed sheet has
   no bottom gutter to spend — 16px of the last 20 in the whole §2 budget was sitting here. It stays
   a variable so a host inside a padded shell can put its own back. */
.nds-grid-sheet { display: flex; flex-direction: column; height: calc(100dvh - var(--nds-grid-sheet-top, 0px) - var(--nds-grid-sheet-gutter, 8px)); min-height: 360px; }
/* 36px, not the base 40 — SCOPED to the sheet on purpose. The 4px is a layout-v2 budget line, and
   layout v2 is this host; the GridCard pages have no such budget and no reason to inherit a
   tighter footer from it. This is the opposite call to the 16px inset above, and for the opposite
   reason: that was one idea rendered at two gutters, this is two hosts with different budgets. */
.nds-grid-sheet .nds-grid-footstrip { height: 36px; flex: 0 0 36px; box-sizing: border-box; padding-top: 0; padding-bottom: 0; }
.nds-ag-fill { flex: 1 1 0; min-height: 0; }
/* 🔴 Reserve the AI copilot FAB's footprint. The status strip is the sheet's ONLY keyboard-hint
   line, and the FAB covers 104×19px of its TAIL — so what an operator loses is "drag the corner to
   fill · ⌘Z", the two things they are least likely to guess. Seen on screen, not deduced.

   Reserved rather than lifting the FAB (the other option DS.1 offered): moving the button up just
   puts it over the grid, which trades a covered hint for a covered cell. The width comes from
   DS.1's measured token rather than a number copied here — if the button's footprint changes, this
   follows it. DS1-2. */
.nds-grid-sheet-status { font-size: 12.5px; color: var(--nds-text-2); padding-right: var(--nds-fab-reserve-inline, 128px); }
.nds-grid-sheet-status-pending { color: var(--nds-warning-strong); }
.nds-grid-sheet-status-refused { color: var(--nds-danger-text); }

/* ── Action confirmations (GDS actions/ActionConfirm) ─────────────────────────
   A verb's confirmation is a safety control, so its look lives with the grid
   engine rather than per lane — one dialog, one set of rules, every surface. */
.nds-grid-confirm-block { margin-bottom: 14px; }
.nds-grid-confirm-block:last-child { margin-bottom: 0; }
/* `list-style` is set explicitly: the app reset strips markers, and without them a confirmation's
   itemised consequences render as a run of plain sentences — which is how a list of five live
   listings reads as one paragraph nobody counts. */
.nds-grid-confirm-list { margin: 6px 0 0; padding-left: 18px; list-style: disc outside; display: flex; flex-direction: column; gap: 4px; }
.nds-grid-confirm-list li { color: var(--nds-text); }
/* The unasked-for consequences are set apart, never mixed into the list above. */
.nds-grid-confirm-aside { border-left: 2px solid var(--nds-warning); padding-left: 10px; }
.nds-grid-confirm-aside li { color: var(--nds-grid-muted-fg); }
.nds-grid-confirm-warn { color: var(--nds-warning); }
.nds-grid-confirm-error { color: var(--nds-danger); }

/* PES.2 F4 — the add-variation form's field grid. Two columns so a four-field identity block reads
   as one shape rather than a column of four, and one column when there is no room for two. */
.nds-addvar-axes { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 10px; margin-top: 6px; }
.nds-addvar-field { display: flex; flex-direction: column; gap: 4px; }


/* 🔴 The thumbnail's fit is the ROW KIND's job, not a CSS cap.
   A cap lived here briefly, written as `min(thumb, calc(var(--ag-row-height) - 4px))`. It was
   INERT and looked careful: `--ag-row-height` is the Theming API's own expression (it computed to
   42 while the rendered row was 28, because AG sets the real height through the `rowHeight` grid
   option in JS and nothing writes it back), so the min never bound. Measured by DS.1 and
   independently here.

   **An AG geometry CSS variable is a theme INPUT, not a readback of what the grid rendered.**
   Anything needing the real row height must read the rendered row or the grid option. The fix is
   `rows="media-line"` on the sheet — 36px, derived as thumb + 4 per tier so it cannot drift from
   the thumbnail it has to contain. */


/* ── AG rich select (the sheet's select editor) — DS parity, DS.1 2026-09-02 under PES.2's claim ──
   Measured against the DS `Listbox` on the same page: border colour and typography already matched;
   the shapes did not. Radii only here — they cannot move layout. The ROW HEIGHT (24 -> 36) is
   deliberately NOT set in CSS: `.ag-rich-select-list` is a VIRTUALISED viewport and AG positions its
   rows from a height it computes, so a CSS height desynchronises the offsets. It goes through the
   editor's `cellHeight` param (`IRichCellEditorParams`), which is AG.1's to set.
   The visual surface is `.ag-rich-select-list` (it also carries `.ag-virtual-list-viewport`);
   `.ag-popup` is a positioning container measuring 1728x0 — reading it reports no border/shadow. */
.nds-ag-nexus .ag-rich-select-list,
.ag-rich-select-list { border-radius: var(--nds-radius-xl); }
.ag-rich-select-row { border-radius: var(--nds-radius-md); }

/* ── GridSheetNote — the sheet's honest message in the footer strip (DS.1, v2 §6.2 r6 / §6.3,
   ruling #230; in PES.2's tree under their claim, disclosed). Sized for the 40px strip, not the
   page: the DS `Banner` is the page-scale callout and carries an 18px icon, title, description,
   action and a dismiss control. The KIND owns the glyph and the tone — never the bar.
   No dismiss rule exists here because the component cannot express one. */
/* 🔴 HEIGHT. This note occupies the footer strip's existing fixed band, and the whole reason the
   slot exists is that the band must never change height — a conditional band above the sheet moved
   the tab strip 148 → 179 and resized the grid under the operator. Measured 2026-09-01: the strip
   is 39.75px with 10px padding each side, so a note has ~19.8px of content box. `RefusalLine`'s
   first version used `padding: 3px 9px`, rendered 22.4px, and pushed the band to 43.4px — a
   component built to stop the sheet moving would have moved it, by 3.6px, on every refusal, and it
   rendered and read correctly the whole time. 12.5px ink at normal line-height is ~18.75px and
   clears it. Any change to font-size or padding here MUST be re-measured inside the strip, not
   against this element's own box. */
/* §14.1 — an `absent` reason, and the "not supplied" notice beside it. A reason is a SENTENCE in a
   40px bar: PES.3's first one laid out at 82 × 312px and pushed the band. One line, clipped, with
   the full text in `title`. `max-width` in ch so it scales with the type rather than a magic px. */
/* 🔴 `flex: none`. As `0 1 auto` this was the only shrinkable item in a bar with no slack, so on a
   full channel toolbar it collapsed to 18px — an ellipsis and nothing else (PES.3 measured it live).
   A reason nobody can read is the silence the `absent` mechanism exists to prevent, so the marker
   is unshrinkable and carries the control's NAME; the reason is in `title`/`aria-label`. */
.nds-grid-toolbar-absent {
  display: inline-flex; align-items: center; flex: none;
  max-width: 24ch; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  /* 🔴 The cursor is NOT changed on hover here. The question-mark hover cursor is banned
     permanently (Owner, 2026-08-20) and enforced at baseline 0 by `check-help-cursor.mjs` — which
     greps comments too, so this note deliberately does not spell the property out. The tooltip is
     the whole explanation channel. I wrote it in and the guard caught it. */
  font-size: 12.5px; height: 28px;
}
.nds-grid-toolbar-absent:focus-visible { outline: 2px solid var(--nds-primary); outline-offset: 1px; border-radius: var(--nds-radius-sm, 4px); }

/* §14.6 — the footer's HEIGHT never changes, only its content. The slot holds one line whatever
   occupies it (a refusal, the shortcut hint, the `?` alone, or nothing at all while the retired
   state is still being read), so the strip cannot move under an operator mid-edit. Without this the
   band collapsed when the slot emptied and the whole grid grew by a line. */
.nds-grid-sheet-note { display: inline-flex; align-items: center; gap: 6px; min-width: 0; font-size: 12.5px; min-height: 18px; }
.nds-grid-sheet-noteslot { display: inline-flex; align-items: center; gap: 8px; min-height: 18px; min-width: 0; }
/* The permanent way back to the shortcuts. Same type scale as the note it restores. */
/* 🔴 This control is the DS Button (#684) — `variant="quiet" size="xs"`. What is left here is ONLY
   the 18px square, which no Button size offers (`.nds-btn.icon.xs` is 23px), and the SELECTOR WEIGHT
   IS LOAD-BEARING. Measured on screen either side of the conversion, because the first attempt got
   this wrong and looked fine in the gate:
     - `.nds-btn.xs` is (0,2,0); the old bare `.nds-grid-sheet-help` was (0,1,0). The DS's
       `padding: 4px 9px` therefore beat `padding: 0` on WEIGHT, not on stylesheet order — an
       order-based reading of this collision is wrong even though order is the usual culprit here.
     - The declared `width: 18px` then lost a SECOND time, and not to any rule: a flex item's
       `min-width: auto` floors it at content + padding + border, so the button rendered 20px wide
       while `width` still computed as 18. Restoring the padding is what restores the width.
   `.nds-btn.xs.nds-grid-sheet-help` is (0,3,0) and wins outright, with no dependence on which
   stylesheet the bundler emits first.
   ⚠ The `.xs` here is COUPLED to `size="xs"` in MasterSheet.tsx. Change that prop and this whole
   block stops matching — silently, and the button grows to the DS's own geometry. */
.nds-btn.xs.nds-grid-sheet-help {
  display: inline-flex; align-items: center; justify-content: center;
  width: 18px; height: 18px; flex: none; padding: 0;
  border: 1px solid var(--nds-border); border-radius: var(--nds-radius-pill);
  background: none; color: var(--nds-text-2); font-size: 11px; font-weight: 600; cursor: pointer;
}
.nds-btn.xs.nds-grid-sheet-help:hover { background: var(--nds-surface-hover); color: var(--nds-text); border-color: var(--nds-border-strong); }
.nds-btn.xs.nds-grid-sheet-help:focus-visible { outline: 2px solid var(--nds-primary); outline-offset: 1px; }
.nds-grid-sheet-note-glyph { display: inline-flex; flex: 0 0 auto; }
.nds-grid-sheet-note-text { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
/* The count is the statement and never truncates — an operator must always be able to read THAT
   work is blocked, even when the example does not fit. The example is what gives way. */
.nds-grid-sheet-note-count { flex: 0 0 auto; font-weight: 600; }
.nds-grid-sheet-note-sep { flex: 0 0 auto; opacity: 0.55; }
.nds-grid-sheet-note-more { flex: 0 0 auto; color: var(--nds-text-2); }
/* Every ink here flips under .dark (verified: danger-text #9c2f2a → #ef9c93, warning-text #6d3f10 →
   #f0b46a, text-2 #5b6573 → #aab6c2). --nds-warning-border does NOT flip and is deliberately
   unused. Neither --nds-warning nor --nds-danger is named here, nor the --nds-note- or --nds-tonal-
   families: they are absent from both .dark blocks and would hold their light values on #18263b.
   (Written without a glob after those prefixes on purpose — a "*" immediately before a "/" ends the
   comment, which is how this rule shipped broken once already.) */
.nds-grid-sheet-note.offline { color: var(--nds-warning-text); }
.nds-grid-sheet-note.provenance { color: var(--nds-warning-text); }

/* 🔴 The cell tooltip's paragraphs must SURVIVE (#662). `composeCellTooltip` joins its lines with a
   blank line so a refusal and a length reading cannot read as one sentence — and AG's tooltip
   element collapses whitespace by default, so the join arrived on screen as
   "…edit to give this row its own value 9 of 700 characters (Amazon · IT)": one run of text saying
   two unrelated things. Measured on the sheet, not inferred; the composer was right and invisible.
   `pre-line` collapses runs of spaces but keeps newlines, which is exactly what the composer writes.
   `max-width` because a long refusal on a single line is its own kind of unreadable. */
.ag-tooltip.ag-cell-tooltip { white-space: pre-line; max-width: 42ch; }

.nds-grid-sheet-note.refusal { color: var(--nds-danger-text); }
.nds-grid-sheet-note.slow { color: var(--nds-text-2); }
.nds-grid-sheet-note.hint { color: var(--nds-text-2); }
/* The `refusal` kind renders a BUTTON, because a count of work must be reachable as a view. It
   still has to sit on the strip's text baseline like the other kinds, so the button chrome is
   stripped rather than restyled — no padding, no border, no background, nothing that could change
   the band's height. */
button.nds-grid-sheet-note { padding: 0; border: 0; background: none; font: inherit; font-size: 12.5px; cursor: pointer; }
button.nds-grid-sheet-note:hover .nds-grid-sheet-note-count { text-decoration: underline; }
/* `--nds-primary`, never `--nds-focus-ring`: that token is a BOX-SHADOW value, so
   `outline: 2px solid var(--nds-focus-ring)` expands to nonsense and is dropped whole, leaving a
   control with no focus indicator and no error anywhere. There is a live instance of exactly that
   at grid.css:304 (`--nds-grid-focus-ring` aliases it), filed to PES.2. */
button.nds-grid-sheet-note:focus-visible { outline: 2px solid var(--nds-primary); outline-offset: 2px; border-radius: var(--nds-radius-sm); }
/* No collapsible detail panel: this strip sits inside `.nds-gridcard`, which is `overflow: hidden`
   to round its corners, so an absolutely-positioned panel here is painted, invisible and
   un-hit-testable (reference_gridcard_clips_dropdowns). A detail surface must be portalled and
   fixed, which makes it the DS popover primitive's job, not a footer span's. */


/* A sheet's toolbar stays on its 40px band. Search absorbs available width. */
.nds-grid-sheet .nds-toolbar {
  padding: 0 6px;
  height: var(--nds-toolbar-h, 40px);
  min-height: var(--nds-toolbar-h, 40px);
  min-width: 0;
  flex: 0 0 var(--nds-toolbar-h, 40px);
  flex-wrap: nowrap;
  box-sizing: border-box;
  align-items: center;
  overflow-x: auto;
}
.nds-grid-sheet .nds-toolbar > * { max-width: 100%; flex-shrink: 0; }
.nds-grid-sheet .nds-toolbar > .cnt { white-space: nowrap; }
.nds-grid-sheet .nds-toolbar > .grow { display: none; }
.nds-grid-sheet .nds-toolbar > .nds-grid-search { flex: 1 1 180px; min-width: 80px; max-width: 340px; }
.nds-grid-sheet .nds-toolbar .nds-grid-search .nds-field { width: 100%; }
.nds-grid-sheet .nds-toolbar .nds-grid-views { min-width: 0; flex-wrap: nowrap; }
.nds-grid-sheet .nds-toolbar .nds-grid-views .nds-btn { white-space: nowrap; }
.nds-sheet-toolbar-actions {
  display: flex;
  flex-wrap: nowrap;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  margin-inline-start: auto;
  min-width: 0;
}
.nds-sheet-toolbar-actions > * { flex-shrink: 0; }
@media (max-width: 1279px) {
  .nds-grid-sheet .nds-toolbar { height: auto; flex-basis: auto; flex-wrap: wrap; padding-block: 6px; overflow-x: visible; }
  .nds-grid-sheet .nds-toolbar .nds-grid-views, .nds-grid-sheet .nds-sheet-toolbar-actions { flex-wrap: wrap; }
}
/* 🔴 The pill override that used to live here is GONE, and the reason it existed was wrong.
   I wrote that `.nds-pill` was oversized because an inline `<svg>` sat on the baseline and dragged
   the descender space with it. **That was reasoning, not a measurement** — I inferred a plausible
   mechanism from the numbers and stated it as the cause. DS.2 measured it: the app's reset declares
   `svg { display: block }`, so the icon took a LINE OF ITS OWN above the label. The tell was there
   and I did not look for it — a block-level child adds height and no width, and the pill measured
   43.75px wide with and without the icon.
   Fixed at the base (`.nds-pill { display: inline-flex; align-items: center; gap: 4px }`), so this
   band needs no override; the `caps` pill now passes `size="md"`, the size `Pill` documents for a
   toolbar. `sm` looked right only because, with an icon, it rendered TALLER than `md`. */
/* 🔴 The 40px band is bought by RE-SCOPING the shared slot height, not by overriding the field.
   `--nds-grid-toolbar-slot-h` (36px above) exists so the search field and the selection cluster
   that replaces it sit on ONE floor — the comment there records a measured half-pixel step when
   they disagreed. Setting the variable on the sheet keeps that invariant exactly (both halves still
   read the same number) and changes only what the number is here. Overriding `.nds-field`'s height
   directly would have hit 40px and quietly reintroduced the step on every selection toggle. */
.nds-grid-sheet { --nds-grid-toolbar-slot-h: 28px; }

/* ─────────────────────────────────────────────────────────────────────────────────────────────
   AG's popup layer, on the DS scale (AG.1, hub #232 · DS.1's ruling · DS.2's measurement).

   AG ships `.ag-popup-child { z-index: 5 }` in its own stylesheet — measured, at
   `ag-grid-community/styles/_css-content.scss:2771`. That 5 is exactly `--nds-z-sticky`, which puts
   every AG column menu, filter popup and rich-select list BELOW the rail (50) and the top bar (60).
   Nothing is visibly broken today only because AG's menus are short and bottom-anchored; the first
   taller menu near the rail would render underneath it.

   🔴 There is NO Theming API parameter for this. The ruling asked for `popupZIndex` "or whichever
   knob the theme exposes" — measured, AG 36.1 exposes `popupShadow` and no z-index param at all
   (grepped its own bundle for `*[zZ]Index*`: one internal hit, no theme key). So the DS token has to
   reach it through CSS, and this stylesheet is the one place permitted to address `.ag-*`.

   Deliberately UNSCOPED. The popup is portalled out of the grid wrapper to `popupParent`
   (`document.body`), so `.nds-ag-nexus .ag-popup-child` would match nothing — the same
   matches-nothing trap DS.1 hit with `.ag-rich-select .ag-virtual-list-viewport`. Every AG popup in
   the app moves together, which is the point: one popup layer, not two conventions.
   ───────────────────────────────────────────────────────────────────────────────────────────── */
.ag-popup-child {
  z-index: var(--nds-z-popover, 1450);
}

/* ── AM.1 §A.3 — list and measure cells + their popup editors (2026-09-05) ─────────────────────────
   Tokens: every one below is used elsewhere in this sheet (`--nds-surface`, `--nds-text`,
   `--nds-border`, `--nds-radius-md`, `--nds-shadow-pop`, `--nds-space-1/2`, `--nds-grid-muted-fg`).
   The chip inside a 36px row is COMPACT: the DS token's 3px/9px padding would make it 24px tall
   against the cell's 18px content box (`reference_clip_rect_is_the_padding_box`). */
.nds-cell-list { display: inline-flex; align-items: center; gap: 4px; min-width: 0; max-width: 100%; overflow: hidden; }
/* 🔴 The list's value chips are `.nds-cell-listchip`, NEVER `.nds-cell-chip` (Owner, 2026-09-05: "N."
   where "Non applicabile" should read). `.nds-cell-chip` is the 20×20 identity/targeting BADGE above;
   its fixed width squeezed every list value to one letter and its ellipsis. A shared class name is a
   shared size — the list token takes its width from its text and its HEIGHT from this rule alone. */
.nds-cell-list .nds-token { flex: 0 1 auto; min-width: 0; max-width: 160px; height: 20px; }
.nds-cell-list .nds-token > .t { padding: 0 6px; line-height: 16px; font-size: 12px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; display: block; }
.nds-cell-list-more { flex: none; font-size: 11px; color: var(--nds-grid-muted-fg); }
.nds-cell-measure { display: inline-flex; align-items: baseline; gap: 4px; min-width: 0; }
.nds-cell-measure .u { font-size: 12px; color: var(--nds-grid-muted-fg); }
.nds-list-editor, .nds-measure-editor {
  display: flex; flex-direction: column; gap: var(--nds-space-1);
  padding: var(--nds-space-2); box-sizing: border-box; min-width: 0;
  background: var(--nds-surface); color: var(--nds-text);
  border: 1px solid var(--nds-border); border-radius: var(--nds-radius-md);
  box-shadow: var(--nds-shadow-pop);
}
.nds-list-editor { overflow: auto; }
.nds-list-editor-count { font-size: 11px; color: var(--nds-grid-muted-fg); }
.nds-measure-editor .nds-field { width: 100%; }


/* Formula editors share one compact anatomy: field, tools, suggestions, result, fixed actions.
   Scroll only the body and never flex-shrink its children into overlapping rectangles. */
.nds-formula-editor { max-height: min(440px, 75dvh); overflow: hidden; }
.nds-formula-body {
  display: flex; flex-direction: column; gap: var(--nds-space-8);
  min-height: 0; overflow: auto; padding: var(--nds-space-10);
}
.nds-formula-body > * { flex-shrink: 0; min-width: 0; }
.nds-formula-help {
  font-size: var(--nds-font-size-sm); color: var(--nds-text);
  line-height: 1.5; overflow-wrap: anywhere;
}
.nds-formula-help code { font-family: var(--nds-font-mono); }
.nds-formula-actions {
  display: flex; flex: none; align-items: center; justify-content: flex-end; flex-wrap: wrap;
  gap: var(--nds-space-8); padding: var(--nds-space-8) var(--nds-space-10);
  border-top: 1px solid var(--nds-border-subtle);
}
.nds-formula-actions > span { flex: 1 1 80px; color: var(--nds-text); font-size: var(--nds-font-size-xs); }
.nds-formula-composer > .nds-formula-actions { padding-inline: 0; }
.nds-formula-editor .nds-formula-preview,
.nds-formula-composer .nds-formula-preview {
  font-family: var(--nds-font-sans); font-size: var(--nds-font-size-sm); line-height: 1.5;
  white-space: normal; overflow-wrap: anywhere; border: 0; padding: 0;
}
.nds-formula-editor .nds-formula-hint, .nds-formula-composer .nds-formula-hint { flex-wrap: wrap; }
@media (forced-colors: active) {
  .nds-formula-editor .nds-field input.nds-formula-input.highlighted { color: FieldText; }
  .nds-formula-overlay { display: none; }
}

/* Shared formula assistance: grid, drawer, and bulk editor. */
.nds-formula-composer, .nds-formula-guidance { display: flex; flex-direction: column; gap: var(--nds-space-8); min-width: 0; }
.nds-formula-composer > *, .nds-formula-guidance > * { flex-shrink: 0; }
.nds-formula-guidance { color: var(--nds-text); font-size: var(--nds-font-size-sm); }
.nds-formula-tools { display: flex; flex-wrap: wrap; align-items: center; gap: var(--nds-space-4); }
.nds-formula-tools .nds-field { flex: 1; min-width: 100px; }
.nds-formula-help-panel {
  display: flex; flex-direction: column; gap: var(--nds-space-6); padding: var(--nds-space-10);
  background: var(--nds-surface-sunken); border-radius: var(--nds-radius-md); line-height: 1.5;
  overflow-wrap: anywhere;
}
.nds-formula-help-panel code { font-family: var(--nds-font-mono); }
.nds-formula-text-builder { gap: var(--nds-space-8); }
.nds-readable .nds-fx-ident { color: var(--nds-text); font-weight: 600; }

/* ── ProjectionCell (VP.5, Variants page §3.3) ──────────────────────────────────────────────
   One variant row × one channel coordinate: [tick 15px] [dot 7px] word … mono detail · note.
   Numbers read off the approved canvas (artboard 1): gap 6, dot 7px, hollow = a 1.5px inset
   ring rather than a fill, detail mono 12px, note 11px muted. Measured light / dark: the word
   15.48 / 12.73, a muted word 5.32 / 7.38, the success dot 3.30 / 4.62, the danger dot
   3.91 / 3.89, the hollow ring 3.62 / 4.98 — AA text and AA non-text in both themes. Every
   colour is a semantic token that `.dark` already redefines, so there is no alias to restate. */
.nds-projcell {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  min-width: 0;
  color: var(--nds-text);
}
/* A row that is not participating on this coordinate reads quiet — the WORD goes muted, never
   the tick, which is the one live control on an excluded row (§4.3). */
.nds-projcell.muted .nds-projcell-word {
  color: var(--nds-text-muted);
}
.nds-projcell-check {
  flex: none;
  gap: 0;
}
/* HELD, not disabled: the input keeps its focus and its click so it can deliver the reason in
   `title` (`scripts/check-silent-disabled.mjs`). 0.62 is `.nds-btn[aria-disabled]`'s own hold,
   so a refusing tick and a refusing button look equally refused. */
.nds-projcell.held .nds-projcell-check,
.nds-projcell.held .nds-projcell-check input {
  opacity: 0.62;
  cursor: default;
}
.nds-projcell-dot {
  width: 7px;
  height: 7px;
  border-radius: var(--nds-radius-round);
  flex: none;
}
.nds-projcell-dot.solid[data-tone='success'] { background: var(--nds-success); }
.nds-projcell-dot.solid[data-tone='warning'] { background: var(--nds-warning); }
.nds-projcell-dot.solid[data-tone='danger'] { background: var(--nds-danger); }
.nds-projcell-dot.solid[data-tone='info'] { background: var(--nds-primary); }
.nds-projcell-dot.solid[data-tone='neutral'] { background: var(--nds-text-3); }
/* A ring, not a pale fill: "included but not published" is a state in progress, and a filled
   grey dot would read as a fifth status colour instead of the absence of one. */
.nds-projcell-dot.hollow { box-shadow: inset 0 0 0 1.5px var(--nds-text-3); }
.nds-projcell-word {
  flex-shrink: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.nds-projcell-detail {
  font-family: var(--nds-font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-size: var(--nds-font-size-sm);
  overflow: hidden;
  text-overflow: ellipsis;
}
/* The right-hand slot belongs to whichever of the two is last: a variant row carries the mono id
   alone and it sits right; a parent row carries the id AND a note, and then the id leads while
   the note takes the edge (the canvas's `Parent ASIN`, `1 listing`). */
.nds-projcell-detail:last-child,
.nds-projcell-note {
  margin-left: auto;
}
.nds-projcell-note {
  flex: none;
  font-size: var(--nds-font-size-xs);
  color: var(--nds-text-muted);
}

/* ── a QUIET row (VP.5, Variants page §4.3) ─────────────────────────────────────────────────
   "Excluded rows render their mapped values muted; the checkbox is the only live control on
   them." A row state, so it belongs to the engine: a page that reaches for `.ag-cell` from its
   own stylesheet fails `scripts/check-ag-grid-import-boundary.mjs`, and the rule for grid chrome
   is that it lives here (feedback_grid_chrome_lives_in_the_engine). Apply with AG's
   `rowClassRules: { 'nds-row-is-quiet': (p) => …excluded… }`.

   A cell opts OUT with `cellClass: 'nds-cell-full-strength'` — the identity band, which names the
   row and must stay readable, and any column carrying the control that undoes the state. Opting
   out by class rather than by `:not(.nds-cell-identity)`, because that class sits on a DIV INSIDE
   the cell: every `.ag-cell` satisfies `:not(.nds-cell-identity)` and the identity would be muted
   with everything else. */
.nds-ag-wrap .ag-row.nds-row-is-quiet .ag-cell {
  color: var(--nds-grid-muted-fg);
}
.nds-ag-wrap .ag-row.nds-row-is-quiet .ag-cell.nds-cell-full-strength {
  color: var(--nds-grid-cell-fg);
}
/* An include that has been painted optimistically and has not landed. It is also HELD (a second
   click cannot race the first write), so the hold above already dims the tick; this marks the
   whole cell so a caller can find it, and `aria-busy` says the same thing to a screen reader. */
.nds-projcell.busy {
  cursor: progress;
}

.nds-grid-sheet .nds-toolbar { container-type: inline-size; container-name: nds-sheet-toolbar; }
@container nds-sheet-toolbar (max-width: 900px) {
  .nds-toolbar .nds-fchip-full { display: none; }
  .nds-fchip .nds-fchip-compact { display: inline; }
}

/* Formula-aware value mode retains the sheet long-text sizing contract. */
.ag-popup-editor .nds-formula-fieldwrap textarea { resize: none; overflow-y: auto; }

apps/factory/src/design-system/grid/them.content:
/**
 * The engine's own stylesheet. Web-only, and deliberately TINY.
 *
 * Everything that can be said as a theme param is said in `theme.ts`, not here. This file only
 * carries what the Theming API has no param for: per-column alignment classes, the no-rows
 * overlay, the cell's line box, the child-row tint and rail, the column-group strip, the density
 * padding knob, and the DS-built column filters. Every colour and number in here is a
 * `--nds-grid-*` token from `tokens/grid.ts` — if a rule starts naming a ramp step or a bare
 * pixel, it belongs in the token table instead. Two places to change a row height is how the
 * five-engine mess started.
 *
 * Not registered in `design-system/styles/`, and not imported by `layout.tsx`: it is imported by
 * the engine component, so it only ships on routes that actually mount a grid. It has no
 * counterpart in apps/factory (factory renders no AG grid) — the grid TOKENS are mirrored there,
 * this sheet is not.
 */

/* `.nds-wsgrid th.num, .nds-wsgrid td.num { text-align: right }` — plus the tabular figures the
   DS learned to set the hard way: a money column that loses proportional-digit alignment is the
   one defect a grid cannot afford. */
.nds-ag-num {
  justify-content: flex-end;
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.nds-ag-head-num .ag-header-cell-label {
  justify-content: flex-end;
}

.nds-ag-ed {
  justify-content: flex-start;
  text-align: left;
}

.nds-ag-ctr {
  justify-content: center;
  text-align: center;
}

/* The identity column: AG already centres its cell content, so only the gap and the ellipsis
   are restated. */
.nds-ag-cell-first {
  gap: 7px;
}

.nds-ag-cell-first > * {
  min-width: 0;
}

/* The empty state. SGX parity: the sentence must WRAP. The hand-rolled grid shipped this bug to
   prod — a long empty state painted straight out of its cell and under the frozen column —
   because the empty cell inherited `white-space: nowrap`. AG Grid's overlay does not inherit that,
   but the wrap is stated anyway so the fix cannot be lost a second time. */
.nds-ag-empty {
  display: block;
  max-width: 320px;
  padding: 28px;
  color: var(--nds-grid-empty-fg);
  text-align: center;
  white-space: normal;
}

/* AG.3 — the bulk-action bay, shown only while rows are selected. Geometry only, deliberately:
   every control inside is the caller's and is already a DS primitive. */
.nds-ag-selbar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  padding: 8px 0;
}

/* A row that opens something must look like it does. Only the cursor: the hover tint is a theme
   param and lives in theme.ts. */
.nds-ag-clickable {
  cursor: pointer;
}

/* AG.3 — the row rule.
 *
 * `theme.ts` asks for this with the `rowBorder` param and AG Grid 36.1.0 emits NOTHING for it:
 * measured, `--ag-row-border-color` is empty in both the object form and the `true` form, and
 * rows render `1px solid rgba(0, 0, 0, 0)` — a rule that is present, sized, and invisible.
 *
 * AG's own base CSS reads a SHORTHAND: `border-bottom: var(--ag-row-border)`, applied to the cell
 * CONTAINERS (`.ag-grid-scrolling-cells`, `.ag-grid-pinned-*-cells`), not to `.ag-cell`. Setting
 * that one variable is therefore not a hand-rolled border — it is supplying the value AG is
 * already asking for, and it stays a token, so dark mode still costs nothing. */
.nds-ag-wrap {
  --ag-row-border: 1px solid var(--nds-grid-row-rule);
}

/* PN.1 — the cell is a flex row with a NORMAL line box, like the DS `td` it replaces.
 *
 * AG sets `line-height: calc(row-height − 3px)` on every cell so a single line of plain text
 * centres itself. Every renderer this product puts in a cell inherits that: a two-line product
 * cell became 82px of content inside a 43px row (measured — thumbnail pushed 22px down and
 * clipped 19px off the bottom), and pills, tag chips and channel labels each sat on a 40px line
 * box, so nothing shared a vertical centre. The Theming API has no param for this, which is the
 * one condition under which a rule belongs in this file.
 *
 * Centring is done the way the DS grid does it — the cell is the flex container — so a renderer
 * needs no knowledge of the row height to sit in the middle of it. */
.nds-ag-wrap .ag-cell,
.nds-ag-wrap .ag-cell-value {
  line-height: normal;
}

.nds-ag-wrap .ag-cell {
  display: flex;
  align-items: center;
}

/* The group cell (the tree column) wraps its chevron and value in `.ag-cell-wrapper`; give the
   value the remaining width so the product cell's ellipsis has a box to work in. */
.nds-ag-wrap .ag-cell .ag-cell-wrapper {
  align-items: center;
  width: 100%;
  min-width: 0;
}

.nds-ag-wrap .ag-cell .ag-group-value {
  flex: 1 1 auto;
  min-width: 0;
}

/* PN.1 — DS tooltips inside cells.
 *
 * The DS `Tooltip` is CSS-only: an absolutely positioned bubble that pops above its trigger on
 * hover, INSIDE the trigger's box. AG clips every cell (`overflow: hidden`) so the bubble was cut
 * at the cell's top edge — measured on the Channels column, and worse at Cozy/Compact where the
 * row is shorter than the bubble. Unclipping every cell would let long plain values spill into
 * their neighbours, so only cells that actually contain a DS tooltip are opened up; everything
 * else keeps AG's ellipsis. `:has()` is what makes that precise.
 *
 * What this cannot fix: a bubble on the FIRST row pops into the scroll viewport's clip, and no
 * cell rule reaches that. That is the case the portal-rendered `InfoTip` exists for (W6). */
.nds-ag-wrap .ag-cell:has(.nds-tooltip),
.nds-ag-wrap .ag-cell:has(.nds-tooltip) .ag-cell-value,
.nds-ag-wrap .ag-cell:has(.nds-tooltip) .ag-cell-wrapper {
  overflow: visible;
}

/* AG rows are absolutely positioned siblings whose DOM order is not their visual order, so a
   bubble rising out of one row can paint BEHIND the row above it. The hovered row wins. */
.nds-ag-wrap .ag-row:hover,
.nds-ag-wrap .ag-row.ag-row-focus {
  z-index: 1;
}

/* PN.1 — `flatTree` (see NexusGrid): the DS says "child" with a tint and a 3px rail, never with an
   indent. A page whose children must line up under their parent owns the tree column's cell
   (`autoGroupColumnDef.cellRenderer`) — AG then renders no chevron slot and no level step, and
   nothing here has to undo them. A full-width row below the top level (the family footer) takes
   the same tint. */
.nds-ag-flat-tree .ag-row:not(.ag-row-level-0) {
  background-color: var(--nds-grid-child-bg);
}

/* On the ROW, not the first cell: a cell is 1px shorter than its row, which left a gap in the
   rail at every row boundary. The DS drew it on the `td`, whose box includes the row rule, so the
   rail ran continuously down the family — the row is AG's equivalent box.
 *
 * ...and it has to PAINT above the cells, which is why this is a pseudo-element and no longer the
 * `inset` box-shadow it was. AG draws the row rule as `border-bottom: var(--ag-row-border)` on
 * `.ag-grid-scrolling-cells` — a `position: relative; z-index: 0` child that spans the row's full
 * height from `left: 0`. A positioned descendant paints ABOVE its parent's box-shadow, so that
 * 1px of the LIGHTER `--nds-grid-row-rule` overwrote the rail's bottom pixel at every boundary
 * and broke the stroke into per-row segments. Measured on prod: consecutive child rows are exactly
 * contiguous (…867.8 | 867.8…) with no border on the row itself — the row BOX was never the
 * problem, the paint ORDER was. The row is `position: absolute`, so `::after` anchors to it. */
.nds-ag-flat-tree .ag-row:not(.ag-row-level-0):not(.ag-full-width-row)::after {
  content: '';
  position: absolute;
  inset-block: 0;
  left: 0;
  width: 3px;
  background-color: var(--nds-grid-child-rail);
  z-index: 1;
  pointer-events: none;
}

.nds-ag-flat-tree .ag-row:not(.ag-row-level-0).ag-row-hover {
  background-color: var(--nds-grid-child-hover-bg);
}

/* PN.1 — a grid inside a `.nds-gridcard` does not draw its own frame.
 *
 * The theme's `wrapperBorder` / `wrapperBorderRadius` frame a STANDALONE grid. /products/next
 * puts the grid inside the DS grid card, which already draws the same 1px border and radius —
 * measured: two identical borders one pixel apart, and a rounded top corner on the header inside
 * a card whose own corner is where the rounding belongs. AG sets these variables on its root
 * wrapper, so the override has to land on that element, not on an ancestor. */
.nds-gridcard .nds-ag-wrap .ag-root-wrapper {
  --ag-wrapper-border: none;
  --ag-wrapper-border-radius: 0;
  border: none;
  border-radius: 0;
}

/* IE.4 — a column-group row is a slim STRIP above the header, not a second header.
 *
 * AG draws group headers in the header's own style, so a grid with groups showed two header rows
 * of full height (93px at the Spacious tier) — against the products page's single 46px header
 * over 85px rows. The Owner: the group labels belong "in the strip above the actual header".
 * Every NexusGrid with column groups gets this band: the height is the grid's `groupHeaderHeight`
 * (`gridGeometry.stripH`), the ground is the sunken surface, labels are the DS eyebrow, and the
 * partitions run the strip's FULL height so it reads as parts of one band rather than as header
 * cells. */
.nds-ag-nexus .ag-header-row-group {
  background: var(--nds-grid-strip-bg);
  box-shadow: inset 0 -1px 0 var(--nds-grid-strip-rule);
}
.nds-ag-nexus .ag-header-group-cell {
  --ag-header-column-border-height: 100%;
  font-size: var(--nds-grid-strip-size);
  font-weight: var(--nds-grid-strip-weight);
  letter-spacing: var(--nds-grid-strip-tracking);
  text-transform: uppercase;
  color: var(--nds-grid-strip-fg);
}
.nds-ag-nexus .ag-header-group-cell .ag-header-group-cell-label {
  justify-content: center;
}

/* PN.1 — compact density tightens the cell's horizontal padding too. The theme sets cell padding
   once, so the density-specific value lands here, keyed off the wrapper's `data-density`. AG sets
   this variable on its root wrapper, hence the selector. (AG renders the padding one pixel under
   the variable — measured 13 at 14, 9 at 10 — so the token states what the DS grid measured +1.) */
.nds-ag-wrap[data-density='compact'] .ag-root-wrapper {
  --ag-cell-horizontal-padding: var(--nds-grid-cell-pad-x-compact);
}

/* ── Column filters: DS-built components inside AG's column menu ───────────────────────────
   The list reuses the MultiSelect option rows (`.nds-ms-opt`) and its search box, so a filter in
   the header menu reads exactly like the same filter in the accordion. These are DS controls, so
   they speak the DS control tokens, not the grid's. */
.nds-ag-filter {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 240px;
  max-width: 320px;
  padding: 8px;
  font-size: 13px;
  color: var(--nds-text);
}
.nds-ag-filter-list {
  display: flex;
  flex-direction: column;
  max-height: 260px;
  overflow-y: auto;
}
.nds-ag-filter-range {
  display: flex;
  gap: 8px;
  align-items: end;
}
.nds-ag-filter-range label {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 4px;
  font-size: 12px;
  color: var(--nds-text-2);
}
.nds-ag-filter-foot {
  display: flex;
  justify-content: flex-end;
  padding-top: 4px;
  border-top: 1px solid var(--nds-border);
}

/* PES.2 — the FLOATING filter row (`filters/gridFloatingFilters.tsx`). It lives INSIDE the header
   block, so it must not add its own frame: AG already draws the row's bottom rule, and a second
   border here reads as a doubled header. The controls are shrunk to the row, not the row grown to
   the controls — the sheet's whole argument is rows on screen. */
.nds-ag-wrap .ag-floating-filter { padding: 0 var(--nds-grid-cell-pad-x-compact); }
.nds-ag-floating { display: flex; align-items: center; gap: 4px; width: 100%; }
.nds-ag-floating-range { gap: 4px; }
/* The DS Input at floating-filter size. Height is the row minus its padding, so a density change
   moves it with everything else instead of leaving a control floating in a taller box. */
.nds-ag-floating .nds-ag-floating-input,
.nds-ag-floating .nds-ag-floating-input input {
  height: 22px;
  min-height: 22px;
  font-size: 11.5px;
  width: 100%;
  min-width: 0;
}
.nds-ag-floating-range .nds-ag-floating-input { flex: 1 1 0; }
/* The set filter's read-out: a control that opens the real list. Styled as a quiet field so it
   reads as the same kind of thing as the inputs beside it, and marked when a filter is on —
   the count is the mark, not the colour. */
.nds-ag-floating-set {
  width: 100%; height: 22px; padding: 0 6px; text-align: left; cursor: pointer;
  font: inherit; font-size: 11.5px; color: var(--nds-grid-muted-fg);
  background: var(--nds-surface); border: 1px solid var(--nds-border);
  border-radius: var(--nds-grid-radius);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.nds-ag-floating-set:hover { border-color: var(--nds-border-strong); }
/* 🔴 `box-shadow`, NOT `outline`. `--nds-grid-focus-ring` aliases `--nds-focus-ring`, which is a
   box-SHADOW value (`0 0 0 2px rgb(… / .12)`) — so `outline: 2px solid var(…)` expanded to
   `outline: 2px solid 0 0 0 2px rgb(…)`, invalid, and the whole declaration was dropped. Measured
   by DS.1 with a positive control: `outlineStyle: none` AND `boxShadow: none` here, while a
   `2px solid red` control on the same probe painted correctly — so the nothing was the page, not a
   blind instrument.

   **This was an accessibility defect, not a cosmetic one**: a keyboard user got no focus indicator
   on this control at all, silently, with no error anywhere.

   The tell worth keeping: the SAME token is used in two properties in this file — dead here, correct
   at `.nds-cell-expand` below — and the working one sitting 60 lines away is exactly what made the
   dead one look verified. A token whose name does not say which property it belongs to will be used
   in the wrong one eventually. */
.nds-ag-floating-set:focus-visible { outline: 2px solid var(--nds-primary); outline-offset: -1px; }
/* `.nds-cell-expand:focus-visible` below carried the SAME weakness in its milder form — it painted,
   but only a 12%-alpha shadow, measured at 1.17:1. FIXED below (DS.1 ruling #296), after DS.1
   enumerated the token and found 9 of 22 rules using that shadow as their ONLY focus signal. Kept
   here as the record of why it was flagged and not silently assumed correct: it was scoped OUT of
   the defect above deliberately, so that it could not be read as verified by proximity — which is
   the exact mistake that hid the dead rule above. */
.nds-ag-floating-set-on { color: var(--nds-text); border-color: var(--nds-grid-accent); font-weight: var(--nds-font-weight-semibold); }

/* ══ GDS cell library (`../renderers`, `../editors`) ══════════════════════════════════════════
   Geometry lifted verbatim from /products/next's page stylesheet (measured there); colours are the
   grid tokens. A page composes these cells; it does not restyle them. */

/* the dash — muted; the title (a measured zero) is on the element, the colour is here */
.nds-cell-empty { color: var(--nds-grid-muted-fg); }
.nds-cell-muted { color: var(--nds-grid-muted-fg); }
.nds-cell-strong { font-weight: var(--nds-font-weight-semibold); }
.nds-cell-date { font-size: var(--nds-font-size-sm); white-space: nowrap; }

/* identity: leading (expander) · thumb · meta (title row + sub-line) */
.nds-cell-identity { display: flex; align-items: center; gap: 11px; min-width: 0; }
.nds-cell-identity-meta { min-width: 0; }
.nds-cell-title-row { display: flex; align-items: center; gap: 6px; min-width: 0; max-width: 330px; }
.nds-cell-title-link {
  font-weight: var(--nds-font-weight-semibold); font-size: var(--nds-font-size-base); color: var(--nds-primary);
  text-decoration: none; cursor: pointer; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; min-width: 0;
}
.nds-cell-title-link:hover { text-decoration: underline; }
/* the hover-revealed "Open in new tab" pill (the ads manager's `.h10-open`, tokenised) */
.nds-cell-open {
  display: none; align-items: center; gap: 4px; font-size: var(--nds-font-size-xs); font-weight: var(--nds-font-weight-semibold);
  color: var(--nds-text-inverse); background: var(--nds-primary); border-radius: var(--nds-radius-sm); padding: 3px 8px;
  text-decoration: none; flex-shrink: 0; white-space: nowrap; line-height: 1.2;
}
.nds-cell-identity:hover .nds-cell-open, .nds-cell-title-row:hover .nds-cell-open { display: inline-flex; }
.nds-cell-open:hover { background: var(--nds-primary-hover); }
.nds-cell-sub { font-size: var(--nds-font-size-xs); color: var(--nds-grid-muted-fg); margin-top: 2px; display: flex; gap: 8px; align-items: center; flex-wrap: nowrap; }
/* `--nds-font-mono` exists as of 2026-09-01 and resolves to JetBrains Mono, which the app already
   loads; this line inlined the OS stack and so every SKU in the sheet rendered in the wrong face.
   The fallback is kept deliberately — it keeps the cell readable if the token is ever removed, and
   it is the reason no guard caught this (`check-css-token-definitions.mjs` only flags a `var()`
   WITHOUT one, so the careful call sites bought the silence). DS.1's DS1-1. */
.nds-cell-sku { font-family: var(--nds-font-mono, ui-monospace, SFMono-Regular, Menlo, monospace); font-size: var(--nds-font-size-xs); color: var(--nds-grid-muted-fg); }

/* ══ the identity band (`renderers/IdentityBand.tsx`) ═════════════════════════════════════════
   ONE row shape for master and every channel scope (#710). Content-derived width: the band is
   `width: max-content` inside its cell so the column can be sized FROM it, which is the thing three
   separate pinned columns could not do — each was sized on its own and the chip ended up overlapping
   the thumbnail (#709a).
   🔴 `min-width: 0` on the text block is load-bearing: without it the flex item's automatic minimum
   is its content width, the SKU refuses to shrink, and the trailing pill is pushed out of the cell —
   the same floor that held the `?` button 2px wide (#684) and the media tile's picture at 80px
   (#688). The SKU truncates; the state pill never moves. */
.nds-identity-band {
  display: flex; align-items: center; gap: 8px; width: 100%; min-width: 0;
}
/* The picture and the mark about it travel together, so the mark cannot be separated from the
   photograph it describes by a later layout change. */
.nds-identity-band-pic { display: inline-flex; align-items: center; gap: 4px; flex: none; }
.nds-identity-band-text {
  display: flex; flex-direction: column; justify-content: center; gap: 1px; min-width: 0; flex: 1 1 auto;
}
.nds-identity-band-sku {
  font-family: var(--nds-font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-size: var(--nds-font-size-xs); color: var(--nds-text-strong); font-weight: 600;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap; min-width: 0;
}
/* The second line is context, not the key: quieter, and it is the one that gives way first. */
.nds-identity-band-sub {
  font-size: var(--nds-font-size-xs); color: var(--nds-text-2); line-height: 1.25;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap; min-width: 0;
}
/* Pinned right and never shrinking — a readiness reading that truncates is worse than absent. */
.nds-identity-band-trail { display: inline-flex; align-items: center; gap: 6px; flex: none; margin-left: auto; }

.nds-readypill { display: inline-flex; align-items: center; gap: 6px; flex: none; }
.nds-readypill-track {
  width: 34px; height: 4px; flex: none; border-radius: var(--nds-radius-pill);
  background: var(--nds-surface-sunken); overflow: hidden;
}
.nds-readypill-fill { display: block; height: 100%; background: var(--nds-grid-muted-fg); }
/* 🔴 A FIXED slot, not a shrink-to-fit one (#739). The band's width is derived from its fixed
   slots, so a pill that is narrower at "9%" than at "100%" gives the same family a different derived
   width on two scopes — which is the one thing #710 exists to prevent. `tabular-nums` makes every
   digit the same width; `min-width` makes every VALUE the same width. Sized for the widest string
   the pill can hold ("100%") and right-aligned so the digits line up down a column. */
.nds-readypill-num {
  font-size: var(--nds-font-size-xs); font-variant-numeric: tabular-nums; color: var(--nds-text-2);
  flex: none; min-width: 30px; text-align: right;
}
/* 🔴 Tone is carried by the NUMBER as well as the bar. A bar-only signal fails anyone who cannot
   separate the two fills, and this is a readiness reading an operator acts on.
   🔴 The tone names are the READINESS vocabulary, not `full`/`low` — they come from
   `readinessMeta(state).tone`, never from the percentage (#43/#727). A pill at 84% in state
   `errors` is DANGER; a pill at 40% in state `ready` is not a warning. */
.nds-readypill-success .nds-readypill-fill { background: var(--nds-success); }
.nds-readypill-success .nds-readypill-num { color: var(--nds-text-strong); font-weight: 600; }
.nds-readypill-warning .nds-readypill-fill { background: var(--nds-warning); }
.nds-readypill-warning .nds-readypill-num { color: var(--nds-warning-text); }
.nds-readypill-danger .nds-readypill-fill { background: var(--nds-danger); }
.nds-readypill-danger .nds-readypill-num { color: var(--nds-danger-text); }
.nds-readypill-info .nds-readypill-fill { background: var(--nds-info-strong); }

/* the 20×20 chips beside a name — targeting A/M (filled), programme SP/SB/SD (outlined), an accent */
.nds-cell-chip {
  display: inline-flex; align-items: center; justify-content: center; flex: none; box-sizing: border-box;
  width: 20px; height: 20px; padding: 0; border-radius: var(--nds-radius-sm); line-height: 1; font-weight: 800;
  font-size: 11px; color: var(--nds-text-inverse);
}
.nds-cell-chip-auto { background: var(--nds-targeting-auto); }
.nds-cell-chip-manual { background: var(--nds-targeting-manual); }
.nds-cell-chip-accent { background: var(--nds-rail-text); }
.nds-cell-chip-program { font-size: 9px; letter-spacing: -0.3px; color: var(--nds-grid-muted-fg); background: var(--nds-grid-bg); border: 1px solid var(--nds-grid-frame); }
.nds-cell-chip-neutral { color: var(--nds-text-2); background: var(--nds-surface-sunken); }
/* Both containers on purpose: `.nds-cell-identity` is the older identity cell (products/next, the
   channel's own rows) and `.nds-identity-band` is the band (#710). The rules below were written for
   the first and silently stopped applying when master moved to the second — C lost its pill and the
   chip overlapped the thumbnail again, inside one build. A scoped rule is only as good as the list
   of scopes it names.
   a chip's tooltip wrapper must not add a line box of its own — nor SHRINK below the chip it wraps.
   🔴 `flex: none` is the half that was missing (#709a): at the default `flex: 0 1 auto` this wrapper
   was squeezed to **4px** while the chip inside went on painting at 20px, so the P chip overlapped
   the thumbnail by 5px and the Owner saw a picture with no parent/child pill. Nothing declared a
   width for the chip to lose — it lost one to flex-shrink, the same automatic-sizing family as the
   `?` button's `min-width: auto` floor (#684). Read the USED size, never the declared one. */
.nds-cell-identity .h10-tipwrap,
.nds-identity-band .h10-tipwrap { display: inline-flex; align-items: center; line-height: 0; flex: none; }

/* 🔴 THE IDENTITY ROLE PILL (#709a, Owner 15:53: "the chip is still dropped slightly, and we need to
   fix it and make it a bit wider"). Scoped to the identity cell ON PURPOSE: `.nds-cell-chip` is
   shared with the Ad Manager's targeting (A/M) and programme (SP/SB/SD) chips, and widening the base
   would resize those surfaces without anyone asking. Here it becomes a real pill — content width
   with horizontal padding, a 20px floor so a single character is still a pill and not a letter —
   and `align-self: center` puts it on the thumbnail's centre line rather than the flex line's
   baseline, which is what "dropped slightly" was.
   `neutral` (the C of a child row) also gains a border: on `--nds-surface-sunken` against a white
   row its fill is nearly invisible, which is why C read as a bare grey glyph while P read as a chip.
   One component, one size, two tones — the Owner's "P and C the same pill". */
.nds-cell-identity .nds-cell-chip,
.nds-identity-band .nds-cell-chip {
  width: auto; min-width: 24px; padding: 0 6px; align-self: center; border-radius: var(--nds-radius-sm);
  /* 🔴 A TRANSPARENT border on every tone, not just the bordered one. Measured: with the border on
     `neutral` alone, C came out 22.2px and P 20px — one pill, two sizes, which is the inconsistency
     the Owner would see before anyone measured it. `width: auto` puts a border OUTSIDE the padding
     box whatever `box-sizing` says, so the only way both tones share a size is for both to carry the
     same border and for `min-width` to sit above their content width. */
  border: 1px solid transparent;
}
.nds-cell-identity .nds-cell-chip-neutral,
.nds-identity-band .nds-cell-chip-neutral { border-color: var(--nds-grid-frame); }

/* the 20px expander and the slot that keeps a leaf aligned under its siblings */
.nds-cell-expand {
  width: 20px; height: 20px; flex: none; display: inline-flex; align-items: center; justify-content: center;
  border-radius: var(--nds-radius-pill); border: none; background: none; color: var(--nds-text-3); cursor: pointer; padding: 0;
  transition: background 0.1s ease, color 0.1s ease;
}
.nds-cell-expand:hover { background: var(--nds-surface-hover); color: var(--nds-grid-cell-fg); }
/* 1.17:1 as the only focus signal is not a focus indicator — see the note at `.nds-ag-floating-set`
   above for how this rule came to be flagged, and why `outline` is written literally here rather
   than through `--nds-grid-focus-ring` (that token is a box-SHADOW value).

   `outline-offset` is NEGATIVE, like its sibling: AG clips every cell with `overflow: hidden` (the
   same fact that cut the hover bubble at `:131`), so an outward ring on a 20px control sitting at a
   cell edge would be the second invisible focus indicator on this control in a row. */
.nds-cell-expand:focus-visible { outline: 2px solid var(--nds-primary); outline-offset: -1px; }
.nds-cell-expand-slot { width: 20px; flex: none; }

/* actions: Edit + ⋯, right-aligned */
.nds-cell-actions { display: flex; gap: 6px; justify-content: flex-end; align-items: center; }

/* tags: one named chip, or up to N glyph chips and a +N */
.nds-cell-tags { display: flex; align-items: center; gap: 5px; flex-wrap: nowrap; overflow: hidden; }
.nds-cell-tagchip {
  display: inline-flex; align-items: center; gap: 5px; padding: 1px 8px; border-radius: var(--nds-radius-round);
  background: var(--nds-surface-sunken); color: var(--nds-text-2); font-size: var(--nds-font-size-xs); white-space: nowrap;
  max-width: 110px; overflow: hidden; text-overflow: ellipsis;
}
.nds-cell-tagchip-name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; min-width: 0; }
.nds-cell-tagglyph { display: inline-flex; align-items: center; justify-content: center; flex: none; width: 18px; height: 18px; border-radius: var(--nds-radius-sm); background: var(--nds-surface-sunken); }
.nds-cell-tagmore { font-size: var(--nds-font-size-xs); color: var(--nds-grid-muted-fg); flex: none; }

/* group row: label + count */
.nds-cell-group { display: inline-flex; align-items: baseline; gap: 8px; min-width: 0; }
.nds-cell-group strong { font-weight: var(--nds-font-weight-semibold); color: var(--nds-grid-header-fg); }
.nds-cell-group-count { font-size: 12px; color: var(--nds-text-2); white-space: nowrap; }

/* stock levels */
.nds-cell-stock-out { color: var(--nds-danger); font-weight: var(--nds-font-weight-semibold); }
.nds-cell-stock-low { color: var(--nds-warning); font-weight: var(--nds-font-weight-semibold); }
.nds-cell-stock-ok { color: var(--nds-success); font-weight: var(--nds-font-weight-semibold); }

/* locked — the cell (a whole read-only column) and the value (a lock glyph beside it) */
.nds-ag-wrap .ag-cell.nds-cell-is-locked { color: var(--nds-grid-locked-fg); }
.nds-cell-locked { color: var(--nds-grid-locked-fg); display: inline-flex; align-items: center; gap: 6px; }
.nds-cell-lock-glyph { font-size: 10px; }

/* the delta chip on a pending edit */
.nds-cell-delta {
  position: absolute; right: 6px; top: 3px; font-family: var(--nds-font-mono, ui-monospace, monospace); font-size: 10px; font-weight: 700;
  line-height: 14px; padding: 0 5px; border-radius: var(--nds-radius-full); background: var(--nds-grid-delta-bg); color: var(--nds-grid-delta-fg);
}
.nds-cell-delta-neg { background: var(--nds-grid-delta-neg-bg); }

/* editing states — batch (pending / refused) and per-cell round trip (saving / saved / refused) */
.nds-ag-wrap .ag-cell.nds-cell-is-editable { cursor: text; }
.nds-ag-wrap .ag-cell.nds-cell-is-editable:hover { box-shadow: inset 0 0 0 1px var(--nds-grid-editable-ring); }

/* ── Closed-list cells (D13) ───────────────────────────────────────────────────────────────
   🔴 DISCLOSED EDIT under PES.2's claim (hub #442). The Owner: the status cell "should really be a
   dropdown". It already IS a select editor — what was missing is that nothing said so. Measured
   2026-09-02 on GALE-JACKET at innerWidth 1728: the closed-list `status` cell and the free-text
   `name` cell were identical in EVERY signal — same `nds-cell-is-editable` class, same single
   child span, no glyph, and the same `cursor: text`.

   The cursor is the half worth naming separately, because it is not missing information but WRONG
   information: `cursor: text` on a closed list invites the operator to type where typing is not
   possible. A cell that cannot accept text should not claim it can, which is why this rule comes
   before the glyph rather than after it.

   The chevron is a flex item, not an absolutely-positioned one: the cell is already
   `display: flex; align-items: center`, so `margin-left: auto` parks the glyph on the right edge
   and the value KEEPS ITS LEFT EDGE — the Owner's "does not move the value". It also means the
   icon is a flex item rather than a block in a line box, which is the trap that put the Pill's
   icon on its own line an hour ago. `pointer-events: none` so it can never swallow the click that
   opens the editor, and it is a chevron in a CELL, where AG draws no sort indicator; sort lives in
   the header, so the two cannot be confused.

   `--nds-grid-muted-fg` is an existing token and no new one was minted: the DS already had the
   glyph convention too (`.chev` on Select, Listbox, Combobox and the nav rail), so PES.2 renders
   the same lucide ChevronDown every other select in the app uses. */
.nds-ag-wrap .ag-cell.nds-cell-is-select { cursor: pointer; }
/* 🔴 NO resting opacity, and that is a contrast decision rather than a taste one. The first draft
   dimmed the glyph to `opacity: 0.5` so it would sit quietly in every row; composited against the
   cell that measured **2.05:1**, under the 3:1 floor a non-text indicator owes. This chevron is not
   decoration — it is the only thing distinguishing a closed list from free text, which is the
   "decorative by category, informative in fact" shape that has cost this DS an Input placeholder at
   2.04 and a Listbox hint at 3.10. An informative glyph is not dimmed; if it is too loud at full
   strength the answer is a quieter TOKEN, not a lower alpha. `--nds-grid-muted-fg` measures 5.32:1
   light and 7.38:1 dark, and matches how every other DS select shows its chevron — always on. */
.nds-ag-chev {
  margin-left: auto;
  flex: none;
  color: var(--nds-grid-muted-fg);
  pointer-events: none;
}
.nds-ag-wrap .ag-cell.nds-cell-is-pending { background: var(--nds-grid-pending-bg) !important; }
.nds-ag-wrap .ag-cell.nds-cell-is-saving { background: var(--nds-grid-saving-bg) !important; }
.nds-ag-wrap .ag-cell.nds-cell-is-saved { box-shadow: inset 0 0 0 1px var(--nds-success); transition: box-shadow 400ms ease; }
.nds-ag-wrap .ag-cell.nds-cell-is-refused { background: var(--nds-grid-refused-bg) !important; box-shadow: inset 0 0 0 1px var(--nds-grid-refused-ring); }
/* 🔴 "We do not know", in warning tone — NOT the danger tone a refusal wears. `waiting` is a flight
   still open past the patience window; `unknown` is a fetch that rejected and may or may not have
   applied. Both are honest ignorance, and painting either as a refusal is what told an operator a
   34-second write had failed when it had in fact saved. */
.nds-ag-wrap .ag-cell.nds-cell-is-waiting { background: color-mix(in srgb, var(--nds-warning) 8%, transparent) !important; }
.nds-ag-wrap .ag-cell.nds-cell-is-unknown { background: color-mix(in srgb, var(--nds-warning) 8%, transparent) !important; box-shadow: inset 0 0 0 1px var(--nds-warning); }
.nds-cell-select-editor { width: 100%; padding: 0 4px; }

/* sheet validation — a tint AND a corner triangle (never colour alone); the reason is the cell's title */
/* #780 — a cell whose formula was refused carries the same tint as an invalid one: the operator's
   next action is the same (open it and fix what produced it), and inventing a third tint for a
   fourth state would multiply the vocabulary without changing where the click lands (§9.6b).
   🔴 Its own CLASS though: `nds-cell-is-refused` already belongs to `roundTripClassRules`, where it
   means a rejected SAVE. Sharing the tint is a design choice; sharing the class name was a bug that
   let a later spread silently win. */
.nds-ag-wrap .ag-cell.nds-cell-is-formula-refused { background: var(--nds-grid-refused-bg) !important; }
.nds-ag-wrap .ag-cell.nds-cell-is-invalid { background: var(--nds-grid-refused-bg) !important; }
.nds-ag-wrap .ag-cell.nds-cell-is-invalid::after, .nds-ag-wrap .ag-cell.nds-cell-is-warned::after { content: ''; position: absolute; top: 0; right: 0; border-style: solid; border-width: 0 7px 7px 0; border-color: transparent var(--nds-danger) transparent transparent; }
.nds-ag-wrap .ag-cell.nds-cell-is-warned { background: var(--nds-grid-pending-bg) !important; }
.nds-ag-wrap .ag-cell.nds-cell-is-warned::after { border-color: transparent var(--nds-warning) transparent transparent; }
/* a value inherited from the parent: readable, and quietly not the row's own */
.nds-ag-wrap .ag-cell.nds-cell-is-inherited { color: var(--nds-grid-muted-fg); background: color-mix(in srgb, var(--nds-info) 6%, transparent); }
/* PES.2 — cell PROVENANCE. A tint AND a glyph (renderers/provenance.tsx); never colour alone.
   Every colour here is a declared token used at the USE site, not aliased into a new `:root`
   custom property — so the dark-alias scope trap (scripts/check-dark-alias-scope.mjs) does not
   apply and `.dark` resolves each one itself. Measured in tokens.css 2026-09-01: --nds-primary
   IS re-declared inside .dark; --nds-info / --nds-purple-600 are theme-invariant, exactly
   like the --nds-info the inherited rule above already rides on. The tints are low-percentage
   mixes over the cell's own ground, which does flip, and the glyph carries the meaning either
   way.

   🔴 This comment used to end "Contrast is verified in BOTH themes, in the browser, before this
   ships." **It was not.** Nobody measured it, and the sentence read as a record of work done — so
   it did the opposite of its job, discouraging the check it claimed to describe. `64` measured the
   marks in the browser afterwards and found three shipped ones under the 3:1 a meaningful glyph
   owes: `ai` 2.07:1 in both themes, `inherited` 2.38, `pinned` 2.83 light.
   What this rests on now: `64`'s browser measurement of every provenance mark, both themes,
   composited over the real cell ground — and the acceptance for the fix below is their re-measure,
   not a re-reading of this comment. **A comment must state what WAS measured, never what should
   be.** */
.nds-ag-wrap .ag-cell.nds-cell-is-pinned { background: color-mix(in srgb, var(--nds-primary) 7%, transparent); }
.nds-ag-wrap .ag-cell.nds-cell-is-ai-draft { background: var(--nds-grid-ai-draft-bg); font-style: italic; }
/* italic overhang — see `.nds-cell-required` */
.nds-ag-wrap .ag-cell.nds-cell-is-ai-draft .nds-cell-value-text { padding-inline-end: 2px; }
/* A STALE draft (PES.8): still a draft, plus the warn triangle the validation states already use,
   so "this would overwrite an edit" reads in the idiom an operator has already learned. */
.nds-ag-wrap .ag-cell.nds-cell-is-ai-draft-stale::after { content: ''; position: absolute; top: 0; right: 0; border-style: solid; border-width: 0 7px 7px 0; border-color: transparent var(--nds-warning) transparent transparent; }
/* The mark sits before the value and never steals width from it: it is `flex: none`, and the
   value beside it is what ellipsises. */
/* 🔴 NO `opacity`. It was 0.75, and that alone put `inherited` at 2.38:1 and `pinned` at 2.83:1 —
   under the 3:1 a non-text indicator owes. My own note on `.nds-ag-chev` states the rule this
   broke: **an informative glyph is not dimmed; if it is too loud at full strength the answer is a
   quieter TOKEN, not a lower alpha.** These marks are the only thing distinguishing an inherited
   value from a typed one, so they are informative by definition. Removing the alpha is what makes
   `inherited` and `pinned` pass on the tokens they already ride. */
.nds-cell-prov { flex: none; display: inline-flex; align-items: center; margin-right: 5px; vertical-align: middle; }
/* DS.2's semantic token (FX.1's measurement: dark 2.55 → 8.44 / 2.67 → 8.85 / 2.28 → 7.55). */
.nds-cell-prov-inherited { color: var(--nds-prov-inherited-fg, var(--nds-info-strong)); }
/* Inherited VIA a layer that itself overrides the master (ruling #16): the same family as plain
   inheritance, distinguished by its own glyph rather than by a shade of the same one. */
.nds-cell-prov-via { color: var(--nds-primary); }
.nds-ag-wrap .ag-cell.nds-cell-is-inherited-override { background: color-mix(in srgb, var(--nds-primary) 5%, transparent); }
.nds-cell-prov-pinned { color: var(--nds-primary); }
/* 🔴 `--nds-prov-ai-fg` with a FALLBACK, deliberately. DS.2 is landing that token now and it does
   not exist yet — and an undefined custom property in a `color` computes to `rgba(0,0,0,0)`, i.e.
   the mark disappears, silently, with no guard in the repo that catches it. Writing it bare would
   have "fixed" a 2.07:1 contrast by making the glyph invisible. The fallback keeps today's colour
   until the token lands, at which point it takes over with no further edit. */
.nds-cell-prov-ai { color: var(--nds-prov-ai-fg, var(--nds-purple-700)); }
.nds-cell-prov-ai-stale { color: var(--nds-warning-strong); }
/* §9.6's derived-value marks. `provenanceMark.tsx` has emitted these classes since the union was
   widened and `grid.css` had NO rule for either — the tests assert the class is APPLIED, never that
   it does anything, so both marks inherited the cell's own colour and said nothing by their tint.
   `--nds-grid-muted-fg` is chosen because it is already measured (5.32:1 light, 7.38:1 dark) and
   because a derived value is informative rather than alarming: it is not a warning, it is a
   statement about where the value came from. If DS.2 would rather mint a semantic token for
   provenance-derived, this is the line to change. */
.nds-cell-prov-mapped { color: var(--nds-grid-muted-fg); }
/* Product-grain: the same family, distinguished by its own glyph (Share2), not by a shade. */
.nds-cell-prov-mapped-shared { color: var(--nds-grid-muted-fg); }
/* §9.6's ninth member: a cell whose value is produced by a stored `CellFormula` (D16, hub #730).
   The token is DS.2's, landed in BOTH themes and measured there — light `#0e7490` (surface 5.36 ·
   ai-tint 4.43 · pinned 4.88), dark `#22d3ee` (8.43 · 8.36 · 7.87). No fallback here, unlike
   `--nds-prov-ai-fg` above: that one was written with one because the token did not exist yet and
   an undefined custom property in a `color` computes to `rgba(0,0,0,0)` — the mark vanishing
   silently. This token exists (`tokens/css-vars.ts:287,574`), verified before the rule was written
   rather than after. */
.nds-cell-prov-formula { color: var(--nds-prov-formula-fg); }

/* 🔴 #780 — a REFUSED formula's mark. It replaces the ƒ rather than joining it, so this is the only
   thing in the cell saying where the value came from, and it has to read as a WARNING at 11px.
   `--nds-warning` rather than `--nds-danger`: the cell still holds its previous value and nothing is
   broken — the formula simply produced nothing — and reserving danger for a cell that is actually
   invalid keeps the two distinguishable on a sheet showing both. Not `opacity`: an informative glyph
   is never dimmed (the banked contrast rule). */
.nds-cell-prov-refused { color: var(--nds-warning); font-weight: 700; }
/* Only the typography is local — italic and weight are what make a `ƒ` read as a function rather
   than an `f`, and they are not what was ruled into the engine. */
.nds-formula-glyph { font-style: italic; font-weight: 700; line-height: 1; font-size: var(--nds-font-size-sm); }

/* ── the `=` formula editor (D16 / §1.3) ───────────────────────────────────────────────────────
   The editor is an AG POPUP, so it is free of the cell's box and grows downward: field, then the
   `$` autocomplete IN FLOW, then the signature hint, then the preview line. The autocomplete is in
   flow rather than floating because floating it covered the preview — the one thing §1.3 step 2
   exists to show, at exactly the moment an operator is choosing what to read. */
.nds-formula-editor {
  display: flex; flex-direction: column;
  background: var(--nds-surface); color: var(--nds-text);
  border: 1px solid var(--nds-border); border-radius: var(--nds-radius-lg);
  /* 🔴 `--nds-shadow-pop`, the DEFINED token (`styles/tokens.css:203`). I first wrote
     `--nds-shadow-md`, which exists nowhere in this repo — and an undefined custom property in a
     `box-shadow` makes the whole declaration invalid at computed-value time, so the popup would
     have rendered with NO shadow and nothing would have said so. Checked every token in this block
     against its definition before shipping, which is how this one was found. */
  box-shadow: var(--nds-shadow-pop);
}
/* The overlay stacks ON the input, so the wrapper is the positioning context. `display: grid`
   stretches `.nds-field` — it is `inline-flex` and would otherwise size to the input's default
   ~20-character width and clip a formula inside a much wider editor (measured in the lab: 231px
   inside a 420px box). */
.nds-formula-fieldwrap { position: relative; display: grid; }
/* 🔴 The input's own text goes TRANSPARENT and the overlay carries the colour, but the CARET stays
   visible and inherits the text colour — a transparent caret is an editor with no cursor, which is
   the kind of defect that only shows up once someone types. Selection still paints natively. */
/* 🔴 MONO, and it is not decoration. `.nds-fx-errmark` positions the error tick in `ch` units, and
   a `ch` in a proportional face is the width of a `0` — which is not the width of the character it
   is meant to sit under. Measured before this line existed: the overlay computed
   `11.5px Inter`, inherited from the field, so every mark landed at a plausible wrong offset. The
   overlay copies the input's resolved face, so setting it here sets both and they cannot drift. */
/* 🔴 `.nds-formula-editor .nds-field input`, not `.nds-formula-input`. The class alone is (0,1,0)
   and the DS's own `.nds-field input` is (0,1,1), so it won and the overlay — which copies the
   input's RESOLVED face — computed `11.5px Inter`. Measured on the live editor after the first
   attempt: `overlayFont: "Inter, Inter Fallback, …"`. This is the banked page-sheet-beats-DS shape
   with the roles reversed, and the tell was that the declaration was present and simply not in
   effect. */
.nds-formula-editor .nds-field input.nds-formula-input,
.nds-formula-composer .nds-field input.nds-formula-input {
  caret-color: var(--nds-text);
  font-family: var(--nds-font-mono);
  font-variant-ligatures: none;
}
.nds-formula-editor .nds-field input.nds-formula-input.highlighted { color: transparent; }
.nds-formula-overlay {
  position: absolute; pointer-events: none;
  display: flex; align-items: center;
  white-space: pre; overflow: hidden;
  box-sizing: border-box;
  /* 🔴 ABOVE the field, and this was a real defect rather than a precaution. `.nds-field` paints an
     opaque white background and the overlay is its previous sibling, so with `z-index: auto` the
     field painted over it and the formula was INVISIBLE — the input's own text being transparent by
     design, the cell looked empty while holding text. Found on screen; the DOM said `overlayText:
     "="` while the screenshot showed nothing, which is the only reason it was caught at all. */
  z-index: 1;
  /* `left` and `padding-left` are set by the component from the INPUT's measured rect — the `ƒ`
     rides as the field's `leadingIcon` inside the border, so the text starts 20px right of the
     field's edge (measured: field 517, input 537). Positioning from the wrapper would put every
     character 20px left of the one it describes. */
}
.nds-formula-overlay-line { position: relative; flex: none; }
.nds-formula-input, .nds-formula-overlay, .nds-formula-help code,
.nds-formula-help-panel code, .nds-formula-hint code { font-variant-ligatures: none; }
.nds-fx-eq { color: var(--nds-text-muted); }
.nds-fx-str { color: var(--nds-success-text); }
.nds-fx-num { color: var(--nds-text); }
.nds-fx-ident { color: var(--nds-primary); }
.nds-fx-op, .nds-fx-punc { color: var(--nds-text-muted); }
.nds-fx-error { color: var(--nds-danger-text); text-decoration: underline wavy; }
/* A reference wears the hue `formulaPalette` assigned it — set inline, because the assignment is
   per-formula and per-edit and there is no class to carry seven rotating hues. */
.nds-fx-ref { font-weight: 600; }
/* 🔴 An UNKNOWN reference is red and underlined, never merely uncoloured. The engine's own failure
   mode for one is to warn and resolve to nothing, and an operator reading a blank cell cannot tell
   a typo from an empty source — which is the whole reason `unknownRefs` was added to the route
   (#723). Red plus a wavy underline, so it does not depend on colour alone. */
.nds-fx-ref.bad { color: var(--nds-danger-text); text-decoration: underline wavy; font-weight: 600; }
.nds-fx-errmark {
  position: absolute; bottom: 0; width: 1ch; height: 2px;
  background: var(--nds-danger-text);
}
/* In flow inside the editor, so it cannot cover the preview line below it. */
.nds-formula-pop { position: static; box-shadow: none; border: 1px solid var(--nds-border-subtle); }
.nds-formula-hint { display: flex; gap: var(--nds-space-2); align-items: baseline; font-size: var(--nds-font-size-xs); color: var(--nds-text-muted); }
.nds-formula-hint code { font-family: var(--nds-font-mono); color: var(--nds-text); }
/* The argument the caret is in. Weight AND colour: emphasis by weight alone is invisible at 11px
   in a monospace face, and by colour alone it fails for an operator who cannot separate the hues. */
.nds-formula-hint code .on { font-weight: 700; color: var(--nds-primary); }
.nds-formula-hint-sum { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.nds-formula-preview {
  font-family: var(--nds-font-mono); font-size: var(--nds-font-size-xs);
  color: var(--nds-text); overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  border-top: 1px solid var(--nds-border-subtle); padding-top: var(--nds-space-1);
}
.nds-formula-preview.muted { color: var(--nds-text-muted); }
.nds-formula-preview.bad { color: var(--nds-danger-text); white-space: normal; }
/* 🔴 A cell being edited by an OVER popup does not paint its own value (#769).
   AG 36's reactive editors report every keystroke through `onValueChange`, which updates the proxy's
   value and repaints the cell UNDERNEATH the popup — so a half-typed formula appeared in the cell as
   though it were the value, which is exactly what (a2) exists to prevent. The editor is the truth
   while it is open; the cell has nothing to add and its text is a stale draft.
   `visibility`, not `display`: the cell keeps its box, so nothing reflows when the edit ends.

   🔴 `:not(.nds-cell-is-select)` — SCOPED TO `over` POPUPS, 2026-09-03 (Owner's Phase 1).
   Unscoped, this also blanked the cell under an `under` popup, and MEASURED that is what happened:
   with the Status list open, the Status cell read `"ACTIVE"` before the gesture and `""` while the
   list was showing — an empty blue box with the options beneath it, so the operator chose a new
   value with the current one hidden. Every other row still read ACTIVE. The reason #769 gives holds
   only where the popup COVERS the cell; where it sits below, the cell is the only place the current
   value appears and hiding it is a defect of its own.
   Keyed on the select class because `cellEditorPopupPosition: 'under'` is set by `selectEditor()`
   alone and nothing else in the product is positioned `under`. It is a PROXY and it is safe in both
   directions: a select cell opened by the `=` editor is an `over` popup that keeps its value
   painted, which the popup then covers anyway — visually identical, nothing leaks. */
.nds-ag-wrap .ag-cell.ag-cell-popup-editing:not(.nds-cell-is-select) .nds-cell-value { visibility: hidden; }

/* 🔴 THE ORIGIN CELL IS OUTLINED WHILE IT IS BEING EDITED (Owner's Phase 1, 2026-09-03).
   "The cell being edited is always the one you are looking at, outlined" — the constant across
   Excel, Sheets and Airtable. It matters most exactly when the geometry cannot be perfect: if a
   column is scrolled so far right that even the room-capped editor cannot sit flush, this outline is
   the only thing still tying the editor to the cell it came from.
   Same `outline` / `outline-offset: -2px` idiom as the formula reference above, and for the same
   reason: a border would change the cell's box and shift every column beside it the moment an
   editor opened. */
.nds-ag-wrap .ag-cell.ag-cell-popup-editing {
  outline: 2px solid var(--nds-primary);
  outline-offset: -2px;
}

/* 🔴 THE EDITOR'S BOX, computed per cell by `editors/editorBox.ts` and published as custom
   properties by `publishEditorBox()` BEFORE AG creates and positions the popup.
   `agLargeTextCellEditor` takes only `rows`/`cols` — character counts — so pixels have to arrive
   this way. The old constant was 488×158 for every cell whatever the content, which AG then slid up
   to 202px sideways to keep it in the window. The fallback values are the previous constants, so a
   failure to publish degrades to the old behaviour rather than to nothing.
   The properties live on `:root` because AG parents editor popups to `document.body`; exactly one
   cell editor is open at a time, so one slot is enough. */
/* 🔴 ONE BOX, AND THE TEXTAREA IS THE THING THAT IS SIZED — Owner item 52(a), 2026-09-04.
   The first version of this rule set a fixed `height` on `.ag-large-text` and `.ag-large-text-input`
   and `resize: none` on the same two, and BOTH halves were wrong in the same way: neither selector
   is the textarea. Measured in the live DOM — `textarea.ag-input-field-input.ag-text-area-input`
   inside `div.ag-large-text-input` (AG's AgInputTextArea WRAPPER) inside `div.ag-large-text` (which
   carries the white background). So `resize: none` bound to nothing, computed `resize` on the real
   textarea stayed `vertical`, and AG only kills it under `.ag-rtl` — in LTR the handle is theirs by
   design and has always been there.
   What my fixed height then added was the TEAR the Owner photographed: AG sets `height: auto` on the
   wrapper precisely so it follows the textarea, I overrode it with a pixel value, and dragging grew
   the textarea while the background stayed put. Reproduced before fixing: textarea 368×250 against
   an outer box frozen at 396×158.
   So the container is no longer sized at all — AG's `auto` stands and it follows its content — and
   the height, the cap, the scroll and the resize lock all live on the textarea, which is the element
   that actually holds the text. One box, because only one of them has a height. */
.ag-popup-editor .ag-large-text {
  width: var(--nds-editor-w, 488px);
  max-width: 100vw;
  box-sizing: border-box;
}
.ag-popup-editor .ag-large-text-input { width: 100%; box-sizing: border-box; }
.ag-popup-editor .ag-text-area-input {
  /* No manual resize handle: the approved rule is that height follows content to a cap, and a drag
     handle offers a second, conflicting way to size the same box. */
  resize: none;
  height: var(--nds-editor-h, 158px);
  max-height: var(--nds-editor-h, 158px);
  overflow-y: auto;
  box-sizing: border-box;
}

/* 🔴 The same-row OUTLINE, in the reference's own hue — Excel's affordance and the Owner's ask.
   `outline`, not `border`: a border would change the cell's box and shift every column beside it by
   2px the moment an operator typed a `$`. `outline-offset: -2px` keeps it inside the cell so
   adjacent outlines do not overlap into a 4px seam. */
.nds-ag-wrap .ag-cell.nds-formula-ref-cell {
  outline: 2px solid var(--nds-formula-ref, var(--nds-primary));
  outline-offset: -2px;
}
/* A cell that carries a mark lays out as a row so the glyph and the text share the line. */
.nds-cell-value { display: inline-flex; align-items: center; min-width: 0; width: 100%; }
.nds-cell-value-text { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; min-width: 0; }
/* 🔴 ITALIC OVERHANG (Owner, 2026-09-05: "required … is cropped a bit at the end"). The clip box is
   `.nds-cell-value-text`'s padding box, sized to the text's ADVANCE width; an italic glyph paints past
   its advance, so the last letter's tail was cut off. Every italic run inside a clipped cell carries
   an end padding of its own (the ai-draft cell does the same, below its rule) so the tail can paint.
   Guarded by `renderers/listChipAndItalicClip.vitest.test.ts`: a new italic needs its padding. */
.nds-cell-required { color: var(--nds-danger-text); font-style: italic; font-size: var(--nds-font-size-xs); padding-inline-end: 2px; }
/* A cell the ACTIVE view chip counted (PES.3's need, hoisted into the engine — grid chrome belongs
   here, never in a page stylesheet, and the import-boundary guard enforces exactly that). Filtering
   to the matching ROWS alone leaves the operator hunting for which of a hundred columns was the
   reason, so the cells themselves are marked. A ring, not a fill, so it composes with the
   provenance tints instead of hiding them. */
.nds-ag-wrap .ag-cell.nds-cell-chip-hit { box-shadow: inset 0 0 0 2px var(--nds-warning); }

/* ══ media cells (`renderers/MediaCellView.tsx`) ══════════════════════════════════════════════
   A grid whose CELL IS A PICTURE — the Amazon Colour × Slot matrix, the eBay bucket grid.
   🔴 Nothing here is `position: absolute`: an absolutely positioned child ESCAPES an AG cell
   (ruling #12), so the marks are laid-out flex children and the tile is a flex container. */
.nds-media-cell {
  display: flex; align-items: center; gap: 6px;
  width: var(--nds-media-size, 96px); height: var(--nds-media-size, 96px);
  border: 1px solid var(--nds-border); border-radius: var(--nds-grid-radius);
  background: var(--nds-surface-sunken); overflow: hidden; position: relative;
}
/* 🔴 THE PICTURE YIELDS; THE MARK NEVER CLIPS (#688, ruled by the hub on PES.7's measurement).
   `.nds-media-cell` is `overflow: hidden` and lays out image + 6px gap + marks in ONE row. With
   the image at `width: 100%` that row is 80 + 6 + 22 = 108px inside an 84px box, so the marks
   rendered OUTSIDE the clip rect and the provenance glyph was simply not painted — measured live
   on the Amazon·IT matrix: tile right edge 568, marks 571→593, i.e. 25px out, on BOTH real
   `pinned` marks of 30 media cells. A tile that wears no glyph has only its border to say where
   its picture came from, which is why the `-ai`/`-ai-stale` split two rules below matters.
   `flex: 1 1 0` + `min-width: 0` makes the image the item that gives way — `min-width: auto` is a
   flex item's automatic floor and would otherwise hold it at its content width, which is the same
   mechanism that held the `?` button 2px too wide (#684). `object-fit: cover` keeps the crop
   centred as the box narrows.
   Measured by UX.1 on both arms of one build: `overflow: hidden` clips at the PADDING box (567),
   not the border box (568), so the marks' right edge at 567 sits EXACTLY flush with the clip rect
   — not one pixel inside, as a border-box reading suggests. The pre-fix overhang was +26 against
   that rect (not the +25 a border-box reading gives), and it ran on 14 of 30 tiles: unmarked image
   tiles overhung by 10px each, with no glyph to lose.
   FLUSH IS NOT FRAGILE — the bound, measured by UX.1 across four in-page arms on this build:
   the image ABSORBS growth in the strip or the gap, down to 0 width, so the mark cannot re-clip
   while `marks + gap <= 82px` (the tile's CONTENT box). Arms: marks 30 → image 46, flush ·
   marks 76 → image 0, flush (the boundary) · marks 90 → 14px over, clipped · gap 20 → image 40,
   flush. At a 6px gap that is a 76px strip, roughly three and a half more glyphs of headroom.
   An earlier version of this comment said any growth re-clips immediately; that was wrong, and so
   was the opposite claim that it never can.
   ⚠ The acceptance is that the GLYPH is reachable, not that the strip fits: at the 90px arm the
   strip overhangs and the first glyph still hit-tests. */
.nds-media-img { flex: 1 1 0; min-width: 0; width: 100%; height: 100%; object-fit: cover; display: block; }
/* 🔴 The empty placeholder NEVER HAD THIS BUG, and the reason is worth keeping because the obvious
   analogy is wrong. "Same box, same row" predicts it clipped like the image; measured, it is 70px in
   BOTH arms, and under an identical forced squeeze the image stayed floored at 80 while this box
   yielded to 54 on its own. `min-width: auto` resolves differently by element: on an `<img>` the
   automatic minimum is the INTRINSIC width, on a `<span>` flex container it is min-content — an
   icon. So this line fixes nothing today. It is kept only so both boxes state the same intent, and
   it starts mattering the day this span gains intrinsic content. (UX.1, one build, both arms.) */
.nds-media-empty { display: flex; align-items: center; justify-content: center; flex: 1 1 0; min-width: 0; width: 100%; height: 100%; color: var(--nds-grid-muted-fg); }
/* The marks sit in their own strip so they never cover the picture they describe. */
.nds-media-marks { display: inline-flex; align-items: center; gap: 3px; flex: none; padding: 0 3px; }
.nds-media-count { font-size: 10px; font-weight: 700; color: var(--nds-text-2); font-variant-numeric: tabular-nums; }

.nds-media-is-empty { border-style: dashed; }
.nds-media-is-locked { opacity: 0.75; }
.nds-media-is-pending { box-shadow: inset 0 0 0 2px var(--nds-grid-saving-bg); }
.nds-media-is-warned { box-shadow: inset 0 0 0 2px var(--nds-warning); }
.nds-media-is-refused { box-shadow: inset 0 0 0 2px var(--nds-grid-refused-ring); background: var(--nds-grid-refused-bg); }
/* Provenance reuses the CELL vocabulary — one idea, one set of names. */
.nds-media-prov-inherited { border-color: var(--nds-prov-inherited-fg, var(--nds-info-strong)); }
.nds-media-prov-inherited-override { border-color: var(--nds-primary); }
.nds-media-prov-pinned { border-color: var(--nds-primary); }
/* 🔴 `ai` and `ai-stale` are DIFFERENT states and must not share a border (#684(a), PES.7's
   measurement). They were byte-identical here — contrast 1.00 — while the cell forms at :535/:536
   already paint them apart. On a TILE the border is doing more work than it looks: PES.7 measured
   `.nds-media-marks` (22px, `flex:0 0 auto`) overflowing `.nds-media-cell` (84px, `overflow:hidden`)
   on tiles whose image cannot shrink, so the provenance GLYPH is clipped away and the border is the
   only channel left. `--nds-warning-strong` is pinned in both themes (tokens.css:104 / :464), so
   unlike the `ai` line it needs no fallback. ⚠ The clipping itself is a separate, unruled defect in
   `.nds-media-cell`/`.nds-media-marks` geometry — not fixed here. */
.nds-media-prov-ai { border-color: var(--nds-prov-ai-fg, var(--nds-purple-700)); }
.nds-media-prov-ai-stale { border-color: var(--nds-warning-strong); }
/* The channel's own answer, as a rule along the bottom rather than a floating dot. */
.nds-media-publish-live { border-bottom: 3px solid var(--nds-success); }
.nds-media-publish-queued { border-bottom: 3px solid var(--nds-warning); }
.nds-media-publish-failed { border-bottom: 3px solid var(--nds-danger); }
/* long text: the text ellipsises, the counter keeps its place */
.nds-cell-longtext { display: inline-flex; align-items: center; gap: 8px; min-width: 0; width: 100%; }
.nds-cell-longtext-text { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; min-width: 0; flex: 1 1 auto; }
/* §9.3a — the length as a MARK, not a counter. "127/200" beside one line of text was most of a
   110px cell, so the figures moved to the tooltip and the state stays on screen.
   🔴 The GLYPH carries the distinction (● filled · ◆ near · ▲ over) and the tone reinforces it:
   amber and red read identically to a large minority of operators, so colour alone would make
   "you have room left" and "this will be refused" the same mark. `unchecked` renders nothing —
   see LongTextCell for why that is only honest while `filled` is visible. */
.nds-cell-longtext-mark { flex: none; font-size: 9px; line-height: 1; color: var(--nds-grid-muted-fg); }
.nds-cell-longtext-mark-near { color: var(--nds-warning-strong); font-size: 10px; }
.nds-cell-longtext-mark-over { color: var(--nds-danger-text); font-size: 10px; }
/* follows-master control */
.nds-cell-follows { font-size: var(--nds-font-size-xs); color: var(--nds-grid-muted-fg); white-space: nowrap; }
.nds-cell-follows-pinned { color: var(--nds-text-2); font-weight: 600; }

/* overlays */
/* AG wraps React overlays in a shrink-to-content flex item. Give the skeleton the grid width. */
.nds-ag-wrap .ag-overlay-loading-wrapper > .ag-react-container:has(> .nds-grid-skel) { width: 100%; }
/* 16px, matching the footstrip and the toolbar. The SKELETON's inset matters more than it looks:
   at 14px the first paint sat 2px left of where the real content lands, so every sheet load ended
   with a 2px jump. DS.2's four-edge measurement. */
.nds-grid-skel { display: flex; flex-direction: column; width: 100%; padding: 0 16px; }
.nds-grid-skel-row { display: flex; align-items: center; gap: 12px; border-bottom: 1px solid var(--nds-grid-row-rule); }
.nds-grid-skel-thumb { flex: none; border-radius: var(--nds-radius-sm); background: var(--nds-grid-skeleton-bg); }
.nds-grid-skel-text { display: flex; flex-direction: column; gap: 7px; flex: 1; }
.nds-grid-skel-line { display: block; height: 11px; border-radius: 6px; background: linear-gradient(90deg, var(--nds-grid-skeleton-bg) 25%, var(--nds-grid-skeleton-shine) 37%, var(--nds-grid-skeleton-bg) 63%); background-size: 400% 100%; animation: nds-grid-shimmer 1.3s ease infinite; }
.nds-grid-skel-line-sub { height: 8px; }
@keyframes nds-grid-shimmer { 0% { background-position: 100% 0; } 100% { background-position: 0 0; } }
@media (prefers-reduced-motion: reduce) { .nds-grid-skel-line { animation: none; } }
.nds-grid-noRows { display: flex; flex-direction: column; align-items: center; gap: 8px; }
.nds-grid-noRows-title { font-weight: var(--nds-font-weight-semibold); color: var(--nds-grid-cell-fg); }
.nds-grid-noRows-msg { color: var(--nds-grid-empty-fg); }

/* ══ hosts and toolbars (`../hosts`, `../toolbars`) ═══════════════════════════════════════════
   Lifted from /products/next (`.pager`, `.rpp`, `.grow`, `.ieFootStrip`, `.gridCard`), measured. */
/* the page host is a size container, so a toolbar's selection cluster adapts to the CARD's width */
.nds-grid-card { container-type: inline-size; }
/* the pager: pages left of the control, rows-per-page on the right (the Ad Manager's arrangement) */
/* 16px — same value, same reason as the footstrip above. I fixed the footstrip alone earlier and
   left this and the skeleton at 14, so the engine's own three chrome bands disagreed with each
   other. Enumerating one consumer and calling it the set is the mistake, not the number. */
.nds-grid-pager { display: flex; align-items: center; gap: 16px; padding: 10px 16px; border-top: 1px solid var(--nds-border); }
.nds-grid-pager-grow { flex: 1; }
.nds-grid-pager-rpp { display: flex; align-items: center; gap: 8px; font-size: 13px; color: var(--nds-text-2); white-space: nowrap; }
/* the editor's footer strip inside the card */
/* 🔴 16px horizontal, not 14 — the studio's gutter. DS.1 measured the three stacked text runs
   inside one sheet card starting at x = 81 / 83 / 81: the footstrip rendered TWICE at the time
   (family band on top, status strip at the bottom) and the toolbar between them at 16px is what
   read as misaligned. The family band has since been folded into the toolbar (§2.1c), so only the
   status strip is left — the 16px stands on its own evidence, not on the pair. `.nds-detailhdr`, `.nds-scopebar`, the tab strip and `.nds-gridcard .nds-toolbar` all
   compute `0 16px`, so the footstrip was the lone outlier. Changed on the BASE rather than added as
   a studio modifier: nothing evidenced the 14 as deliberate, and one consumer at a different inset
   is how a design system grows two gutters for one idea. */
.nds-grid-footstrip { display: flex; align-items: center; gap: 10px; padding: 10px 16px; border-top: 1px solid var(--nds-border); }
.nds-grid-footstrip-grow { flex: 1; }

/* the toolbar's swapping halves (`../toolbars/GridSelectionActions`). The search field is 36px, an
   `sm` button 28: the cluster holds the toolbar's height on the first tick and never wraps —
   labels hide under 1320px and the reach note under 1100px of the CARD (`GridCard` is the container). */
.nds-grid-selbar { display: inline-flex; align-items: center; gap: 7px; flex-wrap: nowrap; white-space: nowrap; min-width: 0; min-height: var(--nds-grid-toolbar-slot-h); }
.nds-grid-selbar-note { color: var(--nds-grid-muted-fg); }
.nds-grid-search { flex: 1; min-width: 220px; max-width: 340px; }
/* The two halves share ONE height. A DS field is a 1px border + padding + a 19.5px line box = 35.5px;
   the cluster's floor was 36 — a half-pixel step on every tick (measured 64.5 → 65 on both surfaces).
   Both sides now sit on the same floor, so the swap is exact by construction. */
.nds-grid-search .nds-field { min-height: var(--nds-grid-toolbar-slot-h); box-sizing: border-box; }
.nds-ag-wrap, .nds-gridcard { --nds-grid-toolbar-slot-h: 36px; }
@container (max-width: 1320px) { .nds-grid-selbar-lbl { display: none; } }
@container (max-width: 1100px) { .nds-grid-selbar-note { display: none; } }

/* ══ the SHEET host (`../hosts/GridSheet`) ═══════════════════════════════════════════════════
   The one page-level grid that is bounded and virtualised: it fills the viewport below its own top
   edge (measured, stamped as --nds-grid-sheet-top) and the grid inside scrolls both ways. */
/* The gutter is 8px, not 24. §2.2 wants 74.8% of the viewport in ROWS, and a full-bleed sheet has
   no bottom gutter to spend — 16px of the last 20 in the whole §2 budget was sitting here. It stays
   a variable so a host inside a padded shell can put its own back. */
.nds-grid-sheet { display: flex; flex-direction: column; height: calc(100dvh - var(--nds-grid-sheet-top, 0px) - var(--nds-grid-sheet-gutter, 8px)); min-height: 360px; }
/* 36px, not the base 40 — SCOPED to the sheet on purpose. The 4px is a layout-v2 budget line, and
   layout v2 is this host; the GridCard pages have no such budget and no reason to inherit a
   tighter footer from it. This is the opposite call to the 16px inset above, and for the opposite
   reason: that was one idea rendered at two gutters, this is two hosts with different budgets. */
.nds-grid-sheet .nds-grid-footstrip { height: 36px; flex: 0 0 36px; box-sizing: border-box; padding-top: 0; padding-bottom: 0; }
.nds-ag-fill { flex: 1 1 0; min-height: 0; }
/* 🔴 Reserve the AI copilot FAB's footprint. The status strip is the sheet's ONLY keyboard-hint
   line, and the FAB covers 104×19px of its TAIL — so what an operator loses is "drag the corner to
   fill · ⌘Z", the two things they are least likely to guess. Seen on screen, not deduced.

   Reserved rather than lifting the FAB (the other option DS.1 offered): moving the button up just
   puts it over the grid, which trades a covered hint for a covered cell. The width comes from
   DS.1's measured token rather than a number copied here — if the button's footprint changes, this
   follows it. DS1-2. */
.nds-grid-sheet-status { font-size: 12.5px; color: var(--nds-text-2); padding-right: var(--nds-fab-reserve-inline, 128px); }
.nds-grid-sheet-status-pending { color: var(--nds-warning-strong); }
.nds-grid-sheet-status-refused { color: var(--nds-danger-text); }

/* ── Action confirmations (GDS actions/ActionConfirm) ─────────────────────────
   A verb's confirmation is a safety control, so its look lives with the grid
   engine rather than per lane — one dialog, one set of rules, every surface. */
.nds-grid-confirm-block { margin-bottom: 14px; }
.nds-grid-confirm-block:last-child { margin-bottom: 0; }
/* `list-style` is set explicitly: the app reset strips markers, and without them a confirmation's
   itemised consequences render as a run of plain sentences — which is how a list of five live
   listings reads as one paragraph nobody counts. */
.nds-grid-confirm-list { margin: 6px 0 0; padding-left: 18px; list-style: disc outside; display: flex; flex-direction: column; gap: 4px; }
.nds-grid-confirm-list li { color: var(--nds-text); }
/* The unasked-for consequences are set apart, never mixed into the list above. */
.nds-grid-confirm-aside { border-left: 2px solid var(--nds-warning); padding-left: 10px; }
.nds-grid-confirm-aside li { color: var(--nds-grid-muted-fg); }
.nds-grid-confirm-warn { color: var(--nds-warning); }
.nds-grid-confirm-error { color: var(--nds-danger); }

/* PES.2 F4 — the add-variation form's field grid. Two columns so a four-field identity block reads
   as one shape rather than a column of four, and one column when there is no room for two. */
.nds-addvar-axes { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 10px; margin-top: 6px; }
.nds-addvar-field { display: flex; flex-direction: column; gap: 4px; }


/* 🔴 The thumbnail's fit is the ROW KIND's job, not a CSS cap.
   A cap lived here briefly, written as `min(thumb, calc(var(--ag-row-height) - 4px))`. It was
   INERT and looked careful: `--ag-row-height` is the Theming API's own expression (it computed to
   42 while the rendered row was 28, because AG sets the real height through the `rowHeight` grid
   option in JS and nothing writes it back), so the min never bound. Measured by DS.1 and
   independently here.

   **An AG geometry CSS variable is a theme INPUT, not a readback of what the grid rendered.**
   Anything needing the real row height must read the rendered row or the grid option. The fix is
   `rows="media-line"` on the sheet — 36px, derived as thumb + 4 per tier so it cannot drift from
   the thumbnail it has to contain. */


/* ── AG rich select (the sheet's select editor) — DS parity, DS.1 2026-09-02 under PES.2's claim ──
   Measured against the DS `Listbox` on the same page: border colour and typography already matched;
   the shapes did not. Radii only here — they cannot move layout. The ROW HEIGHT (24 -> 36) is
   deliberately NOT set in CSS: `.ag-rich-select-list` is a VIRTUALISED viewport and AG positions its
   rows from a height it computes, so a CSS height desynchronises the offsets. It goes through the
   editor's `cellHeight` param (`IRichCellEditorParams`), which is AG.1's to set.
   The visual surface is `.ag-rich-select-list` (it also carries `.ag-virtual-list-viewport`);
   `.ag-popup` is a positioning container measuring 1728x0 — reading it reports no border/shadow. */
.nds-ag-nexus .ag-rich-select-list,
.ag-rich-select-list { border-radius: var(--nds-radius-xl); }
.ag-rich-select-row { border-radius: var(--nds-radius-md); }

/* ── GridSheetNote — the sheet's honest message in the footer strip (DS.1, v2 §6.2 r6 / §6.3,
   ruling #230; in PES.2's tree under their claim, disclosed). Sized for the 40px strip, not the
   page: the DS `Banner` is the page-scale callout and carries an 18px icon, title, description,
   action and a dismiss control. The KIND owns the glyph and the tone — never the bar.
   No dismiss rule exists here because the component cannot express one. */
/* 🔴 HEIGHT. This note occupies the footer strip's existing fixed band, and the whole reason the
   slot exists is that the band must never change height — a conditional band above the sheet moved
   the tab strip 148 → 179 and resized the grid under the operator. Measured 2026-09-01: the strip
   is 39.75px with 10px padding each side, so a note has ~19.8px of content box. `RefusalLine`'s
   first version used `padding: 3px 9px`, rendered 22.4px, and pushed the band to 43.4px — a
   component built to stop the sheet moving would have moved it, by 3.6px, on every refusal, and it
   rendered and read correctly the whole time. 12.5px ink at normal line-height is ~18.75px and
   clears it. Any change to font-size or padding here MUST be re-measured inside the strip, not
   against this element's own box. */
/* §14.1 — an `absent` reason, and the "not supplied" notice beside it. A reason is a SENTENCE in a
   40px bar: PES.3's first one laid out at 82 × 312px and pushed the band. One line, clipped, with
   the full text in `title`. `max-width` in ch so it scales with the type rather than a magic px. */
/* 🔴 `flex: none`. As `0 1 auto` this was the only shrinkable item in a bar with no slack, so on a
   full channel toolbar it collapsed to 18px — an ellipsis and nothing else (PES.3 measured it live).
   A reason nobody can read is the silence the `absent` mechanism exists to prevent, so the marker
   is unshrinkable and carries the control's NAME; the reason is in `title`/`aria-label`. */
.nds-grid-toolbar-absent {
  display: inline-flex; align-items: center; flex: none;
  max-width: 24ch; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  /* 🔴 The cursor is NOT changed on hover here. The question-mark hover cursor is banned
     permanently (Owner, 2026-08-20) and enforced at baseline 0 by `check-help-cursor.mjs` — which
     greps comments too, so this note deliberately does not spell the property out. The tooltip is
     the whole explanation channel. I wrote it in and the guard caught it. */
  font-size: 12.5px; height: 28px;
}
.nds-grid-toolbar-absent:focus-visible { outline: 2px solid var(--nds-primary); outline-offset: 1px; border-radius: var(--nds-radius-sm, 4px); }

/* §14.6 — the footer's HEIGHT never changes, only its content. The slot holds one line whatever
   occupies it (a refusal, the shortcut hint, the `?` alone, or nothing at all while the retired
   state is still being read), so the strip cannot move under an operator mid-edit. Without this the
   band collapsed when the slot emptied and the whole grid grew by a line. */
.nds-grid-sheet-note { display: inline-flex; align-items: center; gap: 6px; min-width: 0; font-size: 12.5px; min-height: 18px; }
.nds-grid-sheet-noteslot { display: inline-flex; align-items: center; gap: 8px; min-height: 18px; min-width: 0; }
/* The permanent way back to the shortcuts. Same type scale as the note it restores. */
/* 🔴 This control is the DS Button (#684) — `variant="quiet" size="xs"`. What is left here is ONLY
   the 18px square, which no Button size offers (`.nds-btn.icon.xs` is 23px), and the SELECTOR WEIGHT
   IS LOAD-BEARING. Measured on screen either side of the conversion, because the first attempt got
   this wrong and looked fine in the gate:
     - `.nds-btn.xs` is (0,2,0); the old bare `.nds-grid-sheet-help` was (0,1,0). The DS's
       `padding: 4px 9px` therefore beat `padding: 0` on WEIGHT, not on stylesheet order — an
       order-based reading of this collision is wrong even though order is the usual culprit here.
     - The declared `width: 18px` then lost a SECOND time, and not to any rule: a flex item's
       `min-width: auto` floors it at content + padding + border, so the button rendered 20px wide
       while `width` still computed as 18. Restoring the padding is what restores the width.
   `.nds-btn.xs.nds-grid-sheet-help` is (0,3,0) and wins outright, with no dependence on which
   stylesheet the bundler emits first.
   ⚠ The `.xs` here is COUPLED to `size="xs"` in MasterSheet.tsx. Change that prop and this whole
   block stops matching — silently, and the button grows to the DS's own geometry. */
.nds-btn.xs.nds-grid-sheet-help {
  display: inline-flex; align-items: center; justify-content: center;
  width: 18px; height: 18px; flex: none; padding: 0;
  border: 1px solid var(--nds-border); border-radius: var(--nds-radius-pill);
  background: none; color: var(--nds-text-2); font-size: 11px; font-weight: 600; cursor: pointer;
}
.nds-btn.xs.nds-grid-sheet-help:hover { background: var(--nds-surface-hover); color: var(--nds-text); border-color: var(--nds-border-strong); }
.nds-btn.xs.nds-grid-sheet-help:focus-visible { outline: 2px solid var(--nds-primary); outline-offset: 1px; }
.nds-grid-sheet-note-glyph { display: inline-flex; flex: 0 0 auto; }
.nds-grid-sheet-note-text { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
/* The count is the statement and never truncates — an operator must always be able to read THAT
   work is blocked, even when the example does not fit. The example is what gives way. */
.nds-grid-sheet-note-count { flex: 0 0 auto; font-weight: 600; }
.nds-grid-sheet-note-sep { flex: 0 0 auto; opacity: 0.55; }
.nds-grid-sheet-note-more { flex: 0 0 auto; color: var(--nds-text-2); }
/* Every ink here flips under .dark (verified: danger-text #9c2f2a → #ef9c93, warning-text #6d3f10 →
   #f0b46a, text-2 #5b6573 → #aab6c2). --nds-warning-border does NOT flip and is deliberately
   unused. Neither --nds-warning nor --nds-danger is named here, nor the --nds-note- or --nds-tonal-
   families: they are absent from both .dark blocks and would hold their light values on #18263b.
   (Written without a glob after those prefixes on purpose — a "*" immediately before a "/" ends the
   comment, which is how this rule shipped broken once already.) */
.nds-grid-sheet-note.offline { color: var(--nds-warning-text); }
.nds-grid-sheet-note.provenance { color: var(--nds-warning-text); }

/* 🔴 The cell tooltip's paragraphs must SURVIVE (#662). `composeCellTooltip` joins its lines with a
   blank line so a refusal and a length reading cannot read as one sentence — and AG's tooltip
   element collapses whitespace by default, so the join arrived on screen as
   "…edit to give this row its own value 9 of 700 characters (Amazon · IT)": one run of text saying
   two unrelated things. Measured on the sheet, not inferred; the composer was right and invisible.
   `pre-line` collapses runs of spaces but keeps newlines, which is exactly what the composer writes.
   `max-width` because a long refusal on a single line is its own kind of unreadable. */
.ag-tooltip.ag-cell-tooltip { white-space: pre-line; max-width: 42ch; }

.nds-grid-sheet-note.refusal { color: var(--nds-danger-text); }
.nds-grid-sheet-note.slow { color: var(--nds-text-2); }
.nds-grid-sheet-note.hint { color: var(--nds-text-2); }
/* The `refusal` kind renders a BUTTON, because a count of work must be reachable as a view. It
   still has to sit on the strip's text baseline like the other kinds, so the button chrome is
   stripped rather than restyled — no padding, no border, no background, nothing that could change
   the band's height. */
button.nds-grid-sheet-note { padding: 0; border: 0; background: none; font: inherit; font-size: 12.5px; cursor: pointer; }
button.nds-grid-sheet-note:hover .nds-grid-sheet-note-count { text-decoration: underline; }
/* `--nds-primary`, never `--nds-focus-ring`: that token is a BOX-SHADOW value, so
   `outline: 2px solid var(--nds-focus-ring)` expands to nonsense and is dropped whole, leaving a
   control with no focus indicator and no error anywhere. There is a live instance of exactly that
   at grid.css:304 (`--nds-grid-focus-ring` aliases it), filed to PES.2. */
button.nds-grid-sheet-note:focus-visible { outline: 2px solid var(--nds-primary); outline-offset: 2px; border-radius: var(--nds-radius-sm); }
/* No collapsible detail panel: this strip sits inside `.nds-gridcard`, which is `overflow: hidden`
   to round its corners, so an absolutely-positioned panel here is painted, invisible and
   un-hit-testable (reference_gridcard_clips_dropdowns). A detail surface must be portalled and
   fixed, which makes it the DS popover primitive's job, not a footer span's. */


/* A sheet's toolbar stays on its 40px band. Search absorbs available width. */
.nds-grid-sheet .nds-toolbar {
  padding: 0 6px;
  height: var(--nds-toolbar-h, 40px);
  min-height: var(--nds-toolbar-h, 40px);
  min-width: 0;
  flex: 0 0 var(--nds-toolbar-h, 40px);
  flex-wrap: nowrap;
  box-sizing: border-box;
  align-items: center;
  overflow-x: auto;
}
.nds-grid-sheet .nds-toolbar > * { max-width: 100%; flex-shrink: 0; }
.nds-grid-sheet .nds-toolbar > .cnt { white-space: nowrap; }
.nds-grid-sheet .nds-toolbar > .grow { display: none; }
.nds-grid-sheet .nds-toolbar > .nds-grid-search { flex: 1 1 180px; min-width: 80px; max-width: 340px; }
.nds-grid-sheet .nds-toolbar .nds-grid-search .nds-field { width: 100%; }
.nds-grid-sheet .nds-toolbar .nds-grid-views { min-width: 0; flex-wrap: nowrap; }
.nds-grid-sheet .nds-toolbar .nds-grid-views .nds-btn { white-space: nowrap; }
.nds-sheet-toolbar-actions {
  display: flex;
  flex-wrap: nowrap;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  margin-inline-start: auto;
  min-width: 0;
}
.nds-sheet-toolbar-actions > * { flex-shrink: 0; }
@media (max-width: 1279px) {
  .nds-grid-sheet .nds-toolbar { height: auto; flex-basis: auto; flex-wrap: wrap; padding-block: 6px; overflow-x: visible; }
  .nds-grid-sheet .nds-toolbar .nds-grid-views, .nds-grid-sheet .nds-sheet-toolbar-actions { flex-wrap: wrap; }
}
/* 🔴 The pill override that used to live here is GONE, and the reason it existed was wrong.
   I wrote that `.nds-pill` was oversized because an inline `<svg>` sat on the baseline and dragged
   the descender space with it. **That was reasoning, not a measurement** — I inferred a plausible
   mechanism from the numbers and stated it as the cause. DS.2 measured it: the app's reset declares
   `svg { display: block }`, so the icon took a LINE OF ITS OWN above the label. The tell was there
   and I did not look for it — a block-level child adds height and no width, and the pill measured
   43.75px wide with and without the icon.
   Fixed at the base (`.nds-pill { display: inline-flex; align-items: center; gap: 4px }`), so this
   band needs no override; the `caps` pill now passes `size="md"`, the size `Pill` documents for a
   toolbar. `sm` looked right only because, with an icon, it rendered TALLER than `md`. */
/* 🔴 The 40px band is bought by RE-SCOPING the shared slot height, not by overriding the field.
   `--nds-grid-toolbar-slot-h` (36px above) exists so the search field and the selection cluster
   that replaces it sit on ONE floor — the comment there records a measured half-pixel step when
   they disagreed. Setting the variable on the sheet keeps that invariant exactly (both halves still
   read the same number) and changes only what the number is here. Overriding `.nds-field`'s height
   directly would have hit 40px and quietly reintroduced the step on every selection toggle. */
.nds-grid-sheet { --nds-grid-toolbar-slot-h: 28px; }

/* ─────────────────────────────────────────────────────────────────────────────────────────────
   AG's popup layer, on the DS scale (AG.1, hub #232 · DS.1's ruling · DS.2's measurement).

   AG ships `.ag-popup-child { z-index: 5 }` in its own stylesheet — measured, at
   `ag-grid-community/styles/_css-content.scss:2771`. That 5 is exactly `--nds-z-sticky`, which puts
   every AG column menu, filter popup and rich-select list BELOW the rail (50) and the top bar (60).
   Nothing is visibly broken today only because AG's menus are short and bottom-anchored; the first
   taller menu near the rail would render underneath it.

   🔴 There is NO Theming API parameter for this. The ruling asked for `popupZIndex` "or whichever
   knob the theme exposes" — measured, AG 36.1 exposes `popupShadow` and no z-index param at all
   (grepped its own bundle for `*[zZ]Index*`: one internal hit, no theme key). So the DS token has to
   reach it through CSS, and this stylesheet is the one place permitted to address `.ag-*`.

   Deliberately UNSCOPED. The popup is portalled out of the grid wrapper to `popupParent`
   (`document.body`), so `.nds-ag-nexus .ag-popup-child` would match nothing — the same
   matches-nothing trap DS.1 hit with `.ag-rich-select .ag-virtual-list-viewport`. Every AG popup in
   the app moves together, which is the point: one popup layer, not two conventions.
   ───────────────────────────────────────────────────────────────────────────────────────────── */
.ag-popup-child {
  z-index: var(--nds-z-popover, 1450);
}

/* ── AM.1 §A.3 — list and measure cells + their popup editors (2026-09-05) ─────────────────────────
   Tokens: every one below is used elsewhere in this sheet (`--nds-surface`, `--nds-text`,
   `--nds-border`, `--nds-radius-md`, `--nds-shadow-pop`, `--nds-space-1/2`, `--nds-grid-muted-fg`).
   The chip inside a 36px row is COMPACT: the DS token's 3px/9px padding would make it 24px tall
   against the cell's 18px content box (`reference_clip_rect_is_the_padding_box`). */
.nds-cell-list { display: inline-flex; align-items: center; gap: 4px; min-width: 0; max-width: 100%; overflow: hidden; }
/* 🔴 The list's value chips are `.nds-cell-listchip`, NEVER `.nds-cell-chip` (Owner, 2026-09-05: "N."
   where "Non applicabile" should read). `.nds-cell-chip` is the 20×20 identity/targeting BADGE above;
   its fixed width squeezed every list value to one letter and its ellipsis. A shared class name is a
   shared size — the list token takes its width from its text and its HEIGHT from this rule alone. */
.nds-cell-list .nds-token { flex: 0 1 auto; min-width: 0; max-width: 160px; height: 20px; }
.nds-cell-list .nds-token > .t { padding: 0 6px; line-height: 16px; font-size: 12px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; display: block; }
.nds-cell-list-more { flex: none; font-size: 11px; color: var(--nds-grid-muted-fg); }
.nds-cell-measure { display: inline-flex; align-items: baseline; gap: 4px; min-width: 0; }
.nds-cell-measure .u { font-size: 12px; color: var(--nds-grid-muted-fg); }
.nds-list-editor, .nds-measure-editor {
  display: flex; flex-direction: column; gap: var(--nds-space-1);
  padding: var(--nds-space-2); box-sizing: border-box; min-width: 0;
  background: var(--nds-surface); color: var(--nds-text);
  border: 1px solid var(--nds-border); border-radius: var(--nds-radius-md);
  box-shadow: var(--nds-shadow-pop);
}
.nds-list-editor { overflow: auto; }
.nds-list-editor-count { font-size: 11px; color: var(--nds-grid-muted-fg); }
.nds-measure-editor .nds-field { width: 100%; }


/* Formula editors share one compact anatomy: field, tools, suggestions, result, fixed actions.
   Scroll only the body and never flex-shrink its children into overlapping rectangles. */
.nds-formula-editor { max-height: min(440px, 75dvh); overflow: hidden; }
.nds-formula-body {
  display: flex; flex-direction: column; gap: var(--nds-space-8);
  min-height: 0; overflow: auto; padding: var(--nds-space-10);
}
.nds-formula-body > * { flex-shrink: 0; min-width: 0; }
.nds-formula-help {
  font-size: var(--nds-font-size-sm); color: var(--nds-text);
  line-height: 1.5; overflow-wrap: anywhere;
}
.nds-formula-help code { font-family: var(--nds-font-mono); }
.nds-formula-actions {
  display: flex; flex: none; align-items: center; justify-content: flex-end; flex-wrap: wrap;
  gap: var(--nds-space-8); padding: var(--nds-space-8) var(--nds-space-10);
  border-top: 1px solid var(--nds-border-subtle);
}
.nds-formula-actions > span { flex: 1 1 80px; color: var(--nds-text); font-size: var(--nds-font-size-xs); }
.nds-formula-composer > .nds-formula-actions { padding-inline: 0; }
.nds-formula-editor .nds-formula-preview,
.nds-formula-composer .nds-formula-preview {
  font-family: var(--nds-font-sans); font-size: var(--nds-font-size-sm); line-height: 1.5;
  white-space: normal; overflow-wrap: anywhere; border: 0; padding: 0;
}
.nds-formula-editor .nds-formula-hint, .nds-formula-composer .nds-formula-hint { flex-wrap: wrap; }
@media (forced-colors: active) {
  .nds-formula-editor .nds-field input.nds-formula-input.highlighted { color: FieldText; }
  .nds-formula-overlay { display: none; }
}

/* Shared formula assistance: grid, drawer, and bulk editor. */
.nds-formula-composer, .nds-formula-guidance { display: flex; flex-direction: column; gap: var(--nds-space-8); min-width: 0; }
.nds-formula-composer > *, .nds-formula-guidance > * { flex-shrink: 0; }
.nds-formula-guidance { color: var(--nds-text); font-size: var(--nds-font-size-sm); }
.nds-formula-tools { display: flex; flex-wrap: wrap; align-items: center; gap: var(--nds-space-4); }
.nds-formula-tools .nds-field { flex: 1; min-width: 100px; }
.nds-formula-help-panel {
  display: flex; flex-direction: column; gap: var(--nds-space-6); padding: var(--nds-space-10);
  background: var(--nds-surface-sunken); border-radius: var(--nds-radius-md); line-height: 1.5;
  overflow-wrap: anywhere;
}
.nds-formula-help-panel code { font-family: var(--nds-font-mono); }
.nds-formula-text-builder { gap: var(--nds-space-8); }
.nds-readable .nds-fx-ident { color: var(--nds-text); font-weight: 600; }

/* ── ProjectionCell (VP.5, Variants page §3.3) ──────────────────────────────────────────────
   One variant row × one channel coordinate: [tick 15px] [dot 7px] word … mono detail · note.
   Numbers read off the approved canvas (artboard 1): gap 6, dot 7px, hollow = a 1.5px inset
   ring rather than a fill, detail mono 12px, note 11px muted. Measured light / dark: the word
   15.48 / 12.73, a muted word 5.32 / 7.38, the success dot 3.30 / 4.62, the danger dot
   3.91 / 3.89, the hollow ring 3.62 / 4.98 — AA text and AA non-text in both themes. Every
   colour is a semantic token that `.dark` already redefines, so there is no alias to restate. */
.nds-projcell {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  min-width: 0;
  color: var(--nds-text);
}
/* A row that is not participating on this coordinate reads quiet — the WORD goes muted, never
   the tick, which is the one live control on an excluded row (§4.3). */
.nds-projcell.muted .nds-projcell-word {
  color: var(--nds-text-muted);
}
.nds-projcell-check {
  flex: none;
  gap: 0;
}
/* HELD, not disabled: the input keeps its focus and its click so it can deliver the reason in
   `title` (`scripts/check-silent-disabled.mjs`). 0.62 is `.nds-btn[aria-disabled]`'s own hold,
   so a refusing tick and a refusing button look equally refused. */
.nds-projcell.held .nds-projcell-check,
.nds-projcell.held .nds-projcell-check input {
  opacity: 0.62;
  cursor: default;
}
.nds-projcell-dot {
  width: 7px;
  height: 7px;
  border-radius: var(--nds-radius-round);
  flex: none;
}
.nds-projcell-dot.solid[data-tone='success'] { background: var(--nds-success); }
.nds-projcell-dot.solid[data-tone='warning'] { background: var(--nds-warning); }
.nds-projcell-dot.solid[data-tone='danger'] { background: var(--nds-danger); }
.nds-projcell-dot.solid[data-tone='info'] { background: var(--nds-primary); }
.nds-projcell-dot.solid[data-tone='neutral'] { background: var(--nds-text-3); }
/* A ring, not a pale fill: "included but not published" is a state in progress, and a filled
   grey dot would read as a fifth status colour instead of the absence of one. */
.nds-projcell-dot.hollow { box-shadow: inset 0 0 0 1.5px var(--nds-text-3); }
.nds-projcell-word {
  flex-shrink: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.nds-projcell-detail {
  font-family: var(--nds-font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-size: var(--nds-font-size-sm);
  overflow: hidden;
  text-overflow: ellipsis;
}
/* The right-hand slot belongs to whichever of the two is last: a variant row carries the mono id
   alone and it sits right; a parent row carries the id AND a note, and then the id leads while
   the note takes the edge (the canvas's `Parent ASIN`, `1 listing`). */
.nds-projcell-detail:last-child,
.nds-projcell-note {
  margin-left: auto;
}
.nds-projcell-note {
  flex: none;
  font-size: var(--nds-font-size-xs);
  color: var(--nds-text-muted);
}

/* ── a QUIET row (VP.5, Variants page §4.3) ─────────────────────────────────────────────────
   "Excluded rows render their mapped values muted; the checkbox is the only live control on
   them." A row state, so it belongs to the engine: a page that reaches for `.ag-cell` from its
   own stylesheet fails `scripts/check-ag-grid-import-boundary.mjs`, and the rule for grid chrome
   is that it lives here (feedback_grid_chrome_lives_in_the_engine). Apply with AG's
   `rowClassRules: { 'nds-row-is-quiet': (p) => …excluded… }`.

   A cell opts OUT with `cellClass: 'nds-cell-full-strength'` — the identity band, which names the
   row and must stay readable, and any column carrying the control that undoes the state. Opting
   out by class rather than by `:not(.nds-cell-identity)`, because that class sits on a DIV INSIDE
   the cell: every `.ag-cell` satisfies `:not(.nds-cell-identity)` and the identity would be muted
   with everything else. */
.nds-ag-wrap .ag-row.nds-row-is-quiet .ag-cell {
  color: var(--nds-grid-muted-fg);
}
.nds-ag-wrap .ag-row.nds-row-is-quiet .ag-cell.nds-cell-full-strength {
  color: var(--nds-grid-cell-fg);
}
/* An include that has been painted optimistically and has not landed. It is also HELD (a second
   click cannot race the first write), so the hold above already dims the tick; this marks the
   whole cell so a caller can find it, and `aria-busy` says the same thing to a screen reader. */
.nds-projcell.busy {
  cursor: progress;
}

.nds-grid-sheet .nds-toolbar { container-type: inline-size; container-name: nds-sheet-toolbar; }
@container nds-sheet-toolbar (max-width: 900px) {
  .nds-toolbar .nds-fchip-full { display: none; }
  .nds-fchip .nds-fchip-compact { display: inline; }
}

/* Formula-aware value mode retains the sheet long-text sizing contract. */
.ag-popup-editor .nds-formula-fieldwrap textarea { resize: none; overflow-y: auto; }

