// ── Components ─────────────────────────────────────────────────
function FieldPair({
  label,
  hint,
  master,
  masterEmpty,
  value,
  onChange,
  as,
  rows,
}: {
  label: string
  hint?: string
  master: string
  masterEmpty: string
  value: string
  onChange: (v: string) => void
  as: 'input' | 'textarea'
  rows?: number
}) {
  const masterIsEmpty = master.trim().length === 0
  return (
    <div className="space-y-1.5">
      <div className="text-base font-medium text-slate-700 dark:text-slate-300">
        {label}
      </div>
      {hint && (
        <div className="text-xs text-slate-500 dark:text-slate-400">
          {hint}
        </div>
      )}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
        <div>
          <div className="text-[10px] uppercase tracking-wider text-slate-500 dark:text-slate-400 mb-1">
            Master · IT
          </div>
          <div
            className={cn(
              'rounded-md border px-3 py-2 text-md whitespace-pre-wrap break-words bg-slate-50 dark:bg-slate-900/40',
              masterIsEmpty
                ? 'border-dashed border-default dark:border-slate-800 italic text-slate-500 dark:text-slate-500'
                : 'border-default dark:border-slate-800 text-slate-700 dark:text-slate-300',
            )}
            style={{ minHeight: as === 'textarea' ? '8rem' : '2.25rem' }}
          >
            {masterIsEmpty ? masterEmpty : master}
          </div>
        </div>
        <div>
          <div className="text-[10px] uppercase tracking-wider text-slate-500 dark:text-slate-400 mb-1">
            Translation
          </div>
          {as === 'input' ? (
            <Input value={value} onChange={(e) => onChange(e.target.value)} />
          ) : (
            <textarea
              rows={rows ?? 5}
              value={value}
              onChange={(e) => onChange(e.target.value)}
              className="w-full rounded-md border border-default dark:border-slate-700 hover:border-slate-300 dark:hover:border-slate-600 bg-white dark:bg-slate-900 text-md text-slate-900 dark:text-slate-100 px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-colors font-sans"
            />
          )}
        </div>
      </div>
    </div>
  )
}

function CompletenessBadge({
  percent,
  t,
}: {
  percent: number
  t: (key: string, vars?: Record<string, string | number>) => string
}) {
  const variant: 'success' | 'warning' | 'danger' | 'default' =
    percent === 100
      ? 'success'
      : percent >= 50
        ? 'warning'
        : percent === 0
          ? 'danger'
          : 'default'
  return (
    <Badge variant={variant}>
      {t('products.edit.locales.percent', { value: percent })}
    </Badge>
  )
}

function SourceBadge({
  source,
  model,
  t,
}: {
  source: string | null
  model: string | null
  t: (key: string) => string
}) {
  if (!source) return null
  if (source === 'manual') {
    return <Badge variant="default">{t('products.edit.locales.sourceManual')}</Badge>
  }
  if (source.startsWith('ai-')) {
    const provider = source.slice(3)
    return (
      <Badge variant="info" mono>
        {provider}
        {model ? ` · ${model.split('-').slice(0, 2).join('-')}` : ''}
      </Badge>
    )
  }
  return <Badge variant="default">{source}</Badge>
}

function ReviewBadge({
  reviewedAt,
  source,
  t,
}: {
  reviewedAt: string | null
  source: string | null
  t: (key: string) => string
}) {
  if (!source?.startsWith('ai-')) return null
  if (reviewedAt) {
    return (
      <Badge variant="success">{t('products.edit.locales.reviewed')}</Badge>
    )
  }
  return <Badge variant="warning">{t('products.edit.locales.unreviewed')}</Badge>
}

