/** The tree control and the P/C mark. The NAME is an editable column and is not repeated here. */
function ProductCell(
  p: ICellRendererParams<StudioRow> & {
    secondaryRef?: { current: SecondaryPlan }
    rowMenuRef?: { current: (row: StudioRow) => MenuItemDef[] }
  },
) {
  const expanded = useExpanded(p.node)
  const d = p.data
  if (!d) return null
  const parent = d.isParent
  const expander =
    parent && d.childCount > 0 ? (
      <ExpandButton expanded={expanded} onToggle={() => p.node.setExpanded(!expanded)} labels={['Expand children', 'Collapse children']} />
    ) : (
      <ExpandSlot />
    )
  const role = <ProductRoleChip product={d} />

  /*
   * Ruling #169 — "the picture on the left" — and #710: the picture, the key, the second line and
   * the readiness reading are ONE band now, drawn by the engine's `IdentityBand` so this scope and
   * every channel scope render the same row. There is no longer a branch for "has an image": the
   * band takes `noImage` and lays out the rest identically either way, which is what stops the two
   * cases drifting into two layouts.
   *
   * 🔴 Still gated on the row actually HAVING an image. The studio contract does not supply one yet
   * (measured: no `imageUrl` on any row, no image column among the 102), and an ungated thumbnail
   * would put a grey placeholder on every row — the empty-column complaint that reopened this lane.
   *
   * 🔴 An INHERITED face image is MARKED, not silently passed off as the row's own: 74 of 301
   * children have no image of their own (PES.5), so the parent's picture stands in. The mark is the
   * sheet's existing `inherited` provenance — one idea, one vocabulary — and the photo count is
   * suppressed with it, because "8 photos" would be a claim about images this row does not have.
   */
  /* One call, one line — computed here rather than twice in the JSX. */
  const line = p.secondaryRef ? identitySecondary(d, p.secondaryRef.current) : d.name

  return (
    <IdentityBand
      expand={expander}
      role={role}
      image={d.imageUrl}
      photoCount={d.imageInherited ? undefined : d.photoCount}
      noImage={!d.imageUrl}
      imageMark={
        d.imageInherited ? (
          <ProvenanceMark provenance="inherited" from="the family's picture — this variation has none of its own" />
        ) : null
      }
      sku={d.sku}
      /* Axis values when the FAMILY is fully covered, else the name — one kind of sentence per
         column, decided once (#716). `identitySecondary` holds the rule and the reasons. */
      secondary={line}
      secondaryTitle={line ?? undefined}
      menuItems={p.rowMenuRef?.current(d)}
      menuLabel={`Actions for ${d.sku}`}
      trailing={
        /* No `state`: master completeness is a RATIO with no readiness behind it, so the pill
           paints neutral and says so, rather than inventing a colour from the percentage (#43). */
        <CompletenessPill
          pct={d.completeness.overall.pct}
          tip={`${d.completeness.overall.pct}% — filled ÷ applicable master attributes`}
        />
      }
    />
  )
}

/** Identity stays visible and pinned while attribute columns are rearranged. */
const DEFAULT_LOCKED_COLUMNS: readonly string[] = ['product']

/** Search remains page state; confirmed layouts are persisted separately by useSheetColumns. */
interface SheetPageState {
  search: string
}

/**
 * 🔴 A module-level constant, NOT `= []` in the signature.
 *
 * A default parameter is evaluated on every call, so `variationAxes = []` handed this component a
 * BRAND NEW ARRAY on every render where the prop was omitted — which is every render, since the
 * studio does not pass it. That identity fed `viewCtx` (deps `[sheet, locale, variationAxes]`),
 * which fed `columnDefs`, which made AG re-render every mounted cell.
 *
 * Measured, after two wrong guesses: I first reasoned from the dependency list that `columnDefs`
 * was stable on dock open (it was not — FE.1 profiled `CellComp` 756 across three commits), then
 * fixed two other props that genuinely did re-identify and did not fix this. Bisecting the memo's
 * five deps with an in-page probe named `viewCtx`, and drilling one level named `variationAxes`.
 * **Neither of my two hypotheses, nor FE.1's named suspect (`openRecordId`), was the cause.**
 */
const NO_VARIATION_AXES: readonly string[] = []

export function MasterSheet({ productId, market, locale, variationAxes = NO_VARIATION_AXES as string[] }: MasterSheetProps) {
  const { apiRef, gridApi: gridReady, getApi: getGridApi, bind: bindGridApi, onGridPreDestroyed: releaseGrid } = useGridLifetime<GridApi<StudioRow>>()
  const reporter = useSaveReporter()
  const record = useStudioRecord()
  /**
   * 🔴 D2 (#356) — why these two are read through a ref.
   *
   * MEASURED: opening the dock changes **nothing** about the grid's geometry. Viewport 1660, root
   * 1660, sheet 1662, 294 cells, 28 columns — identical with the dock closed and open, with the
   * slide-over confirmed present. §5.1 holds: the sheet really is undisplaced. So the 189-cell
   * repaint FE.1 profiled is **not** a response to a resize; something was telling AG the grid had
   * changed.
   *
   * It was these two props. `record` is a context value whose identity changes when `rowId` does —
   * i.e. on every dock open and close — and it reached the grid twice: through `onCellKeyDown`, and
   * through `getContextMenuItems` (via `famActions`, which legitimately needs `record.rowId` as
   * DATA so a verb can refuse the row already open). AG then re-rendered every mounted cell.
   *
   * 🔴 **And this is where my own banked note nearly stopped the investigation.** AG.1 measured that
   * a new `getContextMenuItems` identity fires **0** column-model events, which is true — and I had
   * it written down as "memoise it for tidiness, not for correctness". A column-model rebuild and a
   * React repaint are **different costs**, and measuring the absence of one says nothing about the
   * other. The note now says so.
   *
   * Both are invoked ON DEMAND — a right-click, a keypress — so the latest logic through a ref is
   * exactly right, and neither has any reason to re-identify.
   */
  const recordRef = useRef(record)
  recordRef.current = record

  /**
   * PES.4 §5.4 — "the cell the record would be opened from".
   *
   * 🔴 NOT `getFocusedCell()` read when the verb runs. PES.3 measured why: clicking the `⋯` button
   * MOVES AG's focus to the actions cell, so the verb read `cell=actions` — a pinned, always-visible
   * column — `isCellCovered` answered "not covered", and the whole reveal was inert while looking
   * implemented. `isRevealAnchor` is their rule, lifted into the drawer barrel at #227 so master and
   * channel share ONE definition of what counts as chrome rather than each keeping a list.
   */
  /**
   * 🔴 A REFUSED OPEN GESTURE MUST SAY WHY — ruling 1's second half, 2026-09-03.
   *
   * MEASURED before this existed, on `condition_type` (`editable: false` on the wire, made visible
   * through Customise), master·DE: double-click, Enter, F2 and a typed character each produced
   * **0 editors, 0 toasts, no `title`, nothing new on screen.** Four gestures, four silences — and
   * an operator cannot tell that apart from a broken sheet, which is precisely how the fill-handle
   * defect above went two days without being called one.
   *
   * The words come from `editRefusalReason`, which is DERIVED from `cellIsEditable` rather than
   * restated beside it and is held to that by a test over every combination of the four vetoes: a
   * reason exists for exactly the cells AG refuses. A second predicate one line away would drift,
   * and both directions of drift are invisible — silence where the cell is locked, or an
   * explanation for a refusal that never happened.
   *
   * A DS toast, not an in-cell note: `StudioClient` already mounts `ToastProvider` for this subtree
   * (the root layout's is the OLD library's context and `useToast` throws against it), it is this
   * app's established answer for "an outcome happened", and it changes no cell geometry — a new
   * in-cell surface is a design decision and design authority is the Owner's. **Stated for the
   * Owner: the words are the cell's, the surface is mine, and moving them into the cell is a change
   * of one call.**
   */
  const { toast } = useToast()
  /* Chrome is silent by construction: `ag-Grid-AutoColumn` and the `ready:*` columns are built by
     this sheet and are in no `SheetColumn`, so the lookup misses and nothing is said. Enter on the
     identity cell keeps meaning "open the record" — see `onCellKeyDown`. */
  const columnByKeyRef = useRef<Map<string, SheetColumn>>(new Map())
  /* 🔴 The last thing said, and when. Without it a locked cell answers ONCE PER KEYSTROKE — an
     operator typing five characters into a read-only cell would get five identical toasts stacked
     on top of each other, which is not an explanation, it is a fault of its own. */
  const lastSaid = useRef<{ text: string; at: number }>({ text: '', at: 0 })
  const sayWhyRefused = useCallback(
    (colId: string | undefined, data: StudioRow | undefined): boolean => {
      if (!colId || !data || colId === PRODUCT_MEDIA_COLUMN) return false
      const col = columnByKeyRef.current.get(colId)
      if (!col) return false
      const why = editRefusalReason(col, data)
      if (!why) return false
      const now = Date.now()
      if (lastSaid.current.text === why && now - lastSaid.current.at < 2500) return true
      lastSaid.current = { text: why, at: now }
      toast(why, 'info')
      return true
    },
    [toast],
  )
  /* Invoked on a gesture, so a ref keeps the grid handlers' identity stable — the same reason
     `recordRef` above exists. */
  const sayWhyRefusedRef = useRef(sayWhyRefused)
  sayWhyRefusedRef.current = sayWhyRefused
  const onCellDoubleClicked = useCallback(
    (e: { column?: { getColId(): string } | null; data?: StudioRow }) => {
      sayWhyRefusedRef.current(e.column?.getColId?.(), e.data)
    },
    [],
  )

  const lastDataCell = useRef<string | null>(null)
  const onCellFocused = useCallback((e: { column?: { getColId(): string } | string | null }) => {
    // 🔴 AG types this `Column | string | null` — it really can hand back a bare colId. Reading only
    // `.getColId()` made every string arrive as `undefined`, i.e. "this is chrome", which would have
    // cleared the anchor on exactly the focus events that should set it.
    const col = e.column
    const colId = typeof col === 'string' ? col : col?.getColId?.()
    if (isRevealAnchor(colId)) lastDataCell.current = colId ?? null
  }, [])

  const onWriteStart = useCallback((id: string, rowId: string) => reporter.pending(id, rowId), [reporter])
  const onWriteEnd = useCallback((id: string, ok: boolean, msg?: string, rowId?: string) => reporter.resolved(id, ok, msg, rowId), [reporter])
  /* The ONLY writer of the save clock (#705). `onSettled` fires for every settled batch including
     refusals — `sheetWriter.ts:371` passes `ok` precisely so a caller can tell them apart. */
  const onSettled = useCallback(({ ok, savedAt }: { rowId: string; ok: boolean; savedAt: string }) => {
    if (ok) setLastSavedAt(savedAt)
  }, [])

  const { sheet: loadedSheet, loading, error, contractProblems, reload, refresh, writer, tracker, conflicts, bindGrid } = useMasterSheet({
    productId, market, locale, onWriteStart, onWriteEnd, onSettled,
  })
  const sheet = useReferenceNames(loadedSheet, 'MASTER', market)
  /**
   * D16 — cell formulas (#730). The endpoints live in the hook; the editor is the engine's and
   * knows no URLs. See `useCellFormulas` for why the split is a measurement and not a preference.
   */
  const formulaRowIds = useMemo(() => (sheet?.rows ?? []).map((r) => r.id), [sheet])
  const formulas = useCellFormulas({ writeFacts: (rowId, fieldKey) => sheet?.rows.find(row => row.id === rowId)?.values[fieldKey], productId, market, locale, rowIds: formulaRowIds, onSettled: refresh, onValueSaved: (rowId, fieldKey, value) => {
      const node = getGridApi()?.getRowNode(rowId)
      if (!node?.data) return
      const cell = node.data.values?.[fieldKey]
      if (cell) node.data.values = { ...node.data.values, [fieldKey]: { ...cell, value } }
      getGridApi()?.refreshCells({ rowNodes: [node], columns: [fieldKey], force: true })
    } })

  /**
   * What a `$reference` can name on this row, WITH the value it currently holds.
   *
   * 🔴 Built from the sheet's own columns, so the list is exactly what the operator can see on the
   * row in front of them. It is a TYPING AID and not a verdict: the server resolves against the
   * full per-market key set (#728/#729) and its `unknownRefs` overrides this the moment it answers
   * (`unknownRefNames`). Deriving "unknown" from this list alone would mark a good reference red
   * because the sheet happens to be filtered.
   */
  const candidatesFor = useCallback(
    (row: StudioRow): FormulaCandidate[] => {
      const cols = (sheet?.columns ?? []).map((c) => {
        const cell = cellOf(row, c.key)
        const v = cell?.value
        return {
          name: c.key,
          kind: 'field' as const,
          label: c.label,
          group: 'Columns',
          /* Absent rather than `''` for an empty cell — the editor draws no chip for a field with
             no value, and an empty chip and a missing one look identical while meaning different
             things. */
          value: v == null || v === '' ? undefined : String(v),
        }
      })
      const fns = formulas.functions.map((f) => ({
        name: f.name,
        kind: 'function' as const,
        label: f.signature,
        group: 'Functions',
      }))
      return [...cols, ...fns]
    },
    [sheet, formulas.functions],
  )

  /* `$name` → the column to outline. The sheet's key IS the colId here, but it is looked up rather
     than assumed so a column the sheet does not build gets no outline instead of a stale one. */
  const colIdOfRef = useCallback(
    (name: string): string | null => {
      const hit = (sheet?.columns ?? []).find((c) => c.key.toLowerCase() === name.toLowerCase())
      return hit ? hit.key : null
    },
    [sheet],
  )

  /**
   * 🔴 Identity-STABLE, reading through a ref — never a fresh object per render.
   *
   * This goes into `buildMasterColumns`, and a new `columnDefs` identity makes AG re-run its whole
   * column model and take the operator's widths and order with it. Both halves of this arrive
   * asynchronously (the function docs and the family's formulas), so a value-carrying object would
   * rebuild 102 column definitions twice on every load. `cellEditorParams` runs when an editor
   * opens, so the ref read there is the freshest one available, not a stale one.
   */
  const formulaLive = useRef({ candidatesFor, formulas, colIdOfRef })
  formulaLive.current = { candidatesFor, formulas, colIdOfRef }
  const formulaWiring = useMemo(
    () => ({
      candidatesFor: (row: StudioRow) => formulaLive.current.candidatesFor(row),
      preview: (rowId: string, fieldKey: string, expr: string, signal?: AbortSignal) => formulaLive.current.formulas.preview(rowId, fieldKey, expr, signal),
      functions: () => formulaLive.current.formulas.functions,
      replaceFormula: (rowId: string, fieldKey: string, value: unknown) => formulaLive.current.formulas.replace(rowId, fieldKey, value),
      unavailableReason: () => formulaLive.current.formulas.loadError ?? (formulaLive.current.formulas.ready ? null : 'Loading formulas…'),
      retry: () => formulaLive.current.formulas.reload(),
      sourceLabel: () => formulaLive.current.formulas.sourceLabel,
      exprFor: (rowId: string, fieldKey: string) => formulaLive.current.formulas.exprFor(rowId, fieldKey),
      /* #780 — same ref-read discipline as `exprFor`: the refusal arrives with the formula batch,
         after first paint, and must not rebuild a hundred column definitions to become visible. */
      errorFor: (rowId: string, fieldKey: string) => formulaLive.current.formulas.errorFor(rowId, fieldKey),
      colIdOfRef: (name: string) => formulaLive.current.colIdOfRef(name),
    }),
    [],
  )
  const formulaClipboard = useMemo(() => formulaTransfer<StudioRow>({
    exprFor: (row, key) => formulaWiring.exprFor(row.id, key),
  }), [formulaWiring])


  // F1 — the family overview (audit row 6.16). Its own read; see useFamily for why not the sheet's.
  const familyQuery = useFamily(productId)
  // The DESCRIPTOR half of the folded family bar (§2.1c) — derived from F1's read, rendered in the
  // toolbar's count slot. Derived, never stored: a second copy is a second thing to leave stale.
  const familySummary = familySummaryOf(familyQuery.family, familyQuery.loading)
  // F2 — the family VERBS. Permission is an input rather than a guess: unlink is served from
  // /api/amazon and gated by `channels.sync`, while the other three want `pim.manage`, so an
  // operator can genuinely hold one set and not the other (see familyActions' header).
  const { has, status: authStatus } = useAuth()
  // `has` is rebuilt on every AuthProvider render, so depending on it directly defeats the memo
  // below and re-renders both memo'd bars for nothing. The ANSWERS are stable; the function is not.
  // F4's COLLECT result. Held by the host rather than the bar because it is an INPUT to the verb,
  // and the verb is built here — a copy in the bar would be a second source for what gets created.
  const [newVariation, setNewVariation] = useState<NewVariationDraft | null>(null)
  const familyProductPicker = useFamilyProductPicker(productId)
  const canPim = has('pim.manage')
  const canSync = has('channels.sync')
  const canEdit = has('products.edit')
  const famActions = useMemo(
    () =>
      familyActions({
        family: familyQuery.family,
        ops: familyOps,
        can: (p) => (p === 'pim.manage' ? canPim : p === 'channels.sync' ? canSync : p === 'products.edit' ? canEdit : has(p)),
        authStatus,
        pickProduct: familyProductPicker.pick,
        pending: newVariation ? { newVariation } : undefined,
        openRecord: (rowId) => record.open(rowId, lastDataCell.current ?? undefined),
        openRecordId: record.rowId,
      }),
    // eslint-disable-next-line react-hooks/exhaustive-deps -- `has` is intentionally excluded; the
    // three booleans above are what actually change, and `has` changes identity every render.
    [familyQuery.family, canPim, canSync, canEdit, authStatus, newVariation, record, familyProductPicker.pick],
  )
  /**
   * Ruling #141 — the row's right-click menu, reading the SAME registry the family bar and the
   * selection bar read. Not a second list: `actionsFor(…, ROW, [row])` filters the one declaration,
   * so a verb cannot be offered here and refused there.
   *
   * Memoised because a memo whose dependency changes every render never caches, which
   * makes it a memo in name only. 🔴 NOT because it rebuilds AG's column model — AG.1 measured that
   * on 36.1 with a positive control: a new `getContextMenuItems` identity produces 0
   * `newColumnsLoaded` / 0 `columnEverythingChanged` / 0 `displayedColumnsChanged`, versus 1/1/1 for
   * `columnDefs`. The banked trap is real for column DEFS and I over-generalised it to callbacks
   * (ruling #192). The memo stays on its true reason; the false one is worse than none because the
   * next reader would trust it.
   */
  // A ref rather than the callback itself: `onFamilyChanged` is declared below (it needs `reload`),
  // and threading the value through a ref keeps the press handler's identity stable so the memo
  // above keeps a stable identity rather than churning on every reload closure.
  const onFamilyChangedRef = useRef<() => void>(() => {})
  const rowPress = useActionPress<StudioRow>(() => onFamilyChangedRef.current())

  /*
   * The SAME verbs the right-click offers, in the band's `⋯` (#724) — through the same adapter, so
   * the two surfaces cannot drift into different menus for one row. `actionMenuItems` returns a
   * per-row builder; the band calls it for the row it is drawing.
   *
   * 🔴 Through a REF for the reason the secondary plan is: the band's column def is memoised on
   * `[lockedColumns]`, so a value here would freeze at first render or, in the deps, rebuild the
   * column on every action change.
   */
  const rowMenuRef = useRef<(row: StudioRow) => MenuItemDef[]>(() => [])
  rowMenuRef.current = useMemo(
    () =>
      actionMenuItems<StudioRow>({
        actions: famActions,
        onSelect: (action, rows) => void rowPress.press(action, rows),
        isRecord: (r) => !!r?.id,
      }),
    [famActions, rowPress.press],
  )

  const getContextMenuItems = useMemo(
    () =>
      actionContextMenu<StudioRow>({
        actions: famActions,
        onSelect: (action, rows) => void rowPress.press(action, rows),
        // The parent row IS a record here — the sheet's tree puts it in the grid — so every row
        // qualifies. The verbs themselves refuse a parent where that matters.
        isRecord: (r) => !!r?.id,
      }),
    // 🔴 `rowPress.press`, NOT `rowPress`. `useActionPress` returns a fresh object literal on every
    // render, so depending on the object makes this memo recompute every time — and a
    // a memo that recomputes every render is not a memo. `press` is a `useCallback` and is stable.
    // (This used to cite an AG column-model rebuild; measured false for callbacks — see above.)
    [famActions, rowPress.press],
  )
  /**
   * The identity AG actually receives. `getContextMenuItems` above still re-computes when the dock
   * opens — `famActions` needs `record.rowId` — but the GRID must not see that, so this wrapper is
   * built once and reads the current menu builder at right-click time.
   */
  const contextMenuRef = useRef(getContextMenuItems)
  contextMenuRef.current = getContextMenuItems
  const stableContextMenu = useCallback<typeof getContextMenuItems>((p) => contextMenuRef.current(p), [])

  const onFamilyChanged = useCallback(() => { familyQuery.reload(); reload() }, [familyQuery, reload])
  onFamilyChangedRef.current = onFamilyChanged

  const [search, setSearch] = useState('')
  // F2 — the ROWS, not a count. A selection verb has to see what it would act on: `unlink` refuses
  // a row that is not a variation and says which ones, and a number cannot answer that.
  const [formulaHistoryOpen, setFormulaHistoryOpen] = useState(false)
  const [bulkFormulaRows, setBulkFormulaRows] = useState<Array<{ id: string; label: string }> | null>(null)
  const [selectedRows, setSelectedRows] = useState<StudioRow[]>([])
  const selected = selectedRows.length
  const [pending, setPending] = useState(0)
  const [refused, setRefused] = useState(0)
  const [refusedRowIds, setRefusedRowIds] = useState<ReadonlySet<string>>(() => new Set())
  const [offline, setOffline] = useState(false)
  /** Set by the footer's refusal note: narrow the sheet to the rows a write was refused on. */
  const [showRefusedOnly, setShowRefusedOnly] = useState(false)
  const [lastSavedAt, setLastSavedAt] = useState<string | null>(null)
  /* The structural identity pin only. The operator's column locks live on the
     grid as `pinned: 'left'` and are read from there — never mirrored here, because AG's header
     menu can write them and a mirror would go stale on the first "Pin left". */
  const [lockedColumns, setLockedColumns] = useState<string[]>([...DEFAULT_LOCKED_COLUMNS])
  const [prefsOpen, setPrefsOpen] = useState(false)
  const [prefsDraft, setPrefsDraft] = useState<PreferencesValue | null>(null)
  // 🔴 STATE, not just a ref. The landing effect below needs to run when the grid becomes ready,
  // and `onGridReady` writing a ref triggers no render — so with a ref alone the effect saw
  // `apiRef.current === null`, returned, and never ran again once the api existed. Measured: the
  // sheet kept whatever column state localStorage had and never applied its landing view.

  /**
   * 🔴 Repaint when the family's formulas ARRIVE. Without this the `ƒ` mark is correct and invisible.
   *
   * The mark is drawn from `exprFor`, read through a ref at paint time so a formula load cannot
   * rebuild a hundred column definitions. The cost of that choice is that a load changes no prop
   * AG watches, so nothing repaints — the batch resolves after the first paint and the mark misses
   * its own data. `exprFor`'s identity changes exactly when the map does, which is the one honest
   * signal available here.
   */
  useEffect(() => {
    if (!gridReady) return
    getGridApi()?.refreshCells({ force: true })
  }, [formulas.exprFor, formulas.errorFor, gridReady])

  const rows = useMemo(() => sheet?.rows ?? [], [sheet])
  const rowsRef = useRef<StudioRow[]>(rows)
  rowsRef.current = rows

  /* ── the writer's own counters, so the strip is the truth ───────────────────────────────── */
  useEffect(() => {
    const sync = () => {
      setPending(writer.pending)
      let r = 0
      const ids = new Set<string>()
      for (const row of rowsRef.current) {
        for (const col of sheet?.columns ?? []) {
          if (tracker.get(row.id, col.key)?.state === 'refused') { r++; ids.add(row.id) }
        }
      }
      setRefused(r)
      // The IDS, not just the count — `GridSheetNote`'s `onShow` is required by its type precisely
      // so a refusal cannot be a number you can only stare at, and a handler with nowhere to go
      // would satisfy the compiler while reproducing the bug.
      setRefusedRowIds(ids)
      // The outage is a PAGE fact, stated once, and it clears itself when a read answers — the
      // per-cell marks say what happened to each value; this says why none of them are moving.
      setOffline(writer.unreachable)
      /* Deliberately does NOT stamp: `prev ?? null` was a no-op that looked like an update, and a
         quiet writer means "nothing in flight", never "something just saved". The clock is written
         in one place only — the `onSettled` handler below, gated on `ok`. */
    }
    return writer.subscribe(sync)
  }, [writer, tracker, sheet])

  /*
   * 🔴 RELOAD ASKS BEFORE IT DISCARDS (#663). Measured on the sheet 2026-09-02: pressing Reload
   * with a refused edit replaced the operator's typed value with the stored one and LEFT the marks
   * — the cell stayed red, the footer said "1 cell blocked" and the header said "1 change not
   * saved", all three about a change that no longer existed. Two failures in one press: work
   * destroyed without asking, and marks outliving the values they describe.
   *
   * `writer.discard()` is the second half: it drops the queue WITHOUT sending it and clears the
   * tracker in the same call, so there is no way to do half of it.
   */
  const reloadConfirm = useActionConfirm()
  const onReload = useCallback(async () => {
    const impact = reloadImpact({ pending: writer.pending, refused, unknown: writer.unknownCount })
    if (!impact) {
      reload() // nothing typed is at risk — asking would teach them to dismiss dialogs
      return
    }
    if (!(await reloadConfirm.ask(impact))) return // cancel changes NOTHING, marks and typing intact
    /* 🔴 The header is a THIRD surface and it does not clear itself (#693). `writer.discard()`
       clears the queue and the tracker — the cell and the footer — but the frame's failure count
       is the frame's, and until it is told, it goes on reporting refusals for rows that no longer
       hold one. Measured: rows and footer clean, header still "2 changes not saved".
       Told BEFORE the discard, because `refusedRowIds` is derived from the tracker that
       `discard()` is about to empty. */
    reporter.cleared(sheet?.rows.map(row => row.id) ?? [...refusedRowIds])
    writer.discard()
    reload()
  }, [writer, refused, refusedRowIds, sheet, reporter, reload, reloadConfirm])

  /* ── views ──────────────────────────────────────────────────────────────────────────────── */

  /**
   * The server's field family MINUS the ids the sheet renders itself. Derived ONCE.
   *
   * 🔴 Every consumer must use this, not `sheet.columns`: the schema also contains `sku`, and the
   * sheet draws its own pinned `sku`. Two column defs with one colId makes AG silently rename the
   * second `sku_1` (#273, measured here) — after which every lookup keyed by the column's key
   * addresses a ghost while the grid still looks right. It also lets a VIEW name a key with no
   * built def. This was filtered at four separate call sites; one missed site was all it would have
   * taken, so it is one derivation now and the sites read from it.
   */
  const mediaEditor = useProductMediaEditor(refresh, locale)
  const mediaClipboard = useMemo(() => mediaGridTransfer(formulaClipboard, mediaEditor.actions), [formulaClipboard, mediaEditor.actions])
  const schemaColumns = useMemo(
    () => withProductMediaColumn(sheet?.columns ?? []).filter((c) => !RESERVED_COLUMN_IDS.includes(c.key as never)),
    [sheet],
  )

  const viewCtx = useMemo(
    () => ({
      variationAxes: sheet?.family.variationAxes?.length ? sheet.family.variationAxes : variationAxes,
      locale,
      // Rule 4 of the approved default view (#173): anything readiness flagged on a row IN VIEW.
      // Derived from the rows rather than assumed, because "which fields are in trouble" is a
      // fact about this family — measured on the sample, it is the GPSR pair on 104/120 rows,
      // and the server's own message says those can get a listing suppressed on EU marketplaces.
      flaggedKeys: flaggedColumnKeys(sheet?.rows),
    }),
    [sheet, locale, variationAxes],
  )

  /* ── the column set: views, landing, chips, Customise — ONE hook for BOTH scopes (V.7/V.8) ── */

  /* Filled here rather than at the ref's declaration: `schemaColumns` is defined below it, and the
     refusal words need the SheetColumn the wire actually sent, never a copy. */
  columnByKeyRef.current = useMemo(() => new Map(schemaColumns.map((c) => [c.key, c])), [schemaColumns])
  const allColumnKeys = useMemo(() => schemaColumns.map((c) => c.key), [schemaColumns])
  const customisableColumns = schemaColumns

  /** Identity is structural; attribute pins are read from the grid and saved in the layout. */
  const prefsBridge = useMemo<PrefsBridgeOptions>(
    () => ({
      columns: [
        { key: 'product', locked: true },
        ...allColumnKeys.map((k) => ({ key: k })),
      ],
      treeColumnKey: 'product',
    }),
    [allColumnKeys],
  )

  /* The frame's chip registry, read here because the column hook composes a chip with the active
     view (a chip narrows to its cells' columns; clearing it restores exactly the view it narrowed). */
  const chipBar = useViewChips()

  /**
   * Views, landing, the chip's column narrowing and the Customise dialog's apply all live in
   * `useSheetColumns` — the channel scope calls the same hook, so the two sheets cannot answer the
   * same question two ways (design V.8). It also owns `useGridState`: last-used widths/pins/sort under
   * `product-edit:master`, saved views under `product-edit:views:master`.
   */
  const sheetColumns = useSheetColumns<StudioRow, SheetPageState>({
    apiRef,
    gridReady,
    columns: schemaColumns,
    viewCtx,
    serverViews: sheet?.views,
    identityColumn: IDENTITY_COLUMN,
    prefsBridge,
    activeChip: chipBar.active,
    setChip: chipBar.setActive,
    layoutSurface: `product-edit:layout:master:${market.toUpperCase()}`,
    grid: {
      surface: 'product-edit:master',
      viewsSurface: 'product-edit:views:master',
      baseUrl: getBackendUrl(),
      /* #425 — belt-and-braces beside §9.5a. When the URL names a cell, AG's own deferred
         `initialState` scroll restore lands ~90ms AFTER the reveal has already scrolled there and
         wins the race. §9.5a already strips `scroll.left` from storage, so this is the second lock:
         an explicit coordinate should not have to out-run an implicit one at all. */
      omitScroll: record.colKey != null,
      getPageState: () => ({ search }),
      applyPageState: (pg) => setSearch(pg.search ?? ''),
    },
  })
  const { gridState, applyPreset } = sheetColumns


  const scopeRows = useMemo(() => {
    let out = rows
    if (showRefusedOnly && refusedRowIds.size > 0) {
      // Parents are kept when a child is refused, or the tree has no path to the row.
      const keep = new Set(refusedRowIds)
      for (const r of rows) if (r.parentId && keep.has(r.id)) keep.add(r.parentId)
      out = out.filter((r) => keep.has(r.id))
    }
    const q = search.trim().toLowerCase()
    if (q) {
      const keep = new Set<string>()
      for (const r of out) {
        if (!`${r.sku} ${r.name ?? ''}`.toLowerCase().includes(q) && !Object.entries(r.values).some(([key, cell]) =>
          referenceSearchText(cell?.value, columnByKeyRef.current.get(key)?.optionLabels).includes(q))) continue
        keep.add(r.id)
        if (r.parentId) keep.add(r.parentId)
      }
      out = out.filter((r) => keep.has(r.id))
    }
    return out
  }, [rows, search, showRefusedOnly, refusedRowIds, schemaColumns])

/* ── the Missing-required view chip (#34) ───────────────────────────────────────────────── */

  /**
   * PES.2 PRODUCES this chip; the frame owns only the registry. The count is CELL-level, per the
   * ratified contract — from `{rows, cols}` you cannot recover WHICH cell in the rectangle was the
   * reason, and the chip's whole job is to take the operator to those cells.
   *
   * The source is the server's own `completeness.required.missing`, which is computed from the same
   * applicability rules as the readiness verdict (`@nexus/shared/master-sheet`). Deriving it here
   * from "empty and requiredBy is non-empty" would let the chip and the readiness pill disagree
   * about the same cell.
   */
  const missingRequiredChip = useMemo<ViewChip>(() => {
    if (!sheet) {
      // 🔴 `count: null` is not zero. Nothing has been counted yet, so the chip stays visible and
      // prints no number — rendering `(0)` here would answer "we checked, there are none".
      return {
        id: 'missing-required',
        label: 'Missing required',
        // §6.2 rule 1 (#362): a count of WORK is a view, not a warning. `neutral` keeps the chip and
        // its count and drops the ⚠ — the glyph now follows `tone` (see `viewChipIsAlarm`), so this
        // one line is what decides whether "Missing required (42)" reads as a filter or as an alarm.
        // 42 incomplete fields is the normal state of a catalogue, not an incident.
        tone: 'neutral',
        count: null,
        note: 'Counted once the sheet has loaded',
        cells: EMPTY_VIEW_CHIP_CELLS,
      }
    }
    const byRow: Record<string, string[]> = {}
    let cells = 0
    for (const row of scopeRows) {
      const keys = [...new Set(row.completeness.required.missing.map((m) => m.key))].filter((k) => schemaColumns.some((c) => c.key === k))
      if (keys.length > 0) {
        byRow[row.id] = keys
        cells += keys.length
      }
    }
    // `neutral`, not `warning` — see the pending branch above for why.
    return { id: 'missing-required', label: 'Missing required', tone: 'neutral', count: cells, cells: { byRow } }
  }, [sheet, scopeRows, schemaColumns])

  useRegisterViewChip('missing-required', missingRequiredChip)

  /* CH.1 — the SAME chip rule as the channel scopes (`buildChannelChips`): a `warn`-severity readiness
     issue is a Warnings cell. Master had counted only the required gaps, so its bar showed one chip
     where a channel showed three; the rule is now identical and only the DATA decides what appears. */
  const warningsChip = useMemo<ViewChip>(() => {
    if (!sheet) {
      return { id: 'warnings', label: 'Warnings', tone: 'neutral', count: null, hideWhenZero: true, note: 'Counted once the sheet has loaded', cells: EMPTY_VIEW_CHIP_CELLS }
    }
    const byRow: Record<string, string[]> = {}
    let cells = 0
    for (const row of scopeRows) {
      for (const issue of row.readiness?.issues ?? []) {
        if (issue.severity !== 'warn' || !schemaColumns.some((c) => c.key === issue.key)) continue
        if (byRow[row.id]?.includes(issue.key)) continue
        ;(byRow[row.id] ??= []).push(issue.key)
        cells += 1
      }
    }
    // `neutral` on purpose (§6.2 rule 1, the layout gate's no-warning-chip check): 42 flagged values are
    // WORK to do, not an incident. Mapping errors keep their glyph — a value that would not ship is an alarm.
    return { id: 'warnings', label: 'Warnings', tone: 'neutral', count: cells, hideWhenZero: true, note: 'A value the channel would accept but flag — the same rule the channel scopes count', cells: { byRow } }
  }, [sheet, scopeRows, schemaColumns])
  useRegisterViewChip('warnings', warningsChip)

  const invalidChip = useMemo<ViewChip>(() => {
    const byRow: Record<string, string[]> = {}
    for (const row of scopeRows) {
      const missing = new Set(row.completeness.required.missing.map((m) => m.key))
      const keys = [...new Set((row.readiness?.issues ?? [])
        .filter((i) => i.severity === 'error' && !missing.has(i.key) && schemaColumns.some((c) => c.key === i.key))
        .map((i) => i.key))]
      if (keys.length) byRow[row.id] = keys
    }
    return {
      id: 'validation-errors', label: 'Invalid values', tone: 'danger', hideWhenZero: true,
      count: sheet ? Object.values(byRow).reduce((n, keys) => n + keys.length, 0) : null,
      cells: { byRow },
    }
  }, [sheet, scopeRows, schemaColumns])
  useRegisterViewChip('validation-errors', invalidChip)

  /**
   * PES.8's AI layer. ONE fetch feeds both halves: the `✦ AI drafts (N)` chip registers itself, and
   * `draftFor` is the ref-reading, stable-identity function the column factory takes — so a draft
   * arriving repaints cells instead of rebuilding a hundred column definitions.
   *
   * `channel: null` IS the master scope in their contract, not a missing value.
   */
  const productIds = useMemo(() => rows.map((r) => r.id), [rows])
  // `locale` is passed so a TRANSLATION draft (PES.8's D7) becomes visible when the operator
  // switches locale. Absent it means "the master's own values only" in their contract — safe, but
  // it would leave translation drafts permanently invisible. The overlay index stays keyed by
  // (row, column) and the server filters by locale, which is right while the sheet shows one
  // locale at a time.
  const aiLayer = useAiDraftLayer({ productIds, channel: null, marketplace: market, locale })
  /** The review lists rows by product; an operator reads SKUs, not cuids. */
  const skuById = useMemo(() => Object.fromEntries(rows.map((r) => [r.id, r.sku])), [rows])

  const activeChip = chipBar.active

  /**
   * The active chip's cells, behind a ref.
   *
   * The class rule reads this at PAINT time, so selecting a chip repaints the cells instead of
   * handing AG a new `columnDefs` identity and re-running the column model for a hundred columns
   * (reference_ag_react_inline_options_rerun_column_model).
   */
  const chipCellsRef = useRef(activeChip?.cells ?? null)
  chipCellsRef.current = activeChip?.cells ?? null
  const isChipCell = useCallback(
    (rowId: string, colId: string) => (chipCellsRef.current ? viewChipHasCell(chipCellsRef.current, rowId, colId) : false),
    [],
  )
  useEffect(() => {
    const api = getGridApi()
    if (api && !api.isDestroyed()) api.refreshCells({ force: true })
  }, [activeChip])


  /* ── rows on screen ─────────────────────────────────────────────────────────────────────── */

  const visibleRows = useMemo(() => {
    let out = scopeRows
    if (activeChip) {
      // The chip names its own rows; a child still needs its parent or the tree has no path to it.
      const own = new Set(viewChipRows(activeChip.cells))
      const keep = new Set<string>()
      for (const r of out) {
        if (!own.has(r.id)) continue
        keep.add(r.id)
        if (r.parentId) keep.add(r.parentId)
      }
      out = out.filter((r) => keep.has(r.id))
    }
    return out
  }, [scopeRows, activeChip])

  /* ── columns ────────────────────────────────────────────────────────────────────────────── */

  const attributeColumns = useMemo(
    () => (sheet ? buildMasterColumns({ columns: schemaColumns.filter(column => column.key !== PRODUCT_MEDIA_COLUMN), tracker, locale, market, reservedColumnIds: RESERVED_COLUMN_IDS, isChipCell, draftFor: aiLayer.draftFor, formula: formulaWiring }, rowsRef) : []),
    /* `formulaWiring` is identity-stable by construction (see its definition) — it is in the deps
       because it is used, not because it changes. */
    [sheet, schemaColumns, tracker, locale, market, isChipCell, aiLayer.draftFor, formulaWiring],
  )

  /*
   * 🔴 `sku` and `completeness` USED to be pinned columns here and are now inside the band (#710).
   * The Owner: "It must all be the same exactly, visually and all." Three pinned columns meant
   * three widths kept in step by hand, which is how the P/C chip came to overlap the thumbnail —
   * each was sized on its own and none on the content. The readiness NUMBER did not vanish with its
   * column: it is the band's trailing pill, and it gained a bar, which a 90px numeric column could
   * not show.
   */
  const identityColumns = useMemo<ColDef<StudioRow>[]>(() => [], [])

  /**
   * Readiness renders what the READ actually answered, and the two reads answer differently.
   *
   * The studio route gives ONE verdict for the row in this scope; the catalogue read gives one per
   * channel coordinate. Rather than collapse the richer answer or invent the poorer one, the sheet
   * draws whichever it was given — and the footer already says which read it is showing.
   */
  const readinessColumns = useMemo<ColDef<StudioRow>[]>(() => {
    const toValue = (r: RowReadiness | undefined): ReadinessValue | null =>
      r ? { state: r.state, issues: r.issues.map((i) => i.message), ref: r.ref } : null
    const rowValue = (row: StudioRow | undefined): ReadinessValue | null => {
      if (!row) return null
      const edits = (sheet?.columns ?? []).map(col => tracker.get(row.id, col.key)).filter(Boolean)
      const failures = edits.filter(edit => edit?.state === 'refused' || edit?.state === 'unknown')
      if (failures.length) return { state: 'errors', issues: [...new Set(failures.map(edit => edit?.reason || 'An edit has not been saved.'))] }
      if (edits.some(edit => edit?.state === 'saving')) return null
      return toValue(row.readiness)
    }

    /**
     * AG.1-e — the readiness verdict as TEXT, for every consumer that is not the screen.
     *
     * `ReadinessCell` draws a pill from a structured value, and a column whose only rendering lives
     * in a `cellRenderer` exports as the literal `[object Object]` (AG's `useFormatter` stringifies
     * whatever the column holds). The export now blanks that string rather than printing nonsense,
     * which left the column empty — honest, but a hole where the file's most useful column should
     * be. This states the same verdict the pill states, so the CSV says "Missing · 3" where the
     * screen shows `Missing · 3`.
     */
    const readinessText = (v: ReadinessValue | null | undefined): string => {
      if (!v) return ''
      // Capitalised to match the pill the operator reads (GRID.md §6: `Ready` · `Missing · n` ·
      // `Errors · n`). The wire states are lowercase, and a file that says "missing · 2" where the
      // screen says "Missing · 2" is a small, needless difference between the two.
      const state = v.state ? v.state.charAt(0).toUpperCase() + v.state.slice(1) : ''
      const n = v.issues?.length ?? 0
      return n > 0 ? `${state} · ${n}` : state
    }

    const coordinates = sheet?.coordinates ?? []
    if (coordinates.length > 0) {
      return coordinates.map((c) => ({
        colId: `ready:${c.channel}:${c.marketplace}`,
        headerName: c.label,
        width: 160,
        sortable: false,
        editable: false,
        cellClass: 'nds-ag-cell nds-cell-is-locked',
        valueGetter: (p: ValueGetterParams<StudioRow>): ReadinessValue | null =>
          toValue(p.data?.readinessByCoordinate?.[`${c.channel}:${c.marketplace}`]),
        valueFormatter: (p) => readinessText(p.value as ReadinessValue | null),
        cellRenderer: ReadinessCell,
      }))
    }
    if (!sheet) return []
    return [
      {
        colId: 'ready:scope',
        headerName: 'Readiness',
        width: 170,
        sortable: false,
        editable: false,
        cellClass: 'nds-ag-cell nds-cell-is-locked',
        headerTooltip: `Saved Information against ${sheet.scope.label}; unsaved errors take priority. This is not publication eligibility.`,
        valueGetter: (p: ValueGetterParams<StudioRow>): ReadinessValue | null => rowValue(p.data),
        valueFormatter: (p) => readinessText(p.value as ReadinessValue | null),
        cellRenderer: ReadinessCell,
      },
    ]
  }, [sheet, tracker, pending, refused, offline])

  /**
   * AG.1-d — FLAT. The readiness columns were the last `marryChildren` group on the sheet, and with
   * the attribute bands gone (`columns.tsx`) keeping this one would have been the worst of both:
   * the whole header still paying its 30px strip, to label a single group.
   *
   * Where the market goes, precisely — the two readiness shapes differ and only one of them named
   * it in the band: with per-coordinate columns each header IS the coordinate (`c.label`, e.g.
   * "Amazon · DE"), so the band only repeated its children. With the single-scope fallback the
   * header is the bare word "Readiness" and the coordinate lives in its `headerTooltip` ("This row
   * against …") plus the scope bar directly above the sheet. So one case loses nothing and the
   * other loses a label it already states on hover; neither is worth 30px on every screen.
   */
  /**
   * The default column-definition order. The shared layout hook applies the saved membership
   * and order after these definitions are registered with the grid.
   *
   * `identityColumns` (SKU, Master) stay in front unsorted: they are the row's identity, not
   * attributes competing for the operator's first glance. `readinessColumns` stay at the end.
   * Only the attribute band is re-ranked, and only into a PERMUTATION of itself.
   */
  const columnDefs = useMemo(() => {
    const rank = new Map(orderColumnKeys(schemaColumns, viewCtx).map((k, i) => [k, i]))
    const ordered = attributeColumns
      .map((c, i) => ({ c, r: rankOfColumn(c, rank), i }))
      // Stable on the original index: a column the rule does not name keeps its schema position
      // relative to its unnamed neighbours instead of moving for no stated reason.
      .sort((a, b) => a.r - b.r || a.i - b.i)
      .map((x) => x.c)
    /* 🔴 §9.2's NON-INTERACTIVE TAIL (#448), and it is an invariant rather than a coincidence.
       UX.1 measured that 4 of 19 master columns can never be cleared of the panel at max scroll —
       the trailing panel-width of the sheet is permanently coverable, so whatever sits there is
       unreachable while a record is open. Non-interactive columns are the only ones that can
       afford that position, so `readinessColumns` (`ready:scope` and the per-coordinate
       `ready:<channel>:<marketplace>`) go LAST, after the whole attribute band.

       Stated here because the order was already right by accident of composition, and an accident
       is not a rule: anyone reordering this line would move interactive columns into the dead zone
       with nothing to tell them they had. */
    return [...identityColumns, productMediaColumn<StudioRow>(mediaEditor.open, mediaEditor.actions), ...ordered, ...readinessColumns]
  }, [identityColumns, attributeColumns, readinessColumns, schemaColumns, viewCtx, mediaEditor.open, mediaEditor.actions])

  /* ── grid wiring ────────────────────────────────────────────────────────────────────────── */

  const getRowId = useCallback((p: { data: StudioRow }) => p.data.id, [])
  const getDataPath = useCallback((d: StudioRow) => (d.parentId ? [d.parentId, d.id] : [d.id]), [])
  /*
   * The band's second line, decided ONCE for the family (#716). `rows` and `schemaColumns` are the
   * same values the band renders, so the coverage test and the render cannot disagree — a server
   * coverage figure could say "full" while the rows on screen were empty.
   *
   * 🔴 Handed to the renderer through a REF, for the reason `readRow` gives above: the column def's
   * deps are `[lockedColumns]`, so putting the plan itself in `cellRendererParams` would either
   * capture the first load's answer forever, or — if added to the deps — rebuild the auto group
   * column on every data load and re-run the column model with it. The ref's identity is stable and
   * the renderer reads `.current` when it draws.
   */
  /*
   * The band's WIDTH — derived from the band the browser actually drew (#742).
   *
   * 🔴 No slot constants. They were a measurement of another component's rendering held as numbers
   * in this file: nothing type-checked them, no test could see them, and when `CompletenessPill`
   * gained a fixed-width number the pill went 65.2 → 70 while the constant stayed 66 — five SKUs
   * truncated silently in the same edit. Measuring the first rendered band means the number cannot
   * go stale, and means this scope and the channel derive the SAME width for the same family by
   * construction rather than by two lists agreeing.
   *
   * The cost, stated: the column mounts at the floor and is corrected once the first band exists,
   * so there is one width change on the first paint of a family. The alternative is a constant that
   * is right until someone edits a component, which is the defect this replaces.
   */
  const [bandWidth, setBandWidth] = useState(BAND_WIDTH_FLOOR)
  const bandWidthRef = useRef(bandWidth)
  bandWidthRef.current = bandWidth
  /* 🔴 Has the derivation happened AT ALL — not "is the width plausible". `bandWidth` starts at the
     floor, and a floor is a legitimate derived answer for a family of short SKUs, so no reading of
     the width can tell "240 because measured" from "240 because not yet measured". The reveal needs
     exactly that distinction (`revealHost.ts`), and only this flag carries it. */
  const bandDerivedRef = useRef(false)
  /* The stash replay, reachable from the band derivation above it. A ref rather than a dependency
     because the replay is defined ~500 lines below, next to the stash it drains. */
  const replayRevealRef = useRef<(() => void) | null>(null)
  /** Stable handler for AG's column events — see the JSX. */
  const replayReveal = useCallback(() => replayRevealRef.current?.(), [])

  const secondaryRef = useRef<SecondaryPlan>({ mode: 'none', axisKeys: [] })
  secondaryRef.current = useMemo(() => secondaryPlan(rows, schemaColumns), [rows, schemaColumns])
  const autoGroupColumnDef = useMemo<ColDef<StudioRow>>(
    () => ({
      /*
       * 🔴 SIZED FROM ITS CONTENT, and clamped so nothing can squeeze it below that (#709a, Owner:
       * "we need to make sure that everything fits in the column and in the default view").
       *
       * Measured on master·IT before the fix: the column rendered **46.4px** while this def said 76,
       * and the cell's own content overflowed BOTH numbers — expander 120→140, the P/C chip
       * 146→166 and the thumbnail 131→163 against a clip edge at 156.4. The chip and the picture
       * occupied overlapping x-ranges and both crossed the clip, so the Owner saw a thumbnail and
       * no parent/child pill at all.
       *
       * Two causes, and the width alone was not one of them:
       *  1. CONTENT: expander 20 + 6 + chip 20 + 6 + thumb 32 = 84, plus the cell's 10px padding
       *     either side = 104. At the declared 76 the pill was already being clipped; the persisted
       *     46.4 only made it worse.
       *  2. PERSISTED STATE: `nds-grid:product-edit:master:v1` carried
       *     `{colId: 'ag-Grid-AutoColumn', width: 46.4453125}` — an auto-fit remainder saved from an
       *     earlier session, which beat this `width` on every load. `minWidth` is what a restored
       *     column state cannot argue with, which is why it is here and not just a bigger `width`.
       */
      /*
       * 🔴 ONE BAND, SIZED FROM ITS CONTENT (#710). It replaces `product` + `sku` + `completeness`
       * (104 + 180 + 90 = 374), so 376 is a like-for-like swap and the 1440 budget UX.1 measures is
       * unchanged — the identity is now one column instead of three, not a wider one.
       *
       * `minWidth` is what a RESTORED COLUMN STATE cannot argue with, and that is not theoretical:
       * `nds-grid:product-edit:master:v1` was carrying `{colId:'ag-Grid-AutoColumn', width:46.44}`,
       * an auto-fit remainder from an earlier session, and it beat this def on every load (#709a).
       * Content floor: expander 20 + chip 24 + thumb 32 + the readiness pill 68, four 8px gaps and
       * 20px of cell padding = 196 before a single character of SKU.
       */
      headerName: 'Product', colId: 'product', width: bandWidth, minWidth: BAND_WIDTH_FLOOR,
      pinned: lockedColumns.includes('product') ? 'left' : undefined,
      lockPinned: lockedColumns.includes('product'),
      lockPosition: lockedColumns.includes('product') ? 'left' : undefined,
      cellRenderer: ProductCell, cellClass: 'nds-ag-cell', suppressHeaderMenuButton: true,
      cellRendererParams: { secondaryRef, rowMenuRef },
      headerTooltip: 'Family — a parent and its children',
    }),
    [lockedColumns, bandWidth],
  )
  /*
   * Measure the band and push the width onto the live column.
   *
   * 🔴 Driven by the EVENTS THAT CREATE THE BAND, not by a timer. The first version returned when
   * the band was absent and never looked again — PES.3 found master at the 240 floor with 21 of 21
   * keys truncated. The second version retried 40 × 50 ms, which is still a give-up with a deadline:
   * a background tab is a zero-dimension container, AG renders no rows in it, and a cold dev
   * compile easily outlasts two seconds — so the column would sit at the floor until the next
   * `rows` change, on the one load nobody is watching.
   *
   * `firstDataRendered` and `rowDataUpdated` fire when rows actually exist, and `visibilitychange`
   * re-arms for the tab that was never visible to render into. The short retry stays only as a
   * belt for the gap between an event and layout settling; it is no longer the mechanism.
   */
  const remeasureBand = useCallback(() => {
    if (rowsRef.current.length === 0) return
    /* The band that CARRIES A KEY — the engine picks it, because a channel's alias band row has a
       different trail and measuring it reserves 26px the long keys never spend (#744). */
    const next = deriveBandWidthFromDom(
      findKeyBearingBand(),
      measureLongestSku(rowsRef.current.map((r) => r.sku), buildSkuFont()),
    )
    if (next == null) return false
    /* 🔴 Derived — and the reveal is told, BEFORE the early return below. A reveal that deferred on
       `bandReady` is waiting on this exact moment, and a family whose derived width equals the
       floor still has to release it: gating the publish on the width having CHANGED would strand
       the deep link on precisely the families where nothing moved. */
    const first = !bandDerivedRef.current
    bandDerivedRef.current = true
    /* Skip when it is already right: setting the width re-renders the band, which would re-measure
       and set it again. Terminates on the first pass rather than relying on convergence. */
    if (Math.abs(next - bandWidthRef.current) < 0.5) {
      if (first) replayRevealRef.current?.()
      return true
    }
    setBandWidth(next)
    getGridApi()?.setColumnWidths?.([{ key: 'product', newWidth: next }])
    /* 🔴 The reveal is NOT replayed here, and the first version of this fix was: it called the
       replay on the line below, and MEASURED (trace, cold load at 1280) the replay still reading
       `viewportLeft: 350` — the pre-derivation layout — 124ms after the derivation it was supposed
       to be waiting for. Asking for a width is not the width changing. `setBandWidth` lands through
       a React render of `autoGroupColumnDef`, and the pinned column's id is `ag-Grid-AutoColumn`,
       not `product`, so the `setColumnWidths` call above is not what moves it either. The replay
       rides `onDisplayedColumnsChanged` / `onColumnResized` instead — AG saying the columns HAVE
       moved, which is the event the #744 ruling asks for rather than a frame's grace. */
    return true
  }, [])

  /** One event can arrive a tick before layout settles; this retries briefly, then stops. */
  const remeasureSoon = useCallback(() => {
    const api = getGridApi()
    if (!api) return
    let tries = 0
    const go = () => {
      if (getGridApi() !== api) return
      if (remeasureBand() !== false) return
      if (tries++ < 20) { setTimeout(go, 50); return }
      /* 🔴 Gave up — so RELEASE the reveal rather than strand it. `bandReady` turns a stale
         measurement into a deferral, and a deferral that can never end is a worse defect than the
         one it replaces: the operator's deep-linked cell would sit under the drawer forever with
         nothing reported, which is the give-up-in-silence shape twice over. Measuring at the floor
         is the OLD behaviour, and the old behaviour is the correct floor for this gate. */
      bandDerivedRef.current = true
      replayRevealRef.current?.()
    }
    go()
  }, [remeasureBand])

  useEffect(() => {
    // The tab that was never visible to render into: re-arm when it becomes so.
    const onVis = () => { if (document.visibilityState === 'visible') remeasureSoon() }
    document.addEventListener('visibilitychange', onVis)
    return () => document.removeEventListener('visibilitychange', onVis)
  }, [remeasureSoon])

  const rowSelection = useMemo(() => gridSelection<StudioRow>(), [])
  const defaultColDef = useMemo<ColDef<StudioRow>>(() => ({ sortable: true, resizable: true }), [])
  const processDataFromClipboard = useMemo(
    () => sheetPasteProcessor<StudioRow>(customisableColumns.map((c) => ({ colId: c.key, headerName: c.label }))),
    [customisableColumns],
  )

  const onGridPreDestroyed = useCallback((event: { api: GridApi<StudioRow> }) => {
    if (apiRef.current === event.api) {
      sheetColumns.captureGridState()
      gridState.persist()
      bindGrid(null)
      setSelectedRows([])
    }
    releaseGrid(event)
  }, [apiRef, gridState, releaseGrid, bindGrid, sheetColumns.captureGridState])

  const onGridReady = useCallback(
    (e: GridReadyEvent<StudioRow>) => {
      bindGridApi(e.api)
      bindGrid(e.api)
      gridState.bind(e.api)
    },
    [bindGrid, bindGridApi, gridState],
  )

  /**
   * Every edit — typed, filled down, pasted, or undone — arrives here and goes to the ONE writer.
   * AG fires this per cell, so a fill down 20 rows is 20 calls; the writer batches them per row.
   */
  const onCellValueChanged = useCallback(
    (e: { data: StudioRow; colDef: { colId?: string }; oldValue?: unknown; newValue: unknown; source?: string }) => {
      const colId = e.colDef.colId
      /**
       * One gate, pure and tested (`design-system/grid/editors/writeGate.ts`), rather than a pile
       * of `if`s nothing covers. It refuses three things: a change with no column, the grid setting
       * its own data, and a change this component caused itself.
       *
       * `selfInflicted` is false here and that is a statement, not an oversight: this sheet NEVER
       * reverts. A refusal is a result that stays on the cell with its reason, and a 409 offers a
       * refresh rather than fighting the value back — so there is no programmatic write to
       * re-enter. `setDataValue` (which re-fires this event WITHOUT `source: 'data'`, ruling #63)
       * appears nowhere in this lane; the only programmatic call is `refreshCells`, which repaints
       * and fires nothing.
       *
       * Undo needs no code of its own: AG fires this event for `'undo'` and `'redo'`, so an undone
       * cell travels the same writer, batching and version path as the edit before it.
       */
      /**
       * `oldValue`/`newValue` are passed so the gate can refuse a change that did not change
       * anything (AG.1, hub #256). AG's FILL fires this event for every cell in the range whether or
       * not the value moved — measured on the wire: a fill down three rows that already held the
       * same value issued 2 PATCHes for 0 changes, each carrying an `expectedVersion` that can lose
       * a 409 race against a real concurrent edit.
       */
      if (!writeGate({ colId, source: e.source, selfInflicted: false, oldValue: e.oldValue, newValue: e.newValue }).write) return
      /**
       * 🔴 D16 — a FORMULA is not a value, and this is the line that keeps it from becoming one.
       *
       * The editor commits the text the operator typed. If that text starts with `=` it is an
       * expression, and it belongs in `CellFormula` with the server writing the RESULT into the
       * value layer (§1.6(A)). Sending it down the ordinary write path would store the characters
       * `="a" + $brand` as the cell's literal value — and `overrideData` is read as a value layer
       * by the resolver (`attribute-resolver.ts:258`), so the formula TEXT would publish to a
       * channel and preflight would call it valid. The leading `=` is stripped by `exprOf` on the
       * way, because `=` is a real equality operator in this language and a stored expr that keeps
       * it parses as a comparison against nothing (§1.6(B); the route refuses one).
       */
      if (!formulas.ready) {
        const reason = formulas.loadError ?? 'Formulas are still loading. Retry this edit once they are ready.'
        tracker.set(e.data.id, colId!, 'refused', reason)
        const writeId = `${e.data.id}:${colId}:${Date.now()}`
        onWriteStart(writeId, e.data.id); onWriteEnd(writeId, false, reason, e.data.id)
        return
      }
      const typed = typeof e.newValue === 'string' ? e.newValue : null
      if ((typed !== null && isFormulaDraft(typed)) || formulas.exprFor(e.data.id, colId!)) {
        /**
         * 🔴 Put the DISPLAYED value back at once — the formula text must never sit in the cell as
         * though it were the value (Owner 16:58, ruled #763).
         *
         * AG's `valueSetter` has already written `=upper($brand)` into the row by the time this
         * runs, because that mutation is what makes this event fire at all. Left alone the cell
         * renders the expression until the reload lands, and on a refusal it renders it for good —
         * a formula presented as a value, which is exactly the honest-UI rule this sheet is held
         * to. At rest the cell shows the engine's OUTPUT with the `ƒ` mark; the text belongs to the
         * editor and only while it is open.
         *
         * The value the server computes arrives by re-read below. This is not the sheet "reverting"
         * a refusal — the ruled never-revert policy is about a rejected VALUE, and a formula was
         * never a value. The unsaved counter still carries the failure.
         */
        const prev = cellOf(e.data, colId!)
        /* `cellOf` is `StudioCellValue | undefined` — a cell the row has never held. Guarded rather
           than asserted: writing an `undefined` entry into `values` would make the renderer read a
           cell that is not there, which is the shape that draws "—" over a real value. */
        if (prev) {
          e.data.values = { ...e.data.values, [colId!]: { ...prev, value: e.oldValue } }
          const node = getGridApi()?.getRowNode(e.data.id)
          if (node) getGridApi()?.refreshCells({ force: true, rowNodes: [node], columns: [colId!] })
        }

        const writeId = `${e.data.id}:${colId}:${Date.now()}`
        onWriteStart(writeId, e.data.id)
        /**
         * 🔴 The CELL tracker as well as the header reporter — they are two different things and I
         * had only fed one (PES.3, measured on the channel scope and true here too).
         *
         * `onWriteStart`/`onWriteEnd` drive `SaveReporter`, which is the header's unsaved COUNT.
         * The cell's state and its reason come from `CellSaveTracker`, which every ordinary write
         * goes through (`sheetWriter.ts:239`) and which the formula path never touched. So a refused
         * formula counted in the header, kept its text for correction — and said nothing about WHY,
         * which is exactly the half of my own contract that was missing.
         */
        tracker.set(e.data.id, colId!, 'saving')
        void (typed !== null && isFormulaDraft(typed) ? formulas.save(e.data.id, colId!, exprOf(typed)) : formulas.replace(e.data.id, colId!, e.newValue))
          .then((r) => {
            onWriteEnd(writeId, r.ok, r.error, e.data.id)
            /* The server's sentence, verbatim, on the cell it belongs to — for a refused option it
               is the one that names the allowed values, which is the whole point of PES.5 returning
               it rather than a generic "not allowed". */
            tracker.set(e.data.id, colId!, r.ok ? 'saved' : 'refused', r.error)
            /**
             * 🔴 A REFUSED formula stays in the cell so it can be corrected (Owner, #775).
             *
             * The display was put back to the old value the moment the edit committed, because a
             * formula is not a value and must not sit there looking like one. That is right while
             * the save is in flight and right when it succeeds. It is WRONG on a refusal: the
             * operator's expression would vanish and they would have to retype it to fix one
             * character. So on failure the text goes back, and the sheet's never-revert rule
             * applies — the cell carries the refusal and its reason (`onWriteEnd` above), which is
             * what distinguishes it from a value.
             */
            if (!r.ok) {
              const cell = cellOf(e.data, colId!)
              if (cell) {
                e.data.values = { ...e.data.values, [colId!]: { ...cell, value: e.newValue } }
                const n = getGridApi()?.getRowNode(e.data.id)
                if (n) getGridApi()?.refreshCells({ force: true, rowNodes: [n], columns: [colId!] })
              }
            }
            /* The value layer moved server-side, and nothing on this sheet knows the new value —
               there is no cached result on the formula row by design (§1.6(E)), so the only honest
               way to show what it produced is to re-read. */
            // The formula queue refreshes once after the whole edit batch settles.
          })
          .catch((err: unknown) => {
            const reason = err instanceof Error ? err.message : String(err)
            onWriteEnd(writeId, false, reason, e.data.id)
            /* A transport failure is an UNKNOWN outcome, not a refusal: the write may yet have
               landed. `unknown` is the tracker's word for exactly that, and it must not read as
               "rejected" when a re-read might show it saved. */
            tracker.set(e.data.id, colId!, 'unknown', `Could not reach the server — ${reason}. Refresh to see whether this saved.`)
          })
        return
      }
      writer.set(e.data.id, colId!, e.newValue, { row: e.data })
      /* 🔴 NO SAVE CLOCK HERE (#705). This ran `setLastSavedAt(new Date().toISOString())` the moment
         an edit was QUEUED — before the request had left — so the footer said "Saved HH:MM" for a
         write the server had not seen, and went on saying it when that write came back refused or
         died in an outage. The stamp now comes from the writer's settle callback, and only when
         `ok`. Found by PES.3 on the channel sheet, where the false clock sat 700px from a red cell
         and a header reading "1 change not saved". */
    },
    [writer, formulas, onWriteStart, onWriteEnd, reload],
  )

  const onSelectionChanged = useCallback(
    (e: { api: GridApi<StudioRow> }) =>
      setSelectedRows(e.api.getSelectedNodes().map((n) => n.data).filter((d): d is StudioRow => !!d)),
    [],
  )
  const clearSelection = useCallback(() => getGridApi()?.deselectAll(), [])

  /**
   * 🔴 `onRowDoubleClicked={openRecord}` is RETIRED (spec §7.3, hub ruling #184).
   *
   * **Double-click EDITS the cell.** AG.1 measured 95 of 100 columns editable, so the collision was
   * the normal case rather than an edge, and PES.3 saw this same handler open an editor on the
   * WRONG cell after the drawer reflowed a scrolled grid. One gesture may not have two owners, and
   * the editor has the better claim: the operator double-clicked a CELL, not a row.
   *
   * Three EXPLICIT affordances replace it, because removing a gesture without giving the operator
   * the way back would be the worse bug: Enter on the identity cell (below), the `open-record` verb
   * — which the registry puts on BOTH the row menu and the right-click menu from one declaration —
   * and the identity cell's own control once UX.1 specs its glyph.
   */

  /**
   * Enter on the IDENTITY cell opens the record — one of the three explicit affordances that
   * replace double-click (§7.3).
   *
   * Scoped to the identity columns on purpose: Enter anywhere else is the sheet's own "commit and
   * move down" gesture, and stealing it would be the same mistake as double-click one key over.
   * The identity cell is not editable, so Enter there has no other owner.
   */
  const onCellKeyDown = useCallback(
    (e: { event?: Event | null; data?: StudioRow; column?: { getColId(): string } }) => {
      const ke = e.event as KeyboardEvent | undefined
      if (!ke) return
      /* 🔴 A refused KEY gesture answers too, and answers FIRST — Enter, F2 and a printable
         character are open gestures exactly as a double-click is (ruling 1), and all four were
         measured silent on a locked cell. Chrome falls through: the identity column is in no
         `SheetColumn`, so `sayWhyRefused` declines it and Enter keeps opening the record below. */
      const opensAnEditor =
        !ke.altKey && !ke.ctrlKey && !ke.metaKey &&
        (ke.key === 'Enter' || ke.key === 'F2' || (ke.key.length === 1 && ke.key !== ' '))
      if (opensAnEditor && sayWhyRefusedRef.current(e.column?.getColId?.(), e.data)) return
      if (ke.key !== 'Enter' || ke.altKey || ke.ctrlKey || ke.metaKey || ke.shiftKey) return
      const colId = e.column?.getColId?.()
      if (colId !== 'ag-Grid-AutoColumn' && colId !== 'sku') return
      if (!e.data) return
      ke.preventDefault()
      // The identity cell IS chrome, so the anchor is the last data cell the operator was in.
      recordRef.current.open(e.data.id, lastDataCell.current ?? undefined)
    },
    // 🔴 `[]`, via a ref. See `stableContextMenu` below for the measurement — this handler is
    // INVOKED on a keypress, so it never needs to re-identify, and re-identifying it hands AG a new
    // prop every time the dock opens.
    [],
  )

  /** Read the current order and pins together with the layout's group assignments. */
  const openCustomise = useCallback(() => {
    if (!getGridApi()) return
    setPrefsDraft(sheetColumns.currentPreferences())
    setPrefsOpen(true)
  }, [sheetColumns])

  /* A ref because `revealNow` is defined below this callback and a hoisted `const` would be a TDZ —
     the same trap that took this file down for twenty minutes earlier tonight. The ref is assigned
     immediately after `revealNow` exists, so by the time any operator can press Save it is set. */
  /* D15 — the import drawer. It defaults to the FIXTURE transport, which is dark and bannered and
     cannot write, so mounting it here puts nothing live; PES.5's endpoint swaps the transport in
     later without this file changing. */
  const [importOpen, setImportOpen] = useState(false)
  const [transferIntent, setTransferIntent] = useState<'import' | 'export'>('import')

  const revealNowRef = useRef<((colKey: string, intent: RevealIntent) => boolean) | null>(null)

  const confirmPrefs = useCallback(
    async (next: PreferencesValue) => {
      const api = getGridApi()
      // Capture the previous set before the successful save applies the new layout.
      const wasVisible = new Set((api?.getColumnState() ?? []).filter((c) => !c.hide).map((c) => c.colId))
      const firstNew = next.visibleColumns.find((key) => !wasVisible.has(key)) ?? null
      await sheetColumns.savePreferences(next)
      // Allow AG to apply the saved order before uncovering a newly shown column.
      if (firstNew) setTimeout(() => revealNowRef.current?.(firstNew, 'uncover'), 0)
      setPrefsDraft(next)
    },
    [sheetColumns],
  )

  /** Preserve the confirmed order and groups; update local state only after durable success. */
  const saveDraftAsView = useCallback(
    async (name: string, value: PreferencesValue) => {
      await sheetColumns.savePreferencesAs(name, value)
      setPrefsDraft(value)
    },
    [sheetColumns],
  )
  const updateActiveView = useCallback(
    async (value: PreferencesValue) => {
      const active = sheetColumns.active
      if (active.kind !== 'saved') return
      const view = gridState.views.find((v) => v.id === active.id)
      if (!view) throw new Error('That view no longer exists')
      await sheetColumns.updatePreferences(view, value)
      setPrefsDraft(value)
    },
    [sheetColumns, gridState.views],
  )

  /** Reset clears grid arrangement, then applies the first preset: the full default column set. */
  const landingPresetOf = useCallback(() => sheetColumns.presets[0], [sheetColumns.presets])
  /**
   * 🔴 Restoring the padlocks has to happen in a SEPARATE render from re-applying the view, and
   * that is measured, not defensive.
   *
   * `lockedColumns` feeds `identityColumns` → `columnDefs`. A new `columnDefs` IDENTITY makes AG
   * rebuild its whole column model (measured: `newColumnsLoaded` ×1, `columnEverythingChanged` ×1)
   * and a rebuild restores the colDefs' own order. So calling `setLockedColumns` and then applying
   * the preset in the same handler put the preset's order on screen and let the rebuild throw it
   * away one tick later — Reset left the SCHEMA order, not the view's. Everything else about the
   * reset looked right, which is exactly why only the on-screen check caught it.
   *
   * The common case does not pay for this at all: an operator who never touched a padlock takes the
   * straight path, no state change, no rebuild.
   */
  const pendingResetRef = useRef(false)
  const resetColumns = useCallback(() => {
    const api = getGridApi()
    if (!api) return
    // AG's own reset drops what a VIEW deliberately no longer touches (AG.1-c): sort, ad-hoc pins,
    // widths. Clearing those is a reset's job, and a reset says so.
    api.resetColumnState()
    /* That is also what releases the operator's LOCKS, and it is the whole mechanism: a lock is a
       left pin, `resetColumnState` puts every column back on its colDef (identity pinned, the rest
       unpinned), and the preset applied below reads its lock set off the grid — so it re-states the
       identity's structural pin and nothing else. Defaults restored, no second list to keep. */
    // A reset also stops remembering: the persisted widths, pins and sort are exactly what
    // `resetColumnState` just cleared, and a reload that brought them back would undo the reset.
    gridState.forget()
    setPrefsDraft(null)
    const locksAreDefault =
      lockedColumns.length === DEFAULT_LOCKED_COLUMNS.length && lockedColumns.every((k) => DEFAULT_LOCKED_COLUMNS.includes(k))
    if (locksAreDefault) {
      const preset = landingPresetOf()
      if (preset) applyPreset(preset)
      return
    }
    pendingResetRef.current = true
    setLockedColumns([...DEFAULT_LOCKED_COLUMNS])
  }, [lockedColumns, landingPresetOf, applyPreset, gridState])

  useEffect(() => {
    if (!pendingResetRef.current) return
    pendingResetRef.current = false
    const preset = landingPresetOf()
    if (preset) applyPreset(preset)
  }, [lockedColumns, landingPresetOf, applyPreset])

  /* CH.1 — the family verbs as items of the toolbar's ⋯ overflow: the bar is identical on every scope. */
  const familyVerbs = useFamilyVerbs({
    family: familyQuery.family,
    actions: famActions,
    error: familyQuery.error,
    onRetry: familyQuery.reload,
    onDone: onFamilyChanged,
    onCollectVariation: setNewVariation,
  })
  const columnDialog = useMemo(() => ({ customise: openCustomise, reset: resetColumns }), [openCustomise, resetColumns])

  /**
   * PES.4 §5.4 — the slide-over overlays the right band of the sheet, so a record opened FROM a
   * column in that band lands underneath its own panel. The RULE is PES.4's (`revealDistance` /
   * `revealScroll`, pure and unit-tested); the SCROLL is the sheet's, because the sheet holds the
   * `GridApi`.
   *
   * 🔴 A POSITION, not a column. This used `ensureColumnVisible(colKey, 'start')`, and UX.1's sweep
   * across 25 positions showed why that cannot work: its target is derived from the COLUMN and is
   * independent of the viewport — `status` lands at 380 and `brand` at 490 at every window width —
   * so for the leftmost scrollable column the target is 0, which is where the grid already is, and
   * it no-ops however badly the panel covers it. AG has no idea the panel exists. `scrollGridTo`
   * (the engine's helper) applies `revealScroll`'s pixels instead; AG 36.1 has no horizontal-scroll
   * setter of its own, which is why that helper had to be written.
   *
   * 🔴 Only scrolls when the rule says the cell is covered — `revealDistance` returns 0 otherwise
   * and `revealScroll` hands back the current position unchanged. Scrolling regardless would move
   * the grid under an operator who could already see the cell: the same class of defect as the
   * double-click collision AG.1-a removed, an action firing when nothing asked for it.
   *
   * The anchor is `lastDataCell` — the last NON-CHROME cell the operator focused — not the cell
   * focused when the verb runs. Clicking `⋯` moves AG's focus to the actions column, which is
   * pinned and always visible, so reading focus at verb time answered "not covered" every time and
   * the reveal was inert while looking implemented (PES.3's measurement, #227).
   */
  /* The dock no longer sends a width at all (#457) — the boundary used to accept and discard one.
     The reveal measures the panel's real box, so nothing here needs the dock's own dimensions. */
  const revealNow = useCallback((colKey: string, intent: RevealIntent = 'uncover'): boolean => {
    const api = getGridApi()
    // Reported, not silently dropped: these two exits ARE the cold path, and a `false` that says
    // nothing is indistinguishable from a reveal that never ran (`traceRevealSkip`).
    if (!api || api.isDestroyed()) return traceRevealSkip(colKey, intent, 'no-api')
    const host = document.querySelector<HTMLElement>('.nds-grid-sheet .ag-root-wrapper')
    if (!host) return traceRevealSkip(colKey, intent, 'no-host')
    /* The URL cursor, never the DOM — `record.rowId` is set before the drawer has a track to
       portal into, which is the whole window this reveal is served in. */
    return revealColumn(api, host, colKey, intent, record.rowId != null, bandDerivedRef.current)
    /* 🔴 `record.rowId` IS a dependency. This was `[]`, and with the cursor now read inside it an
       empty list would freeze the value from the first render — false for the whole life of a
       verb-opened record, which is the stale-closure shape that has already cost this sheet its
       landing view (#194). The identity churn is wanted here: the replay effect below keys on this
       callback, so a record OPENING re-runs it, which is precisely when a stashed reveal becomes
       servable. */
  }, [record.rowId])
  revealNowRef.current = revealNow

  /**
   * Hold-until-ready, and replay UNTIL SERVED (hub #277/#286, amended by #750).
   *
   * ⚠ "replay ONCE" is what this said, and it was true of the code until #750 measured what the one
   * replay actually lands in. Restated rather than left standing: a comment asserting a property
   * the code no longer has is worse than none, because the next reader stops looking.
   *
   * Measured on a cold `?rec=…&cell=…` load: `StudioDock` fires the reveal once, ~1.3s in, with
   * `apiRef.current` still `null` and the grid not yet in the DOM — and because it dedupes per
   * opened cell it never fires again. 1,089px of scroll sat unused and the operator's cell stayed
   * under the panel. So a fire that cannot be served is STASHED rather than dropped.
   *
   * 🔴 Replayed off `gridReady` STATE, not the api ref: a ref assignment triggers no render, so an
   * effect keyed on it never re-runs and the stash would sit there forever — the trap that already
   * cost this sheet its landing view (#194). `sheet` is in the deps too, because the grid can be
   * ready before the rows and columns exist and there is nothing to measure until they do.
   */
  /* 🔴 The stash carries the INTENT. Found by PES.3 and not named in the ruling: the `?rec=&cell=`
     path is both the one that needs `'reveal'` AND the one that always defers, so a stash without
     the intent replays as `'uncover'` and loses exactly the deep-link case — silently, because the
     replay still reports success. The deferred path is the one that matters most and the one a
     defaulted argument breaks. */
  const pendingReveal = useRef<RevealRequest | null>(null)
  const onRevealCell = useCallback(
    (colKey: string, intent: RevealIntent = 'uncover') => {
      const request = { colKey, intent }
      pendingReveal.current = revealStash(pendingReveal.current, {
        kind: 'request', request, served: revealNow(colKey, intent),
      })
    },
    [revealNow],
  )

  /**
   * 🔴 The replay KEEPS an unserved request, and re-arms on the panel — #750, and it is a reversal.
   *
   * This used to clear the stash before attempting, on the stated reasoning that "a stash that
   * survives a failed replay would scroll the grid the next time the sheet happened to re-render".
   * The hazard is real; the conclusion was still wrong, because the single replay fires on
   * `gridReady` and that RACES the drawer. On a cold `?rec=&cell=` load the one attempt lands in the
   * window where the panel does not exist yet, so the request was discarded having never once been
   * measurable — a retry that gives up before the thing it waits for can exist.
   *
   * Measured, on my own #747 build: `bullet_point` at 1280 stayed covered by 24px with `writes []`,
   * byte-identical to the pre-fix reading, three runs (UX.1) and reproduced on both scopes (PES.3).
   *
   * So the stash survives, and the stale-scroll hazard is answered by a NARROWER guard — the stash
   * is dropped when the record closes (`revealStash`'s `'recordClosed'`), so nothing can replay into
   * a sheet whose drawer has gone.
   *
   * 🔴 Re-armed on the panel PUBLISHING its position, not on a timer. The hub's standing ruling from
   * the band width (#744): a bounded retry loop is "a give-up with a timer", and the event exists —
   * `StudioDock` writes `data-resting-left` the moment it knows where the panel lands. The observer
   * is filtered to that one attribute over the whole document rather than watching the drawer
   * (which is not in the DOM yet to be watched): a subtree registration reaches nodes added later,
   * and no grid cell carries the attribute, so a virtualising sheet does not wake it.
   */
  useEffect(() => {
    if (!gridReady || !sheet) return
    const replay = () => {
      const p = pendingReveal.current
      if (!p) return
      pendingReveal.current = revealStash(p, { kind: 'replay', served: revealNow(p.colKey, p.intent) })
    }
    replay()
    /* 🔴 Published to the band derivation, whether or not there is something stashed right now:
       the reveal can be stashed AFTER this effect runs, and a ref assigned only on the branch that
       still has work would leave the later stash with nothing to be woken by. */
    replayRevealRef.current = replay
    if (!pendingReveal.current) return
    const obs = new MutationObserver(() => {
      replay()
      if (!pendingReveal.current) obs.disconnect()
    })
    obs.observe(document.body, { attributes: true, subtree: true, attributeFilter: ['data-resting-left'] })
    return () => obs.disconnect()
  }, [gridReady, sheet, revealNow])

  /* A reveal belongs to the record that asked for it. Without this the surviving stash could replay
     into a closed drawer on the next `data-resting-left` write (a resize, or the next record). */
  useEffect(() => {
    if (record.rowId == null) pendingReveal.current = revealStash(pendingReveal.current, { kind: 'recordClosed' })
  }, [record.rowId])

  /**
   * AG.1-e (#216) — Export. Owner decision D9 removed the header's "Datasheet" link-out, and
   * "the grid IS the flat file" was true for READING with no way to get the file out.
   *
   * `exportGridCsv` takes the columns as displayed and ordered, the rows as filtered and sorted, and
   * each cell as the grid renders it — so `country_of_origin` exports "Pakistan", not "PK". It
   * refuses under a server-side row model rather than writing a silent subset; this sheet is
   * client-side and holds every row, so here the grid IS the full scope.
   */
  const [exportNote, setExportNote] = useState<string | null>(null)
  /** Reference table only. Editable exports use the scoped catalog workbook engine. */
  const onExport = useCallback(
    (mode: SheetExportMode) => {
      const api = getGridApi()
      if (!api || api.isDestroyed() || !sheet) return
      try {
        const r = exportGridCsv<StudioRow>(api, `${sheet.family.sku}-${market}-table`, {
          columns: mode === 'all' ? sheetColumns.orderedKeys : 'displayed',
          leading: [{ colId: '__sku', header: 'SKU', value: row => row.sku }],
          narrowed: search.trim().length > 0,
        })
        setExportNote(`${r.rows} rows · ${r.columns} columns → ${r.fileName} · reference table`)
      } catch (e) {
        setExportNote(e instanceof GridExportRefused ? e.message : 'Could not build the file.')
      }
    },
    [sheet, market, search, sheetColumns],
  )

  /* ── PES.4's record drawer (ruling #30) ─────────────────────────────────────────────────── */

  /**
   * The dock lives HERE because the data it needs lives here: the frame reserves the track but
   * holds no rows, no columns and no writer. PES.4 deliberately did not cross the boundary.
   */
  /**
   * The row the drawer opens on — the object the grid already holds, which was the point.
   *
   * `completeness` no longer needs converting: PES.4's mirror now matches the wire (verified against
   * their `types.ts` and `master-completeness.service.ts`), so that shim is gone per the #47
   * handshake. ONE field still differs and it is not mine to rename: their `SheetRow` requires
   * `listings` (a map keyed by coordinate, the catalogue read's shape) while the live studio route
   * sends `listing` — singular, and `null` on master because a master row has no channel listing.
   *
   * On THIS sheet `{}` is the truthful answer rather than a placeholder: master scope genuinely has
   * no per-coordinate listings. It would NOT be truthful on PES.3's channel sheet, which is why
   * this is a master-only line and a rename request rather than a shared helper.
   */
  const resolveRow = useCallback((rowId: string) => {
    const row = rowsRef.current.find((r) => r.id === rowId)
    return row ? ({ ...row, listings: {} } as unknown as DrawerSheetRow) : null
  }, [])

  const drawerScope = useMemo(
    () => ({ kind: 'master' as const, marketplace: market, locale, label: sheet?.scope.label ?? `Master · ${market}` }),
    [market, locale, sheet],
  )

  /**
   * A drawer edit goes through the SAME writer as a cell edit — one write path, one dirty state,
   * one set of cell states. The drawer's `intent` rides along; `commit` decides what a reset costs
   * on this scope (see `useMasterSheet`).
   *
   * It answers `pending` rather than waiting for the server: the write is queued and batched, and
   * the cell it belongs to paints its own outcome. Blocking the drawer's field on a round trip
   * would give the operator two different accounts of the same save.
   */
  const onDrawerWrite = useCallback(
    async (req: RecordWriteRequest): Promise<RecordWriteResult> => {
      const row = rowsRef.current.find((r) => r.id === req.rowId)
      if (!row) return { state: 'refused', message: 'That row is no longer on the sheet — reload it.' }
      // The drawer speaks `writeField` (the wire name); the writer and the grid speak column keys.
      const column = (sheet?.columns ?? []).find((c) => c.writeField === req.writeField || c.key === req.writeField)
      if (!column) return { state: 'refused', message: `No column on this sheet writes “${req.writeField}”.` }
      writer.set(req.rowId, column.key, req.value, { row, intent: req.intent })
      return { state: 'pending' }
    },
    [sheet, writer],
  )

  const compareTargets = useMemo(
    () => (sheet ? [{ id: 'master', label: sheet.scope.label ?? 'Master', kind: 'master' as const, scope: drawerScope }] : []),
    [sheet, drawerScope],
  )
  const staleTypes = sheet?.meta.schemaAge.filter((a) => Date.now() - new Date(a.fetchedAt).getTime() > 7 * 864e5) ?? []
  const emptyState = sheetEmptyState(rows.length, () => {
    setSearch('')
    chipBar.setActive(null)
    setShowRefusedOnly(false)
    getGridApi()?.setFilterModel(null)
  }, onReload)

  return (
    <>
      {mediaEditor.element}
      {formulaHistoryOpen && <FormulaHistoryDialog familyProductId={productId} coordinate={{ scope: 'master', market, locale }}
        onClose={() => setFormulaHistoryOpen(false)} onApplied={() => { formulas.reload(); refresh() }} />}
      {bulkFormulaRows && <FormulaBulkDialog rows={bulkFormulaRows} columns={sheet?.columns ?? []}
        coordinate={{ scope: 'master', market, locale }} functions={formulas.functions} preview={formulas.preview}
        candidatesFor={id => { const row = rowsRef.current.find(row => row.id === id); return row ? candidatesFor(row) : [] }}
        onClose={() => setBulkFormulaRows(null)} onApplied={() => { formulas.reload(); refresh() }} />}
      <GridSheet
        toolbar={
          <>
          {/* §2.1c — the family bar is FOLDED, not deleted: its 49px band cost more than it earned
              above a sheet, but both halves survive. The descriptor joins the count slot (it is
              what this sheet IS, which is the same kind of fact as how many rows it has); the
              family verbs move into the toolbar's right-hand group.

              🔴 The verbs go to the TOOLBAR, not the selection bar — the correction that came out
              of §2.1c. They are `contextOf('product-family')`: they act on the family, so on a real
              session they are available at ZERO selection, and a selection-gated bar would make an
              operator tick an arbitrary row to reach a verb that does not act on it. The evidence
              that they were "all disabled at zero selection anyway" was a local-dev artifact —
              every `can()` is false on this machine because the session is `anon`. */}
          {/* §14.1 — the SHARED bar. Master and channel mount the same component; the family
              verbs and the schema-staleness warning are ADDITIONS to it, not a replacement for it.
              Nothing standard is passed in, so nothing standard can be silently dropped. */}
          <SheetToolbar
            visible={visibleRows.length}
            total={rows.length}
            selected={selected}
            descriptor={
              familySummary.role !== '—' ? (
                <span className="nds-cell-muted"> · {familySummary.role} · {familySummary.detail}</span>
              ) : null
            }
            search={search}
            onSearch={setSearch}
            views={gridState}
            presets={sheetColumns.presets}
            activePresetId={sheetColumns.activePresetId}
            onApplyPreset={applyPreset}
            viewsEmptyLabel={sheetColumns.emptyLabel}
            onSaveCurrentView={sheetColumns.saveCurrentAs}
            onUpdateCurrentView={sheetColumns.updateView}
            describeView={sheetColumns.describeView}
            chips={chipBar.chips}
            activeChipId={chipBar.activeId}
            onChipToggle={chipBar.setActive}
            onCustomise={openCustomise}
            onExport={() => { setTransferIntent('export'); setImportOpen(true) }}
            exportCounts={{ view: sheetColumns.visibleAttributeKeys().length, all: sheetColumns.orderedKeys.length }}
            exportDisabled={!sheet || loading || !has('products.export')}
            exportPurpose="workbook"
            onImport={() => { setTransferIntent('import'); setImportOpen(true) }}
            /* Disabled until the sheet has loaded: the drawer writes to the coordinate the sheet
               was on, and until `sheet.scope` exists there is no coordinate to name. */
            importDisabled={!sheet || loading || !has('products.import')}
            onReload={onReload}
            loading={loading}
            unavailable={!!error}
            overflow={[...familyVerbs.items, { id: 'formula-history', label: 'Formula history…', onSelect: () => setFormulaHistoryOpen(true) }, { id: 'bulk-formula', label: 'Apply formula to selected products…', disabled: !selected || !formulas.ready || !canEdit, onSelect: () => setBulkFormulaRows(selectedRows.map(row => ({ id: row.id, label: row.sku ?? row.id })).sort((a, b) => Number(a.id === productId) - Number(b.id === productId))) }]}
            trailing={
              <>
                <ClassificationDialog productId={productId} disabled={loading || !!error || !canEdit} onChanged={onFamilyChanged} />
                {(staleTypes.length > 0 || (sheet?.meta.schemaMissing.length ?? 0) > 0) && (
                  <InfoTip
                    tip={
                      sheet && sheet.meta.schemaMissing.length > 0
                        ? `Attribute setup is incomplete: ${sheet.meta.schemaMissing.join(', ')}. Choose a product family in Classification; channel requirements use their selected category.`
                        : `Length caps and lists come from a schema last fetched ${staleTypes.map((t) => `${t.productType} ${t.fetchedAt.slice(0, 10)}`).join(', ')}.`
                    }
                  >
                    <Pill tone="warning" size="md"><AlertTriangle size={11} /> {(sheet?.meta.schemaMissing.length ?? 0) > 0 ? 'Setup incomplete' : 'Cached requirements'}</Pill>
                  </InfoTip>
                )}
                {familyVerbs.status}
              </>
            }
          />
          </>
        }
        footer={
          !loading && !error && <>
          {/* F2 — the selection verbs. In the FOOTER so it sits at the bottom of the sheet's own
              bounded container, which is where BulkActionBar is specified to live; it renders
              nothing at zero selection, so it costs no space until there is a selection. */}
          <FamilySelectionBar rows={selectedRows} actions={famActions} onClear={clearSelection} onDone={onFamilyChanged} />
          {/* 🔴 The right-click menu's OWN confirm dialog. Without this mounted, a verb run from the
              context menu would await an `ask()` whose dialog never renders — the promise never
              settles and the verb hangs silently, with the row menu simply closing as if nothing
              had been pressed. Every surface that runs a verb has to mount its own. */}
          {rowPress.problem && <div className="nds-grid-footstrip" role="alert"><span className="nds-cell-stock-out">{rowPress.problem}</span></div>}
          {rowPress.confirmElement}
          {familyVerbs.dialogs}
          {reloadConfirm.element}
          <GridSheetStatus rows={visibleRows.length} selected={selected} pending={pending} refused={refused} saving={writer.busy} lastSavedAt={lastSavedAt}>
            {/* §6.5 — ONE footer slot, occupants by priority. The refusal outranks the hint because a
                blocked write is the only thing here an operator must act on; the hint is what they
                can already do. Height never changes (DS.2 measured STRIP_GREW 0 for all four kinds),
                so the strip does not move under them when a write is refused. */}
            {/* The ONE note slot — offline · refusal · keyboard hint — is `SheetFooterNote`, shared with
                the channel scopes so the footer reads identically on all three (2026-09-04). */}
            <SheetFooterNote
              layoutRecovery={sheetColumns.loadError ? { retry: sheetColumns.reloadSavedPreferences } : null}
              offline={offline}
              refused={refused}
              showRefusedOnly={showRefusedOnly}
              onToggleRefused={() => setShowRefusedOnly((v) => !v)}
              lastSavedAt={lastSavedAt}
            />
            {/* AG.1-e — what the file actually contains. A download that says nothing leaves the
                operator checking their Downloads folder to find out whether it worked, and a REFUSAL
                (a server-side row model) has to be readable rather than silent. */}
            {exportNote && <span className="nds-cell-muted">{exportNote}</span>}
            {sheet?.meta.source === 'legacy' && (
              <InfoTip tip="The studio sheet route is not deployed yet, so this is the catalogue read adapted to the same shape. Cell values and versions are real; the layer each value came from is INFERRED here rather than stated by the server.">
                <Pill tone="neutral" size="sm">adapted read</Pill>
              </InfoTip>
            )}
            {conflicts.length > 0 && (
              <Button size="sm" variant="link" onClick={reload}>
                {conflicts.length} {conflicts.length === 1 ? 'row' : 'rows'} changed elsewhere — refresh
              </Button>
            )}
          </GridSheetStatus>
          </>
        }
      >
        {error ? (
          <SheetLoadError label="shared product information" onRetry={reload} />
        ) : (
          <>
            {contractProblems.length > 0 && (
              <Banner tone="warning" title="The sheet read did not match its contract">
                {contractProblems.join(' · ')}
              </Banner>
            )}
            <NexusGrid<StudioRow>
              fill
              {...SHEET_GRID_OPTIONS}
              {...SHEET_STATE_OVERLAYS}
              noRowsOverlayComponentParams={emptyState}
              {...mediaClipboard}
              rows="media-line"
              getContextMenuItems={stableContextMenu}
              treeData
              flatTree
              groupDefaultExpanded={-1}
              tooltipShowDelay={300}
              rowData={loading ? [] : visibleRows}
              /* The band's width is measured from the band, so it is measured when AG says a band
                 exists — never on a timer (#744). */
              onFirstDataRendered={remeasureSoon}
              onRowDataUpdated={remeasureSoon}
              /* A stashed reveal becomes measurable the moment the columns actually move — which is
                 what the band's derivation does to every centre column. Cheap: `replayReveal` is a
                 no-op unless something is stashed, and the stash is dropped once served. */
              onDisplayedColumnsChanged={replayReveal}
              onColumnResized={replayReveal}
              columnDefs={columnDefs}
              defaultColDef={defaultColDef}
              autoGroupColumnDef={autoGroupColumnDef}
              getRowId={getRowId}
              getDataPath={getDataPath}
              rowSelection={rowSelection}
              onSelectionChanged={onSelectionChanged}
              onGridReady={onGridReady}
              onGridPreDestroyed={onGridPreDestroyed}
              onCellValueChanged={onCellValueChanged}
              processDataFromClipboard={processDataFromClipboard}
              loading={loading}
              columnDialog={columnDialog}
              initialState={sheetColumns.initialState}
              onCellDoubleClicked={onCellDoubleClicked}
              onCellKeyDown={onCellKeyDown}
              onCellFocused={onCellFocused}
            />
          </>
        )}
      </GridSheet>

      {/*
        PES.8's review panel (ruling #75), shown only while the ✦ chip is ACTIVE.
        The chip stays a pure filter (#34) — it narrows the sheet to the drafted cells — and this
        appears beside that filtered view, so approve/reject sits next to the tinted cells it
        decides on rather than in a surface of its own. It shares the chip's fetch: one
        `useAiDraftLayer` feeds the overlay, the chip and this panel.

        🔴 `onApplied={reload}` is not optional. Approving replays through `PATCH /api/products/bulk`,
        so the CELL now holds a new value while these rows still hold the old one. PES.8's hook
        refreshes its own drafts and has no way to refresh mine — without this the tint clears and
        the cell underneath still shows the pre-approval value, breaking "displayed must round-trip"
        at the exact moment the operator is watching for the change they just made.
      */}
      {chipBar.activeId === 'ai-drafts' && <AiDraftReview drafts={aiLayer.drafts} skuById={skuById} onApplied={reload} />}

      {/*
        PES.4's record drawer (ruling #30). It portals itself into the frame's reserved track, so
        it renders nothing until a row is open — the sheet does not lay out around it.
      */}
      <StudioDock
        resolveRow={resolveRow}
        columns={sheet?.columns ?? []}
        scope={drawerScope}
        compareTargets={compareTargets}
        loading={loading}
        error={error}
        onWrite={onDrawerWrite}
        onRevealCell={onRevealCell}
        /* PES.4's D16 formula field in the drawer (#730). The hook stays HERE and is injected
           because it needs the full coordinate including `market`, which `DrawerScope` does not
           carry — `/pim/formulas/preview` refuses without one (#729) and a guessed market is a
           plausible wrong answer rather than an error. Injecting also keeps ONE answer to "what
           formula is on this cell" for rows the sheet already holds.
           🔴 No `writesRefused` here, deliberately: master's drawer DOES write. The channel scope
           refuses writes wholesale and must declare it, because a host that refuses by RETURNING a
           refusal from `onWrite` can only be discovered by calling `onWrite` — and calling it is
           the write. A formula reaches the server through `save`, not through `onWrite`, so that
           refusal could not have stopped it (PES.3's catch, not mine). */
        formulas={formulas}
      />

      {/*
        The ONE Customise dialog, wired the way `/products/next` wires it — same component, same
        props shape, same behaviour. `showSticky={false}`: the sheet pins its identity block through
        the padlocks above, and a second sticky control would be a different answer to the same
        question. No group/aggregate options: the rows are one family's tree, and row grouping would
        fight `treeData`.
      */}
      {sheet && (
        <ProductTransferDrawer
          open={importOpen}
          intent={transferIntent}
          onClose={() => setImportOpen(false)}
          productId={productId}
          market={market}
          locale={locale}
          selectedIds={selectedRows.map(row => row.id)}
          visibleFields={sheetColumns.visibleAttributeKeys().flatMap(key => { const c = sheet.columns.find(c => c.key === key); return c ? [c.slot?.of ?? c.key] : [] })}
          onReference={() => onExport('view')}
          onApplied={() => { formulas.reload(); reload(); familyQuery.reload() }}
        />
      )}
      {familyProductPicker.element}
      <PreferencesModal
        open={prefsOpen}
        onClose={() => setPrefsOpen(false)}
        value={prefsDraft ?? { visibleColumns: [], lockedColumns, stickyFirstColumn: true, stickyLastColumn: false, pageSize: 0, sortBy: '', sortDir: 'asc' }}
        onConfirm={confirmPrefs}
        /* 🔴 ONE identity entry, derived — not three hardcoded ones. `sku` and `completeness` were
           offered here as lockable columns after they had become the band's key line and its
           readiness pill, so the dialog promised two toggles the grid could not honour and the
           bridge refused them on every load. The label names what the single locked column now
           contains, because "Family" no longer describes a cell holding the SKU and the pill. */
        allColumns={sheetColumns.preferenceColumns}
        // Reset = the ground state: every column, §9.2 order (design V.4d).
        defaultVisible={sheetColumns.allColumnKeys}
        pageSizeChoices={[]}
        sortFieldOptions={[]}
        showSticky={false}
        groupToggles
        inViewCount
        attributeGroups
        onReloadSaved={sheetColumns.reloadSavedPreferences}
        viewSave={{ activeName: sheetColumns.activeViewName, onSaveAs: saveDraftAsView, onUpdate: sheetColumns.activeViewName ? updateActiveView : undefined }}
        title={sheetColumns.activeViewName ? `Customise columns · ${sheetColumns.activeViewName}` : 'Customise columns'}
        listHint="Organise attributes into groups and choose their order. Save keeps your personal layout for this market, including after a reload."
      />
    </>
  )
}

/**
 * PES.2 — the master scope's WRITE, in its own module so the node suite can reach it.
 *
 * 🔴 Two separate reasons this file exists, and the second one is the trap.
 *
 * 1. `commit` was declared **inside** `useMasterSheet`, so no test could touch it — the master
 *    sheet's whole write path, and the function at the centre of P2-1's in-flight latch. Its twin
 *    `commitChannelRow` was module-level with `channelWrite.vitest.test.ts` beside it. Same
 *    operation, two lanes: one testable and tested, one neither. (FE.1's set-scan, hub #348.)
 *
 * 2. **Hoisting it to module scope was NOT enough**, and this is the part worth remembering.
 *    `useMasterSheet.ts` VALUE-imports `@/design-system/grid` for `SheetWriter` and
 *    `CellSaveTracker`; that barrel re-exports `NexusGrid.tsx`, and a node test importing anything
 *    from that module dies at **parse** — before a single test runs. `useChannelSheet.ts` is
 *    testable because its grid import is `import type`, which is erased. So the rule is not "hoist
 *    to module scope", it is: **a unit is testable only if nothing on its import path is a `.tsx`.**
 *    Same lesson as `design-system/grid/renderers/emptyValue.ts`, in a second place.
 *
 * This module therefore type-imports the grid and imports no React at all.
 */
import { getBackendUrl } from '@/lib/backend-url'

import type { SheetWriteRequest, SheetWriteResult } from '@/design-system/grid'
import type { StudioRow, StudioSheet } from './types'
import type { UseMasterSheetOptions } from './useMasterSheet'

/**
 * The master scope's write, as a MODULE-LEVEL function so it can be tested.
 *
 * 🔴 This was declared inside `useMasterSheet` and **no test touched it** — the master sheet's whole
 * write path, the `commit` that `SheetWriter` calls, and the function at the centre of the P2-1
 * in-flight latch. Its counterpart `commitChannelRow` is a module-level export in
 * `useChannelSheet.ts` with `channelWrite.vitest.test.ts` beside it, and that is the one that got
 * probed with a stubbed `fetch` when the `errors[]`-before-`updated` ordering needed confirming.
 * Same operation, two lanes: one testable and tested, one neither. Found by FE.1's set-scan, which
 * measured that 76% of the logic in these trees is unreachable by the suite that exists.
 *
 * It hoisted cleanly because it only ever captured three things — two refs and a scalar — so the
 * context is passed explicitly. **The refs are read by the CALLER at call time**, not captured here:
 * `sheet` is whatever the last read produced, and a stale copy would write against a column set the
 * operator is no longer looking at.
 */
export interface MasterCommitContext {
  /** The sheet as of THIS call — supplies `columns`, i.e. where each cell writes. */
  sheet: StudioSheet | null
  /** Only the write callbacks; this function has no business with the rest of the options. */
  opts: Pick<UseMasterSheetOptions, 'onWriteStart' | 'onWriteEnd'>
  locale: string
  /**
   * 🔴 The marketplace the sheet was READ with — NOT `sheet.scope.marketplace`.
   *
   * The ruling said to take it from the sheet's own scope. Measured before writing: on master the
   * server returns `scope: { kind: 'master', marketplace: null, locale: 'de', label: 'Master' }`
   * even when the sheet was requested at `?market=DE`. So the scope does not carry it back, and a
   * fix reading from there would have omitted the context and left every `attr_*` write refused —
   * the defect intact behind a change that looked like the fix.
   *
   * This is the same coordinate that built the read URL, so the write is validated against exactly
   * the schema that declared the columns writable.
   */
  market: string
}

export async function commitMasterRow(
  req: SheetWriteRequest<StudioRow>,
  ctx: MasterCommitContext,
): Promise<SheetWriteResult> {
  const backend = getBackendUrl()
  const columns = ctx.sheet?.columns ?? []
  const byKey = new Map(columns.map((c) => [c.key, c]))
  const cells: Record<string, { ok: boolean; reason?: string; unreachable?: boolean }> = {}

  const bulk = req.cells

/**
 * The row version a response is allowed to teach us — `undefined` when it is about something else.
 *
 * 🔴 `currentVersion` is NOT unconditionally the product's (#701, PES.5). The route answers
 * `versionOf: 'product' | 'channelListing'`, and on a channel-only write the number is the
 * LISTING's version. Storing that as the product's would poison the row: every later write would
 * send a version the product never had and come back 409 "someone else changed this row", when the
 * someone else was this arithmetic. Absent is treated as `product` because that is what the route
 * omits it for — a master write that answered before the field existed.
 *
 * Keeping the held version is the conservative direction, and it is what the 200 branch's own
 * comment already argues for: a kept version costs at most one recoverable 409, a wrong one costs a
 * row that cannot be written until reload.
 *
 * ⚠ `sheetWriter.ts:223` has a METHOD called `versionOf(rowId)` that returns a row's version. It is
 * a homonym of this response field, in the same subsystem, and grepping the name finds it first.
 */
function versionFromBody(body: { currentVersion?: unknown; versionOf?: unknown } | null): number | undefined {
  if (typeof body?.currentVersion !== 'number') return undefined
  if (body.versionOf !== undefined && body.versionOf !== 'product') return undefined
  return body.currentVersion
}

  /* The ROW is the subject the header counts (#693) — passed explicitly rather than parsed back
     out of `writeId`, because the three reporter callers each build that id differently and a
     frame that split on ':' would be guessing at two of them. */
  const writeId = `${req.rowId}:${Date.now()}`
  ctx.opts.onWriteStart?.(writeId, req.rowId)

  let version: number | undefined
  let conflict = false
  let batchReason: string | undefined
  let anyOk = false

  try {
    if (bulk.length > 0) {
      const res = await fetch(`${backend}/api/products/bulk`, {
        method: 'PATCH',
        signal: AbortSignal.timeout(30_000),
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          changes: bulk.map((c) => ({
            id: req.rowId,
            contentAddress: req.row?.values?.[c.colId]?.contentAddress,
            contentVersion: req.row?.values?.[c.colId]?.contentVersion,
            // The server told us the field name; never re-derive it from the column key.
            field: byKey.get(c.colId)?.writeField ?? c.colId,
            // 🔴 On the MASTER scope a `reset` really is "store nothing here", because the layer
            // above is the parent and `resolveAttributes` falls through to it the moment this row
            // holds no value of its own. That is a fact about THIS scope, not about resets: a
            // channel scope resets by clearing `*Override` and restoring `followMaster*`, which
            // is a different route entirely (PES.3 owns that `commit`). The intent is honoured
            // here rather than in the writer precisely so the two can differ.
            value: c.intent === 'reset' ? null : c.value === '' ? null : c.value,
            ...(c.intent === 'reset' ? { intent: 'reset' } : {}),
          })),
          /* 🔴 THE MARKETPLACE CONTEXT. Without it every `attr_*` write on the master scope was
             REFUSED — the Owner's "I'm unable to write a lot of attributes still, such as color".
             `products.routes.ts:1403` validates each `attr_*` change with
             `getFieldDefinition(field, { marketplace: primaryContext?.marketplace ?? null })`, and
             this body carried no contexts at all, so every master attribute arrived with
             `marketplace: null` and came back 400 "Unknown or read-only category attribute".
             SC.1 measured it across the whole schema: **master DE/de 60 of 60 `attr_*` columns
             refused, Amazon·DE 57 accepted** — the difference being that the channel writer sends
             its contexts and this one did not.

             The marketplace comes from the coordinate the sheet was READ with — see
             `MasterCommitContext.market` for why NOT from `sheet.scope`, which the server returns
             as `null` on this endpoint. A write is validated against the schema that declared the
             column, or the two are answering different questions. */
          ...(ctx.market
            ? { marketplaceContexts: [{ marketplace: ctx.market, locale: ctx.locale }] }
            : {}),
          // Omitted when unknown — the endpoint treats absent as "no concurrency guard", which is
          // honest, where a guessed number would refuse a write the operator is entitled to make.
          //
          // ⚠ NOT covered by a test, and it cannot be: `expectedVersion: req.expectedVersion` with
          // an undefined value is an EQUIVALENT MUTANT, because `JSON.stringify` drops undefined
          // properties — both forms put identical bytes on the wire. The spread stays because it
          // states the intent at the call site, but do not read the green suite as evidence that
          // this line is load-bearing; it becomes so only if the body stops going through
          // `JSON.stringify`.
          ...(req.expectedVersion !== undefined ? { expectedVersion: req.expectedVersion } : {}),
        }),
      })
      const body = await res.json().catch(() => null)
      if (res.status >= 500 || res.ok && (!body || typeof body.updated !== 'number' && !Array.isArray(body.errors))) throw new Error('Save confirmation was unavailable. Checking the stored values.')

      if (res.status === 409) {
        conflict = true
        version = versionFromBody(body)
        batchReason = body?.message || body?.error || 'Someone else changed this row. Refresh to see their version.'
        for (const c of bulk) cells[c.colId] = { ok: false, reason: batchReason }
      } else if (!res.ok) {
        const errors: Array<{ id?: string; field?: string; error?: string }> = Array.isArray(body?.errors) ? body.errors : []
        batchReason = body?.error || body?.message || errors[0]?.error || `Refused (HTTP ${res.status})`
        for (const c of bulk) {
          const field = byKey.get(c.colId)?.writeField ?? c.colId
          const mine = errors.find(e => e.id === req.rowId && (e.field === field || e.field === c.colId))
          cells[c.colId] = { ok: false, reason: mine?.error || batchReason }
        }
      } else {
        // A 200 can still carry per-cell refusals beside a partial success.
        const errors: Array<{ id?: string; field?: string; error?: string }> = Array.isArray(body?.errors) ? body.errors : []
        for (const c of bulk) {
          const field = byKey.get(c.colId)?.writeField ?? c.colId
          const mine = errors.find((e) => e.id === req.rowId && (e.field === field || e.field === c.colId))
          cells[c.colId] = mine ? { ok: false, reason: mine.error || 'Refused' } : { ok: true }
          if (!mine) anyOk = true
        }
        /*
         * 🔴 READ BACK, never computed. The `expectedVersion + 1` that used to sit here invented a
         * version the row might never have had — the banked `Product.version` ≠ row version trap —
         * and the route was doing the same arithmetic on its own side
         * (`freshChannelVersion ?? expectedVersion + 1`), directly beneath a comment explaining why
         * computing is wrong. **Two independent guesses agreeing is not a measurement.**
         *
         * If the server returns no version it did not participate in the CAS, and the caller keeps
         * the version it read from the sheet. A guessed version loses a race it should have won.
         */
        version = versionFromBody(body) ?? version
      }
    }


  } catch (err) {
    /*
     * 🔴 `unreachable: true`. This catch swallows a NETWORK failure — `fetch` rejects when the
     * connection is refused — and returning a plain `{ ok: false }` made it indistinguishable from
     * a server refusal, so the writer painted `refused`. Measured against a real API restart:
     * `net::ERR_CONNECTION_REFUSED`, cell `refused`, and the operator told a change had failed that
     * the server may well have applied.
     *
     * The writer's `unknown` path existed and was UNREACHABLE from this sheet, because the unit
     * test mocked a `commit` that rejects and the real one never does.
     */
    const reason = err instanceof Error ? err.message : String(err)
    for (const c of req.cells) cells[c.colId] = cells[c.colId] ? { ...cells[c.colId], unreachable: false } : { ok: false, reason, unreachable: true }
    ctx.opts.onWriteEnd?.(writeId, false, reason, req.rowId)
    return { ok: false, reason, cells, unreachable: true }
  }

  const ok = Object.values(cells).every((c) => c.ok)
  // Ruling #27: the header renders the reporter's message verbatim, so it must never be empty on
  // a failure. A 200 can carry per-cell refusals with no batch-level reason at all, and reporting
  // `undefined` there would leave the header saying a write failed without saying why.
  const firstReason = Object.values(cells).find((c) => !c.ok)?.reason
  ctx.opts.onWriteEnd?.(writeId, ok, ok ? undefined : (batchReason ?? firstReason), req.rowId)
  return { ok: ok || anyOk, reason: batchReason, version, cells, conflict }
}

'use client'

/**
 * PES.3 — the channel scope's data: read one channel×market, save ONE CELL at a time.
 *
 * Reads `GET /api/products/:id/studio/sheet?scope=channel&…` (PES.5 §3.2, Owner-approved
 * 2026-09-01). Writes stay on `PATCH /api/products/bulk` — §3.2 is explicit that "the write path
 * itself is unchanged" — driven by PES.2's `SheetWriter`, which owns batching, version advancement
 * and per-row serialisation (hub ruling #11). This module supplies only its `commit`.
 *
 * Autosave per cell, no page-level Save, no dirty-sheet state; a refusal is a RESULT that stays on
 * the cell rather than a toast that scrolls away.
 *
 * ── Honesty about the backend ───────────────────────────────────────────────────────────────────
 * PES.5's route is approved but not deployed yet. Until it is, this reports `backendMissing` and the
 * sheet says so on screen. It NEVER substitutes fixture rows: a channel scope drawing plausible
 * aliases from a fixture would be a page lying about live listings.
 */
import { useCallback, useEffect, useRef, useState } from 'react'
import { commitShopifySheetRow } from '../../shopify/channelSheetWriter'
import { applyNormalizedReferenceChanges } from '../normalizedReferenceChanges'

import { getBackendUrl } from '@/lib/backend-url'

import type { SheetWriteRequest, SheetWriteResult } from '@/design-system/grid'

import { wireAliasKey } from './types'
import { wholeListWriteField } from './provenance'
import type { AliasGroup, ChannelScopeChannel, ChannelScopePage, ChannelSheetRow } from './types'

export interface UseChannelSheetOptions {
  schemaRevision?: string

  accountId?: string
  /** The route's `[id]`. May be a parent or a child — PES.5 resolves to the family root. */
  productId: string
  channel: ChannelScopeChannel
  marketplace: string
  locale?: string
  view?: string
}

export interface ChannelSheetState {
  data: ChannelScopePage | null
  loading: boolean
  error: string | null
  /**
   * True when the failure is specifically "PES.5's route is not deployed yet" (404 / 501). The sheet
   * renders an honest notice for this instead of an empty grid — an empty grid and a missing
   * endpoint look identical to an operator, and only one is a fact about the catalogue.
   */
  backendMissing: boolean
  reload: () => void
  /** Reconcile saved values and provenance without replacing the grid with a loading state. */
  refresh: (canApply: () => boolean) => Promise<void>
  applyLocal: (rowId: string, mutate: (row: ChannelSheetRow) => void) => void
}

/**
 * PES.5 §3.2.
 *
 * 🔴 The market parameter is `market`, NOT `marketplace`. §3.2's prose writes `&marketplace=`, but
 * the shipped route reads `q.market` and answers `400 {"error":"market is required"}` — verified
 * against the running service, not the doc. The RESPONSE still calls it `scope.marketplace`, so the
 * two names genuinely coexist and only the request side takes `market`.
 */
export function channelScopeUrl(o: UseChannelSheetOptions): string {
  const params = new URLSearchParams({
    scope: 'channel',
    channel: o.channel,
    market: o.marketplace,
  })
  if (o.accountId) params.set('accountId', o.accountId)
  if (o.locale) params.set('locale', o.locale)
  if (o.view) params.set('view', o.view)
  return `${getBackendUrl()}/api/products/${o.productId}/studio/sheet?${params}`
}

/** A successful HTTP response must contain a sheet before it can replace the current view. */
export function channelSheetResponse(body: unknown): ChannelScopePage {
  const page = body as Partial<ChannelScopePage> | null
  if (!page || !Array.isArray(page.rows) || !Array.isArray(page.columns) || !Array.isArray(page.aliases) ||
      !page.scope || typeof page.scope.channel !== 'string' || typeof page.scope.marketplace !== 'string' ||
      !page.meta || !Array.isArray(page.meta.schemaMissing) || !Array.isArray(page.meta.schemaAge)) {
    throw new Error('The information response was incomplete. Try again.')
  }
  return page as ChannelScopePage
}

export function useChannelSheet(options: UseChannelSheetOptions): ChannelSheetState {
  const url = channelScopeUrl(options)
  const activeUrl = useRef(url)
  activeUrl.current = url
  const [response, setResponse] = useState<{ url: string; data: ChannelScopePage | null } | null>(null)
  const data = response?.url === url ? response.data : null
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [backendMissing, setBackendMissing] = useState(false)
  const [nonce, setNonce] = useState(0)
  // A slow coordinate must not paint over a faster one the operator has since switched to.
  const requestRef = useRef(0)

  useEffect(() => {
    const mine = ++requestRef.current
    let cancelled = false
    const abort = new AbortController()
    setLoading(true)
    setError(null)
    setBackendMissing(false)

    // Keep the current coordinate's schema during reload so AG retains column state.
    // `response.url === url` above already prevents another coordinate's data from showing.
    fetch(url, {
      credentials: 'include',
      cache: 'no-store',
      signal: AbortSignal.any([abort.signal, AbortSignal.timeout(30_000)]),
    })
      .then(async (res) => {
        const body = await res.json().catch(() => null)
        if (res.status === 404 || res.status === 501) {
          const err = new Error(body?.message || body?.error || `HTTP ${res.status}`)
          ;(err as Error & { backendMissing?: boolean }).backendMissing = true
          throw err
        }
        if (!res.ok) throw new Error(body?.message || body?.error || `HTTP ${res.status}`)
        return channelSheetResponse(body)
      })
      .then((body) => {
        if (cancelled || mine !== requestRef.current || activeUrl.current !== url) return
        setResponse({ url, data: body })
      })
      .catch((err: unknown) => {
        if (cancelled || mine !== requestRef.current || activeUrl.current !== url) return
        setResponse(previous => previous?.url === url ? previous : { url, data: null })
        setBackendMissing(!!(err as { backendMissing?: boolean })?.backendMissing)
        setError(err instanceof Error ? err.message : String(err))
      })
      .finally(() => {
        if (!cancelled && mine === requestRef.current && activeUrl.current === url) setLoading(false)
      })

    return () => {
      cancelled = true
      requestRef.current++
      abort.abort()
    }
  }, [url, nonce, options.schemaRevision])

  const reload = useCallback(() => setNonce((n) => n + 1), [])

  const refresh = useCallback(async (canApply: () => boolean) => {
    if (activeUrl.current !== url) return
    const mine = ++requestRef.current
    try {
      const res = await fetch(url, {
        credentials: 'include', cache: 'no-store', signal: AbortSignal.timeout(30_000),
      })
      if (!res.ok) return
      const body = channelSheetResponse(await res.json())
      if (mine === requestRef.current && activeUrl.current === url && canApply()) setResponse({ url, data: body })
    } catch {
      // Preserve the confirmed edit if the follow-up read is temporarily unavailable.
    }
  }, [url])

  const applyLocal = useCallback((rowId: string, mutate: (row: ChannelSheetRow) => void) => {
    setResponse((prev) => {
      if (!prev?.data || prev.url !== url || activeUrl.current !== url) return prev
      const rows = prev.data.rows.map((r) => {
        const id = `${r.aliasId ?? 'primary'}:${r.id}`
        if (id !== rowId && r.id !== rowId) return r
        const next = { ...r, values: { ...r.values } } as ChannelSheetRow
        mutate(next)
        return next
      })
      return { url, data: { ...prev.data, rows } }
    })
  }, [url])

  const current = response?.url === url
  return { data, loading: current ? loading : true, error: current ? error : null, backendMissing: current && backendMissing, reload, refresh, applyLocal }
}

/**
 * Send ONE row's batch of cell edits — the `commit` PES.2's `SheetWriter` asks this lane for.
 *
 * The writer owns batching, version advancement and per-row serialisation; this owns only the wire.
 * Two rules it must not get wrong:
 *
 *  1. **The write target comes from the CELL**, not from this client. PES.5 §3.2 sends `writeField`
 *     + `writeTarget` "so the grid never has to re-derive where a cell writes". Re-deriving it here
 *     is exactly how a channel edit silently lands on the master record.
 *  2. **A reset is not "write null".** The substrate carries `intent` per cell, so a reset rides as
 *     `intent: 'reset'` and the server restores `follows` / deletes the override key, letting the
 *     value fall back up the cascade. Writing null instead would pin an explicit blank.
 *
 * A refusal is a RESULT, never an exception, and `version` is returned on success AND on a 409 so
 * the writer stays able to retry instead of stuck one version behind for the session.
 */
/**
 * Does this cell's write land on the ChannelListing rather than the Product?
 *
 * The SERVER's answer (`writeTarget`), never a client copy of the API's `CHANNEL_FIELD_MAP`
 * (D15.16.4). Exported so the write contract's test can assert the predicate itself rather than
 * only its consequences.
 */
export const writeLandsOnListing = (cell: { writeTarget?: string } | null | undefined): boolean =>
  cell?.writeTarget === 'channelListing'

export async function commitChannelRow(
  req: SheetWriteRequest<ChannelSheetRow>,
  coord: { channel: ChannelScopeChannel; marketplace: string; accountId?: string; locale?: string },
): Promise<SheetWriteResult> {
  const row = req.row
  if (!row) return { ok: false, reason: 'The grid no longer holds this row — reload the sheet' }
  if (row.shopify && req.cells.every(cell => !!row.values[cell.colId]?.shopifyWrite && !row.values[cell.colId]?.contentAcknowledgement)) return commitShopifySheetRow(req, coord)
  if (req.cells.some(cell => !!row.values[cell.colId]?.shopifyWrite && !row.values[cell.colId]?.contentAcknowledgement)) {
    const results: SheetWriteResult[] = [], cells: NonNullable<SheetWriteResult['cells']> = {}
    // Shared/listing CAS first; the narrow Shopify adapter independently checks each draft cell.
    for (const native of [false, true]) {
      const subset = req.cells.filter(cell => (!!row.values[cell.colId]?.shopifyWrite && !row.values[cell.colId]?.contentAcknowledgement) === native)
      const result = await commitChannelRow({ ...req, cells: subset }, coord)
      results.push(result)
      for (const cell of subset) cells[cell.colId] = { ...(result.cells?.[cell.colId] ?? { ok: result.ok, reason: result.reason }), unreachable: result.cells?.[cell.colId]?.unreachable ?? !!result.unreachable }
    }
    return { ok: results.every(result => result.ok), cells, version: results[0].version, conflict: results.some(result => result.conflict), unreachable: results.some(result => result.unreachable), reason: results.find(result => !result.ok)?.reason }
  }

  const changes = req.cells.map(({ colId, value, intent }) => {
    const cell = row.values?.[colId]
    const address = intent === 'reset' || intent === 'reset-list' ? cell?.contentAcknowledgement?.pin.address ?? cell?.contentAddress : cell?.contentAddress
    const isReset = intent === 'reset' || intent === 'reset-list'
    return {
      colId,
      change: {
        id: row.id,
        contentAddress: address,
        ...(cell?.contentAcknowledged || isReset && cell?.contentAcknowledgement ? { contentAcknowledged: true } : {}),
        contentVersion: cell?.contentVersion,
        // Fall back to the column key only when the server sent no cell for it; a made-up
        // writeField would be a write aimed at nothing.
        field: intent === 'reset-list' ? wholeListWriteField(cell?.writeField ?? colId) ?? cell?.writeField ?? colId : cell?.writeField ?? colId,
        value: isReset ? null : value,
        /**
         * 🔴 THE ROW THE WRITE LANDS ON, from the server's own `writeTarget` (#697, hub-ruled).
         *
         * This was `cell.writeVerb`, under a comment of mine asserting that sending `target:
         * 'channel'` for the six column-backed fields (`{amazon,ebay}_{title,description,
         * variationTheme}` — `writeTarget: 'channelListing'`, `writeVerb: 'master'`) "would send
         * both routes and land the write twice over". **Verified against the route before changing
         * it, and it is false today:** `isChannelChange` (`products.routes.ts:1354`) routes a
         * NON-`attr_*` field by its field NAME and ignores `target` entirely, and the write is an
         * `if (v.cascade) … else if (isCh) … else` chain (`:2536`) — one branch, never two. What
         * `target` actually decides for these fields is `hasMasterTargetedChange` (`:2703`), i.e.
         * WHICH ROW's version the CAS guards, and the audit row's layer (`:2946`).
         *
         * So the old pairing sent the PRODUCT's version as the token for a write that only ever
         * touched the listing — captured on the wire at 14:52: `field: amazon_title`, `target:
         * "master"`, `expectedVersion: 3`, on a row whose listing was at 82. Wrong in both
         * directions: a concurrent listing change did not conflict, and a concurrent product change
         * would have 409'd a write that never touched the product.
         *
         * `writeTarget` is the SERVER's statement of where the write lands, so target and token now
         * come from one source. It is deliberately NOT a client copy of the API's
         * `CHANNEL_FIELD_MAP` (D15.16.4): a client that re-derives the routing drifts the first time
         * a field is added to the map, and that map has grown twice already.
         *
         * Defaulting to `'master'` when the server sent no cell matches the endpoint's own default
         * — the safe direction is the shared record refusing the edit, not a silent channel write.
         */
        target: cell?.contentAcknowledgement ? address?.tier === 'pin' ? 'channel' : 'master' : writeLandsOnListing(cell) ? 'channel' : cell?.writeVerb ?? 'master',
        intent: intent === 'reset-list' ? 'reset' : intent,
      },
    }
  })

  const touchesChannel = changes.some(c => c.change.target === 'channel')
  const touchesMaster = changes.some(c => c.change.target !== 'channel')
  // Each persisted row has its own counter. Split a mixed paste into two guarded writes,
  // and retain each cell's verdict if one scope fails or loses its connection.
  if (touchesChannel && touchesMaster) {
    const cells: NonNullable<SheetWriteResult['cells']> = {}
    const results: SheetWriteResult[] = []
    for (const target of ['master', 'channel'] as const) {
      const subset = req.cells.filter((_, i) => (changes[i].change.target === 'channel') === (target === 'channel'))
      const result = await commitChannelRow({ ...req, cells: subset }, coord)
      results.push(result)
      for (const cell of subset) cells[cell.colId] = {
        ...(result.cells?.[cell.colId] ?? { ok: result.ok, reason: result.reason }),
        unreachable: result.cells?.[cell.colId]?.unreachable ?? !!result.unreachable,
      }
    }
    return {
      ok: results.every(r => r.ok), cells, version: results[0].version,
      conflict: results.some(r => r.conflict), unreachable: results.some(r => r.unreachable),
      reason: results.find(r => !r.ok)?.reason,
    }
  }
  const casVersion = touchesChannel ? row.listing?.version : req.expectedVersion

  try {
    const res = await fetch(`${getBackendUrl()}/api/products/bulk`, {
      method: 'PATCH',
        signal: AbortSignal.timeout(30_000),
      credentials: 'include',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        changes: changes.map((c) => c.change),
        // `aliasKey`, not `aliasId` — and never omitted. The server treats an absent key as `''`
        // only as a courtesy; naming it is what makes the override merge land on THIS alias's
        // listing rather than the primary (§14's ON CONFLICT names the five-column key).
        marketplaceContexts: [
          { channel: coord.channel, marketplace: coord.marketplace, ...(coord.accountId ? { accountId: coord.accountId } : {}), ...(coord.locale ? { locale: coord.locale } : {}), aliasKey: wireAliasKey(row.aliasId) },
        ],
        ...(casVersion !== undefined ? { expectedVersion: casVersion } : {}),
      }),
    })
    const body = await res.json().catch(() => null)
    if (res.status >= 500 || res.ok && (!body || typeof body.updated !== 'number' && !Array.isArray(body.errors))) {
      return { ok: false, unreachable: true, reason: 'Save confirmation was unavailable. Checking the stored values.' }
    }
    const raw = typeof body?.currentVersion === 'number' ? body.currentVersion : undefined
    /**
     * 🔴 `versionOf` says WHICH ROW the number belongs to — read it, never infer it.
     *
     * The two counters are unrelated (89% of listings differ from their product), so applying a
     * listing version to the product row, or the reverse, silently poisons the next CAS with a
     * number from the wrong table. Before this field existed a channel conflict returned the
     * PRODUCT's version and the sheet reported "someone changed this listing (v1)" while the
     * listing was at 19.
     *
     * A listing version is written straight back onto `row.listing` so the NEXT edit on this row
     * chains without a refetch — and is deliberately NOT returned as the write result's `version`,
     * which the sheet writer applies to the product row it tracks.
     */
    const versionOf: 'channelListing' | 'product' | undefined = body?.versionOf
    if (versionOf === 'channelListing' && raw !== undefined && row.listing) row.listing.version = raw
    const version = versionOf === 'product' ? raw : undefined

    if (res.status === 404 || res.status === 501) {
      return { ok: false, reason: 'The channel write path is not deployed yet (PES.5)' }
    }
    if (res.status === 409) {
      if (['AMBIGUOUS_CONNECTION', 'LISTING_SCOPE_MISMATCH'].includes(body?.code ?? body?.error)) {
        return { ok: false, reason: body?.message || 'Reload and choose the correct listing and account before editing.' }
      }
      // Hand the server's version back so the writer can retry rather than stay behind.
      return {
        ok: false,
        conflict: true,
        version,
        // Name the row the number belongs to, or say nothing about a version at all. Asserting a
        // listing version we were handed from the product row is how the old message said "v1"
        // about a listing sitting at 19.
        reason: body?.message || body?.error || (
          versionOf === 'channelListing'
            ? `Someone else changed this listing (now v${raw ?? '?'}). Review the edit before reloading.`
            : versionOf === 'product'
              ? `Someone else changed this product (now v${raw ?? '?'}). Review the edit before reloading.`
              : 'Someone else changed this row first. Review the edit before reloading.'),
      }
    }
    if (!res.ok) {
      const first = Array.isArray(body?.errors) ? body.errors[0] : undefined
      return { ok: false, reason: first?.error || body?.message || body?.error || `Refused (HTTP ${res.status})` }
    }

    // A 200 can still carry per-cell refusals alongside partial success. Map them back onto the
    // cells that caused them so each one paints its own outcome.
    applyNormalizedReferenceChanges(body ?? {}, row, changes.map(({ colId, change }) => ({ colId, field: change.field, value: change.value })))
    const errors: Array<{ id?: string; field?: string; error?: string }> = Array.isArray(body?.errors) ? body.errors : []
    if (errors.length > 0) {
      const cells: Record<string, { ok: boolean; reason?: string }> = {}
      for (const { colId, change } of changes) {
        const hit = errors.find((e) => e.field === change.field && (e.id === undefined || e.id === row.id))
        cells[colId] = hit ? { ok: false, reason: hit.error || 'Refused' } : { ok: true }
      }
      return { ok: false, version, cells }
    }
    /**
     * 🔴 `updated: 0` IS A SUCCESS WHEN THE SERVER SAYS WHY (#700, measured on screen).
     *
     * This branch was written when `updated: 0` meant "nothing happened and nobody said why" — the
     * silent-drop shape, which must never paint as saved. PES.5's #675 then made a no-op EXPLICIT:
     * a request whose values already match returns `200 { success: true, updated: 0, unchanged: n }`
     * with the listing's own version. Against that response the old test read a stated success as a
     * failure — measured on the screen at 15:19: a refusal corrected back to its stored value
     * answered `{updated: 0, unchanged: 1, currentVersion: 82, versionOf: 'channelListing'}` and the
     * header still said "1 change not saved", with the operator's cell showing the right value and
     * nothing left to save. That is the honest-UI rule broken in the direction nobody checks: a lie
     * about work still being OUTSTANDING.
     *
     * `unchanged` is what separates the two. Without it — an older server, or a drop nobody
     * explained — the guard stands exactly as before.
     */
    if (body?.updated === 0) {
      const unchanged = typeof body?.unchanged === 'number' ? body.unchanged : 0
      if (unchanged === 0) {
        return { ok: false, version, reason: 'The server accepted the request but changed nothing' }
      }
    }

    return { ok: true, version }
  } catch (err) {
    return { ok: false, unreachable: true, reason: `Connection lost — refresh to check whether this saved. ${err instanceof Error ? err.message : String(err)}` }
  }
}

/**
 * `[+ Add listing alias]` — PES.5 §3.4.
 *
 * The server creates the alias AND its `ChannelListing` rows (family root + children) with no
 * overrides, so the new alias opens fully inheriting. Nothing is sent to the channel: it is a local
 * record until the operator publishes it explicitly through the preflight-first path.
 */
export async function addListingAlias(input: {
  productId: string
  channel: ChannelScopeChannel
  marketplace: string
  accountId?: string
  label?: string
}): Promise<{ ok: boolean; alias?: AliasGroup; reason?: string }> {
  const { productId, channel, marketplace, label, accountId } = input
  try {
    const res = await fetch(`${getBackendUrl()}/api/products/${productId}/aliases`, {
      method: 'POST',
      credentials: 'include',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ channel, marketplace, label, accountId }),
    })
    const body = await res.json().catch(() => null)
    if (res.status === 404 || res.status === 501) {
      return { ok: false, reason: 'The alias route is not deployed yet (PES.5 §3.4)' }
    }
    if (!res.ok) return { ok: false, reason: body?.message || body?.error || `Refused (HTTP ${res.status})` }
    return { ok: true, alias: body as AliasGroup }
  } catch (err) {
    return { ok: false, reason: err instanceof Error ? err.message : String(err) }
  }
}

/**
 * Rename or reorder an alias (PES.5 §3.4). Archiving (`DELETE`) is deliberately NOT wired here:
 * it takes a live listing's local record out of the sheet, so it asks first, separately.
 */
export async function updateListingAlias(input: {
  productId: string
  aliasId: string
  accountId?: string
  label?: string
  position?: number
}): Promise<{ ok: boolean; reason?: string }> {
  const { productId, aliasId, ...patch } = input
  try {
    const res = await fetch(`${getBackendUrl()}/api/products/${productId}/aliases/${aliasId}`, {
      method: 'PATCH',
        signal: AbortSignal.timeout(30_000),
      credentials: 'include',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(patch),
    })
    if (res.status === 404 || res.status === 501) {
      return { ok: false, reason: 'The alias route is not deployed yet (PES.5 §3.4)' }
    }
    if (!res.ok) {
      const body = await res.json().catch(() => null)
      return { ok: false, reason: body?.message || body?.error || `Refused (HTTP ${res.status})` }
    }
    return { ok: true }
  } catch (err) {
    return { ok: false, reason: err instanceof Error ? err.message : String(err) }
  }
}

'use client'

/** Shared sheet layout: server-saved membership, ordering, groups and pins, plus transient chips. */
import { useCallback, useEffect, useMemo, useRef, useState, type MutableRefObject } from 'react'
import type { GridApi, GridState } from '@/design-system/grid'
import {
  ALL_VIEW_ID, arrangementColumnState, columnStateToPrefs, columnsViewPayload,
  isColumnsViewPayload, pickGridState, prefsToColumnState, resolveLanding, resolvePreset, useGridState,
  type ColumnsViewPayload, type GridStateApi, type GridStateKey, type GridViewPreset,
  type Landing, type PrefsBridgeOptions, type SavedGridView, type UseGridStateOptions,
} from '@/design-system/grid'
import type { PreferencesColumnSpec, PreferencesValue } from '@/design-system/patterns/PreferencesModal'
import { loadWorkingLayout, saveWorkingLayout, type StoredSheetLayout } from '@/design-system/grid/views/savedViewTransport'
import { viewChipColumns, type ViewChip } from '../contracts'
import type { SheetColumn } from './master/types'
import { alwaysColumnsFor, orderColumnKeys, sheetViews, type ViewContext } from './views'
import { layoutFromPreferences, preferencesFromLayout, visibleLayoutKeys, mergeVisibleColumnOrder } from '@/design-system/grid/views/columnLayout'

/** Widths and sort remain lightweight browser preferences. Complete layouts are saved explicitly. */
export const SHEET_PERSIST_KEYS: readonly GridStateKey[] = ['columnSizing', 'columnPinning', 'sort']
export type ActiveColumns =
  | { kind: 'all' }
  | { kind: 'preset'; id: string; label: string }
  | { kind: 'saved'; id: string; name: string; missing: string[] }
  | { kind: 'custom'; count: number }

export interface UseSheetColumnsArgs<TRow, TPage> {
  apiRef: MutableRefObject<GridApi<TRow> | null>
  gridReady: GridApi<TRow> | null
  columns: SheetColumn[]
  viewCtx: ViewContext
  serverViews?: Array<{ id: string; label: string; columnKeys: string[] }>
  identityColumn: string
  prefsBridge: PrefsBridgeOptions
  activeChip: ViewChip | null
  setChip?: (id: string | null) => void
  /** Personal working layout, isolated by scope and market. Named views remain reusable. */
  layoutSurface: string
  grid: Pick<UseGridStateOptions<TPage>, 'surface' | 'viewsSurface' | 'baseUrl' | 'getPageState' | 'applyPageState' | 'omitScroll'>
}
export interface SheetColumnsApi<TPage> {
  gridState: GridStateApi<TPage>
  initialState: GridState | undefined
  captureGridState: () => void
  presets: GridViewPreset[]
  viewsSource: 'server' | 'rules'
  active: ActiveColumns
  activePresetId: string | null
  emptyLabel: string
  activeViewName: string | null
  landed: boolean
  landing: Landing | null
  loadError: string | null
  orderedKeys: string[]
  preferenceColumns: PreferencesColumnSpec[]
  alwaysColumns: string[]
  allColumnKeys: string[]
  applyPreset: (preset: GridViewPreset) => void
  applyCustom: (keys: readonly string[], locks?: readonly string[]) => void
  currentPreferences: () => PreferencesValue
  currentPayload: () => ColumnsViewPayload
  savePreferences: (value: PreferencesValue) => Promise<void>
  savePreferencesAs: (name: string, value: PreferencesValue) => Promise<string>
  updatePreferences: (view: SavedGridView<TPage>, value: PreferencesValue) => Promise<void>
  reloadSavedPreferences: () => Promise<PreferencesValue>
  saveCurrentAs: (name: string) => Promise<string | null>
  updateView: (view: SavedGridView<TPage>) => Promise<unknown>
  describeView: (view: SavedGridView<TPage>) => { note?: string; title?: string } | null
  visibleAttributeKeys: () => string[]
}

export function useSheetColumns<TRow, TPage>(a: UseSheetColumnsArgs<TRow, TPage>): SheetColumnsApi<TPage> {
  const { apiRef, gridReady, columns, viewCtx, serverViews, identityColumn, prefsBridge, activeChip, setChip, layoutSurface } = a
  const baseUrl = a.grid.baseUrl
  const scopeRef = useRef(layoutSurface)
  scopeRef.current = layoutSurface
  const orderedKeys = useMemo(() => orderColumnKeys(columns, viewCtx), [columns, viewCtx])
  const attributeKeys = useMemo(() => new Set(orderedKeys), [orderedKeys])
  const addressable = useMemo(() => [identityColumn, ...orderedKeys], [identityColumn, orderedKeys])
  const addressableSet = useMemo(() => new Set(addressable), [addressable])
  const alwaysColumns = useMemo(() => alwaysColumnsFor(addressable), [addressable])
  const allColumnKeys = useMemo(() => [...alwaysColumns, ...orderedKeys.filter((k) => !alwaysColumns.includes(k))], [alwaysColumns, orderedKeys])
  const specs = useMemo<PreferencesColumnSpec[]>(() => {
    // The modal receives this schema order too. Required-first grid ranking must not reorder groups on Save.
    return [{ key: identityColumn, label: 'Identity (SKU, readiness)', locked: true }, ...columns.map((c) => ({ key: c.key, label: c.label, group: c.group, groupKey: c.groupKey }))]
  }, [columns, identityColumn])
  const views = useMemo(() => sheetViews(columns, viewCtx, serverViews), [columns, viewCtx, serverViews])
  const [active, setActive] = useState<ActiveColumns>({ kind: 'all' })
  const [landing, setLanding] = useState<Landing | null>(null)
  const [landedScope, setLandedScope] = useState<string | null>(null)
  const [landedGrid, setLandedGrid] = useState<GridApi<TRow> | null>(null)
  const [recovery, setRecovery] = useState<{ surface: string; state: GridState } | null>(null)
  const landed = landedScope === layoutSurface && landedGrid === gridReady
  const activeColumnsRef = useRef<string[]>([])
  // Retain the full payload: changing product type must never delete temporarily unavailable IDs.
  const layoutRef = useRef<ColumnsViewPayload | null>(null)
  const workingRef = useRef<{ surface: string; record: StoredSheetLayout | null; ready: boolean }>({ surface: layoutSurface, record: null, ready: false })
  const [loadState, setLoadState] = useState<{ surface: string; ready: boolean; error: string | null }>({ surface: layoutSurface, ready: false, error: null })
  const loadError = loadState.surface === layoutSurface ? loadState.error : null
  const requestSequence = useRef(0)
  const saving = useRef(false)
  const applySavedRef = useRef<(payload: ColumnsViewPayload, view: SavedGridView<TPage>) => void>(() => {})
  const gridState = useGridState<TPage>({ ...a.grid, persistKeys: SHEET_PERSIST_KEYS, applyColumnsView: (payload, view) => applySavedRef.current(payload, view) })
  const recoveryState = recovery?.surface === layoutSurface ? recovery.state : undefined
  const captureGridState = useCallback(() => {
    const api = apiRef.current
    if (api && !api.isDestroyed()) setRecovery({ surface: layoutSurface, state: pickGridState(api.getState(), SHEET_PERSIST_KEYS) })
  }, [apiRef, layoutSurface])

  const fetchLayout = useCallback(async () => {
    const sequence = ++requestSequence.current
    try {
      const record = await loadWorkingLayout(baseUrl, layoutSurface)
      if (scopeRef.current !== layoutSurface || sequence !== requestSequence.current) throw new Error('The sheet scope changed. Reopen Customise in the current scope.')
      workingRef.current = { surface: layoutSurface, record, ready: true }
      setLoadState({ surface: layoutSurface, ready: true, error: null })
      return record
    } catch (error) {
      if (scopeRef.current === layoutSurface && sequence === requestSequence.current) {
        workingRef.current = { surface: layoutSurface, record: null, ready: false }
        setLoadState({ surface: layoutSurface, ready: false, error: error instanceof Error ? error.message : 'Could not load your saved layout' })
      }
      throw error
    }
  }, [baseUrl, layoutSurface])

  useEffect(() => {
    setLandedScope(null)
    setLanding(null)
    layoutRef.current = null
    workingRef.current = { surface: layoutSurface, record: null, ready: false }
    setLoadState({ surface: layoutSurface, ready: false, error: null })
    void fetchLayout().catch(() => {})
    return () => { requestSequence.current += 1 }
  }, [layoutSurface, fetchLayout])

  const gridLocks = useCallback((api: GridApi<TRow>) => columnStateToPrefs(api.getColumnState(), preferencesFromLayout(null, specs), prefsBridge).lockedColumns ?? [], [specs, prefsBridge])
  const applyToGrid = useCallback((keys: readonly string[], order: boolean, locks?: readonly string[]) => {
    const api = apiRef.current
    if (!api || api.isDestroyed()) return false
    const value = { ...preferencesFromLayout(null, specs), visibleColumns: keys.filter((k) => addressableSet.has(k)), lockedColumns: [...(locks ?? gridLocks(api))] }
    api.applyColumnState({ state: prefsToColumnState(value, prefsBridge), applyOrder: order })
    return true
  }, [apiRef, specs, addressableSet, gridLocks, prefsBridge])

  const activate = useCallback((next: ActiveColumns, payload: ColumnsViewPayload, restoreLocks = true) => {
    layoutRef.current = payload
    const keys = [...alwaysColumns, ...visibleLayoutKeys(payload, specs)]
    activeColumnsRef.current = keys
    setActive(next)
    applyToGrid(keys, true, restoreLocks && payload.v === 3 ? payload.lockedColumns : undefined)
    gridState.markDirty()
  }, [alwaysColumns, specs, applyToGrid, gridState])
  const applyPreset = useCallback((preset: GridViewPreset) => {
    const resolved = resolvePreset(preset, addressable, alwaysColumns)
    gridState.markActive(null)
    activate(preset.id === ALL_VIEW_ID ? { kind: 'all' } : { kind: 'preset', id: preset.id, label: preset.label }, columnsViewPayload(resolved.columns.filter((k) => attributeKeys.has(k))), false)
    setChip?.(null)
  }, [addressable, alwaysColumns, gridState, activate, attributeKeys, setChip])
  const applySaved = useCallback((payload: ColumnsViewPayload, view: SavedGridView<TPage>) => {
    activate({ kind: 'saved', id: view.id, name: view.name, missing: payload.columns.filter((k) => !attributeKeys.has(k)) }, payload)
    setChip?.(payload.chip ?? null)
  }, [activate, attributeKeys, setChip])
  applySavedRef.current = applySaved
  const applyCustom = useCallback((keys: readonly string[], locks?: readonly string[]) => {
    const prefs = preferencesFromLayout(layoutRef.current, specs)
    const payload = layoutFromPreferences(specs, { ...prefs, visibleColumns: [...keys], ...(locks ? { lockedColumns: [...locks] } : {}) }, alwaysColumns)
    gridState.markActive(null)
    activate({ kind: 'custom', count: payload.columns.filter((k) => attributeKeys.has(k)).length }, payload, locks !== undefined)
  }, [specs, alwaysColumns, gridState, activate, attributeKeys])

  useEffect(() => {
    const api = apiRef.current
    if (landed || !api || api.isDestroyed() || !gridReady || !orderedKeys.length || !gridState.loaded || loadState.surface !== layoutSurface || !loadState.ready) return
    const colIds = api.getColumnState().map((c) => c.colId)
    if (!orderedKeys.some((k) => colIds.includes(k))) return
    const savedState = recoveryState ?? gridState.lastUsed?.gridState
    const arrangement = arrangementColumnState(savedState, colIds)
    if (arrangement.length) api.applyColumnState({ state: arrangement, applyOrder: false })
    // A failed read removes AG without unmounting this hook. Reapply the current view on retry,
    // including a temporary chip, instead of leaving default columns under the old view label.
    if (landedScope === layoutSurface && layoutRef.current) {
      const wanted = activeChip ? viewChipColumns(activeChip.cells) : []
      applyToGrid(activeColumnsRef.current, true)
      if (wanted.length) applyToGrid([...alwaysColumns, ...wanted], false)
      setLandedGrid(api)
      return
    }
    const working = workingRef.current.record
    const dv = gridState.defaultView
    const l = resolveLanding({ orderedKeys, always: alwaysColumns, defaultView: dv ? { id: dv.id, name: dv.name, payload: dv.payload } : null })
    setLanding(l)
    if (working) {
      const named = gridState.views.find((v) => JSON.stringify(v.payload) === JSON.stringify(working.filters))
      activate(named ? { kind: 'saved', id: named.id, name: named.name, missing: working.filters.columns.filter((k) => !attributeKeys.has(k)) } : { kind: 'custom', count: visibleLayoutKeys(working.filters, specs).length }, working.filters)
      gridState.markActive(named?.id ?? null)
      setChip?.(working.filters.chip ?? null)
    } else if (dv && isColumnsViewPayload(dv.payload)) {
      applySaved(dv.payload, dv)
      gridState.markActive(dv.id)
    } else {
      activate({ kind: 'all' }, columnsViewPayload(orderedKeys), false)
      gridState.markActive(null)
    }
    setLandedScope(layoutSurface)
    setLandedGrid(api)
  }, [recoveryState, landedScope, activeChip, applyToGrid, landed, apiRef, gridReady, orderedKeys, gridState, loadState, layoutSurface, alwaysColumns, activate, specs, setChip, applySaved, attributeKeys])

  const keySignature = JSON.stringify(orderedKeys)
  const lastSignature = useRef(keySignature)
  useEffect(() => {
    if (!landed || lastSignature.current === keySignature) return
    lastSignature.current = keySignature
    if (active.kind === 'all') { activate(active, columnsViewPayload(orderedKeys), false); return }
    if (active.kind === 'preset') {
      const preset = views.presets.find((p) => p.id === active.id)
      if (preset) applyPreset(preset)
      return
    }
    const payload = layoutRef.current
    if (payload) activate(active.kind === 'saved' ? { ...active, missing: payload.columns.filter((k) => !attributeKeys.has(k)) } : { kind: 'custom', count: visibleLayoutKeys(payload, specs).length }, payload)
  }, [landed, keySignature, active, activate, orderedKeys, views.presets, applyPreset, attributeKeys, specs])

  useEffect(() => {
    if (!landed || !gridState.loaded || active.kind !== 'saved') return
    const acknowledged = gridState.activeId && gridState.activeId !== active.id ? gridState.views.find((v) => v.id === gridState.activeId) : null
    if (acknowledged) { setActive({ ...active, id: acknowledged.id, name: acknowledged.name }); return }
    const still = gridState.views.find((v) => v.id === active.id)
    if (!still) setActive({ kind: 'custom', count: activeColumnsRef.current.filter((k) => attributeKeys.has(k)).length })
    else if (still.name !== active.name) setActive({ ...active, name: still.name })
  }, [landed, gridState.loaded, gridState.views, gridState.activeId, active, attributeKeys])

  useEffect(() => {
    if (!landed) return
    const wanted = activeChip ? viewChipColumns(activeChip.cells) : []
    applyToGrid(wanted.length ? [...alwaysColumns, ...wanted] : activeColumnsRef.current, false)
    // A chip changes membership only, preserving the chosen layout's order and pins.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [activeChip, landed])

  const visibleAttributeKeys = useCallback(() => {
    const api = apiRef.current
    return (!api || api.isDestroyed() ? activeColumnsRef.current : api.getColumnState().filter((s) => !s.hide).map((s) => s.colId)).filter((k) => attributeKeys.has(k))
  }, [apiRef, attributeKeys])
  const currentPreferences = useCallback(() => {
    const previous = preferencesFromLayout(layoutRef.current, specs)
    const api = apiRef.current
    if (!api || api.isDestroyed()) return previous
    const fromGrid = columnStateToPrefs(api.getColumnState(), previous, prefsBridge)
    const unavailable = (keys: readonly string[]) => keys.filter((k) => !addressableSet.has(k))
    // Chip filters are temporary: opening Customise edits the underlying view's membership.
    return {
      ...fromGrid,
      visibleColumns: activeChip ? previous.visibleColumns : [...fromGrid.visibleColumns, ...unavailable(previous.visibleColumns)],
      lockedColumns: [...(fromGrid.lockedColumns ?? []), ...unavailable(previous.lockedColumns ?? [])],
      columnOrder: mergeVisibleColumnOrder(previous.columnOrder ?? [], fromGrid.visibleColumns.filter((key) => attributeKeys.has(key) && !fromGrid.lockedColumns?.includes(key) && !fromGrid.rowGroups?.includes(key))),
    }
  }, [specs, apiRef, prefsBridge, addressableSet, activeChip, attributeKeys])
  const currentPayload = useCallback((): ColumnsViewPayload => ({ ...layoutFromPreferences(specs, currentPreferences(), alwaysColumns), ...(activeChip ? { chip: activeChip.id } : {}) }), [specs, currentPreferences, alwaysColumns, activeChip])

  const persistDraft = useCallback(async (value: PreferencesValue, named?: { name: string; view?: SavedGridView<TPage>; chip?: string }) => {
    if (saving.current) throw new Error('A layout save is already in progress')
    const working = workingRef.current
    if (scopeRef.current !== layoutSurface || working.surface !== layoutSurface || !working.ready) throw new Error('Load your saved layout before saving. Use Reload saved layout to retry.')
    const payload = { ...layoutFromPreferences(specs, value, alwaysColumns), ...(named?.chip ? { chip: named.chip } : {}) }
    saving.current = true
    try {
      let id: string | null = null
      let stored: StoredSheetLayout
      if (named) {
        const saved = await gridState.saveRecord(named.name, {
          id: named.view?.id, isDefault: named.view?.isDefault, expectedUpdatedAt: named.view?.updatedAt, payload,
          workingLayout: { surface: layoutSurface, filters: payload, expectedUpdatedAt: working.record?.updatedAt ?? null },
        })
        if (!saved.workingLayout || !isColumnsViewPayload(saved.workingLayout.filters)) throw new Error('The server did not acknowledge the saved layout. Reload saved layout before retrying.')
        stored = { ...saved.workingLayout, filters: saved.workingLayout.filters }
        id = saved.id
      } else stored = await saveWorkingLayout(baseUrl, layoutSurface, payload, working.record)
      if (scopeRef.current !== layoutSurface) return id
      workingRef.current = { surface: layoutSurface, record: stored, ready: true }
      activate(id && named ? { kind: 'saved', id, name: named.name, missing: payload.columns.filter((k) => !attributeKeys.has(k)) } : { kind: 'custom', count: visibleLayoutKeys(payload, specs).length }, payload)
      gridState.markActive(id)
      setChip?.(payload.chip ?? null)
      return id
    } finally { saving.current = false }
  }, [layoutSurface, specs, alwaysColumns, gridState, baseUrl, activate, attributeKeys, setChip])
  const savePreferences = useCallback(async (value: PreferencesValue) => { await persistDraft(value) }, [persistDraft])
  const savePreferencesAs = useCallback(async (name: string, value: PreferencesValue) => (await persistDraft(value, { name, chip: activeChip?.id }))!, [persistDraft, activeChip])
  const updatePreferences = useCallback(async (view: SavedGridView<TPage>, value: PreferencesValue) => { await persistDraft(value, { name: view.name, view, chip: activeChip?.id }) }, [persistDraft, activeChip])
  const saveCurrentAs = useCallback((name: string) => savePreferencesAs(name, currentPreferences()), [savePreferencesAs, currentPreferences])
  const updateView = useCallback((view: SavedGridView<TPage>) => updatePreferences(view, currentPreferences()), [updatePreferences, currentPreferences])
  const reloadSavedPreferences = useCallback(async () => {
    const record = await fetchLayout()
    await gridState.refresh()
    if (scopeRef.current !== layoutSurface) throw new Error('The sheet scope changed. Reopen Customise in the current scope.')
    const payload = record?.filters ?? columnsViewPayload(orderedKeys)
    activate({ kind: 'custom', count: visibleLayoutKeys(payload, specs).length }, payload)
    gridState.markActive(null)
    setChip?.(payload.chip ?? null)
    return preferencesFromLayout(payload, specs)
  }, [fetchLayout, gridState, layoutSurface, orderedKeys, activate, specs, setChip])

  const describeView = useCallback((view: SavedGridView<TPage>) => {
    if (!isColumnsViewPayload(view.payload)) return view.payload ? { note: 'Saved in an older format — open it to convert' } : { note: 'Holds no columns' }
    const missing = view.payload.columns.filter((k) => !attributeKeys.has(k))
    const legacy = view.legacyShared ? 'Shared legacy template; saving creates your personal copy.' : ''
    if (!missing.length) return legacy ? { note: legacy } : null
    return { note: `${missing.length} of ${view.payload.columns.length} not on this product type: ${missing.slice(0, 4).join(', ')}${missing.length > 4 ? ', …' : ''}`, title: [legacy, missing.join(', ')].filter(Boolean).join(' ') }
  }, [attributeKeys])
  return {
    gridState, initialState: recoveryState ?? gridState.initialState, captureGridState,
    presets: views.presets, viewsSource: views.source, active,
    activePresetId: active.kind === 'all' ? ALL_VIEW_ID : active.kind === 'preset' ? active.id : null,
    emptyLabel: active.kind === 'custom' ? `Custom (${active.count})` : 'View',
    activeViewName: active.kind === 'saved' ? active.name : null,
    landed, landing, loadError: loadError ?? gridState.loadError, orderedKeys, preferenceColumns: specs, alwaysColumns, allColumnKeys,
    applyPreset, applyCustom, currentPreferences, currentPayload, savePreferences, savePreferencesAs,
    updatePreferences, reloadSavedPreferences, saveCurrentAs, updateView, describeView, visibleAttributeKeys,
  }
}

'use client'

/**
 * PES.2 — the master sheet's column factory.
 *
 * 🔴 **It builds EVERY column the server returns — all 102 of them on the real catalogue.** The old
 * sheet built only the 26 flagged `defaultVisible`, which meant the other 76 had no column
 * definition at all: not in the grid, not in the Customise dialog, not reachable by any control.
 * Visibility is a VIEW's decision (`views.ts` → `prefsToColumnState`), never a build-time filter.
 * A column that is not built cannot be shown, and nothing on screen explains its absence.
 *
 * Every cell renders its provenance through the DS (`classifyProvenance` + `ProvenanceMark`), so
 * the master sheet, PES.3's channel scopes and PES.4's drawer reach the same verdict about the
 * same cell.
 */
import { StructuredAttributeEditor, parseRecordValue, recordSummary } from '../StructuredAttributeEditor'
import { SourceIndicator } from '@/design-system/components'
import { ImpactProtectorsEditor, protectorSummary } from '../ImpactProtectorsInput'
import { AttributeShapeEditor } from '../AttributeShapeInput'
import { formulaAvailability, formulaCellEditorSelector, SelectPanelEditor, suppressFormulaKeys, type FormulaWiring } from '@/design-system/grid'
import { CellSaveReason, composeCellTooltip, longTextTooltipLine, EmptyValue, RequiredValue, LongTextCell, ShapeValue, isEmptyShape, shapeColumnDef, shapeEditorSpec, shapeTooltipLine, ProvenanceMark, classifyProvenance, longTextEditor, numericColumn, provenanceClassRules, provenanceTooltip, roundTripClassRules, selectEditor, SelectChevron, SELECT_CELL_CLASS, sheetValidationFor, composeSheetCellClassRules, type CellSaveTracker, type ColDef, type ColGroupDef, type ICellRendererParams, type ValueGetterParams, type ValueSetterParams } from '@/design-system/grid'
import type { CellClassParams } from '@/design-system/grid'

import { scalarColumnDef, booleanLabel, BOOLEAN_OPTIONS, SHEET_NUMBER_EDITOR_PARAMS } from '@/design-system/grid/editors/scalarValue'
import { columnRequiredByAny, isProductRelationshipColumn } from '@nexus/shared/master-sheet'

import { cellIsEditable, cellOf, sourceLabel, validationApplies, widthFor } from './columnRules'
import { optionLabel } from '../optionLabel'
import { parseReferenceOrScalarValue, referenceColumnDef, referenceTooltip } from '../referenceLabels'
import { isReferenceField } from '../referenceOptions'
import { ReferenceSelectEditor } from '../ReferenceSelectEditor'
import type { SheetColumn, StudioRow } from './types'

export interface BuildColumnsOptions {
  columns: SheetColumn[]
  tracker: CellSaveTracker
  locale: string
  market?: string
  /**
   * Is this cell one the ACTIVE view chip counted? Read through a REF by the caller, never captured
   * — a chip click must not rebuild a hundred column definitions (AG re-runs its whole column model
   * for a new `columnDefs` identity). The class rule reads it at paint time and the caller repaints.
   */
  isChipCell?: (rowId: string, colId: string) => boolean
  /**
   * PES.8's AI draft for this cell, if there is one. Read through a REF for the same reason.
   *
   * 🔴 The draft is RENDERED; it is not the cell's VALUE. `valueGetter` keeps returning the
   * resolved value, so the diff PES.8 needs stays reachable, an edit saves what the operator typed
   * rather than a suggestion they never accepted, and approving a draft remains an explicit act
   * through their own apply path. A draft that quietly became the value would be exactly the
   * "lands as confirmed fact without review" the layout forbids.
   */
  draftFor?: (rowId: string, colId: string) => AiDraft | null
  /**
   * Group the columns under their `group` header band. **Default `false` — AG.1-d.**
   *
   * The band cost 30px of header on every screen and broke twice over:
   *  1. it renders its header TWICE the moment an operator pins any attribute column (measured —
   *     `productType` → Pin Left draws "IDENTITY" over the pinned block AND over the centre), which
   *     the old comment below asserted could not happen;
   *  2. `marryChildren` makes AG discard a whole column ORDERING rather than move a column out of
   *     its group (AG warning #39), which is what forced `applyOrder: false` on every view and made
   *     the layout spec's §9.2 ordering rule unimplementable.
   *
   * Grouping survives where it earns its place: the Customise dialog builds its own grouped list
   * from `SheetColumn.group`, and that is the one surface where ~100 columns genuinely need
   * headings — once, in a modal, instead of 30px on every screen forever.
   */
  grouped?: boolean
  /** Column ids the SHEET renders itself (the pinned identity block). Never built twice. */
  reservedColumnIds?: readonly string[]
  /**
   * D16 — `=` formula editing on text columns (#730). Absent ⇒ the plain text editor, unchanged.
   *
   * 🔴 Supplied by the LANE, never assembled here, because every call needs `market`: the preview
   * route refuses without it (#729) and the key set a `$ref` may name differs per market.
   */
  formula?: MasterFormulaWiring
}

/**
 * 🔴 Identity-STABLE, and every member a FUNCTION. `buildMasterColumns` is memoised, and a new
 * `columnDefs` identity makes AG re-run its whole column model and take the operator's widths and
 * order with it. The formula batch and the function docs both land after the first paint, so a
 * wiring object carrying VALUES would rebuild 102 column definitions the moment either arrived.
 * `cellEditorParams` is evaluated when an editor OPENS, so reading through a ref there is the
 * freshest read available, not a stale one.
 *
 * The shape itself is the engine's `FormulaWiring<StudioRow>` — one definition, both scopes.
 */
export type MasterFormulaWiring = FormulaWiring<StudioRow>

/** PES.8 supplies these; PES.2 owns how they render. */
export interface AiDraft {
  draftValue: unknown
  baseValue?: unknown
  /** The underlying cell moved since the draft was generated — approving it overwrites an edit. */
  stale?: boolean
  unverified?: boolean
  violations?: string[]
}


/**
 * The one place a cell's provenance is decided on this sheet.
 *
 * A pending AI draft is layered ON TOP of whatever the cell already was: the operator needs to know
 * a machine is proposing something here before they need to know where the current value came from.
 */
const provOf = (row: StudioRow, key: string, draft?: AiDraft | null, hasFormula?: boolean, refusedReason?: string | null) =>
  classifyProvenance(
    { ...cellOf(row, key), aiDrafted: !!draft, aiStale: !!draft?.stale, formula: !!hasFormula, refusedReason },
    'master',
  )



/**
 * The `=` selector, from the ENGINE — not a local copy (#775, PES.3's request).
 *
 * 🔴 What it holds is policy, not wiring: which editor a cell opens, that a stored formula overrides
 * the gate whatever key started the edit, and that a refused column falls back. A copy per sheet
 * means the first person to fix one of those fixes it on one scope — the drift "shared = exactly the
 * same" exists to stop, and the same argument that moved `useCellFormulas` above both sheets.
 *
 * `rowIdOf` is the only thing it reads off a row, passed so the engine knows neither row shape.
 */
const formulaSelector = (
  wiring: MasterFormulaWiring,
  col: SheetColumn,
  fallback: { component: unknown; params?: Record<string, unknown>; popup?: boolean },
) => formulaCellEditorSelector<StudioRow>(wiring, col, fallback, (r) => r.id)

export function buildMasterColumns(
  opts: BuildColumnsOptions,
  rowsRef: { current: StudioRow[] },
): (ColDef<StudioRow> | ColGroupDef<StudioRow>)[] {
  const { columns, tracker, grouped = false, reservedColumnIds = [], isChipCell, draftFor } = opts
  const rt = roundTripClassRules<StudioRow>(tracker, (r) => r.id)
  // ONE provenance rule set, and it is draft-aware. `draftFor` is a ref-reading function, so this
  // stays correct without rebuilding column defs when a draft arrives.
  /* `opts.formula.exprFor` is a REF-READING function (see `MasterFormulaWiring`), so the mark tracks
     the family's formulas as they load without rebuilding a hundred column definitions. */
  const prov = provenanceClassRules<StudioRow>((row, key) =>
    provOf(row, key, draftFor?.(row.id, key) ?? null, !!opts.formula?.exprFor(row.id, key), opts.formula?.errorFor?.(row.id, key)),
  )

  // Both now read from `columnRules.ts`, where they are tested — see that file for why the pure
  // decisions had to leave this `.tsx` to be reachable at all.
  const applies = (row: StudioRow, col: SheetColumn) => validationApplies(col, row)
  const requiredHere = (row: StudioRow, col: SheetColumn) => columnRequiredByAny(col, row)

  const build = (col: SheetColumn): ColDef<StudioRow> => {
    /* The validation, GATED on `applies` — one definition for master and the channel scopes
       (`sheetValidationFor`). The `?? 4000` lesson (BE-10: an absent wire cap means UNCAPPED,
       never a number invented here) lives with it. */
    const validation = sheetValidationFor<StudioRow>(col, (d) => applies(d, col))
    const editable = (p: { data?: StudioRow }) => cellIsEditable(col, p.data)

    /**
     * The mark + the value. One layout for every kind, so a column never loses its glyph.
     *
     * 🔴 `trail` is chrome that must sit on the value's LINE, pinned right — the select chevron.
     * It is a separate slot and not part of `body` because `body` goes inside
     * `.nds-cell-value-text`, which is the ellipsizing box (`overflow:hidden; text-overflow:
     * ellipsis; min-width:0`). Anything rendered in there is INLINE CONTENT of a truncating block,
     * not a flex item of the cell — so `.nds-ag-chev`'s `margin-left:auto; flex:none` were inert
     * and the glyph fell to a second line below the value (Owner, #707: "they should be on the same
     * row and not be a mess"). Measured before the fix on master·IT: value span 28.5px tall — two
     * line boxes in a 36px row — with the chevron's top 6.8px below the provenance glyph's.
     * `grid.css`'s own note on that rule says the icon "is a flex item rather than a block in a
     * line box, which is the trap that put the Pill's icon on its own line" — the rule was right and
     * the DOM had stopped matching it.
     */
    const withMark = (p: ICellRendererParams<StudioRow>, body: React.ReactNode, trail?: React.ReactNode) => {
      if (!p.data || isProductRelationshipColumn(col.key)) return body
      const draft = draftFor?.(p.data.id, col.key) ?? null
      /* #780 — the server's refusal reason, read at PAINT time through the ref-backed wiring, so a
         refusal that arrives with the formula batch repaints the mark without a column rebuild. */
      const refusedReason = opts.formula?.errorFor?.(p.data.id, col.key) ?? null
      const provenance = provOf(p.data, col.key, draft, !!opts.formula?.exprFor(p.data.id, col.key), refusedReason)
      // A drafted cell SHOWS the proposal; the value underneath is untouched and still what saves.
      const shown = draft ? <>{draft.draftValue == null || draft.draftValue === '' ? <EmptyValue /> : String(draft.draftValue)}</> : body
      return (
        <span className="nds-cell-value">
          {/* 🔴 `from` carries the SERVER'S REASON VERBATIM for a refused cell, and the source label
              for every other member. The mark's tooltip is the reason and nothing else (#780,
              hub-ruled) — no prefix, no field name, no client-side label logic, because the server
              is being fixed to name the field by the sheet's own label and a second voice here
              would put two labels back. */}
          {cellOf(p.data, col.key)?.translationState && cellOf(p.data, col.key)?.translationState !== 'current' && !draft && !refusedReason ? <SourceIndicator
            kind={cellOf(p.data, col.key)?.needsTranslation ? 'warning' : 'override'} tabIndex={-1}
            label={cellOf(p.data, col.key)?.translationState === 'fallback' ? 'Language fallback' : `${cellOf(p.data, col.key)?.translationState} content`}
            description={`Requested ${cellOf(p.data, col.key)?.requestedLocale}; showing ${cellOf(p.data, col.key)?.effectiveLocale}. ${cellOf(p.data, col.key)?.needsTranslation ? 'This content does not satisfy the requested language requirement.' : ''}`}
          /> : <ProvenanceMark
            provenance={provenance}
            from={provenance === 'refused' ? refusedReason : draft ? undefined : sourceLabel(p.data, col.key, rowsRef.current)}
          />}
          <span className="nds-cell-value-text">{shown}</span>
          {/* A SIBLING of the text, so it is a flex item of `.nds-cell-value` and the value
              truncates before it moves. */}
          {trail}
          {/* The tooltip's first paragraph, as text — for anything that cannot hover (#662). Same
              source as the getter reads, so the two cannot drift into two wordings. */}
          <CellSaveReason reason={tracker.get(p.data.id, col.key)?.reason} />
        </span>
      )
    }

    const emptyOrRequired = (p: ICellRendererParams<StudioRow>) =>
      p.data && applies(p.data, col) && requiredHere(p.data, col) ? <RequiredValue /> : <EmptyValue />

    const def: ColDef<StudioRow> = {
      ...scalarColumnDef<StudioRow>(col),
      ...referenceColumnDef<StudioRow>(col, row => cellOf(row, col.key)?.value),
      colId: col.key,
      headerName: col.label + (col.requiredBy.length > 0 ? ' *' : ''),
      headerTooltip:
        [
          col.requiredBy.length > 0 ? `Required by ${col.requiredBy.join(', ')}` : null,
          col.maxLength ? `Max ${col.maxLength} characters${col.capFrom ? ` (${col.capFrom})` : ''}` : null,
          col.maxBytes ? `Max ${col.maxBytes} bytes` : null,
          col.helpText,
        ]
          .filter(Boolean)
          .join(' · ') || undefined,
      // §9.3's ruled widths win over the contract's for the columns it names — see `widthFor`.
      width: widthFor(col, col.kind === 'longtext' ? 240 : 150),
      editable,
      // A sheet filters in the browser; the DS predicates do the work (filterPredicates.ts).
      // Branched rather than passed a union: `gridFilterDef` is overloaded so that a `set` filter
      // cannot be built without its options, and a union argument would defeat exactly that check.
      valueGetter: (p: ValueGetterParams<StudioRow>) => (p.data ? cellOf(p.data, col.key)?.value ?? null : null),
      valueSetter: (p: ValueSetterParams<StudioRow>) => {
        if (!p.data || !applies(p.data, col)) return false
        // 🔴 AG rebuilds `newValue` by re-running the value getter on `params.data` the moment this
        // returns, so the row object must be MUTATED here — scheduling React state hands the save
        // path the OLD value (reference_ag_value_setter_must_mutate_params_data).
        const previous = cellOf(p.data, col.key)
        p.data.values = {
          ...p.data.values,
          [col.key]: {
            ...previous,
            // The row keeps a real `source` after an edit: this row now stores the value, so the
            // resolver would report it as the row's own on the next read.
            source: p.data.isParent ? 'master' : 'variant',
            value: parseReferenceOrScalarValue(col, p.newValue),
            // Editing a cell gives THIS row the value: it is no longer inherited, and on a child
            // that is exactly the layout's "edit to pin".
            inherited: false,
            inheritedFrom: null,
            layer: p.data.isParent ? 'master' : 'variant',
            pinned: !p.data.isParent,
            editable: previous?.editable ?? true,
            writeField: previous?.writeField ?? col.writeField,
            writeTarget: previous?.writeTarget ?? 'master',
          },
        }
        return true
      },
      /* 🔴 `editable`, NOT `applies` — the same predicate AG is given above, and that is the whole
         point. `applies` is `validationApplies`: it answers "does this column apply to this row",
         which is the right question for validation and for the required mark and the WRONG one
         here. `cellIsEditable` is three conditions (`col.editable` AND the column applies AND the
         cell's own flag) and this rule was testing only the middle one, so a column the server
         marks `editable: false` still painted as editable.
         MEASURED on screen (2026-09-03, master·DE·it, XAVIA): `condition_type` carries
         `editable: false` on the wire; AG correctly refuses to open an editor for Enter and for a
         printable key alike — and the cell rendered `nds-cell-is-editable` throughout. A cell that
         advertises an affordance it does not have is the disabled-control-that-cannot-explain-
         itself shape, and the operator's only feedback was a keystroke doing nothing.
         Re-deriving an "equivalent" test one line from the real one is how these diverge. */
      /* 🔴 Tab belongs to the completion panel while one is open, and to AG otherwise. Only this
         ColDef-level opt-out can take it: measured on screen, a React `preventDefault` on the
         editor's own input leaves `defaultPrevented: true` and AG still ends the edit and moves a
         column. On the base `def`, so every branch inherits it through `...def` — the same
         inheritance the editable/locked rule above relies on. */
      suppressKeyboardEvent: suppressFormulaKeys,
      cellClass: (p) => (cellIsEditable(col, p.data) ? 'nds-ag-cell nds-cell-is-editable' : 'nds-ag-cell nds-cell-is-locked'),
      /* THE order, fixed once for every scope: validation → provenance → round-trip → the sheet's own. */
      cellClassRules: composeSheetCellClassRules<StudioRow>({
        validation,
        provenance: prov,
        roundTrip: rt,
        extra: { 'nds-cell-chip-hit': (p) => !!p.data && !!isChipCell && isChipCell(p.data.id, col.key) },
      }),
      /*
       * The cell's ONE tooltip (#662). COMPOSED, not an early return: the save reason used to be
       * returned INSTEAD of everything else, so a refused cell lost its length figures, and those
       * figures survived only through a rival `title` the renderer put on its own span. Reason
       * first — what happened to the value you just typed outranks what the field's limits are.
       */
      tooltipValueGetter: (p) => {
        if (!p.data) return ''
        const own = (): string => {
          const v = validation.validate(p.value, p.data!, col.key)
          if (v.message) return v.message
          if (!applies(p.data!, col)) {
            return p.data!.isParent ? 'Belongs to each variation, not to the parent' : `Not part of ${p.data!.productType ?? 'this product type'}`
          }
          const draft = draftFor?.(p.data!.id, col.key) ?? null
          if (draft) {
            const base = draft.baseValue ?? cellOf(p.data!, col.key)?.value
            return [
              provenanceTooltip(provOf(p.data!, col.key, draft, !!opts.formula?.exprFor(p.data!.id, col.key))),
              base == null || base === '' ? 'The cell is empty now' : `Now: ${String(base)}`,
              draft.violations?.length ? `⚠ ${draft.violations.join(' · ')}` : null,
              draft.unverified ? 'Not verified against the channel' : null,
            ].filter(Boolean).join('\n')
          }
          return provenanceTooltip(
            provOf(p.data!, col.key, null, !!opts.formula?.exprFor(p.data!.id, col.key)),
            sourceLabel(p.data!, col.key, rowsRef.current),
          )
        }
        return composeCellTooltip(
          tracker.get(p.data.id, col.key)?.reason,
          own(),
          /* 🔴 "…and says why in the cell" (#753(b)). A `=` typed on a column the writer refuses
             falls through to the ordinary editor and becomes plain text, which is silent — the
             operator is left thinking formulas simply did not work. The reason rides on the cell's
             own tooltip, in the sheet's existing vocabulary, next to every other thing this cell has
             to say about itself. `formulaAvailability` owns the wording so the editor gate and this
             line can never describe the same refusal differently. */
          opts.formula && p.data
            ? (() => {
                const a = formulaAvailability({
                  formulaWritable: col.formulaWritable,
                  hasStoredFormula: !!opts.formula!.exprFor(p.data!.id, col.key),
                })
                if (a.kind === 'blocked') return a.reason
                /* 🔴 On a CLOSED LIST, say both halves (Owner, #775): that `=` works here at all —
                   which is not obvious on a cell that otherwise only offers a dropdown — and that
                   the answer still has to be one of the options. Telling them only the first invites
                   a formula the server will refuse; telling them only the second reads as "no
                   formulas". `select` covers Yes/No too: it is a two-member list. */
                return col.kind === 'select' || col.kind === 'boolean'
                  ? 'Type = for a formula. Its result must be one of this column\u2019s allowed options.'
                  : undefined
              })()
            : undefined,
          col.kind === 'longtext'
            ? longTextTooltipLine(p.value, { maxLength: col.maxLength, maxBytes: col.maxBytes, capFrom: col.capFrom })
            : undefined,
          shapeTooltipLine(col, p.value),
          referenceTooltip(p.value, col.optionLabels),
        )
      },
    }

    if (Array.isArray(col.validation?.recordFields)) return { ...def,
      cellEditor: StructuredAttributeEditor, cellEditorPopup: true, cellEditorParams: { attributeColumn: col },
      ...(opts.formula ? formulaSelector(opts.formula, col, { component: StructuredAttributeEditor, popup: true, params: { attributeColumn: col } }) : {}),
      valueParser: p => parseRecordValue(p.newValue), equals: (a, b) => JSON.stringify(a) === JSON.stringify(b),
      valueFormatter: p => recordSummary(p.value, col.validation!.recordFields as any),
      cellRenderer: (p: ICellRendererParams<StudioRow>) => withMark(p, recordSummary(p.value, col.validation!.recordFields as any) || emptyOrRequired(p)),
    }
    if (col.key === 'impactProtectors') {
      return { ...def, cellEditor: ImpactProtectorsEditor, cellEditorPopup: true,
        ...(opts.formula ? formulaSelector(opts.formula, col, { component: ImpactProtectorsEditor, popup: true }) : {}),
        valueFormatter: p => protectorSummary(p.value),
        equals: (a, b) => JSON.stringify(a) === JSON.stringify(b),
        cellRenderer: (p: ICellRendererParams<StudioRow>) => withMark(p, protectorSummary(p.value) || emptyOrRequired(p)),
      }
    }

    if (col.shape === 'list' || col.shape === 'measure') {
      /* AM.1 §A.3 rows 3–4 — ONE rule in the engine (`shapeColumnDef`: editor, formatter, parser,
         filter value, equality), spread here and by the channel builder. A measure is a number and
         right-aligns like one; the cell class is composed by hand because `numericColumn.cellClass`
         is an array and would otherwise drop the editable/locked half of `def`'s function. */
      return {
        ...def,
        ...(col.shape === 'measure' ? numericColumn : {}),
        ...shapeColumnDef<StudioRow>(col, (d) => cellOf(d, col.key)?.value),
        ...(col.key === 'bulletPoints' ? { cellEditor: AttributeShapeEditor, cellEditorPopup: true, cellEditorParams: { attributeColumn: col } } : {}),
        ...(opts.formula ? formulaSelector(opts.formula, col, col.key === 'bulletPoints' ? { component: AttributeShapeEditor, popup: true, params: { attributeColumn: col } } : shapeEditorSpec(col)!) : {}),
        editable,
        cellClass: (p) => [...(col.shape === 'measure' ? numericColumn.cellClass : ['nds-ag-cell']), cellIsEditable(col, p.data) ? 'nds-cell-is-editable' : 'nds-cell-is-locked'].join(' '),
        cellRenderer: (p: ICellRendererParams<StudioRow>) =>
          withMark(p, isEmptyShape(col.shape, p.value) ? emptyOrRequired(p) : <ShapeValue shape={col.shape} value={p.value} optionLabels={col.optionLabels} />),
      }
    }

    if (col.kind === 'select' || isReferenceField(col.key)) {
      const options = (col.options ?? []).map((o) => ({ value: o, label: col.optionLabels?.[o] ?? o }))
      const reference = isReferenceField(col.key)
      const referenceParams = (row?: StudioRow) => ({ fieldKey: col.key, market: opts.market, productType: row?.productType })
      /**
       * 🔴 The code → label map lives on the COLUMN, not only in its renderer (AG.1-e).
       *
       * It used to exist solely inside `cellRenderer`, which meant only the SCREEN ever saw
       * "Pakistan" — every non-visual consumer of the column got the raw code. Measured: the first
       * CSV export wrote `PK` for `country_of_origin` and `not_applicable` for the hazmat column.
       * `valueFormatter` is where AG expects the mapping, so export, clipboard copy and anything
       * else that asks the grid for a displayed value all get the label from one declaration.
       *
       * The renderer still exists because it draws the provenance mark beside the text; it now
       * agrees with the formatter by construction rather than by both being written the same way.
       */
      // One definition, shared with IO.1's import diff — see `optionLabel` for why (#501).
      const label = (v: unknown) => optionLabel(v, col.optionLabels)
      return {
        ...def,
        ...selectEditor(options),
        ...(reference ? { cellEditor: ReferenceSelectEditor, cellEditorPopup: true, cellEditorParams: (p: { data?: StudioRow }) => referenceParams(p.data) } : {}),
        /* `=` opens the formula editor on a closed list too (Owner, #775). The option list is still
           the rule: the server refuses a result that is not one of them, naming them, and the cell
           shows that refusal with the formula kept for correction. */
        ...(opts.formula ? formulaCellEditorSelector<StudioRow>(opts.formula, col, row => reference
          ? { component: ReferenceSelectEditor, popup: true, params: referenceParams(row) }
          : { component: SelectPanelEditor, params: { options } }, row => row.id) : {}),
        editable,
        valueFormatter: (p) => label(p.value),
        /* D13 — the closed-list affordance, from the ENGINE and applied by KIND, never per column:
           every `kind === 'select'` gets it, so a lane cannot ship a select that looks like free
           text. `def.cellClass` is a function (locked vs editable), so it is composed rather than
           replaced — overwriting it here would have silently dropped the locked state. */
        cellClass: (p: CellClassParams<StudioRow>) => {
          const base = typeof def.cellClass === 'function' ? def.cellClass(p) : def.cellClass
          return [Array.isArray(base) ? base.join(' ') : base, SELECT_CELL_CLASS].filter(Boolean).join(' ')
        },
        cellRenderer: (p: ICellRendererParams<StudioRow>) =>
          withMark(
            p,
            p.value != null && p.value !== '' ? label(p.value) : emptyOrRequired(p),
            <SelectChevron />,
          ),
      }
    }
    if (col.kind === 'longtext') {
      return {
        ...def,
        /* Uncapped when the server declares no cap — see the note above. The editor simply does
           not limit what can be typed; the server remains the authority on what it will accept. */
        ...longTextEditor(col.maxLength ? { maxLength: Math.max(col.maxLength, 200) } : {}),
        /* `=` opens the formula editor here too — `item_name` and `product_description` are long-text
           and are exactly the fields D16's worked example is about. The large-text box stays the
           editor for ordinary edits. */
        ...(opts.formula
          ? formulaSelector(opts.formula, col, {
              component: 'agLargeTextCellEditor',
              popup: true,
              /* No `rows`/`cols` here: selector params merge LAST (`mergeParams`, main.esm.mjs:3102)
                 and a constant 8×60 silently overrode the per-cell size `longTextEditor()` computes
                 — the same 488×158 the sizing rule exists to remove, back through a second door.
                 The size is the ColDef's; the selector only names the component. */
              params: { ...(col.maxLength ? { maxLength: Math.max(col.maxLength, 200) } : {}) },
            })
          : {}),
        editable,
        cellRenderer: (p: ICellRendererParams<StudioRow>) =>
          /* 🔴 The RAW caps, not a cap plus a unit flag (AG.1, §9.3a). `countBytes={!!col.maxBytes}`
             passed the byte cap's EXISTENCE while dropping its VALUE, so `product_description`
             counted bytes against `undefined` and reported a capped field as uncapped.
             🔴 The wire OMITS an uncapped unit — it does not send `null`. Measured 2026-09-02 04:32
             (GALE-JACKET, master, DE/de, 96 columns): `maxLength` absent 60 / value 36 / **null 0**;
             `product_description` arrives as `{ maxBytes: 20000 }` with no `maxLength` key at all.
             The earlier "`maxLength: null`" in this comment was a relayed claim nobody had measured.
             The mirrors accept `null` defensively, never as the live shape. `capFrom` rides along because a mark that warns at 80% has to
             name whose cap it is. The remaining half — `lengthCapFor` and `lengthValidation` in the
             counted unit — is PES.2's. */
          withMark(p, <LongTextCell {...p} maxLength={col.maxLength} maxBytes={col.maxBytes} capFrom={col.capFrom} required={col.requiredBy.length > 0} />),
      }
    }
    if (col.kind === 'number') {
      return {
        ...def,
        ...numericColumn,
        cellEditor: 'agNumberCellEditor', cellEditorParams: SHEET_NUMBER_EDITOR_PARAMS,
        /* 🔴 `=` reaches this cell only through the SELECTOR (#775). `agNumberCellEditor` refuses the
           keystroke outright — it accepts digits — so the mode switch can never be typed once that
           editor is mounted. `cellEditorSelector` is resolved BEFORE any editor exists and sees
           `eventKey`, which is the only point where `=` on a numeric cell can still be caught. */
        ...(opts.formula
          ? formulaSelector(opts.formula, col, {
              component: 'agNumberCellEditor',
              params: SHEET_NUMBER_EDITOR_PARAMS,
            })
          : {}),
        editable,
        cellClass: (p) =>
          // Same correction as the text branch above — `cellIsEditable`, the predicate AG is given.
          [...numericColumn.cellClass, cellIsEditable(col, p.data) ? 'nds-cell-is-editable' : 'nds-cell-is-locked'].join(' '),
        cellRenderer: (p: ICellRendererParams<StudioRow>) => withMark(p, p.value == null ? emptyOrRequired(p) : <>{String(p.value)}</>),
      }
    }
    if (col.kind === 'boolean') {
      return {
        ...def,
        ...selectEditor(BOOLEAN_OPTIONS),
        ...(opts.formula
          ? formulaSelector(opts.formula, col, {
              component: SelectPanelEditor,
              params: { options: BOOLEAN_OPTIONS },
            })
          : {}),
        editable,
        valueFormatter: (p) => booleanLabel(p.value),
        cellRenderer: (p: ICellRendererParams<StudioRow>) =>
          withMark(p, p.value == null || p.value === '' ? emptyOrRequired(p) : <>{booleanLabel(p.value)}</>, <SelectChevron />),
      }
    }
    return {
      ...def,
      /**
       * D16 — the formula editor replaces the plain text editor when the lane wires it (#730/#753).
       *
       * 🔴 It is NOT a second editor the operator has to choose. It behaves as an ordinary text
       * field until the text starts with `=`, which is the mode switch §1.3 specifies and the only
       * one there is: the layout struck the formula bar at §1.4 precisely so there is one way to do
       * this. A column that offered both would need the operator to know in advance which they
       * wanted.
       *
       * `cellEditorPopup` is REQUIRED and its absence is silent — an editor that renders outside
       * the cell box without it is torn down the moment focus leaves the grid root, which is what
       * made the DS Listbox look "incompatible with AG" for a whole ruling (`SelectCellEditor`'s
       * header). This editor is far bigger than its cell: field, autocomplete, hint, preview.
       */
      cellEditor: 'agTextCellEditor',
      ...(opts.formula ? formulaSelector(opts.formula, col, { component: 'agTextCellEditor' }) : {}),
      editable,
      cellRenderer: (p: ICellRendererParams<StudioRow>) =>
        withMark(p, p.value != null && p.value !== '' ? <>{p.valueFormatted ?? optionLabel(p.value, col.optionLabels)}</> : emptyOrRequired(p)),
    }
  }

  // EVERY column, not the default-visible ones. See the header comment.
  //
  // One exclusion, and it is not a visibility decision: the sheet's own PINNED identity block
  // already renders `sku`, so building the schema's `sku` too gives AG two columns with one id —
  // it renames the second `sku_1` (warning #273, measured) and every view that names `sku` then
  // addresses a column the operator cannot see.
  const owned = new Set(reservedColumnIds)
  const buildable = columns.filter((c) => !owned.has(c.key))
  const built = buildable.map(build)
  if (!grouped) return built

  const order: string[] = []
  const byGroup = new Map<string, ColDef<StudioRow>[]>()
  buildable.forEach((c, i) => {
    const g = c.group || 'Other'
    if (!byGroup.has(g)) {
      byGroup.set(g, [])
      order.push(g)
    }
    byGroup.get(g)!.push(built[i])
  })
  return order.map((g) => ({
    groupId: g,
    headerName: g,
    /**
     * 🔴 `marryChildren` renders the group header TWICE once ANY child is pinned — measured on real
     * data, both before and after the claim below was written.
     *
     * The old comment here read: "The identity columns are pinned by the sheet and are NOT in these
     * groups, so no group here crosses the boundary." That is true at load and **false the moment
     * an operator uses the column menu's Pin Left on an attribute column** — pinning moves that
     * child across the boundary its group is married across, and "IDENTITY" draws twice. A comment
     * asserting a protection the code never had is worse than no comment; it is why the defect
     * survived a review (`reference_docs_describe_deleted_code`, the same class one step over).
     *
     * The path is kept for a caller that opts in with `grouped: true` and never pins, but the
     * studio sheet no longer does — see `BuildColumnsOptions.grouped`.
     */
    marryChildren: true,
    children: byGroup.get(g)!,
  }))
}

import { describe, expect, it } from 'vitest'

import { ALL_VIEW_ID } from '@/design-system/grid/views/presets'

import { ALWAYS_COLUMNS, alwaysColumnsFor, essentialsColumns, IDENTITY_COLUMN, orderColumnKeys, REQUIRED_VIEW_ID, rowIsMissingRequired, sheetViews, type ViewContext } from './views'
import type { SheetColumn } from './master/types'

const col = (over: Partial<SheetColumn> & Pick<SheetColumn, 'key'>): SheetColumn => ({
  writeField: over.key,
  label: over.key,
  group: 'Attributes',
  kind: 'text',
  storage: 'categoryAttributes',
  scope: 'global',
  requiredBy: [],
  editable: true,
  defaultVisible: false,
  ...over,
})

/** A slice of the REAL prod column set (market=IT, OUTERWEAR — measured 2026-09-01). */
const COLUMNS: SheetColumn[] = [
  col({ key: 'name', group: 'Identity', storage: 'column' }),
  col({ key: 'status', group: 'Identity', storage: 'column', kind: 'select' }),
  col({ key: 'description', group: 'Identity', storage: 'localizedContent', kind: 'longtext' }),
  col({ key: 'brand', group: 'Identity', storage: 'column', requiredBy: ['Amazon · IT'] }),
  col({ key: 'item_name', kind: 'longtext', requiredBy: ['Amazon · IT'] }),
  col({ key: 'bullet_point', kind: 'longtext', requiredBy: ['Amazon · IT'] }),
  col({ key: 'material' }),
  col({ key: 'fabric_type', kind: 'longtext', requiredBy: ['Amazon · IT'] }),
  col({ key: 'fit_type' }),
  /* `axis` is what the SERVER derived (exact match against the family's axis KEYS). The labels stay
     localised so the fixture keeps modelling the case the old substring matcher got wrong. */
  col({ key: 'color', scope: 'per_variant', label: 'Colore', axis: true }),
  col({ key: 'size', scope: 'per_variant', label: 'Taglia', axis: true }),
  col({ key: 'country_of_origin', kind: 'select', requiredBy: ['Amazon · IT'] }),
  col({ key: 'merchant_shipping_group' }),
  col({ key: 'totalStock', group: 'Inventory', storage: 'column', kind: 'number' }),
  col({ key: 'weightValue', group: 'Physical', storage: 'column', kind: 'number' }),
  col({ key: 'basePrice', group: 'Pricing', storage: 'column', kind: 'number' }),
  col({ key: 'costPrice', group: 'Pricing', storage: 'column', kind: 'number' }),
  col({ key: 'ean', group: 'Identifiers', storage: 'column', scope: 'per_variant' }),
  col({ key: 'amazonAsin', group: 'Identifiers', storage: 'column' }),
  col({ key: 'model_number' }),
  col({ key: 'league_name' }),
  col({ key: 'theme' }),
  // The real set has Amazon (6) and eBay (5) groups that no view rule claims — they are what the
  // residual view exists for. Without them in the fixture the orphan test passes vacuously.
  col({ key: 'amazon_title', group: 'Amazon', storage: 'column' }),
  col({ key: 'amazon_browseNode', group: 'Amazon', storage: 'column' }),
  col({ key: 'ebay_duration', group: 'eBay', storage: 'column', kind: 'select' }),
  // A GLOBAL attribute whose label contains an axis word. The axis test must not claim it, or the
  // NARROW view gains a column that does not vary per row.
  col({ key: 'main_color', label: 'Colore principale', scope: 'global' }),
]

const ctx: ViewContext = { variationAxes: ['Colore', 'Taglia'], locale: 'it' }

it('keeps classification and content together when later offer fields are required', () => {
  const columns = [
    col({ key: 'categoryId', group: 'Classification' }),
    col({ key: 'name', group: 'Content', requiredBy: ['eBay · IT'] }),
    col({ key: 'subtitle', group: 'Content' }),
    col({ key: 'conditionId', group: 'Offer', requiredBy: ['eBay · IT'] }),
  ]
  expect(orderColumnKeys(columns, ctx)).toEqual(['categoryId', 'name', 'subtitle', 'conditionId'])
  expect(sheetViews(columns, ctx).presets[0].columns).toEqual(orderColumnKeys(columns, ctx))
})

describe('sheetViews — ALL ATTRIBUTES is first, and it IS the sheet (Owner, 2026-09-04)', () => {
  it('🔴 the first preset is every column, in the §9.2 order — the ground state the sheet lands on', () => {
    const { presets } = sheetViews(COLUMNS, ctx)
    expect(presets[0].id).toBe(ALL_VIEW_ID)
    expect(presets[0].columns).toEqual(orderColumnKeys(COLUMNS, ctx))
    expect([...presets[0].columns].sort()).toEqual(COLUMNS.map((c) => c.key).sort())
  })

  it('stays first when the server supplies the task views — the ground state is the sheet’s, not a server view’s', () => {
    const r = sheetViews(COLUMNS, ctx, [{ id: 'pricing', label: 'Pricing', columnKeys: ['basePrice'] }])
    expect(r.presets[0].id).toBe(ALL_VIEW_ID)
  })

  it('keeps Required second and offers focused Information presets', () => {
    const ids = sheetViews(COLUMNS, ctx).presets.map((v) => v.id)
    expect(ids).not.toContain('narrow')
    expect(ids).toContain('essentials')
    expect(ids[1]).toBe(REQUIRED_VIEW_ID)
  })
})

describe('sheetViews — complete and focused Information views', () => {
  it('retains evaluated conditional fields in Required after their errors are resolved', () => {
    const columns = [col({ key: 'conditional', group: 'Details', requiredBy: [] })]
    expect(sheetViews(columns, { ...ctx, requiredKeys: ['conditional'], flaggedKeys: [] }).presets.find(view => view.id === REQUIRED_VIEW_ID)?.columns).toEqual(['conditional'])
  })
  it('offers All attributes, Required, Essentials and Localized content from column rules', () => {
    const r = sheetViews(COLUMNS, ctx)
    expect(r.source).toBe('rules')
    expect(r.presets.map((v) => v.id)).toEqual([ALL_VIEW_ID, REQUIRED_VIEW_ID, 'essentials', 'localized-content'])
  })

  it('Required is every column some channel requires on this product type, filled or not, in the §9.2 order', () => {
    const required = sheetViews(COLUMNS, ctx).presets.find((v) => v.id === REQUIRED_VIEW_ID)!
    expect(required.label).toBe('Required')
    const expected = orderColumnKeys(COLUMNS, ctx).filter((k) => COLUMNS.find((c) => c.key === k)!.requiredBy.length > 0)
    expect(required.columns).toEqual(expected)
    expect(required.columns).toEqual(expect.arrayContaining(['brand', 'item_name', 'bullet_point', 'fabric_type', 'country_of_origin']))
    // Filled or not: `brand` is required and (in this fixture) not flagged missing — it is still in the set.
    expect(required.columns).toContain('brand')
  })

  it('🔴 a band column (sku, completeness) is never offered by Required — it is always on screen', () => {
    const cols = [...COLUMNS, col({ key: 'sku', group: 'Identity', storage: 'column', requiredBy: ['Amazon · IT'] })]
    const required = sheetViews(cols, ctx).presets.find((v) => v.id === REQUIRED_VIEW_ID)!
    expect(required.columns).not.toContain('sku')
  })

  it('omits an empty Required set while retaining useful content views', () => {
    const none = COLUMNS.map((c) => ({ ...c, requiredBy: [] }))
    expect(sheetViews(none, ctx).presets.map((v) => v.id)).toEqual([ALL_VIEW_ID, 'essentials', 'localized-content'])
  })

  it('avoids provider group duplication while retaining the Essentials rule', () => {
    const ids = sheetViews(COLUMNS, ctx).presets.map((v) => v.id)
    expect(ids.some((id) => id.startsWith('group:'))).toBe(false)
    expect(ids).not.toContain('localisation')
    // `essentialsColumns` is a tested rule kept for the day the Owner asks for it back.
    expect(essentialsColumns(COLUMNS, ctx)).toEqual(expect.arrayContaining(['color', 'size']))
  })

  /**
   * "Missing required" is a view CHIP, not a preset — it filters rows AND columns, which a column
   * preset cannot express, and the layout draws it as its own control beside the views trigger.
   * Offering both would be two controls for one idea.
   */
  it('does NOT offer missing-required as a preset — the chip owns it', () => {
    expect(sheetViews(COLUMNS, ctx).presets.map((v) => v.id)).not.toContain('missing-required')
  })

  /**
   * Every column is in All attributes — and the sheet lands full anyway, so an operator can never
   * mistake "this product has no such field" for "your view is hiding it".
   */
  it('every column is reachable from SOME view — nothing is orphaned', () => {
    const { presets } = sheetViews(COLUMNS, ctx)
    const reachable = new Set([...presets.flatMap((v) => v.columns), ...ALWAYS_COLUMNS])
    const orphans = COLUMNS.map((c) => c.key).filter((k) => !reachable.has(k))
    expect(orphans).toEqual([])
  })
})

describe('sheetViews — the server wins when it speaks', () => {
  it('uses PES.5’s views verbatim, after All attributes, and says they came from the server', () => {
    const r = sheetViews(COLUMNS, ctx, [{ id: 'pricing', label: 'Pricing', columnKeys: ['basePrice'] }])
    expect(r.source).toBe('server')
    expect(r.presets.slice(1)).toEqual([{ id: 'pricing', label: 'Pricing', columns: ['basePrice'] }])
  })

  it('an EMPTY server list is not an answer — the rules still run', () => {
    const r = sheetViews(COLUMNS, ctx, [])
    expect(r.source).toBe('rules')
    expect(r.presets.length).toBeGreaterThan(1)
  })
})

describe('rowIsMissingRequired', () => {
  it('reads the server’s own missing[] so the filter and the readiness pill cannot disagree', () => {
    expect(rowIsMissingRequired({ completeness: { required: { missing: [{ key: 'brand', label: 'Brand' }] } } })).toBe(true)
    expect(rowIsMissingRequired({ completeness: { required: { missing: [] } } })).toBe(false)
  })

  it('a row with no completeness block is not claimed to be missing anything', () => {
    expect(rowIsMissingRequired({})).toBe(false)
    expect(rowIsMissingRequired({ completeness: {} })).toBe(false)
  })
})

describe('alwaysColumnsFor — the guarantee resolved against columns that exist (#770)', () => {
  it('🔴 drops the band contents when the grid has no such columns', () => {
    // `sku` became the identity band's key line and `completeness` its readiness pill, so neither is
    // built. Asking for them made the prefs bridge refuse two columns on EVERY master load.
    expect(alwaysColumnsFor([IDENTITY_COLUMN, 'brand', 'name'])).toEqual(['product'])
  })

  it('🔴 keeps them the moment they exist again — the point of deriving rather than trimming', () => {
    // A constant trimmed to ['product'] would silently stop guaranteeing them if they came back.
    expect(alwaysColumnsFor(['product', 'sku', 'completeness', 'brand'])).toEqual(['product', 'sku', 'completeness'])
    expect(alwaysColumnsFor(['product', 'completeness'])).toEqual(['product', 'completeness'])
  })

  it('an empty addressable set yields nothing rather than inventing an id', () => {
    expect(alwaysColumnsFor([])).toEqual([])
  })

  it('preserves the intent order, not the caller order', () => {
    expect(alwaysColumnsFor(['completeness', 'sku', 'product'])).toEqual([...ALWAYS_COLUMNS])
  })
})

/**
 * PES.1 — the Product Edit Studio frame's TYPES.
 *
 * Pure: no React, no runtime imports. A server component and a `'use client'` module can both read it,
 * and so can a vitest file. The runtime half of the contract (providers + hooks) is
 * `contracts.tsx`; everything here is re-exported from there, so a consuming lane has one import.
 *
 * Owned by PES.1. PES.2/3/4/5/7 CONSUME these shapes — see `docs/pes-claims.md`, "Contracts PES.1
 * publishes". If a lane needs a field that is not here, ask for it rather than widening a local
 * copy: a second definition of the same fact is the fork this file exists to prevent.
 */

// Type-only: the DS component that DRAWS readiness defines its four states and its nullable
// percentage. The app extends that render contract below rather than re-declaring either half.
import type { ScopeBarReadiness, ScopeReadinessState } from '@/design-system/patterns'

/* ── the coordinate ──────────────────────────────────────────────────────────────────────── */

/**
 * Which layer of the data spine is being edited.
 *
 * `'master'` is the stored truth; anything else is a CHANNEL key exactly as the API spells it
 * (`'AMAZON'`, `'EBAY'`, `'SHOPIFY'`, …). It is deliberately NOT `channel:market` — the market is
 * its own control. One control per fact: the chips name the channel, the switcher names the
 * market. Merging them is what sank the reverted ads scope bar
 * (reference_one_filter_bar_merged_scope, "two controls for one fact").
 */
export type StudioScopeId = 'master' | (string & {})

export const MASTER_SCOPE = 'master' as const

/**
 * The non-tabular surfaces. The sheet IS the page; these are the things it is not.
 *
 * `visibleTabs()` in `scopes.ts` is the one place that decides which tasks a scope offers.
 * Presentation is eBay-specific; shared Needs attention explains its available checks.
 *
 * 🔴 `'variants'` is ONE page re-projected by the scope bar, not one page per channel: family STRUCTURE on
 * master, each channel's PROJECTION on its own scope (variants spec §1.1).
 *
 * 🔴 There is no `'relationships'` member. The task was removed on the Owner's call (2026-09-12) — the page
 * was never needed — so it is absent from the union, from `STUDIO_TABS` and from the frame's tab map. A
 * bookmarked `?tab=relationships` falls back to `sheet` in `contracts.tsx`, which reads the URL against
 * `STUDIO_TABS`.
 */
export type StudioTabId = 'sheet' | 'variants' | 'images' | 'analytics' | 'activity' | 'errors' | 'presentation' | 'variation-order' | 'shopify-family' | 'shopify-metafields'

/**
 * How much of a publish actually reaches a channel — the SERVER's vocabulary, verbatim.
 *
 * `getAmazonPublishMode()` returns `'gated' | 'dry-run' | 'sandbox' | 'live'` and nothing else
 * decides whether a feed is submitted, so this is the one place the four words are written down.
 *
 * 🔴 Added because there were TWO of these for one concept, each masked by the other's behaviour
 * (PES.7 / PES.3, 2026-09-02): the images lane's was OPEN but three-membered and missing
 * `'sandbox'` — safe, because everything that is not `'live'` is treated as a rehearsal, but unable
 * to *say* "sandbox"; channel-ops' had all four and was CLOSED, so a mode the server adds tomorrow
 * would not typecheck. This is the union of the two: **all four members, and still open**, because
 * degrading an unrecognised mode to "not live" is the safe direction and dropping it is not.
 *
 * Only `'live'` may submit. Treat every other value, known or not, as a rehearsal.
 */
export type PublishMode = 'gated' | 'dry-run' | 'sandbox' | 'live' | (string & {})

/** Declaration order IS the order of the secondary navigation drawer. Canvas artboard "Product navigation". */
export const STUDIO_TABS: readonly StudioTabId[] = ['sheet', 'variants', 'images', 'presentation', 'variation-order', 'shopify-family', 'shopify-metafields', 'errors', 'analytics', 'activity']

/** A channel × marketplace pair. `null` on master scope — master has no coordinate. */
export interface StudioCoordinate {
  channel: string
  marketplace: string
  accountId?: string
}

/* ── what the frame derives from live marketplaces ───────────────────────────────────────── */

/** The subset of `Marketplace` the frame reads. Mirrors the API's `/marketplaces/grouped` rows. */
export interface MarketplaceLite {
  /** Ordered Marketplace.languages authority, projected by the API. */
  languages?: string[]
  accounts?: Array<{ id: string; label: string; primary: boolean }>
  id: string
  channel: string
  code: string
  name: string
  language: string
  /** False when the marketplace is configured without an active account. */
  connected?: boolean
}

export interface ChannelOption {
  /** The API's channel key — also the scope id. */
  id: string
  label: string
  /** Market codes this channel actually serves. A chip is disabled outside them. */
  markets: string[]
}

export interface MarketOption {
  code: string
  label: string
  /** Channels present in this market. */
  channels: string[]
}

export interface LocaleOption {
  code: string
  label: string
}

export interface StudioScopeOptions {
  channels: ChannelOption[]
  markets: MarketOption[]
  locales: LocaleOption[]
}

/* ── readiness (PES.5 supplies it; the frame only renders it) ────────────────────────────── */

/**
 * The SCOPE-level readiness vocabulary — four states, deliberately its own.
 *
 * The grid's per-row `ReadinessState` (`ready|missing|errors|live|unlisted`) answers "can THIS ROW
 * ship?". A scope chip answers "how far is this whole scope from shippable?", which is a different
 * question with a different set of answers. They must still LOOK like one system, which is why
 * PES.2 has been asked to export the grid's tone map rather than PES.1 re-declaring it.
 */
export type { ScopeReadinessState }

export interface ScopeReadiness extends ScopeBarReadiness {
  languages?: Array<{ language: string; pct: number | null; state: ScopeReadinessState }>
  /** The counts the percentage came from, so the chip's tooltip can show its own arithmetic. */
  required?: { filled: number; total: number }
  /**
   * How many mapping rules this coordinate has for THIS product type (PES.5 §11).
   *
   * `0` is the machine-readable discriminator for "nothing is configured here yet" — three
   * different causes now produce `state: 'absent'`, and `note` is what tells them apart in words.
   * `null` when the server did not say.
   *
   * 🔴 Rules are per PRODUCT TYPE, so the same Amazon · IT chip is legitimately `blocked 71%` for
   * one product and `absent` for another. Readiness must never be cached per coordinate.
   */
  mappingRules?: number | null
}

/**
 * The whole query, not just its happy answer.
 *
 * `unavailable` is a first-class state, not an error: until PES.5 ships the endpoint, every chip
 * is legitimately un-scored, and a frame that silently rendered blanks would look identical to a
 * frame whose fetch had failed.
 */
export type ScopeReadinessQuery =
  /**
   * Still measuring. `slow` means it has been in flight long enough to say so in the footer — it is
   * a DISPLAY hint, never a failure: the request is alive and still wanted (§3.6).
   */
  | { status: 'loading'; slow?: boolean }
  /**
   * `coordinate` is the `productId:market` these values answer for. A re-read keeps them on screen
   * only while it matches — a different coordinate is a different question, and the old answer is
   * not a stale version of it (§3.6; measured IT→DE showing IT's 71% under a DE bar).
   */
  | { status: 'ready'; byScope: Readonly<Record<string, ScopeReadiness>>; matrix: ReadinessMatrixEntry[]; at: number; coordinate: string }
  | { status: 'unavailable'; reason: string }
  | { status: 'error'; message: string }

/** The wire shape PES.1 asked PES.5 for (docs/pes-claims.md). */
export interface ReadinessMatrixEntry extends ScopeReadiness {
  coordinateKey: string
  channel: string | null
  market: string | null
  accountId: string | null
  aliasId: string | null
  language: string
  label: string
  missing: Array<{ productId: string; field: string; label: string; reason: string }>
  computedAt: string | null
}

export interface ScopeReadinessResponse {
  matrix: ReadinessMatrixEntry[]
  market: string
  scopes: Array<{ id: string } & ScopeReadiness>
}

/* ── autosave (PES.2/3 write it; the header renders it) ──────────────────────────────────── */

/**
 * The aggregate autosave state.
 *
 * 🔴 The header does not compute this and cannot. It has no view of the sheet's writes, so a
 * header that guessed "Saved" from its own timers would say so while a cell was refusing. The
 * sheet reports; the header renders what it was told (feedback_100_percent_honest_ui).
 */
export type StudioSaveState =
  | { kind: 'idle' }
  | { kind: 'saving'; pending: number }
  | { kind: 'saved'; at: number; count: number }
  | { kind: 'error'; failed: number; pending: number; message: string }

/**
 * What PES.2/PES.3 call. Keyed by a write id so overlapping writes count correctly — a sheet
 * fills a column down and forty writes are in flight at once; a boolean would report the last one.
 */
export interface SaveReporter {
  /**
   * A write has left the browser.
   *
   * `subject` is what the write is ABOUT — a row id for a sheet, an asset id for the gallery.
   * Failures are counted per SUBJECT, so a second attempt at the same row REPLACES its failure
   * instead of adding one. Callers with no subject may omit it and are counted per write, which
   * is the old behaviour and means their failures only clear via `cleared()`.
   */
  pending(writeId: string, subject?: string): void
  /** The server answered. `message` is ITS words on failure, shown verbatim. */
  resolved(writeId: string, ok: boolean, message?: string, subject?: string): void
  /**
   * Withdraw the failures for these subjects: the work is GONE, not fixed.
   *
   * 🔴 Reload-discard needs this and nothing else could express it (#693). `resolved(id, true)`
   * would clear the count by claiming a success that never happened — a lie on the one line the
   * operator trusts about their unsaved work.
   */
  cleared(subjects: readonly string[]): void
}

/* ── the record drawer (PES.4) ───────────────────────────────────────────────────────────── */

/** URL-backed so a drawer survives reload and back/forward, as PES.4 asked. */
export interface StudioRecordValue {
  rowId: string | null
  colKey: string | null
  open(rowId: string, colKey?: string): void
  close(): void
}

/* ── the product the frame renders (identity only) ───────────────────────────────────────── */

/**
 * Identity, and nothing else.
 *
 * The frame draws a name, a SKU and a status. It deliberately does NOT load attributes, listings,
 * children or images — those belong to the tab that shows them, and loading them here would put
 * the old edit page's five-fetch cold start back in front of a sheet that does not need it.
 */
export interface StudioProduct {
  id: string
  sku: string
  name: string | null
  status: string | null
  isParent: boolean
  parentId: string | null
  productType: string | null
  /**
   * The Amazon ASIN, when the product has one. Already carried by `GET /api/products/:id` as
   * `amazonAsin` — no new backend field was needed for parity row 1.6.
   */
  asin: string | null
}

/**
 * The family a CHILD product belongs to (parity 1.29 / 8.11).
 *
 * Identity only, and fetched only when `parentId` is set. The old page's banner also listed sibling
 * chips; in the studio the SHEET is the family — it renders the parent and every variation as rows —
 * so duplicating the siblings in a banner would be a second, staler list of the same thing. What the
 * sheet cannot say is "the row you are on belongs to THIS parent, here is the way up", which is
 * identity, and identity is the header's job.
 */
export interface StudioFamily {
  parentId: string
  parentSku: string
  parentName: string | null
  parentAsin: string | null
}

/* ── view chips (the View bar's filtered views) ──────────────────────────────────────────── */

/**
 * The cells a chip is about, as `rowId → affected column ids`.
 *
 * Cell-level and not two flat lists, because "rows AND columns" is a projection of this and the
 * reverse is not: from `{rows, cols}` you cannot tell WHICH cell in the rectangle was the reason,
 * so a renderer could not highlight the seven actually-missing cells inside a 7 × 12 grid. Rows are
 * the keys; columns are the union of the values (`viewChipRows` / `viewChipColumns` derive both).
 */
export interface ViewChipCells {
  byRow: Readonly<Record<string, readonly string[]>>
}

export interface ViewChip {
  compactLabel?: string
  /** Counted unit. Information defaults to columns; row filters declare variants. */
  noun?: 'columns' | 'variants' | 'combinations' | 'axes'
  /** Stable, and the URL value when this chip is selected — `missing-required`, `ai-drafts`. */
  id: string
  label: string
  tone?: 'warning' | 'danger' | 'info' | 'neutral'
  /**
   * 🔴 `null` is NOT zero. `null` means nobody has counted yet (the fetch is in flight, or the
   * endpoint that would answer is not there); `0` means counted, and there are none. A renderer
   * shows `null` as a pending chip with no number and must never print `(0)` for it — that would
   * state "we checked, there are none" on the strength of not having checked.
   */
  count: number | null
  /** Hide the chip entirely at a REAL zero. Default true: "Missing required (0)" is noise. */
  hideWhenZero?: boolean
  /** Why the count is `null`, or what the chip means. The producer's own words. */
  note?: string
  /** Empty while `count` is null. */
  cells: ViewChipCells
}

'use client'

/**
 * PES.8 — everything the sheet needs from this lane, in one hook.
 *
 * Two consumers, one call: PES.2's `buildMasterColumns({ draftFor })` renders the proposal in the
 * cell, and PES.1's View bar gets an `✦ AI drafts` chip. Both are derived from the same fetch, so a
 * lane wiring this in takes one line and gets a consistent count and overlay rather than two reads
 * that can disagree.
 *
 * 🔴 `draftFor` is REF-READING and its identity never changes.
 *
 * PES.2's contract asks for this explicitly and the reason is load-bearing: AG re-runs its entire
 * column model whenever `columnDefs` gets a new identity, so a `draftFor` that changed when drafts
 * arrived would rebuild a hundred column definitions on every fetch — the same inline-options trap
 * the grid's memoisation guard exists for (reference_ag_react_inline_options_rerun_column_model).
 * The drafts live in a ref; the function reading it is created once.
 */
import { useCallback, useEffect, useMemo, useRef } from 'react'

import { useRegisterViewChip, type ViewChip, type ViewChipCells } from '../contracts'

import { cellIndexKey, indexDrafts, toSheetDraft, type SheetAiDraft } from './drafts'
import { useAiDrafts, type UseAiDraftsInput, type UseAiDraftsValue } from './useAiDrafts'
import type { AiDraft } from './types'

export interface AiDraftLayer {
  /** Pass straight to `buildMasterColumns({ draftFor })`. Stable identity, reads a ref. */
  draftFor: (rowId: string, colId: string) => SheetAiDraft | null
  /** The full lane state, for the review surface. */
  drafts: UseAiDraftsValue
}

export function useAiDraftLayer(input: UseAiDraftsInput): AiDraftLayer {
  const drafts = useAiDrafts(input)

  // The ref the stable `draftFor` reads. Updated on every load; never a dependency of anything.
  const indexRef = useRef(new Map<string, AiDraft>())
  useEffect(() => {
    indexRef.current = indexDrafts(drafts.drafts)
  }, [drafts.drafts])

  const draftFor = useCallback((rowId: string, colId: string): SheetAiDraft | null => {
    const hit = indexRef.current.get(cellIndexKey(rowId, colId))
    return hit ? toSheetDraft(hit) : null
  }, [])

  /**
   * The chip's cells: which (row, column) pairs it counts, so selecting it filters the sheet to
   * exactly the drafted cells rather than to a rectangle around them.
   */
  const cells: ViewChipCells = useMemo(() => {
    const byRow: Record<string, string[]> = {}
    for (const d of drafts.drafts) {
      if (d.status !== 'pending') continue
      const cols = byRow[d.productId] ?? []
      if (!cols.includes(d.columnKey)) cols.push(d.columnKey)
      byRow[d.productId] = cols
    }
    return { byRow }
  }, [drafts.drafts])

  const chip: ViewChip = useMemo(() => {
    // 🔴 `null` is NOT zero, and this is the case that makes the distinction matter: while the
    // fetch is in flight, or when it FAILED, we have not counted. Reporting 0 there would tell the
    // operator "we checked, there are no drafts" on the strength of not having checked — and the
    // chip would then hide itself at that fake zero, so drafts waiting for review would be
    // invisible with nothing on screen admitting it.
    const counted = !drafts.loading && drafts.error === null
    const pending = drafts.drafts.filter((d) => d.status === 'pending').length
    return {
      id: 'ai-drafts',
      label: 'AI drafts',
      tone: 'info',
      count: counted ? pending : null,
      note: drafts.error
        ? `Could not read AI drafts: ${drafts.error}`
        : drafts.loading
          ? 'Counting AI drafts…'
          : 'Cells an AI has proposed a value for. Nothing applies until you approve it.',
      cells: counted ? cells : { byRow: {} },
    }
  }, [drafts.loading, drafts.error, drafts.drafts, cells])

  useRegisterViewChip('ai-drafts', chip)

  return { draftFor, drafts }
}

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'

import { commitMasterRow, type MasterCommitContext } from './masterWrite'
import type { SheetColumn, StudioSheet, StudioRow } from './types'
import type { SheetWriteRequest } from '@/design-system/grid'

/*
 * The master sheet's write path. It had NO tests at all — it was declared inside the hook and was
 * therefore unreachable, while its twin `commitChannelRow` was module-level with
 * `channelWrite.vitest.test.ts` beside it (FE.1's finding, hub #348). Same operation, two lanes.
 *
 * These probe the SEAMS a reading of the source does not settle: which endpoint a cell routes to,
 * what a 409 does to the version, what a 200 carrying per-cell `errors[]` reports, and the two
 * places where this function INFERS rather than reads.
 */

const col = (key: string, over: Partial<SheetColumn> = {}): SheetColumn =>
  ({ key, label: key, group: 'g', requiredBy: [], storage: 'categoryAttributes', ...over } as SheetColumn)

const sheet = {
  // The coordinate the sheet was on — the write is validated against the schema that declared the
  // columns, so the caller hands the same scope back.
  scope: { kind: 'master', label: 'Master · DE', marketplace: 'DE', locale: 'it' },
  columns: [
    col('name', { storage: 'column', writeField: 'name' }),
    col('attr_colour'),
    col('description', { storage: 'localizedContent' }),
  ],
} as unknown as StudioSheet

const ctx = (over: Partial<MasterCommitContext> = {}): MasterCommitContext =>
  ({ sheet, opts: {}, locale: 'it', market: 'DE', ...over })

const req = (cells: SheetWriteRequest<StudioRow>['cells'], over: Partial<SheetWriteRequest<StudioRow>> = {}) =>
  ({ rowId: 'p1', row: {} as StudioRow, cells, ...over }) as SheetWriteRequest<StudioRow>

const json = (status: number, body: unknown) =>
  ({ ok: status >= 200 && status < 300, status, json: async () => body })

/**
 * `SheetWriteResult.cells` is optional on the contract, and a commit that returned NO per-cell
 * outcomes would be a real defect — the writer would have nothing to paint. So this asserts rather
 * than using `!`: every test below is entitled to per-cell outcomes, and if one goes missing the
 * failure should say that, not read as an undefined-property crash somewhere downstream.
 */
const cellsOf = (r: { cells?: Record<string, { ok: boolean; reason?: string }> }) => {
  if (!r.cells) throw new Error('commitMasterRow returned no per-cell outcomes')
  return r.cells
}

let fetchMock: ReturnType<typeof vi.fn>
beforeEach(() => {
  fetchMock = vi.fn()
  vi.stubGlobal('fetch', fetchMock)
})
afterEach(() => vi.unstubAllGlobals())

describe('commitMasterRow — routing', () => {
  it('reports the actual per-field validation error from a refused bulk request', async () => {
    fetchMock.mockResolvedValue(json(400, { errors: [{ id: 'p1', field: 'attr_colour', error: 'Composition percentages must total 100' }] }))
    const result = await commitMasterRow(req([{ colId: 'attr_colour', value: [] }] as never), ctx())
    expect(cellsOf(result).attr_colour).toEqual({ ok: false, reason: 'Composition percentages must total 100' })
  })
  it('sends Product columns and attr_* to the bulk endpoint, and a locale slot to the global patch', async () => {
    fetchMock.mockResolvedValue(json(200, { errors: [] }))
    await commitMasterRow(req([
      { colId: 'name', value: 'Jacket' },
      { colId: 'description', value: 'Ciao' },
    ] as never), ctx())

    expect(fetchMock).toHaveBeenCalledTimes(2)
    const [bulkUrl, bulkInit] = fetchMock.mock.calls[0]
    const [globalUrl, globalInit] = fetchMock.mock.calls[1]
    expect(String(bulkUrl)).toContain('/api/products/bulk')
    expect(String(globalUrl)).toContain('/api/products/p1/global')
    // 🔴 The locale slot is keyed by the CONTEXT's locale, not by the column key.
    expect(JSON.parse(globalInit.body).patch).toEqual({ it: { description: 'Ciao' } })
    expect(JSON.parse(bulkInit.body).changes).toEqual([{ id: 'p1', field: 'name', value: 'Jacket' }])
  })

  it('🔴 sends the SHEET\'s marketplace context — without it every attr_* write is refused', async () => {
    /*
     * The Owner's "I'm unable to write a lot of attributes still, such as color". The server
     * validates each `attr_*` with `getFieldDefinition(field, { marketplace })`, and this body
     * carried no contexts — so every master attribute arrived with `marketplace: null` and came
     * back 400 "Unknown or read-only category attribute". SC.1 measured 60 of 60 refused on master
     * DE/de against 57 accepted on Amazon·DE; the channel writer sent its contexts, this one did not.
     *
     * 🔴 All 21 tests in this file passed while that was true. They asserted the shape of `changes`
     * and never the ENVELOPE around it, so the one field whose absence refused every write was the
     * one field nothing looked at.
     */
    fetchMock.mockResolvedValue(json(200, { errors: [] }))
    await commitMasterRow(req([{ colId: 'attr_colour', value: 'Black' }] as never), ctx())
    expect(JSON.parse(fetchMock.mock.calls[0][1].body).marketplaceContexts)
      .toEqual([{ marketplace: 'DE', locale: 'it' }])
  })

  it('omits the context rather than inventing one when there is no marketplace', async () => {
    // A guessed marketplace would validate the write against a schema the server never used.
    fetchMock.mockResolvedValue(json(200, { errors: [] }))
    await commitMasterRow(req([{ colId: 'attr_colour', value: 'Black' }] as never), ctx({ market: '' }))
    expect(JSON.parse(fetchMock.mock.calls[0][1].body)).not.toHaveProperty('marketplaceContexts')
  })

  it('writes the server-supplied writeField, never the column key', async () => {
    fetchMock.mockResolvedValue(json(200, { errors: [] }))
    const s = { columns: [col('brandName', { storage: 'column', writeField: 'brand' })] } as unknown as StudioSheet
    await commitMasterRow(req([{ colId: 'brandName', value: 'Gale' }] as never), ctx({ sheet: s }))
    expect(JSON.parse(fetchMock.mock.calls[0][1].body).changes[0].field).toBe('brand')
  })

  it('makes no request at all when the batch has no cells', async () => {
    await commitMasterRow(req([] as never), ctx())
    expect(fetchMock).not.toHaveBeenCalled()
  })
})

describe('commitMasterRow — a reset and an empty string both mean "store nothing"', () => {
  it('sends null for both', async () => {
    fetchMock.mockResolvedValue(json(200, { errors: [] }))
    await commitMasterRow(req([
      { colId: 'name', intent: 'reset', value: 'ignored' },
      { colId: 'attr_colour', value: '' },
    ] as never), ctx())
    const changes = JSON.parse(fetchMock.mock.calls[0][1].body).changes
    expect(changes.map((c: { value: unknown }) => c.value)).toEqual([null, null])
  })
})

describe('commitMasterRow — a reset and an empty string mean "store nothing" on BOTH routes', () => {
  it('the localized reset removes its own slot so inheritance can resume', () => {
    // The bulk route was covered and this one was not, so deleting the whole ternary here kept the
    // suite green. A reset that silently wrote the string "" into a locale slot would look like a
    // successful save and read back as an empty translation rather than an absent one.
    fetchMock.mockResolvedValue(json(200, {}))
    return commitMasterRow(req([
      { colId: 'description', intent: 'reset', value: 'ignored' },
    ] as never), ctx()).then(() => {
      expect(JSON.parse(fetchMock.mock.calls[0][1].body)).toMatchObject({ patch: { it: {} }, reset: { it: ['description'] } })
    })
  })

  it('and an empty string on the localized route is null, not ""', async () => {
    fetchMock.mockResolvedValue(json(200, {}))
    await commitMasterRow(req([{ colId: 'description', value: '' }] as never), ctx())
    expect(JSON.parse(fetchMock.mock.calls[0][1].body).patch).toEqual({ it: { description: null } })
  })
})

describe('commitMasterRow — the concurrency guard', () => {
  it('omits expectedVersion when unknown rather than guessing one', async () => {
    // A guessed version refuses a write the operator is entitled to make; absent means "no guard".
    fetchMock.mockResolvedValue(json(200, { errors: [] }))
    await commitMasterRow(req([{ colId: 'name', value: 'x' }] as never), ctx())
    expect(JSON.parse(fetchMock.mock.calls[0][1].body)).not.toHaveProperty('expectedVersion')
  })

  it('reports a 409 as a CONFLICT, carries the server version, and refuses every cell', async () => {
    fetchMock.mockResolvedValue(json(409, { currentVersion: 12 }))
    const r = await commitMasterRow(req([{ colId: 'name', value: 'x' }] as never, { expectedVersion: 7 }), ctx())
    expect(r.conflict).toBe(true)
    expect(r.version).toBe(12)
    expect(r.ok).toBe(false)
    expect(cellsOf(r).name.ok).toBe(false)
    expect(cellsOf(r).name.reason).toMatch(/Someone else changed this row/)
  })

  it('🔴 does NOT infer a version the server did not answer — read back or keep what you read', () => {
    /*
     * This test previously asserted the OPPOSITE — that `expectedVersion + 1` was correct — and it
     * passed for hours. The route was doing the same arithmetic on its own side, so two independent
     * guesses agreed and looked like corroboration. **Two guesses agreeing is not a measurement.**
     *
     * A computed version is the banked `Product.version` ≠ row version trap: it can lose a race it
     * should have won, or win one it should have lost.
     */
    fetchMock.mockResolvedValue(json(200, { errors: [] }))
    return commitMasterRow(req([{ colId: 'name', value: 'x' }] as never, { expectedVersion: 7 }), ctx())
      .then((r) => expect(r.version).toBeUndefined())
  })

  it('prefers the server’s currentVersion over the inference when both are available', async () => {
    fetchMock.mockResolvedValue(json(200, { errors: [], currentVersion: 41 }))
    const r = await commitMasterRow(req([{ colId: 'name', value: 'x' }] as never, { expectedVersion: 7 }), ctx())
    expect(r.version).toBe(41)
  })

  it('infers NOTHING when no version was sent — there was no guard to advance', async () => {
    fetchMock.mockResolvedValue(json(200, { errors: [] }))
    const r = await commitMasterRow(req([{ colId: 'name', value: 'x' }] as never), ctx())
    expect(r.version).toBeUndefined()
  })
})

describe('commitMasterRow — a 200 can still refuse individual cells', () => {
  it('matches a per-cell error by writeField OR colId and leaves its neighbours ok', async () => {
    fetchMock.mockResolvedValue(json(200, {
      errors: [{ id: 'p1', field: 'name', error: 'Too long' }],
    }))
    const r = await commitMasterRow(req([
      { colId: 'name', value: 'x' },
      { colId: 'attr_colour', value: 'red' },
    ] as never), ctx())
    expect(cellsOf(r).name).toEqual({ ok: false, reason: 'Too long' })
    expect(cellsOf(r).attr_colour).toEqual({ ok: true })
  })

  it('ignores an error belonging to a DIFFERENT row', async () => {
    fetchMock.mockResolvedValue(json(200, { errors: [{ id: 'p2', field: 'name', error: 'not mine' }] }))
    const r = await commitMasterRow(req([{ colId: 'name', value: 'x' }] as never), ctx())
    expect(cellsOf(r).name).toEqual({ ok: true })
  })

  it('🔴 never reports a failure without a message (ruling #27)', async () => {
    // The header renders the reporter's message verbatim. A 200 carrying per-cell refusals has no
    // batch-level reason at all, so reporting `undefined` would say a write failed without saying
    // why. The per-cell reason is the fallback.
    const onWriteEnd = vi.fn()
    fetchMock.mockResolvedValue(json(200, { errors: [{ id: 'p1', field: 'name', error: 'Too long' }] }))
    await commitMasterRow(req([{ colId: 'name', value: 'x' }] as never), ctx({ opts: { onWriteEnd } }))
    const [, ok, message] = onWriteEnd.mock.calls[0]
    expect(ok).toBe(false)
    expect(message).toBe('Too long')
  })
})

describe('commitMasterRow — failures and reporting', () => {
  it('reports an HTTP refusal with the server’s own error text', async () => {
    fetchMock.mockResolvedValue(json(422, { error: 'Brand is not on the allow list' }))
    const r = await commitMasterRow(req([{ colId: 'name', value: 'x' }] as never), ctx())
    expect(r.reason).toBe('Brand is not on the allow list')
    expect(cellsOf(r).name.ok).toBe(false)
  })

  it('keeps an unavailable server acknowledgement unconfirmed until a recovery read', async () => {
    fetchMock.mockResolvedValue(json(500, null))
    const r = await commitMasterRow(req([{ colId: 'name', value: 'x' }] as never), ctx())
    expect(r.reason).toMatch(/confirmation was unavailable/i)
    expect(r.unreachable).toBe(true)
  })

  it('does not treat malformed success JSON as proof that a write saved', async () => {
    fetchMock.mockResolvedValue(json(200, {}))
    expect(await commitMasterRow(req([{ colId: 'name', value: 'x' }] as never), ctx())).toMatchObject({ ok: false, unreachable: true })
  })

  it('a thrown fetch refuses EVERY cell in the batch and still closes the write', async () => {
    const onWriteEnd = vi.fn()
    fetchMock.mockRejectedValue(new Error('Failed to fetch'))
    const r = await commitMasterRow(req([
      { colId: 'name', value: 'x' },
      { colId: 'description', value: 'y' },
    ] as never), ctx({ opts: { onWriteEnd } }))
    expect(r.ok).toBe(false)
    expect(cellsOf(r).name.reason).toBe('Failed to fetch')
    expect(cellsOf(r).description.reason).toBe('Failed to fetch')
    // A write that never closes leaves the row latched — the P2-1 failure, one level up.
    // The 4th argument is the ROW the write was about (#693): the header counts rows with unsaved
    // work, and a refusal that did not name its row could never be cleared by that row succeeding.
    expect(onWriteEnd).toHaveBeenCalledWith(expect.any(String), false, 'Failed to fetch', 'p1')
  })

  /* ── `versionOf` (#701) ────────────────────────────────────────────────────────────────────
   * `currentVersion` is only the PRODUCT's when the route says so. A channel-only response carries
   * the LISTING's version, and storing that as the product's poisons the row: every later write
   * sends a version the product never had and comes back 409 "someone else changed this row".
   * Not reachable on the master sheet today — every response measured on 2026-09-02 said
   * `versionOf: "product"`, including an `attr_*` write with `marketplaceContexts`. These pin the
   * guard so it stays true when it becomes reachable. */
  it('🔴 a channelListing version is NOT taken as the product version (200)', async () => {
    fetchMock.mockResolvedValue(json(200, { errors: [], currentVersion: 99, versionOf: 'channelListing' }))
    const r = await commitMasterRow(req([{ colId: 'name', value: 'x' }] as never), ctx())
    expect(r.ok).toBe(true)
    expect(r.version).toBeUndefined() // the caller keeps the version it already held
  })

  it('🔴 a channelListing version is NOT taken as the product version (409)', async () => {
    fetchMock.mockResolvedValue(json(409, { currentVersion: 99, versionOf: 'channelListing' }))
    const r = await commitMasterRow(req([{ colId: 'name', value: 'x' }] as never), ctx())
    expect(r.conflict).toBe(true)
    expect(r.version).toBeUndefined()
  })

  it('a product version IS taken, on both branches', async () => {
    fetchMock.mockResolvedValue(json(200, { errors: [], currentVersion: 42, versionOf: 'product' }))
    expect((await commitMasterRow(req([{ colId: 'name', value: 'x' }] as never), ctx())).version).toBe(42)
    fetchMock.mockResolvedValue(json(409, { currentVersion: 43, versionOf: 'product' }))
    expect((await commitMasterRow(req([{ colId: 'name', value: 'x' }] as never), ctx())).version).toBe(43)
  })

  it('an ABSENT versionOf is treated as the product — what the route omits it for', async () => {
    fetchMock.mockResolvedValue(json(200, { errors: [], currentVersion: 7 }))
    expect((await commitMasterRow(req([{ colId: 'name', value: 'x' }] as never), ctx())).version).toBe(7)
    fetchMock.mockResolvedValue(json(409, { currentVersion: 8 }))
    expect((await commitMasterRow(req([{ colId: 'name', value: 'x' }] as never), ctx())).version).toBe(8)
  })

  it('a no-op 200 still teaches the fresh version — the measured #689 shape', async () => {
    // {updated:0, unchanged:1, expectedVersion:34, currentVersion:35, versionOf:'product'} — the
    // real body captured off the sheet at 15:07:12.
    fetchMock.mockResolvedValue(json(200, { success: true, updated: 0, unchanged: 1, expectedVersion: 34, currentVersion: 35, versionOf: 'product' }))
    const r = await commitMasterRow(req([{ colId: 'name', value: 'x' }] as never), ctx())
    expect(r.ok).toBe(true)
    expect(r.version).toBe(35)
  })

  it('opens and closes the write with the SAME id, and names the SAME row (#693)', async () => {
    const onWriteStart = vi.fn()
    const onWriteEnd = vi.fn()
    fetchMock.mockResolvedValue(json(200, { errors: [] }))
    await commitMasterRow(req([{ colId: 'name', value: 'x' }] as never), ctx({ opts: { onWriteStart, onWriteEnd } }))
    expect(onWriteStart.mock.calls[0][0]).toBe(onWriteEnd.mock.calls[0][0])
    // 🔴 The row id is passed, never parsed back out of the write id: `masterWrite` builds
    // `${rowId}:${Date.now()}`, but the channel sheet and the image workspace build theirs
    // differently, so a frame that split on ':' would be guessing at two of its three callers.
    expect(onWriteStart.mock.calls[0][1]).toBe('p1')
    expect(onWriteEnd.mock.calls[0][3]).toBe('p1')
  })

  it('surfaces a localized-route refusal with the first detail', async () => {
    fetchMock
      .mockResolvedValueOnce(json(200, { errors: [] }))
      .mockResolvedValueOnce(json(400, { details: ['description must be under 2000 characters'] }))
    const r = await commitMasterRow(req([
      { colId: 'name', value: 'x' },
      { colId: 'description', value: 'y' },
    ] as never), ctx())
    expect(cellsOf(r).name).toEqual({ ok: true })
    expect(cellsOf(r).description.reason).toBe('description must be under 2000 characters')
  })

  it('uses the returned bulk version for a subsequent localized edit', async () => {
    fetchMock.mockResolvedValueOnce(json(200, { errors: [], currentVersion: 8, versionOf: 'product' }))
      .mockResolvedValueOnce(json(200, { currentVersion: 9, versionOf: 'product' }))
    const result = await commitMasterRow(req([{ colId: 'name', value: 'x' }, { colId: 'description', value: 'y' }] as never, { expectedVersion: 7 }), ctx())
    expect(JSON.parse(fetchMock.mock.calls[1][1].body).expectedVersion).toBe(8)
    expect(result.version).toBe(9)
  })
})

describe('commitMasterRow — a PARTIAL success is reported as progress, not as a failure', () => {
  it('🔴 returns ok:true when some cells landed, while each refused cell stays refused', async () => {
    // Deliberate: `ok || anyOk`. The row DID move, so the writer must advance rather than replay —
    // but the operator must still see which cells did not land. Reporting the batch as a flat
    // failure would re-send writes the server already accepted.
    fetchMock.mockResolvedValue(json(200, { errors: [{ id: 'p1', field: 'name', error: 'Too long' }] }))
    const r = await commitMasterRow(req([
      { colId: 'name', value: 'x' },
      { colId: 'attr_colour', value: 'red' },
    ] as never), ctx())
    expect(r.ok).toBe(true)
    expect(cellsOf(r).name.ok).toBe(false)
    expect(cellsOf(r).attr_colour.ok).toBe(true)
  })

  it('returns ok:false when EVERY cell was refused', async () => {
    fetchMock.mockResolvedValue(json(200, {
      errors: [{ id: 'p1', field: 'name', error: 'Too long' }, { id: 'p1', field: 'attr_colour', error: 'Bad' }],
    }))
    const r = await commitMasterRow(req([
      { colId: 'name', value: 'x' },
      { colId: 'attr_colour', value: 'red' },
    ] as never), ctx())
    expect(r.ok).toBe(false)
  })
})

'use client'

/**
 * §14.1 — ONE toolbar for both scopes.
 *
 * 🔴 The divergence this closes is structural, not cosmetic. The master scope mounted `GridToolbar`;
 * the channel scope hand-rolled `<div className="nds-grid-prefsbar nds-channel-toolbar">` and never
 * mounted it at all. Two components for one role, so the two scopes drifted into two applications:
 * SR.1 measured 42px against 99–111px, and the channel scope had silently lost search, Overview ▾,
 * Customise, Export, Reload, the checkbox column, the filter row and the bulk bar — carrying six of
 * ten operator tasks. **A sheet's chrome is a property of the SHEET, not of the scope.**
 *
 * The rule this component enforces, and the reason it takes the props it does:
 *
 *  1. **Scope-specific controls are ADDITIONS, never replacements — and since CH.1 (Owner,
 *     2026-09-05) they are not BUTTONS either.** A scope's own verbs (the family verbs, a listing's
 *     preflight, add alias) are items of the one ⋯ overflow; `trailing` holds transient status only.
 *     The bar therefore renders the same controls, in the same order, on master and on every channel.
 *  2. **A control absent on a scope is absent for a STATED REASON.** `absent` is not documentation —
 *     it is the only way to omit anything, it is typed, and the reason is rendered as a disabled overflow item. Silence is what let the channel scope lose five controls without anyone deciding
 *     to remove them.
 *
 * Owner item 26 (two master sheets, one role) is the same shape one level up; this is the fix for
 * the toolbar half of it.
 *
 * CH.1 (Owner, 2026-09-05 — the converged sheet-chrome recommendation): five controls, one way to
 * narrow columns. The views trigger lists All attributes and the operator's saved views (pick ·
 * save · default); the second fixed set, Required, is a chip beside it; the view chips stay; Export
 * always writes the full importable file; Reload lives in the ⋯ overflow. Presets per group, quick
 * picks, "Export view" and the per-column filter row are gone by the Owner's ruling, not by omission.
 */
import { type ReactNode } from 'react'
import { AlertTriangle, MoreHorizontal, Search } from 'lucide-react'

import { Button, FilterChip, Input } from '@/design-system/primitives'
import { Menu, type MenuItemDef } from '@/design-system/components'
import { GridToolbar } from '@/design-system/patterns'
import { ALL_VIEW_ID, GridSearchSlot, GridViewsMenu, type GridStateApi, type GridViewPreset, type SavedGridView } from '@/design-system/grid'

import { viewChipIsAlarm, type ViewChip } from '../contracts'
import { viewChipColumnCountLabel, viewChipSummary } from '../viewChips'

/** A control this scope does not offer, and why. Both fields are required — that is the point. */
export interface AbsentControl {
  control: 'search' | 'views' | 'chips' | 'customise' | 'export' | 'import' | 'reload'
  /** Shown to the operator. Write what is true of the SCOPE, not of the implementation. */
  reason: string
}

/**
 * Generic over the page-state type, like `GridViewsMenu` itself. Flattening it to `unknown` here
 * would push every caller into a cast — a shared component that costs its consumers their types is
 * not shared, it is duplicated with extra steps.
 */
export interface SheetToolbarProps<TPage> {
  /* ── the count slot ─────────────────────────────────────────────────────────────────────── */
  visible: number
  total: number
  selected: number
  /** What this sheet IS — the family descriptor, or the channel coordinate. */
  descriptor?: ReactNode

  /* ── the standard controls. Every scope gets all of them unless it says otherwise. ───────── */
  search: string
  onSearch: (v: string) => void
  views?: GridStateApi<TPage>
  presets?: readonly GridViewPreset[]
  activePresetId?: string | null
  onApplyPreset?: (preset: GridViewPreset) => void
  /** The trigger's label when neither a preset nor a saved view is active ("Custom (23)"). */
  viewsEmptyLabel?: string
  /** Save / update what is on screen as a columns view; the hook supplies both (`useSheetColumns`). */
  onSaveCurrentView?: (name: string) => Promise<unknown>
  onUpdateCurrentView?: (view: SavedGridView<TPage>) => Promise<unknown>
  /** A note under a saved view — the columns it names that this product type lacks. */
  describeView?: (view: SavedGridView<TPage>) => { note?: string; title?: string } | null
  /** Already filtered by `isViewChipVisible` — `useViewChips()` does it. Do not re-filter. */
  chips?: readonly ViewChip[]
  activeChipId?: string | null
  onChipToggle?: (id: string | null) => void
  onCustomise?: () => void
  /**
   * Export requests every attribute. Shared sheets retain their editable key row; channel sheets
   * declare review-only output because resolved values do not describe stored overrides.
   */
  onExport?: (mode: 'view' | 'all') => void
  exportPurpose?: 'editing' | 'review' | 'workbook'
  exportCounts?: { view: number; all: number }
  exportDisabled?: boolean
  /** Opens the import drawer. A scope that does not offer import declares it `absent` with a reason. */
  onImport?: () => void
  importDisabled?: boolean
  onReload?: () => void
  loading?: boolean
  /** The current read failed; keep recovery available without authoring an empty layout. */
  unavailable?: boolean

  /* ── scope-specific ADDITIONS ───────────────────────────────────────────────────────────── */
  /**
   * CH.1 (Owner, 2026-09-05): the bar is the SAME on every scope — every button, in the same order.
   * A scope's own verbs (the family verbs, a listing's preflight, add alias) are ITEMS of the one ⋯
   * overflow, above Reload; they never add a button of their own.
   */
  overflow?: readonly MenuItemDef[]
  /** Transient STATUS only — a staleness pill, an export note, an in-flight acknowledgement. Never a control. */
  trailing?: ReactNode
  /** 🔴 The ONLY way to omit a standard control, and it costs a reason. */
  absent?: readonly AbsentControl[]
}

export function SheetToolbar<TPage>(p: SheetToolbarProps<TPage>) {
  const blocked = !!(p.loading || p.unavailable)
  const gone = (c: AbsentControl['control']) => p.absent?.find((a) => a.control === c)

  return (
    <GridToolbar
      count={
        blocked ? <span role="status">{p.loading ? 'Loading information…' : 'Information unavailable'}</span> : <>
          <b>{p.visible}</b> {p.visible === 1 ? 'row' : 'rows'}
          {p.visible !== p.total && <> of {p.total}</>}
          {p.selected > 0 && <> · <b>{p.selected}</b> selected</>}
          {p.descriptor}
        </>
      }
      right={
        <>
          {/*
            🔴 A hole PES.3 found as the first consumer, in exactly the guarantee this component
            exists to make. This read `{!gone('views') && p.views && p.presets && …}`, so a scope
            that simply did not pass the data lost the control **with no `absent` entry and no
            reason** — "cannot drop by omission" held only for the unconditionally rendered controls,
            which is to say it held wherever it was not needed.

            A data-driven control with no data and no `absent` entry does not vanish: it says so, in
            the bar, where the person who forgot the data will see it. Silence was the whole defect.
          */}
          {!gone('views') && (
            blocked ? <Button size="sm" disabled>All attributes</Button> : p.views && p.presets ? (
              <>
                <GridViewsMenu
                  views={p.views}
                  presets={p.presets}
                  activePresetId={p.activePresetId}
                  onApplyPreset={p.onApplyPreset ?? (() => {})}
                  emptyLabel={p.viewsEmptyLabel ?? 'View'}
                  showCounts
                  manage="minimal"
                  presetInMenu={(x) => x.id === ALL_VIEW_ID}
                  onSaveCurrent={p.onSaveCurrentView}
                  onUpdateCurrent={p.onUpdateCurrentView}
                  describeView={p.describeView}
                />
                {/* The other fixed sets — today exactly one, Required — are chips beside the trigger,
                    not items inside it: a column SET an operator toggles daily earns a control they
                    can see, and pressing it again returns to every attribute. */}
                {p.presets.filter((x) => x.id !== ALL_VIEW_ID).map((x) => {
                  const on = !p.activeChipId && p.activePresetId === x.id
                  const all = p.presets!.find((y) => y.id === ALL_VIEW_ID)
                  return (
                    <FilterChip
                      key={x.id}
                      size="md"
                      pressed={on}
                      count={`${x.columns.length} ${x.columns.length === 1 ? 'column' : 'columns'}`}
                      onClick={() => {
                        if (!on) p.onApplyPreset?.(x)
                        else if (all) p.onApplyPreset?.(all)
                      }}
                      title={x.description ?? x.label}
                    >
                      {x.label}
                    </FilterChip>
                  )
                })}
              </>
            ) : (
              <span
                className="nds-grid-toolbar-absent nds-cell-stock-out"
                title="Saved views are unavailable. Reload the information grid to try again."
              >
                Views unavailable
              </span>
            )
          )}
          {/*
            The View bar's chips. This component renders them; every lane that has data PRODUCES one
            through `useRegisterViewChip`, so a new chip appears here with no change to this file.
            Selection is single and URL-backed — two active chips would need union-or-intersection
            semantics nobody has specified.
          */}
          {!gone('chips') && (p.chips ?? []).map((chip) => {
            const on = p.activeChipId === chip.id
            const n = viewChipColumnCountLabel(chip)
            const detail = [viewChipSummary(chip), chip.count !== null ? chip.note : null].filter(Boolean).join('. ')
            return (
              /*
               * A FILTER CHIP, not a button (CT.1, 2026-09-04). This was a `Button size="sm"`
               * carrying `aria-pressed` — a toggle that filters the sheet, styled as a secondary
               * action — while the Errors & Sync facets, the same role, were a clickable Pill. One
               * role, one control, on every surface: the DS `FilterChip` at its toolbar height.
               */
              <FilterChip
                key={chip.id}
                size="md"
                disabled={blocked}
                pressed={on}
                // `null` renders no number and keeps the chip — see the ViewChip contract.
                count={n ?? undefined}
                onClick={() => p.onChipToggle?.(on ? null : chip.id)}
                title={detail}
                aria-label={`${chip.label}: ${detail}`}
                compactLabel={chip.compactLabel}
              >
                {/* The glyph follows the chip's KIND (§6.2). A warning glyph on a count of WORK is
                    a false positive, and a false positive teaches operators the alarm means nothing. */}
                {viewChipIsAlarm(chip) && <AlertTriangle size={11} />} {chip.label}
              </FilterChip>
            )
          })}
          {p.trailing}
          <div className="nds-sheet-toolbar-actions">
            {!gone('customise') && p.onCustomise && <Button size="sm" disabled={blocked} onClick={p.onCustomise}>Customise</Button>}
            {!gone('export') && p.onExport && (
              /* The scope declares whether this file carries editable values or review data. */
              <Button
                size="sm"
                onClick={() => p.onExport?.('all')}
                disabled={blocked || p.exportDisabled}
                title={
                  blocked || p.exportDisabled
                    ? 'Nothing to export until the sheet has loaded'
                    : p.exportPurpose === 'workbook' ? 'Choose products and destinations for an editing workbook'
                      : `Every attribute this scope declares${p.exportCounts ? ` (${p.exportCounts.all})` : ''} — ${p.exportPurpose === 'review' ? 'table data for review; use Catalog import & export for editing' : 'importable as-is'}`
                }
              >
                Export
              </Button>
            )}
            {/* Beside Export deliberately: they are the same idea in two directions, and an operator
                looking for one will look where the other is. */}
            {!gone('import') && p.onImport && (
              <Button size="sm" onClick={p.onImport} disabled={blocked || p.importDisabled}>Import</Button>
            )}
            {((!gone('reload') && p.onReload) || (p.overflow?.length ?? 0) > 0 || p.absent?.length) ? (
              /* The ONE overflow: the scope's own verbs first, then Reload. Reload is a recovery verb,
                 not a daily one, so it does not spend a bar slot; with no live cells in this build
                 (CH.1 row 19), Reload plus the 409 version check on write is the whole "what changed
                 elsewhere" story. */
              <Menu
                label={<MoreHorizontal size={14} aria-hidden />}
                triggerProps={{ className: 'nds-btn sm', 'aria-label': 'More' }}
                items={[
                  ...(p.absent ?? []).map(a => ({ id: `absent-${a.control}`, label: a.control === 'views' ? 'Saved views — fixed column set on this page' : `${a.control} — unavailable`, description: a.reason, disabled: true })),
                  ...(p.overflow ?? []).map(item => blocked ? { ...item, disabled: true } : item),
                  ...((p.overflow?.length ?? 0) > 0 && !gone('reload') && p.onReload
                    ? [{ id: 'sep-overflow', separator: true } as MenuItemDef]
                    : []),
                  ...(!gone('reload') && p.onReload
                    ? [
                        {
                          id: 'reload',
                          label: p.loading ? 'Loading…' : 'Reload',
                          description: 'Re-read this sheet from the server',
                          disabled: p.loading,
                          onSelect: () => p.onReload?.(),
                        } as MenuItemDef,
                      ]
                    : []),
                ]}
              />
            ) : null}
          </div>
        </>
      }
    >
      {!gone('search') && (
        <GridSearchSlot>
          <Input
            /* `xs`, not `sm`. Measured: the sm field is 36px against 28px buttons, and it was the
               single control holding the toolbar at 49 — 6 + 36 + 6 + 1. At xs it matches the
               buttons beside it and the band lands on the 40px token. */
            size="xs"
            leadingIcon={<Search size={13} />}
            placeholder="Find a SKU or a name…"
            aria-label="Find"
            value={p.search}
            disabled={blocked}
            onChange={(e) => p.onSearch(e.target.value)}
            style={{ width: '100%' }}
          />
        </GridSearchSlot>
      )}
    </GridToolbar>
  )
}

'use client'

/**
 * PES.2 — the master sheet's half of D16 cell formulas: the endpoints, and nothing else.
 *
 * The EDITOR is the engine's (`design-system/grid/editors/FormulaCellEditor`), and it deliberately
 * knows no URLs. This hook is the lane side of that seam, and the seam exists for a measured reason
 * rather than a tidy one: `POST /pim/formulas/preview` **requires `market`** and refuses without it
 * (#729), because the column key set a `$ref` may name differs per market — 40 keys on IT and 35 on
 * DE for the same product. A component that assembled its own request body would have to guess at a
 * market it cannot see, and a guess there is a plausible wrong answer, not an error.
 *
 * 🔴 It also owns the SAVE, and that is the part with teeth. A formula is stored in `CellFormula`
 * and its RESULT is written to the value layer by the server (§1.6(A)). If the sheet's ordinary
 * write path saw `="a" + $brand` it would store those characters as the cell's literal value — and
 * `overrideData` is read as a value layer by the resolver, so the formula text would publish to a
 * channel and preflight would call it valid. The interception in `onCellValueChanged` is what stops
 * that, and this is the function it hands off to.
 */
import { useCallback, useEffect, useMemo, useRef, useState } from 'react'

import { formulaSaveOutcome } from '@/design-system/grid'
import { createFormulaSaveQueue } from '@/design-system/grid/editors/formulaSaveQueue'
import type { FormulaFunctionDoc, FormulaPreviewResponse } from '@/design-system/grid'
import { getBackendUrl } from '@/lib/backend-url'

export interface CellFormulaRow {
  productId: string
  fieldKey: string
  expr: string
  /**
   * #780 — the SERVER'S OWN reason the last evaluation produced nothing, or null when it produced a
   * value. `CellFormula.lastError`, serialised by `toRow` and returned by `/pim/formulas/batch`.
   *
   * 🔴 IT WAS ON THE WIRE ALL ALONG AND THIS MIRROR DROPPED IT. Measured 2026-09-04: the server row
   * carries fifteen fields (`id scope channel marketplace locale market dependsOn lastError
   * evaluatedAt version updatedBy …`) and this interface named three, so a refused formula reached
   * the browser and was discarded at the parse boundary — which is why the refusal "rendered
   * nowhere at rest" and only the person who caused it ever saw it. Fourth instance of the wire→UI
   * mirror drift in this programme (#770 counted three). Widened only by what is consumed; the rest
   * stays unmirrored deliberately, and that is a choice rather than an oversight now.
   */
  lastError?: string | null
}

export interface UseCellFormulasInput {
  writeFacts?: (rowId: string, fieldKey: string) => import('@nexus/shared/content-language').ContentWriteFacts | undefined
  channelConnectionId?: string | null
  aliasKey?: string | null
  /** The family's parent — the id in the URL, used for the family-wide read. */
  productId: string
  /**
   * 🔴 The full COORDINATE, not just a market (#775). A formula is stored per
   * `scope · channel · marketplace · locale · market`, and the channel sheets need every part —
   * `cell-formula.routes.ts:52` has taken them all along. Master passes `scope: 'master'` and leaves
   * the channel pair undefined; a channel scope passes all five.
   *
   * This hook moved out of `sheet/master/` for that reason: master and the channel scopes must share
   * ONE seam or they drift the first time either fixes a parse. The engine cannot own it — it knows
   * URLs, and the editor deliberately knows none — so it lives here, above both sheets.
   */
  scope?: 'master' | 'channel'
  channel?: string | null
  marketplace?: string | null
  market: string
  locale: string
  /** Every row on the sheet, so one batch read covers the family. */
  rowIds: readonly string[]
  rowScopes?: Readonly<Record<string, { productId: string; aliasKey: string }>>
  onSettled?: () => void
  onValueSaved?: (rowId: string, fieldKey: string, value: unknown) => void
}

export interface CellFormulas {
  ready: boolean
  loadError: string | null
  sourceLabel: string
  replace: (rowId: string, fieldKey: string, value: unknown) => Promise<{ ok: boolean; error?: string }>

  /** `rowId` + `fieldKey` → the stored expression, so editing a formula cell opens the formula. */
  exprFor: (rowId: string, fieldKey: string) => string | null
  /**
   * #780 — `rowId` + `fieldKey` → the SERVER'S reason the formula produced nothing, or `null`.
   * The sheet renders this verbatim as the refused cell's tooltip; it is never composed with, and
   * never prefixed by, anything the client writes.
   */
  errorFor: (rowId: string, fieldKey: string) => string | null
  /** The language's functions, for the signature hint. Empty until loaded — never invented. */
  functions: FormulaFunctionDoc[]
  preview: (rowId: string, fieldKey: string, expr: string, signal?: AbortSignal) => Promise<FormulaPreviewResponse>
  save: (rowId: string, fieldKey: string, expr: string) => Promise<{ ok: boolean; error?: string }>
  /** Drop a formula, keeping the value it last produced. The audit row keeps it restorable. */
  pinOver: (rowId: string, fieldKey: string) => Promise<{ ok: boolean; error?: string }>
  reload: () => void
}

/* `::`, not a raw NUL. A separator has to be one that neither half can contain, or two different
   cells collide on one key — a product id is a cuid and a column key is `[A-Za-z0-9_.]`, so `::`
   cannot appear in either and the key stays unambiguous.

   🔴 It was a literal NUL byte, and that made the whole FILE binary to every text tool: `file(1)`
   reported `data`, BSD grep answered "Binary file matches", and the grep wrapper here returns a
   BLANK count — which reads as zero. So every grep-based DS guard was silently scanning nothing
   here while reporting clean. I met the symptom myself and missed it: two greps on this file came
   back empty and I worked around them with a direct read instead of asking why. A quiet instrument
   is not a negative result, and that time the quiet instrument was mine. */
const key = (rowId: string, fieldKey: string) => `${rowId}::${fieldKey}`

export function useCellFormulas({ productId, scope = 'master', channel = null, marketplace = null, market, locale, channelConnectionId, aliasKey, rowIds, rowScopes, writeFacts, onSettled, onValueSaved }: UseCellFormulasInput): CellFormulas {
  const coord = useMemo(() => ({ scope, channel, marketplace, market, locale, channelConnectionId, aliasKey }), [scope, channel, marketplace, market, locale, channelConnectionId, aliasKey])
  const rowScopeKey = JSON.stringify(rowScopes ?? {})
  const scopes = useMemo(() => JSON.parse(rowScopeKey) as NonNullable<UseCellFormulasInput['rowScopes']>, [rowScopeKey])
  const target = useCallback((rowId: string) => {
    if (rowScopes && !scopes[rowId]) throw new Error('This listing is no longer in the selected destination. Reload before editing.')
    return { ...coord, productId: scopes[rowId]?.productId ?? rowId, aliasKey: scopes[rowId]?.aliasKey ?? coord.aliasKey }
  }, [coord, scopes, !!rowScopes])
  const coordinateKey = JSON.stringify([coord, rowScopeKey])
  const idsKey = rowIds.join(',')
  const snapshotKey = JSON.stringify([coordinateKey, idsKey])
  const [snapshot, setSnapshot] = useState<{ key: string; formulas: Map<string, CellFormulaRow> }>({ key: '', formulas: new Map() })
  const [loadError, setLoadError] = useState<string | null>(null)
  const [functions, setFunctions] = useState<FormulaFunctionDoc[]>([])
  const [nonce, setNonce] = useState(0)
  const live = useRef({ coordinateKey, writeFacts, onSettled, onValueSaved })
  live.current = { coordinateKey, writeFacts, onSettled, onValueSaved }
  const revision = useRef(0)
  const queue = useMemo(() => createFormulaSaveQueue(() => {
    if (live.current.coordinateKey !== coordinateKey) return
    setNonce(n => n + 1)
    live.current.onSettled?.()
  }), [coordinateKey])
  useEffect(() => { queue.activate(); return () => queue.dispose() }, [queue])
  const reload = useCallback(() => setNonce(n => n + 1), [])

  useEffect(() => {
    const controller = new AbortController()
    fetch(`${getBackendUrl()}/api/pim/formulas/functions`, { credentials: 'include', signal: controller.signal })
      .then(r => r.ok ? r.json() : null).then(j => { if (Array.isArray(j?.functions)) setFunctions(j.functions) }).catch(() => {})
    return () => controller.abort()
  }, [])

  useEffect(() => {
    const controller = new AbortController()
    const mine = revision.current
    setLoadError(null)
    const ids = idsKey ? idsKey.split(',') : []
    const read = async () => {
      const next = new Map<string, CellFormulaRow>()
      const groups = new Map<string, string[]>()
      for (const id of ids) {
        const alias = scopes[id]?.aliasKey ?? coord.aliasKey ?? ''
        groups.set(alias, [...(groups.get(alias) ?? []), id])
      }
      for (const [listingAlias, group] of groups) {
      for (let start = 0; start < group.length; start += 250) {
        const batch = group.slice(start, start + 250)
        const rowByProduct = new Map(batch.map(id => [scopes[id]?.productId ?? id, id]))
        const response = await fetch(`${getBackendUrl()}/api/pim/formulas/batch`, {
          method: 'POST', credentials: 'include', signal: controller.signal,
          headers: { 'content-type': 'application/json' }, body: JSON.stringify({ ...coord, aliasKey: listingAlias, productIds: [...rowByProduct.keys()] }),
        })
        if (!response.ok) throw new Error('Could not load formulas. Retry before editing formula fields.')
        const body = await response.json()
        if (!body.formulas || typeof body.formulas !== 'object') throw new Error('The formula list could not be read. Retry before editing.')
        const add = (f: CellFormulaRow) => { if (f && typeof f.expr === 'string') next.set(key(rowByProduct.get(f.productId) ?? f.productId, f.fieldKey), f) }
        if (Array.isArray(body.formulas)) body.formulas.forEach(add)
        else for (const [pid, fields] of Object.entries(body.formulas)) {
          for (const [fieldKey, f] of Object.entries(fields as Record<string, CellFormulaRow>)) add({ ...f, productId: pid, fieldKey })
        }
      }
      }
      if (!controller.signal.aborted && mine === revision.current) setSnapshot({ key: snapshotKey, formulas: next })
    }
    read().catch(error => { if (!controller.signal.aborted) setLoadError(error instanceof Error ? error.message : String(error)) })
    return () => controller.abort()
  }, [idsKey, nonce, coord, scopes, snapshotKey])

  const ready = snapshot.key === snapshotKey && !loadError
  const exprFor = useCallback((rowId: string, fieldKey: string) => snapshot.key === snapshotKey ? snapshot.formulas.get(key(rowId, fieldKey))?.expr ?? null : null, [snapshot, snapshotKey])
  const errorFor = useCallback((rowId: string, fieldKey: string) => snapshot.key === snapshotKey ? snapshot.formulas.get(key(rowId, fieldKey))?.lastError ?? null : null, [snapshot, snapshotKey])
  const preview = useCallback(async (rowId: string, fieldKey: string, expr: string, signal?: AbortSignal): Promise<FormulaPreviewResponse> => {
    const res = await fetch(`${getBackendUrl()}/api/pim/formulas/preview`, { method: 'POST', credentials: 'include', signal,
      headers: { 'content-type': 'application/json' }, body: JSON.stringify({ ...target(rowId), fieldKey, expr }) })
    const body = await res.json()
    return res.ok ? body : { ok: false, error: body?.error ?? 'Could not check the formula.' }
  }, [target])

  const commit = useCallback((rowId: string, fieldKey: string, change: { expr: string } | { value: unknown }) => queue.enqueue(rowId, async () => {
    const destination = target(rowId)
    const literal = 'value' in change
    const res = await fetch(`${getBackendUrl()}/api/pim/formulas/product/${encodeURIComponent(destination.productId)}${literal ? '/value' : ''}`, {
      method: 'PUT', credentials: 'include', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ ...destination, fieldKey, ...change, contentAddress: live.current.writeFacts?.(rowId, fieldKey)?.contentAddress, contentAcknowledged: live.current.writeFacts?.(rowId, fieldKey)?.contentAcknowledged }),
    })
    const body = await res.json()
    if (!res.ok) return { ok: false, error: body?.error ?? 'Could not save this field.' }
    revision.current += 1
    if (live.current.coordinateKey === coordinateKey) setSnapshot(previous => {
      if (previous.key !== snapshotKey) return previous
      const formulas = new Map(previous.formulas)
      if (literal) formulas.delete(key(rowId, fieldKey))
      else if (body.formula) formulas.set(key(rowId, fieldKey), body.formula)
      return { ...previous, formulas }
    })
    const result = literal ? { ok: true } : formulaSaveOutcome(body)
    if (result.ok && live.current.coordinateKey === coordinateKey) live.current.onValueSaved?.(rowId, fieldKey, body.value)
    return result
  }), [queue, target, coordinateKey, snapshotKey])
  const save = useCallback((rowId: string, fieldKey: string, expr: string) => commit(rowId, fieldKey, { expr }), [commit])
  const replace = useCallback((rowId: string, fieldKey: string, value: unknown) => commit(rowId, fieldKey, { value }), [commit])
  const pinOver = useCallback((rowId: string, fieldKey: string) => queue.enqueue(rowId, async () => {
    const { productId: canonicalId, ...destination } = target(rowId)
    const q = new URLSearchParams({ fieldKey })
    for (const [name, value] of Object.entries(destination)) if (value != null) q.set(name, value)
    const res = await fetch(`${getBackendUrl()}/api/pim/formulas/product/${encodeURIComponent(canonicalId)}?${q}`, { method: 'DELETE', credentials: 'include' })
    const body = await res.json()
    return res.ok ? { ok: true } : { ok: false, error: body?.error ?? 'Could not remove the formula.' }
  }), [queue, target])
  void productId
  return { ready, loadError, sourceLabel: scope === 'channel' ? `${channel} · ${marketplace} · ${locale}` : `Shared product · ${locale}`,
    exprFor, errorFor, functions, preview, save, replace, pinOver, reload }
}

'use client'

import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { Button, Select, SegmentedControl } from '@/design-system/primitives'
import { Modal } from '@/design-system/components'
import { DataGrid } from '@/design-system/grid/datagrid'
import { FormulaComposer, type FormulaCandidate, type FormulaFunctionDoc, type FormulaPreviewResponse } from '@/design-system/grid'
import { getBackendUrl } from '@/lib/backend-url'
import { formulaOperationRequest as request, operationPending, mergeFormulaOperation, operationLabel, type FormulaOperation } from './formulaOperations'
import styles from './formulaBulk.module.css'

type PreviewRow = { productId: string; ok: boolean; before?: unknown; value?: unknown; expectedState?: string; error?: string; applied?: boolean; unknown?: boolean; undone?: boolean }
const products = (count: number) => `${count} ${count === 1 ? 'product' : 'products'}`
const display = (value: unknown) => value == null || value === '' ? 'Empty' : typeof value === 'object' ? JSON.stringify(value) : String(value)

export function FormulaBulkDialog({ rows, columns, coordinate, candidatesFor, functions, preview, onClose, onApplied }: {
  rows: Array<{ id: string; label: string }>
  columns: Array<{ key: string; label: string; kind?: string; editable?: boolean; formulaWritable?: boolean; writeTarget?: string }>
  coordinate: { scope: 'master' | 'channel'; market: string; locale: string; channel?: string; marketplace?: string; channelConnectionId?: string; aliasKey?: string }
  candidatesFor: (rowId: string) => FormulaCandidate[]; functions: FormulaFunctionDoc[]
  preview: (rowId: string, fieldKey: string, expr: string, signal?: AbortSignal) => Promise<FormulaPreviewResponse>
  onClose: () => void; onApplied: () => void
}) {
  const fields = useMemo(() => columns.filter(c => c.editable !== false && c.formulaWritable !== false), [columns])
  const [fieldKey, setFieldKey] = useState(fields.find(c => c.key === 'manufacturer')?.key ?? fields.find(c => c.key === 'name')?.key ?? fields[0]?.key ?? '')
  const [text, setText] = useState('=')
  const [mode, setMode] = useState<'once' | 'linked'>('once')
  const [results, setResults] = useState<PreviewRow[]>([])
  const [busy, setBusy] = useState(false)
  const [progress, setProgress] = useState('')
  const [error, setError] = useState<string | null>(null)
  const [operation, setOperation] = useState<FormulaOperation | null>(null)
  const retryInput = useRef<Record<string, unknown> | null>(null)
  const mounted = useRef(true)
  useEffect(() => { mounted.current = true; return () => { mounted.current = false } }, [])
  const [applied, setApplied] = useState(false)
  const working = useRef(false)
  const labels = useMemo(() => new Map(rows.map(row => [row.id, row.label])), [rows])
  const field = fields.find(c => c.key === fieldKey)
  const sample = rows[0]?.id ?? ''
  const samplePreview = useCallback(async (expr: string, signal?: AbortSignal): Promise<FormulaPreviewResponse> => {
    if (mode === 'linked') return preview(sample, fieldKey, expr, signal)
    const response = await fetch(`${getBackendUrl()}/api/pim/formulas/bulk/preview`, {
      method: 'POST', credentials: 'include', signal, headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ ...coordinate, fieldKey, expr, mode, rows: [{ productId: sample }] }),
    })
    const body = await response.json()
    return response.ok ? body.rows[0] : { ok: false, error: body.error ?? 'Could not check this formula.' }
  }, [preview, sample, fieldKey, mode, coordinate.scope, coordinate.channel, coordinate.marketplace, coordinate.market, coordinate.locale, coordinate.channelConnectionId, coordinate.aliasKey])
  const invalidate = () => { setResults([]); setError(null); setApplied(false); setProgress('') }
  const accept = (response: FormulaOperation) => {
    if (!mounted.current) return
    setOperation(current => mergeFormulaOperation(current, response))
    setResults(current => current.map(row => {
      const result = response.rows.find(result => result.productId === row.productId)
      return result ? { ...row, ...result, applied: result.status === 'applied', undone: result.status === 'restored', unknown: false } : row
    }))
    setProgress(`${operationLabel(response.status)} · ${response.processed} of ${products(response.total)} checked.`)
  }
  const advance = async (first: FormulaOperation) => {
    let response = first
    accept(response)
    while (mounted.current && operationPending(response)) {
      response = await request(`${response.operationId}/continue`)
      accept(response)
    }
    if (mounted.current) accept(await request(response.operationId, undefined, 'GET'))
  }
  const run = async (action: 'preview' | 'apply') => {
    if (working.current) return
    working.current = true; setBusy(true); setError(null)
    try {
      if (action === 'preview') {
        const next: PreviewRow[] = []
        for (let start = 0; start < rows.length && mounted.current; start += 20) {
          setProgress(`Checking ${start + 1}–${Math.min(start + 20, rows.length)} of ${products(rows.length)}…`)
          const response = await request<{ rows: PreviewRow[] }>('preview', { ...coordinate, fieldKey, expr: text, mode,
            rows: rows.slice(start, start + 20).map(row => ({ productId: row.id })) })
          next.push(...response.rows)
          if (mounted.current) setResults([...next])
        }
        if (mounted.current) setProgress(`${next.filter(row => row.ok).length} of ${products(rows.length)} ready.`)
      } else {
        setApplied(true)
        const input = retryInput.current ?? { operationId: crypto.randomUUID(), ...coordinate, fieldKey, expr: text, mode,
          rows: results.filter(row => row.ok).map(row => ({ productId: row.productId, label: labels.get(row.productId), expectedState: row.expectedState, expectedValue: row.value })) }
        retryInput.current = input
        await advance(await request('apply', input))
        retryInput.current = null
      }
    } catch (e) {
      if (mounted.current) setError(action === 'apply' ? `Connection interrupted. Use Check and continue to recover the saved progress. ${e instanceof Error ? e.message : String(e)}` : e instanceof Error ? e.message : String(e))
    } finally { working.current = false; if (mounted.current) { setBusy(false); if (action === 'apply') onApplied() } }
  }
  const resume = async (undo = false) => {
    if (working.current) return
    if (!operation) { void run('apply'); return }
    working.current = true; setBusy(true); setError(null)
    try {
      await advance(await request(`${operation.operationId}/${undo ? 'undo' : 'continue'}`))
      retryInput.current = null
    } catch (e) { if (mounted.current) setError(`Connection interrupted. Check and continue is safe to retry. ${e instanceof Error ? e.message : String(e)}`) }
    finally { working.current = false; if (mounted.current) { setBusy(false); onApplied() } }
  }
  const valid = results.filter(row => row.ok && !row.undone).length
  return <Modal open readable onClose={onClose} title={`Apply a formula · ${rows.length} ${rows.length === 1 ? 'product' : 'products'}`} size="xl"
    subtitle="Preview changes. Resume and undo later in More → Formula history."
    footer={<>
      {operation && ['APPLYING', 'SUCCESS', 'PARTIAL'].includes(operation.status) && <Button disabled={busy} onClick={() => void resume(true)}>Undo applied changes</Button>}
      {applied && (retryInput.current || (operation && operationPending(operation))) && <Button disabled={busy} onClick={() => void resume()}>Check and continue</Button>}
      <Button onClick={onClose}>Close</Button>
      <Button disabled={busy || applied || !fieldKey || text.trim() === '='} onClick={() => void run('preview')}>Preview products</Button>
      <Button variant="primary" disabled={busy || !valid || applied || results.length !== rows.length} onClick={() => void run('apply')}>Apply to {products(valid)}</Button>
    </>}>
    <div className={styles.content}>
      <label className={styles.field}>Field to update<Select value={fieldKey} disabled={busy || applied} onChange={event => { setFieldKey(event.target.value); invalidate() }}>
        {fields.map(column => <option key={column.key} value={column.key}>{column.label}</option>)}
      </Select></label>
      {coordinate.scope === 'channel' && field?.writeTarget === 'master' && <p>This is a shared product field. Changes appear across channels.</p>}
      <SegmentedControl wrap ariaLabel="How to apply the formula" value={mode} disabled={busy || applied} onChange={value => { setMode(value as 'once' | 'linked'); invalidate() }}
        options={[{ value: 'once', label: 'Apply values once' }, { value: 'linked', label: 'Keep linked with formulas' }]} />
      <p>{mode === 'once' ? 'Replaces these cells with calculated values. Existing formulas are removed.' : 'Stores a formula in each cell. Values follow changes to its source fields.'}</p>
      <FormulaComposer showModeHelp={false} text={text} onChange={value => { setText(value.startsWith('=') ? value : `=${value}`); invalidate() }}
        candidates={candidatesFor(sample).filter(candidate => mode === 'once' || candidate.kind !== 'field' || candidate.name !== fieldKey)}
        functions={functions} preview={samplePreview} linked={mode === 'linked'} disabled={busy || applied} allowText={field?.kind !== 'number'}
        sourceLabel={coordinate.scope === 'channel' ? `${coordinate.channel} · ${coordinate.marketplace} · ${coordinate.locale}` : `Shared product · ${coordinate.locale}`} />
      {rows.length > 1 && <p className={styles.note}>The result above previews {labels.get(sample)}. Preview products checks every selected row.</p>}
      <div role="status" aria-live="polite">{progress}</div>
      {error && <p role="alert" className={styles.error}>{error}</p>}
      {results.length > 0 && <DataGrid keyboardScroll ariaLabel="Formula changes" rows={results} rowKey={row => row.productId}
        columns={[
          { key: 'product', label: 'Product', width: 200, render: row => <span className={styles.cell}>{labels.get(row.productId)}</span> },
          { key: 'before', label: 'Before', width: 250, render: row => <span className={styles.cell}>{display(row.before)}</span> },
          { key: 'after', label: 'After', width: 250, render: row => <span className={styles.cell}>{row.undone ? display(row.before) : row.unknown ? 'Check result' : row.error ? 'Previous value kept' : display(row.value)}</span> },
          { key: 'status', label: 'Status', width: 150, render: row => <span className={styles.cell}>{row.undone ? 'Restored' : row.error ?? (row.applied ? 'Applied' : applied ? 'Not applied' : 'Ready')}</span> },
        ]} />}
    </div>
  </Modal>
}

/**
 * PES.8 — the studio's calls to the enrichment API.
 *
 * Three endpoints, and the split between them is the permission model, not tidiness: reading and
 * deciding drafts sits under `/api/products/...` (products:view / products:edit), while generation
 * sits under `/api/ai/...` (ai:run). This file deliberately does NOT expose generate — under hub
 * ruling #13 the Owner has held live generation, and a UI that cannot call it is a stronger
 * guarantee than a UI that chooses not to.
 *
 * ⚠ Local dev hits the PROD API unless NEXT_PUBLIC_API_URL is set. Approving a draft here writes a
 * real catalogue value (reference_local_dev_hits_prod_api).
 */
import { getBackendUrl } from '@/lib/backend-url'

import type { AiDraftsResponse, ApproveResponse } from './types'

export interface LoadDraftsQuery {
  productIds: string[]
  /** `null` = the master scope; a channel key otherwise. */
  channel: string | null
  marketplace: string | null
  /**
   * The locale on screen. Absent/null returns only the master's own values — a translation draft
   * for another language must never tint the cell the operator is looking at.
   */
  locale?: string | null
}

async function readError(res: Response): Promise<string> {
  try {
    const body = (await res.json()) as { error?: string; message?: string }
    return body.error ?? body.message ?? `${res.status} ${res.statusText}`
  } catch {
    return `${res.status} ${res.statusText}`
  }
}

/**
 * Pending + failed drafts for the products on screen.
 *
 * `master` is sent as the literal string for the master scope, because an ABSENT channel means
 * "any scope" to the endpoint while a null one means "the master scope" — two different questions
 * that a bare empty parameter cannot tell apart.
 */
export async function loadDrafts(q: LoadDraftsQuery, signal?: AbortSignal): Promise<AiDraftsResponse> {
  if (q.productIds.length === 0) {
    return { drafts: [], counts: { total: 0, pending: 0, failed: 0, stale: 0 } }
  }
  const params = new URLSearchParams({
    productIds: q.productIds.join(','),
    status: 'pending,failed',
  })
  params.set('channel', q.channel ?? 'master')
  if (q.locale) params.set('locale', q.locale)
  if (q.channel !== null && q.marketplace) params.set('marketplace', q.marketplace)
  else if (q.channel === null) params.set('marketplace', 'master')

  const res = await fetch(`${getBackendUrl()}/api/products/ai/drafts?${params.toString()}`, {
    credentials: 'include',
    signal,
  })
  if (!res.ok) throw new Error(await readError(res))
  return (await res.json()) as AiDraftsResponse
}

/**
 * Approve drafts. Each one is replayed by the server through `PATCH /api/products/bulk`, so it
 * meets the same validation, the same version conflict and the same audit trail as a typed edit.
 *
 * `allowStale` is passed explicitly, per call, and defaults to false. It means "I have seen the
 * value that is there now and I still want mine" — so the surface must only ever send it from a
 * control that showed the operator that value.
 */
export async function approveDrafts(
  draftIds: string[],
  opts: { allowStale?: boolean } = {},
): Promise<ApproveResponse> {
  const res = await fetch(`${getBackendUrl()}/api/products/ai/drafts/approve`, {
    method: 'POST',
    credentials: 'include',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ draftIds, allowStale: opts.allowStale === true }),
  })
  if (!res.ok) throw new Error(await readError(res))
  return (await res.json()) as ApproveResponse
}

export async function rejectDrafts(draftIds: string[]): Promise<{ rejected: number }> {
  const res = await fetch(`${getBackendUrl()}/api/products/ai/drafts/reject`, {
    method: 'POST',
    credentials: 'include',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ draftIds }),
  })
  if (!res.ok) throw new Error(await readError(res))
  return (await res.json()) as { rejected: number }
}

'use client'

/**
 * PES.8 — the drafts a scope currently carries, and the two decisions an operator can make.
 *
 * One fetch per (scope, product set). The hook holds no optimistic state: an approve replays through
 * `PATCH /api/products/bulk` on the server and can be refused there — by a version conflict, by a
 * validator, by staleness — so the only honest thing to draw afterwards is what the server says on
 * the next read. Painting a cell approved and then taking it back is the shape of dishonesty the
 * 100%-honest-UI rule exists to stop.
 */
import { useCallback, useEffect, useMemo, useRef, useState } from 'react'

import { approveDrafts as approveApi, loadDrafts, rejectDrafts as rejectApi } from './api'
import {
  groupByColumn,
  indexDrafts,
  provenanceFor,
  type AiProvenance,
  type CellRef,
  type DraftColumnGroup,
} from './drafts'
import type { AiDraft, ApproveResponse } from './types'

export interface UseAiDraftsInput {
  /** The rows on screen. An empty list skips the fetch entirely. */
  productIds: string[]
  /** `null` = master scope. */
  channel: string | null
  marketplace: string | null
  /** The locale on screen. Absent = the master's own values only. */
  locale?: string | null
}

export interface UseAiDraftsValue {
  drafts: AiDraft[]
  groups: DraftColumnGroup[]
  counts: { total: number; pending: number; failed: number; stale: number }
  loading: boolean
  error: string | null
  /** Busy while a decision is in flight — the review surface disables its controls on this. */
  deciding: boolean
  /**
   * The AI half of PES.2's `ProvenanceLike` for one cell, or `null` when nothing is drafted there.
   * This is the whole of this lane's contribution to how a cell is drawn; wire it into the sheet's
   * column factory when PES.2's overlay hook lands (2.6).
   */
  provenanceFor(ref: CellRef): AiProvenance | null
  approve(draftIds: string[], opts?: { allowStale?: boolean }): Promise<ApproveResponse>
  reject(draftIds: string[]): Promise<{ rejected: number }>
  refresh(): void
}

const EMPTY_COUNTS = { total: 0, pending: 0, failed: 0, stale: 0 }

export function useAiDrafts(input: UseAiDraftsInput): UseAiDraftsValue {
  const { productIds, channel, marketplace, locale } = input
  const [drafts, setDrafts] = useState<AiDraft[]>([])
  const [counts, setCounts] = useState(EMPTY_COUNTS)
  const [loading, setLoading] = useState(false)
  const [deciding, setDeciding] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [nonce, setNonce] = useState(0)

  // A stable identity for the row set — a new array of the same ids must not refetch, or the hook
  // re-runs on every parent render for the life of the page.
  const idsKey = useMemo(() => [...productIds].sort().join(','), [productIds])

  const abortRef = useRef<AbortController | null>(null)

  useEffect(() => {
    const ids = idsKey ? idsKey.split(',') : []
    if (ids.length === 0) {
      setDrafts([])
      setCounts(EMPTY_COUNTS)
      setError(null)
      return
    }
    abortRef.current?.abort()
    const ac = new AbortController()
    abortRef.current = ac
    setLoading(true)
    loadDrafts({ productIds: ids, channel, marketplace, locale }, ac.signal)
      .then((res) => {
        if (ac.signal.aborted) return
        setDrafts(res.drafts)
        setCounts(res.counts)
        setError(null)
      })
      .catch((err: unknown) => {
        if (ac.signal.aborted) return
        // A drafts failure must not read as "no drafts" — an empty review list and a broken fetch
        // look identical, and only one of them means there is nothing to approve.
        setDrafts([])
        setCounts(EMPTY_COUNTS)
        setError(err instanceof Error ? err.message : String(err))
      })
      .finally(() => {
        if (!ac.signal.aborted) setLoading(false)
      })
    return () => ac.abort()
  }, [idsKey, channel, marketplace, locale, nonce])

  const refresh = useCallback(() => setNonce((n) => n + 1), [])

  const index = useMemo(() => indexDrafts(drafts), [drafts])
  const groups = useMemo(() => groupByColumn(drafts), [drafts])

  const provFor = useCallback((ref: CellRef) => provenanceFor(index, ref), [index])

  const approve = useCallback(
    async (draftIds: string[], opts: { allowStale?: boolean } = {}) => {
      setDeciding(true)
      try {
        const res = await approveApi(draftIds, opts)
        return res
      } finally {
        setDeciding(false)
        // Refetch whatever the outcome: a partial approval leaves some drafts pending with an
        // error on them, and that is exactly the state the operator needs to see next.
        refresh()
      }
    },
    [refresh],
  )

  const reject = useCallback(
    async (draftIds: string[]) => {
      setDeciding(true)
      try {
        return await rejectApi(draftIds)
      } finally {
        setDeciding(false)
        refresh()
      }
    },
    [refresh],
  )

  return {
    drafts,
    groups,
    counts,
    loading,
    error,
    deciding,
    provenanceFor: provFor,
    approve,
    reject,
    refresh,
  }
}

/**
 * PES.8 — the pure half of the review surface: indexing, grouping, and the display of a value.
 *
 * Kept free of React and of `fetch` so the rules that matter can be tested without a server: which
 * drafts a column offers, which of them an "approve column" would actually send, and how a value
 * that is a list renders beside one that is a string.
 */
import type { AiDraft, AiDraftViolation } from './types'

/** How the sheet addresses a cell: the row is a product, the column is the sheet column key. */
export interface CellRef {
  rowId: string
  colId: string
}

/**
 * PES.2's `ProvenanceLike` fields for one cell. The classifier reads only these two; supplying
 * them is this lane's whole contribution to how a drafted cell is drawn.
 */
export interface AiProvenance {
  aiDrafted: boolean
  aiStale: boolean
}

/**
 * `productId` + `columnKey` — the key the sheet can ask by.
 *
 * The separator is NUL, written as an ESCAPE and never as a literal byte. NUL is the right
 * separator — a product id or a column key can contain a space or a colon, neither can contain
 * NUL, so the key cannot collide — but a raw 0x00 in the source made this whole file read as
 * `data` to `file(1)`, so a plain `grep` found nothing in it and the exported types looked absent.
 * PES.2 nearly concluded the contract did not exist. Same value at runtime, plain text on disk.
 */
export function cellIndexKey(rowId: string, colId: string): string {
  return `${rowId}\u0000${colId}`
}

/**
 * Index the pending drafts by (product, column).
 *
 * `failed` drafts are indexed too but never marked drafted on the grid: the model broke a hard cap,
 * so there is no value to show in the cell. They surface in the review list, where the violation
 * can be read, rather than tinting a cell with something nobody can approve.
 */
export function indexDrafts(drafts: AiDraft[]): Map<string, AiDraft> {
  const out = new Map<string, AiDraft>()
  for (const d of drafts) {
    // One pending draft per cell is a server invariant (recordDrafts supersedes), but the client
    // must not fall over if it ever sees two — newest wins, deterministically.
    const key = cellIndexKey(d.productId, d.columnKey)
    const prev = out.get(key)
    if (!prev || d.createdAt > prev.createdAt) out.set(key, d)
  }
  return out
}

/**
 * The provenance a cell should carry. `null` when nothing is drafted there, so the caller can leave
 * the cell's existing provenance untouched rather than overwriting it with a negative.
 */
export function provenanceFor(index: Map<string, AiDraft>, ref: CellRef): AiProvenance | null {
  const d = index.get(cellIndexKey(ref.rowId, ref.colId))
  if (!d) return null
  // A failed draft is not a drafted VALUE — there is nothing in the cell to approve.
  if (d.status !== 'pending') return null
  return { aiDrafted: true, aiStale: d.stale || d.unverified }
}

/**
 * The shape PES.2's cell renderer takes (`BuildColumnsOptions['draftFor']`). Narrower than our own
 * `AiDraft` on purpose: the cell needs the proposal, the value it would replace, the two warning
 * states and the reasons — nothing else.
 */
export interface SheetAiDraft {
  draftValue: unknown
  baseValue?: unknown
  stale?: boolean
  unverified?: boolean
  violations?: string[]
}

/**
 * Project a draft onto the cell renderer's shape, or `null` when it must not reach a cell.
 *
 * 🔴 A failed draft returns null. The cell shows a proposal an operator can act on; a draft that
 * broke a hard cap is not one, because the server refuses to apply it. It stays in the review
 * list, where the cap it broke can actually be read.
 */
export function toSheetDraft(d: AiDraft): SheetAiDraft | null {
  if (d.status !== 'pending') return null
  return {
    draftValue: d.draftValue,
    baseValue: d.baseValue,
    stale: d.stale,
    unverified: d.unverified,
    violations: (d.violations ?? []).map((v) => v.message),
  }
}

/** A draft an operator can act on right now, without waiving anything. */
export function isCleanlyApprovable(d: AiDraft): boolean {
  return d.status === 'pending' && !d.stale && !d.unverified
}

/**
 * Drafts grouped by column, which is how the review reads: an operator judging thirty titles
 * judges them against each other, not against thirty unrelated fields.
 */
export interface DraftColumnGroup {
  columnKey: string
  writeField: string
  drafts: AiDraft[]
  /** Approvable without waiving staleness — what "approve column" would send. */
  approvable: AiDraft[]
  staleCount: number
  failedCount: number
  unverifiedCount: number
  /** The tightest cap any draft in this column was written against, for the header. */
  caps: { maxLength?: number | null; maxBytes?: number | null; capFrom?: string | null } | null
}

export function groupByColumn(drafts: AiDraft[]): DraftColumnGroup[] {
  const byCol = new Map<string, AiDraft[]>()
  for (const d of drafts) {
    const list = byCol.get(d.columnKey) ?? []
    list.push(d)
    byCol.set(d.columnKey, list)
  }
  const groups: DraftColumnGroup[] = []
  for (const [columnKey, list] of byCol) {
    const sorted = [...list].sort((a, b) => a.productId.localeCompare(b.productId))
    const withCaps = sorted.find((d) => d.capsUsed && (d.capsUsed.maxLength || d.capsUsed.maxBytes))
    groups.push({
      columnKey,
      writeField: sorted[0].writeField,
      drafts: sorted,
      approvable: sorted.filter(isCleanlyApprovable),
      staleCount: sorted.filter((d) => d.status === 'pending' && d.stale).length,
      failedCount: sorted.filter((d) => d.status === 'failed').length,
      unverifiedCount: sorted.filter((d) => d.unverified).length,
      caps: withCaps?.capsUsed
        ? {
            maxLength: withCaps.capsUsed.maxLength,
            maxBytes: withCaps.capsUsed.maxBytes,
            capFrom: withCaps.capsUsed.capFrom,
          }
        : null,
    })
  }
  return groups.sort((a, b) => a.columnKey.localeCompare(b.columnKey))
}

/**
 * Render a cell value for the diff.
 *
 * A list is shown one member per line because that is how a bullet set is read and how an operator
 * spots the one bullet that is wrong. Never truncated: this is the review, and a value the operator
 * cannot see in full is a value they cannot judge.
 */
export function displayValue(v: unknown): string {
  if (v == null) return ''
  if (Array.isArray(v)) return v.map((x) => (x == null ? '' : String(x))).join('\n')
  if (typeof v === 'object') return JSON.stringify(v, null, 2)
  return String(v)
}

/** True when the two sides of the diff are the same text — nothing to review. */
export function isNoOpDiff(d: AiDraft): boolean {
  return displayValue(d.draftValue) === displayValue(d.baseValue)
}

/** Errors block the offer; warnings ride along and are shown beside the value. */
export function splitViolations(v: AiDraftViolation[] | null): {
  errors: AiDraftViolation[]
  warnings: AiDraftViolation[]
} {
  const all = v ?? []
  return {
    errors: all.filter((x) => x.severity === 'error'),
    warnings: all.filter((x) => x.severity === 'warn'),
  }
}

/** Character and UTF-8 byte length of a rendered value, against the caps it was held to. */
export function measure(value: unknown): { chars: number; bytes: number } {
  const s = displayValue(value)
  return { chars: s.length, bytes: new TextEncoder().encode(s).length }
}

/**
 * PES.8 — the rules the review surface depends on, tested without a server.
 *
 * The two that matter most are negative: a cell must NOT be tinted for a draft nobody can approve,
 * and "approve this column" must NOT quietly include the stale ones. Both are the kind of thing
 * that looks right on screen while doing the wrong thing.
 */
import { describe, expect, it } from 'vitest'

import {
  cellIndexKey,
  displayValue,
  groupByColumn,
  indexDrafts,
  isCleanlyApprovable,
  isNoOpDiff,
  measure,
  provenanceFor,
  splitViolations,
  toSheetDraft,
} from './drafts'
import type { AiDraft } from './types'

const draft = (over: Partial<AiDraft> = {}): AiDraft => ({
  id: over.id ?? 'd1',
  productId: over.productId ?? 'p1',
  cellKey: 'master:name',
  writeField: 'name',
  columnKey: 'item_name',
  channel: null,
  marketplace: null,
  aliasId: null,
  locale: null,
  draftValue: 'a new title',
  baseValue: 'the old title',
  baseSource: 'stored',
  status: 'pending',
  confidence: 'high',
  rationale: null,
  violations: null,
  capsUsed: null,
  runId: 'r1',
  provider: 'anthropic',
  model: 'claude-opus-5',
  createdAt: '2026-09-01T00:00:00.000Z',
  stale: false,
  unverified: false,
  lastApplyError: null,
  ...over,
})

describe('provenanceFor', () => {
  it('marks a clean pending draft as drafted, not stale', () => {
    const idx = indexDrafts([draft()])
    expect(provenanceFor(idx, { rowId: 'p1', colId: 'item_name' })).toEqual({
      aiDrafted: true,
      aiStale: false,
    })
  })

  it('marks a stale draft stale, so it cannot be drawn as a clean one', () => {
    const idx = indexDrafts([draft({ stale: true })])
    expect(provenanceFor(idx, { rowId: 'p1', colId: 'item_name' })).toEqual({
      aiDrafted: true,
      aiStale: true,
    })
  })

  it('treats an unverifiable draft as stale — never as clean', () => {
    // We could not read the cell, so "not stale" would be a claim we have not earned.
    const idx = indexDrafts([draft({ unverified: true })])
    expect(provenanceFor(idx, { rowId: 'p1', colId: 'item_name' })?.aiStale).toBe(true)
  })

  it('does NOT tint a cell for a failed draft', () => {
    // A draft that broke a hard cap has no offerable value; tinting the cell would promise the
    // operator something to approve that the server will refuse.
    const idx = indexDrafts([draft({ status: 'failed' })])
    expect(provenanceFor(idx, { rowId: 'p1', colId: 'item_name' })).toBeNull()
  })

  it('returns null for a cell with no draft, so existing provenance survives', () => {
    const idx = indexDrafts([draft()])
    expect(provenanceFor(idx, { rowId: 'p1', colId: 'description' })).toBeNull()
    expect(provenanceFor(idx, { rowId: 'p2', colId: 'item_name' })).toBeNull()
  })

  it('keeps the newest when a cell somehow carries two drafts', () => {
    const idx = indexDrafts([
      draft({ id: 'old', draftValue: 'old', createdAt: '2026-09-01T00:00:00.000Z' }),
      draft({ id: 'new', draftValue: 'new', createdAt: '2026-09-02T00:00:00.000Z' }),
    ])
    expect(idx.get(cellIndexKey('p1', 'item_name'))?.id).toBe('new')
  })
})

describe('groupByColumn', () => {
  it('offers only cleanly approvable drafts for a column-level approve', () => {
    const group = groupByColumn([
      draft({ id: 'clean', productId: 'p1' }),
      draft({ id: 'stale', productId: 'p2', stale: true }),
      draft({ id: 'failed', productId: 'p3', status: 'failed' }),
      draft({ id: 'unverified', productId: 'p4', unverified: true }),
    ])[0]

    expect(group.drafts).toHaveLength(4)
    // The bulk control must never waive staleness — that decision belongs beside the value it
    // would replace, one cell at a time.
    expect(group.approvable.map((d) => d.id)).toEqual(['clean'])
    expect(group.staleCount).toBe(1)
    expect(group.failedCount).toBe(1)
    expect(group.unverifiedCount).toBe(1)
  })

  it('surfaces the caps a column was held to', () => {
    const group = groupByColumn([
      draft({ capsUsed: null }),
      draft({ id: 'd2', productId: 'p2', capsUsed: { maxLength: 200, maxBytes: 200, capFrom: 'Amazon · IT' } }),
    ])[0]
    expect(group.caps).toEqual({ maxLength: 200, maxBytes: 200, capFrom: 'Amazon · IT' })
  })

  it('sorts groups by column so the review is stable across reloads', () => {
    const groups = groupByColumn([
      draft({ columnKey: 'material' }),
      draft({ columnKey: 'bullet_point', id: 'b' }),
      draft({ columnKey: 'item_name', id: 'c' }),
    ])
    expect(groups.map((g) => g.columnKey)).toEqual(['bullet_point', 'item_name', 'material'])
  })
})

describe('isCleanlyApprovable', () => {
  it('is true only for a pending, fresh, verifiable draft', () => {
    expect(isCleanlyApprovable(draft())).toBe(true)
    expect(isCleanlyApprovable(draft({ stale: true }))).toBe(false)
    expect(isCleanlyApprovable(draft({ unverified: true }))).toBe(false)
    expect(isCleanlyApprovable(draft({ status: 'failed' }))).toBe(false)
    expect(isCleanlyApprovable(draft({ status: 'approved' }))).toBe(false)
  })
})

describe('displayValue / measure', () => {
  it('renders a list one member per line, never truncated', () => {
    const long = 'x'.repeat(500)
    expect(displayValue(['a', 'b', 'c'])).toBe('a\nb\nc')
    expect(displayValue([long])).toHaveLength(500)
  })

  it('renders an absent value as empty rather than "null"', () => {
    expect(displayValue(null)).toBe('')
    expect(displayValue(undefined)).toBe('')
  })

  it('counts UTF-8 bytes, not just characters', () => {
    // The whole reason the byte cap exists: 150 accented characters are 300 bytes, and a
    // character-only counter reads green on a value Amazon refuses.
    const accented = 'à'.repeat(150)
    expect(measure(accented)).toEqual({ chars: 150, bytes: 300 })
  })
})

describe('isNoOpDiff / splitViolations', () => {
  it('spots a draft that would change nothing', () => {
    expect(isNoOpDiff(draft({ draftValue: 'same', baseValue: 'same' }))).toBe(true)
    expect(isNoOpDiff(draft({ draftValue: ['a', 'b'], baseValue: ['a', 'b'] }))).toBe(true)
    expect(isNoOpDiff(draft())).toBe(false)
  })

  it('separates blocking errors from ride-along warnings', () => {
    const { errors, warnings } = splitViolations([
      { kind: 'over_max_bytes', severity: 'error', message: 'too long' },
      { kind: 'off_list', severity: 'warn', message: 'not in the list' },
    ])
    expect(errors).toHaveLength(1)
    expect(warnings).toHaveLength(1)
  })

  it('treats no violations as no violations', () => {
    expect(splitViolations(null)).toEqual({ errors: [], warnings: [] })
  })
})

describe('the sheet overlay shape (PES.2 contract)', () => {
  it('never offers a failed draft to the cell renderer', () => {
    // The cell shows a proposal an operator can act on. A draft that broke a hard cap is not one:
    // the server refuses it, so tinting the cell would promise something undeliverable. It stays
    // in the review list where its violation can be read.
    expect(toSheetDraft(draft({ status: 'failed' }))).toBeNull()
    expect(toSheetDraft(draft({ status: 'approved' }))).toBeNull()
    expect(toSheetDraft(draft())).toMatchObject({ draftValue: 'a new title', stale: false })
  })

  it('passes violation MESSAGES through, since the cell tooltip renders strings', () => {
    const d = draft({
      violations: [{ kind: 'off_list', severity: 'warn', message: 'not in the list' }],
    })
    expect(d.violations?.map((v) => v.message)).toEqual(['not in the list'])
  })
})

apps/web/src/design-system/grid/editors/.content:
'use client'

import { FormulaGuidance, formulaSuggestions, useFormulaPreview } from './formulaAssistance'

import { createElement, forwardRef, useCallback, useEffect, useId, useLayoutEffect, useMemo, useRef, useState, type ComponentType } from 'react'
import type { ICellEditorParams } from 'ag-grid-community'
import { useGridCellEditor } from 'ag-grid-react'
import { Button, Input, Textarea } from '../../primitives'
import { ListboxPanel, type ListboxOption } from '../../components'
import { editorBox, roomToRightOf } from './editorBox'
