apps/web/src/app/products/[id]/edit/_stu.content:
/**
 * PES.4 — what a `$reference` may name on the record open in the drawer (D16, #708/#775).
 *
 * 🔴 A pure module, and deliberately so. The list is built inside a React pane, and a rule that
 * lives inside a component in this repo cannot be tested at all: `apps/web`'s vitest is NODE-ONLY,
 * and a module that imports a `.tsx` reports "no tests" and looks GREEN while never running. The
 * types below are `import type` only — erased at compile time — so nothing here pulls a component
 * into the test program.
 *
 * 🔴 It must agree with `MasterSheet.candidatesFor` exactly. Two surfaces offering different
 * autocomplete for the same row is the drift the "shared = exactly the same" rule exists to stop,
 * and it would show as an operator finding a column on the sheet that the drawer will not complete.
 * The shape is pinned by this module's test rather than by anyone remembering.
 */
import type { FormulaCandidate } from '@/design-system/grid/editors/formulaEditing'
import type { FormulaFunctionDoc } from '@/design-system/grid/editors/formulaPreview'

/** Just enough of a column to describe it — the drawer's `SheetColumn`, structurally. */
export interface CandidateColumn {
  key: string
  label: string
}

/** Just enough of a cell to read its value — the drawer's `StudioCellValue`, structurally. */
export interface CandidateCell {
  value?: unknown
}

/**
 * Where ↑/↓ moves the highlight, as a pure rule.
 *
 * 🔴 Extracted from the keydown handler rather than left inline, and the reason is a measurement:
 * the only screen reading anyone took of this field's autocomplete had a **single match**, so the
 * wrap arithmetic was never exercised on screen and could not be — a one-row list looks identical
 * whether the modulo is right, inverted, or off by one. Verifying it in a browser would have meant
 * another live session on a production fixture to test two lines of arithmetic. This is the cheaper
 * and stricter answer.
 *
 * Wraps deliberately: a list that stops dead at either end makes an operator who overshot travel all
 * the way back. `count === 0` returns the current index untouched — there is nothing to highlight,
 * and moving to 0 would point `aria-activedescendant` at a row that is not rendered.
 */
export function nextActiveIndex(current: number, key: 'ArrowDown' | 'ArrowUp', count: number): number {
  if (count <= 0) return current
  /* 🔴 There is no separate "normalise `current` first" step, and there WAS one until a mutation
     test showed it did nothing: for any index ≥ 0 the modulo below already folds a past-the-end
     value back into range (`(9+1) % 3 === 1`, and `(9-1+3) % 3 === 2` — identical with or without
     pre-normalising), and `current` cannot be negative because it only ever comes from this
     function, from `setActiveIndex(0)`, or from the panel's own index. The line read as a guard,
     was dead for every reachable input, and its comment claimed work it did not do. A stale index
     from a list that has since shrunk is still handled — by the modulo, which is load-bearing. */
  return key === 'ArrowDown' ? (current + 1) % count : (current - 1 + count) % count
}

export function buildFormulaCandidates(
  columns: readonly CandidateColumn[],
  values: Readonly<Record<string, CandidateCell | undefined>>,
  functions: readonly FormulaFunctionDoc[],
): FormulaCandidate[] {
  const cols = columns.map((col) => {
    const raw = values[col.key]?.value
    return {
      name: col.key,
      kind: 'field' as const,
      label: col.label,
      /* 🔴 The literal `'Columns'`, NOT the column's own group. The drawer groups its FORM by
         `col.group` ("Identity", "Compliance", …), so passing that through here would split the
         autocomplete into a dozen headed sections where the sheet shows exactly one — the same list,
         shaped differently, on two surfaces. */
      group: 'Columns',
      /* 🔴 Absent, never `''`, for an empty cell. The editor draws no value chip for a field with
         nothing in it, and an empty chip and a missing one look identical while meaning different
         things — "this column is empty" vs "this candidate has no value to show". */
      value: raw == null || raw === '' ? undefined : String(raw),
    }
  })
  const fns = functions.map((f) => ({
    name: f.name,
    kind: 'function' as const,
    label: f.signature,
    group: 'Functions',
  }))
  /* Fields first. `completionsFor` ranks them ahead of functions anyway, but the order it is HANDED
     is the order equal-ranked entries keep, and the Owner's cases are "pull the value from that
     column" — a language reference is the rarer need. */
  return [...cols, ...fns]
}

/**
 * PES.4 — the drawer's `$` autocomplete list, and the two invariants no type can catch.
 *
 * The builder itself is tested for real. The two SOURCE assertions at the bottom are not padding:
 * both guard behaviour that is invisible to the compiler, silently wrong, and expensive — a formula
 * stored as a literal VALUE publishes to a channel and preflight calls it valid, and an autosave
 * that fires mid-formula writes `=`, `=u`, `=up` into the cell as the operator types the rule.
 *
 * Each source assertion is PAIRED with the negative form, because a `toContain` that only ever
 * looks for the right string passes just as happily when the file has been rewritten around it.
 */
import { readFileSync } from 'node:fs'
import { describe, expect, it } from 'vitest'

import { buildFormulaCandidates, nextActiveIndex } from './formulaCandidates'

const COLS = [
  { key: 'brand', label: 'Brand' },
  { key: 'item_name', label: 'Title' },
  { key: 'basePrice', label: 'Price' },
]
const FNS = [
  { name: 'upper', signature: 'upper(text)', summary: 'Uppercase' },
  { name: 'concat', signature: 'concat(a, b)', summary: 'Join' },
]

describe('buildFormulaCandidates', () => {
  it('offers every column as a field, then every function', () => {
    const out = buildFormulaCandidates(COLS, {}, FNS)
    expect(out.map((c) => c.name)).toEqual(['brand', 'item_name', 'basePrice', 'upper', 'concat'])
    expect(out.filter((c) => c.kind === 'field')).toHaveLength(3)
    expect(out.filter((c) => c.kind === 'function')).toHaveLength(2)
  })

  it('🔴 groups every column under the literal "Columns", never under the form\'s own group', () => {
    /* The drawer's FORM is grouped by `col.group` ("Identity", "Compliance", …). If that leaked in
       here the autocomplete would fragment into a dozen headed sections where the sheet shows one —
       the same list, two shapes, one of them wrong. */
    const out = buildFormulaCandidates(COLS, {}, FNS)
    expect(new Set(out.filter((c) => c.kind === 'field').map((c) => c.group))).toEqual(new Set(['Columns']))
    expect(new Set(out.filter((c) => c.kind === 'function').map((c) => c.group))).toEqual(new Set(['Functions']))
  })

  it('🔴 carries the row\'s CURRENT value, which is the half that answers "is this the column I meant"', () => {
    const out = buildFormulaCandidates(COLS, { brand: { value: 'Xavia' } }, [])
    expect(out.find((c) => c.name === 'brand')?.value).toBe('Xavia')
  })

  it('🔴 leaves `value` ABSENT for an empty cell rather than setting an empty string', () => {
    /* An empty chip and a missing chip look identical on screen and mean different things. The
       editor draws nothing for `undefined`; `''` would draw an empty one. */
    const out = buildFormulaCandidates(COLS, { brand: { value: '' }, item_name: { value: null } }, [])
    expect(out.find((c) => c.name === 'brand')).not.toHaveProperty('value', '')
    expect(out.find((c) => c.name === 'brand')?.value).toBeUndefined()
    expect(out.find((c) => c.name === 'item_name')?.value).toBeUndefined()
    /* A cell the payload omits entirely is the same case, and it is the common one on a sparse row. */
    expect(out.find((c) => c.name === 'basePrice')?.value).toBeUndefined()
  })

  it('stringifies a non-string value rather than passing a number through', () => {
    /* `FormulaCandidate.value` is documented as text — the chip renders it directly. */
    const out = buildFormulaCandidates(COLS, { basePrice: { value: 105 } }, [])
    expect(out.find((c) => c.name === 'basePrice')?.value).toBe('105')
  })

  it('🔴 a zero is a VALUE, not an empty cell', () => {
    /* `0` and `false` are falsy, so a truthiness test here would hide a real price of 0 behind
       "this column is empty" — the classic form of this bug and the reason the check is `== null`. */
    const out = buildFormulaCandidates(COLS, { basePrice: { value: 0 } }, [])
    expect(out.find((c) => c.name === 'basePrice')?.value).toBe('0')
  })

  it('offers no functions before the docs have loaded, and invents none', () => {
    const out = buildFormulaCandidates(COLS, {}, [])
    expect(out.filter((c) => c.kind === 'function')).toHaveLength(0)
  })
})

describe('nextActiveIndex — the ↑/↓ walk', () => {
  /* 🔴 This exists BECAUSE the screen could not test it. The one live reading of the autocomplete
     had a single match, and a one-row list behaves identically whether the modulo is correct,
     inverted, or off by one. The alternative to these assertions was another browser session
     against a production fixture to exercise two lines of arithmetic. */
  it('walks down and up through the list', () => {
    expect(nextActiveIndex(0, 'ArrowDown', 4)).toBe(1)
    expect(nextActiveIndex(2, 'ArrowDown', 4)).toBe(3)
    expect(nextActiveIndex(2, 'ArrowUp', 4)).toBe(1)
  })

  it('🔴 wraps at BOTH ends — an operator who overshot must not travel all the way back', () => {
    expect(nextActiveIndex(3, 'ArrowDown', 4)).toBe(0)
    expect(nextActiveIndex(0, 'ArrowUp', 4)).toBe(3)
  })

  it('🔴 an index left over from a LONGER list does not survive past the end', () => {
    /* The operator types another character, the matches shrink, and the stored index is now past
       the end. Un-normalised it would point `aria-activedescendant` at a row that is not rendered
       — a dangling reference that audits as wired, the same failure as a bad `aria-controls`. */
    expect(nextActiveIndex(9, 'ArrowDown', 3)).toBe(1)
    expect(nextActiveIndex(9, 'ArrowUp', 3)).toBe(2)
  })

  it('🔴 an EMPTY list leaves the index alone rather than moving to 0', () => {
    /* There is nothing to highlight; 0 would name a row that does not exist. */
    expect(nextActiveIndex(2, 'ArrowDown', 0)).toBe(2)
    expect(nextActiveIndex(2, 'ArrowUp', 0)).toBe(2)
  })

  it('a single match stays put in both directions — the case the screen DID see', () => {
    expect(nextActiveIndex(0, 'ArrowDown', 1)).toBe(0)
    expect(nextActiveIndex(0, 'ArrowUp', 1)).toBe(0)
  })
})

describe('🔴 invariants the compiler cannot see', () => {
  const field = readFileSync(new URL('./fields/FormulaField.tsx', import.meta.url), 'utf8')
  const composer = readFileSync(new URL('../../../../../../design-system/grid/editors/FormulaComposer.tsx', import.meta.url), 'utf8')
  const record = readFileSync(new URL('./fields/RecordField.tsx', import.meta.url), 'utf8')

  it('a formula is saved through the FORMULA writer, never through the value writer', () => {
    /* 🔴 The dangerous one. `onWrite` stores what it is given as the cell's literal value, and
       `overrideData` is read as a value layer by the resolver — so a formula sent that way would
       publish its own CHARACTERS to a channel and preflight would call the listing valid. */
    expect(field).toContain('formulas.save(rowId, column.key, exprOf(draft))')
    expect(field).not.toMatch(/\bonWrite\b/)
  })

  it('entering formula mode cancels the idle autosave instead of scheduling one', () => {
    /* Without the early return the 900ms autosave fires on the mode switch itself and writes `=`,
       then `=u`, then `=up` into the cell as the rule is typed — each one a real write. */
    expect(record).toContain('window.clearTimeout(timer.current)\n            setFormulaMode(true)\n            return')
    /* The ordinary path must still schedule one, or every plain edit stops saving. */
    expect(record).toContain('scheduleCommit(next)')
  })

  it('the drawer builds no formula hook of its own — the seam is injected by the host', () => {
    /* `useCellFormulas` needs a `market` this drawer cannot see, and a second instance would be a
       second answer to "what formula is on this cell".

       🔴 The assertion names the IMPORT, not the word. Both these files DISCUSS `useCellFormulas`
       in their comments — explaining why they do not call it — so a bare `not.toMatch(/useCell…/)`
       fails on the prose that documents the rule it is enforcing. It did, on the first run: the
       banked "a guard greps comments" shape, caught here only because the assertion was written to
       be capable of failing. */
    expect(field).not.toMatch(/import[^\n]*useCellFormulas/)
    expect(record).not.toMatch(/import[^\n]*useCellFormulas/)
  })

  it('🔴 a scope that refuses writes cannot author a formula through the side door', () => {
    /* PES.3's channel scope passes an `onWrite` that always refuses, because channel writes belong
       to the sheet's own cascade. A formula IS a write and reaches the server through
       `DrawerFormulas.save`, NOT `onWrite` — so the host's refusal is structurally unable to stop
       it, and without this signal the drawer would offer a live ƒ control three lines under its own
       "read-only" message. Every authoring path must consult the flag: the ƒ button, the remove
       button, the `=` keystroke, and the field's own disabled state. */
    const gates = record.match(/!formulaWritesRefused/g) ?? []
    expect(gates.length).toBeGreaterThanOrEqual(3)
    expect(record).toContain('disabled={!editable || formulaWritesRefused}')
    /* Defence in depth: the WRITE functions guard too, because a hidden control and an impossible
       write are different claims and only the second is worth relying on. */
    expect(record).toContain('if (formulaWritesRefused) return')
    expect(field).toContain('disabled={disabled || formulas.ready === false}')
    expect(composer).toContain('!onApply || disabled || busy.current')
    /* 🔴 And the guards must be in the callbacks' DEPS, or a stale closure keeps the write path open
       after the scope closed it — a guard present in the source and not in effect. */
    expect(field).toContain('onApply={async draft =>')
    expect(record).toMatch(/onFormulaSaved, formulaWritesRefused\]/)
  })

  it('🔴 a STORED formula still displays where writes are refused', () => {
    /* Hiding it would leave the operator looking at a computed value whose rule they can neither
       read nor account for — the hazard `formulaAvailability`'s "always available when stored" arm
       exists to prevent. Only AUTHORING is suppressed, which is why the refusal gates the
       `formulaMode` half of the disjunction and not the `storedExpr` half. */
    expect(record).toContain('(storedExpr != null || (formulaMode && !formulaWritesRefused))')
  })

  it('🔴 ↑/↓ indexes the panel\'s OWN match list, never the field\'s options array', () => {
    /* `ListboxPanel` re-ranks and regroups what it is handed (`searchOptions` + `groupOptions`), so
       `options[i]` and `matches[i]` are different rows. Indexing the local array would highlight one
       candidate and insert another — invisible on a short list where the orders happen to agree,
       and wrong exactly when the list is long enough that the operator needs the keyboard. */
    expect(composer).toContain('matches[active] ?? matches[0] ?? suggestions.options[0]')
    expect(composer).not.toMatch(/choose\(suggestions.options\[active\]/)
    /* The panel is told what is highlighted, and hands back the list that index belongs to. */
    expect(composer).toContain('onMatchesChange={setMatches}')
    expect(composer).toContain('activeIndex={active}')
  })

  it('🔴 walking the list is announced, because focus never moves', () => {
    /* The caret stays in the input while the highlight moves in a panel the input does not contain.
       Without `aria-activedescendant` the feature exists and is silent to a screen reader. */
    expect(composer).toContain('aria-activedescendant={open && matches[active] ? `${id}-o${active}`')
    /* The shared ListboxPanel now exposes its ID, so aria-controls resolves.
       Previous contract: no dangling `aria-controls`: the panel's container carries no id to point at, so the
       attribute would name an element that does not exist.
       🔴 Matched as an ATTRIBUTE (`aria-controls=`), not as the word — the file's comment names it
       precisely to record why it is absent, and the bare word fails on that prose. Third time this
       shape has bitten in this file; each time the test caught it only because it was written to be
       capable of failing rather than to pass. */
    expect(composer).toContain('aria-controls={open ? `${id}-listbox`')
    expect(composer).toContain('<ListboxPanel idPrefix={id}')
  })

  it('the formula field does not wear the grid wrapper that would make its text invisible', () => {
    /* `.nds-formula-editor` sets `color: transparent` on the input for the grid's syntax-highlight
       overlay. This field has no overlay, so that class would hide everything typed into it.
       Matched as a className, for the same comment reason as above — the file's header names the
       class precisely to record why it is not used. */
    expect(composer).not.toMatch(/className=["'][^"']*nds-formula-editor/)
    /* The classes it SHOULD share, so the two surfaces look like one feature rather than two. */
    expect(field).toContain('<FormulaComposer')
    expect(composer).toContain('nds-formula-preview')
    expect(composer).toContain('nds-formula-pop')
  })
})

'use client'

/**
 * PES.4.3 — the whole record as a form, grouped the way the sheet groups its columns.
 *
 * The groups are `SheetColumn.group`, not a second taxonomy invented here: the drawer and the
 * sheet must agree about what "Content" contains, or an operator who cannot find a field in one
 * will look for it under a different heading in the other.
 *
 * It renders from the row object the grid ALREADY holds. No fetch on open — `SheetRow` carries the
 * resolved value, its provenance, readiness and completeness for every column.
 */

import { columnForCategory } from '@nexus/shared/master-sheet'
import { useEffect, useMemo, useRef, useState } from 'react'
import { ChevronDown, ChevronRight } from 'lucide-react'
import { GalleryStrip, type GalleryImage } from '../fields/GalleryStrip'
import { RecordField } from '../fields/RecordField'
import type {
  DrawerFormulas,
  DrawerScope,
  ReadinessIssue,
  RecordWriteResult,
  SheetColumn,
  SheetRow,
} from '../types'
import type { FormulaCandidate } from '@/design-system/grid'
import { buildFormulaCandidates } from '../formulaCandidates'
import { PressableRow } from '@/design-system/components/PressableRow'
import styles from '../drawer.module.css'

/**
 * #166's quiet sub-form: `?? []` mints a NEW array on every render and does not look like a
 * literal, so it survives the grep that catches `return {`. Harmless until the child memoises —
 * and then it is a memo that never hits, for a reason nobody can see at the call site. Frozen so
 * the shared instance cannot be mutated by a consumer that assumes it owns its props.
 */
const NO_IMAGES: readonly GalleryImage[] = Object.freeze([])

export interface RecordPaneProps {
  row: SheetRow
  columns: SheetColumn[]
  scope: DrawerScope
  focusKey?: string
  images?: readonly GalleryImage[]
  /** Parent label when `images` are inherited; null when they are the record's own. */
  imagesInheritedFrom?: string | null
  /** Why the gallery is absent, when it is absent because the read FAILED. */
  imagesError?: string | null
  /** Per-field save state, keyed by `SheetColumn.key`. Owned by the host's write queue. */
  writeStates: Record<string, RecordWriteResult>
  onWrite: (column: SheetColumn, value: unknown, intent: 'set' | 'pin') => void
  onReset: (column: SheetColumn) => void
  onHistory: (column: SheetColumn) => void
  /** D16 formulas, supplied by the host sheet. Absent = no formula affordances (#708/#775). */
  formulas?: DrawerFormulas
  /** A formula was stored or removed — the host refetches, because the VALUE is the server's. */
  onFormulaSaved?: () => void
  /** Why this scope refuses writes wholesale. Suppresses formula AUTHORING; see `RecordDrawerProps`. */
  writesRefused?: string
}

export function RecordPane({
  row,
  columns,
  scope,
  focusKey,
  images,
  imagesInheritedFrom,
  imagesError,
  writeStates,
  onWrite,
  onReset,
  onHistory,
  formulas,
  onFormulaSaved,
  writesRefused,
}: RecordPaneProps) {
  /**
   * What a `$reference` may name on THIS record, with the value each column currently holds.
   *
   * 🔴 Built ONCE per record here rather than per field. There are ~100 fields in this pane and the
   * list is identical for every one of them; building it inside `RecordField` would mint a hundred
   * copies of the same array on every render and hand each memoised field a prop that differs by
   * identity every time — the exact shape FE.1 measured costing 178.8 ms of a 254 ms drawer open.
   *
   * It is a TYPING AID, never a verdict: the server resolves against the full per-market key set
   * and its answer overrides this list the moment it arrives. Deriving "unknown" from here alone
   * would mark a good reference wrong whenever the record shows fewer columns than the market has.
   */
  const formulaCandidates = useMemo<FormulaCandidate[]>(
    () => (formulas ? buildFormulaCandidates(columns, row.values, formulas.functions) : []),
    [formulas, columns, row.values],
  )

  const groups = useMemo(() => {
    const byGroup = new Map<string, SheetColumn[]>()
    for (const header of columns) {
      const col = columnForCategory(header, scope.kind === 'channel' ? Object.keys(header.channels ?? {})[0] ?? '' : 'Master', row.productType ?? null) 
      // A per-variant field on a parent row is shown, LOCKED, with the reason — not hidden. A
      // field that vanishes between two rows reads as a missing field, and the operator goes
      // looking for the bug instead of reading the explanation.
      const list = byGroup.get(col.group) ?? []
      list.push(col)
      byGroup.set(col.group, list)
    }
    return [...byGroup.entries()]
  }, [columns, scope.kind, row.productType])

  /** The group holding the cell the operator arrived on — the one group that starts open. */
  const arrivingGroup = useMemo(
    () => (focusKey ? (columns.find((c) => c.key === focusKey)?.group ?? null) : null),
    [columns, focusKey],
  )

  /**
   * Groups start COLLAPSED, except the one holding the arriving cell (UX.1, re-ruled #330).
   *
   * This reverses #283. The earlier reasoning — "a collapsed group hides the empty required fields
   * that are the work" — was sound about hiding and wrong about the arithmetic: SR.1 measured 97
   * fields over 21.3 screens, of which 4 are visible either way. Expanded does not show the work,
   * it buries it 21 screens deep. Collapsed is only acceptable BECAUSE the header carries its own
   * count ("Identity · 7 fields · 3 required missing"), so a closed group still states what is
   * inside it and one click reaches it. A collapsed group that said nothing would be the hiding
   * the first ruling was right to refuse.
   *
   * Open state is per RECORD and never persisted (#283 stands): carrying it to the next record
   * would decide, on a record nobody has seen, which fields are worth showing.
   */
  const [open, setOpen] = useState<Record<string, boolean>>({})
  useEffect(() => {
    setOpen(arrivingGroup ? { [arrivingGroup]: true } : {})
  }, [row.id, arrivingGroup])

  /**
   * This scope's issues, keyed by field.
   *
   * `row.readiness` is ONE `{state, issues}` for the scope the sheet is loaded for — not a map
   * keyed by coordinate. This used to `Object.values()` over it and read `.issues` off each,
   * which on the real payload iterates the STRING "missing" and throws. `?? []` is not
   * belt-and-braces either: a row whose readiness has not been computed omits `issues` entirely.
   */
  const issues = useMemo(() => {
    const out: Record<string, ReadinessIssue> = {}
    for (const issue of row.readiness?.issues ?? []) {
      // An error outranks a warn on the same field: the stricter verdict is the one that decides
      // whether this record can ship.
      if (!out[issue.key] || (out[issue.key].severity === 'warn' && issue.severity === 'error')) {
        out[issue.key] = issue
      }
    }
    return out
  }, [row.readiness])

  /**
   * Scroll the cell the operator arrived on into view — WITHOUT focusing it. They are still
   * navigating the grid; taking the caret would end that.
   *
   * 🔴 This used to run once and miss. A single query on `[focusKey, row.id]` fires in the commit
   * where those change, which is BEFORE the fields of a freshly-loaded record are in the DOM — and
   * now also before the arriving group has opened. `querySelector` returned null, nothing scrolled,
   * and the effect never ran again: SR.1 measured `scrollTop 11` with the target at 1,429. Nothing
   * reported an error, because not-scrolling looks exactly like already-in-view.
   *
   * So it retries across frames until the element exists, then scrolls once. Bounded at ~30 frames
   * so a `focusKey` naming a column this scope does not have gives up instead of spinning. The rAF
   * is cancelled on cleanup and restarted by the re-run, so StrictMode's double-invoke re-arms it
   * rather than latching it off.
   */
  const paneRef = useRef<HTMLDivElement>(null)
  useEffect(() => {
    if (!focusKey) return
    let raf = 0
    let frames = 0
    let corrections = 0

    /**
     * The scroller is FOUND, not named.
     *
     * 🔴 This first asked for `.nds-drawer-b`, the DS drawer's scrolling body — and measured the
     * wrong box. Inside the dock that element is `scrollHeight === clientHeight`; the element that
     * actually scrolls is the pane below it, 9,468px of content in a 641px window. Hardcoding a
     * class made the check answer about a box that never moves, which would have reported a
     * landing for a field 8,000px away. Walking up for the first ancestor that can actually scroll
     * asks the question about whatever element is really doing the scrolling.
     */
    const scrollerOf = (el: HTMLElement): HTMLElement | null => {
      let n = el.parentElement
      while (n) {
        if (n.scrollHeight - n.clientHeight > 2 && /auto|scroll/.test(getComputedStyle(n).overflowY)) return n
        n = n.parentElement
      }
      return null
    }

    /** Landed = the operator can SEE the field, not merely that a scroll was requested. */
    const landed = (el: HTMLElement) => {
      const scroller = scrollerOf(el)
      // Nothing scrolls: there is no scrolling left to do, so the field is as visible as it gets.
      if (!scroller) return true
      const a = el.getBoundingClientRect()
      const b = scroller.getBoundingClientRect()
      // Fully inside — a field peeking one pixel over the fold is "in view" to an overlap test and
      // unreadable to a person. A field TALLER than the window can never be fully inside, so it
      // counts as landed once it covers the window.
      if (a.height >= b.height) return a.top <= b.top && a.bottom >= b.bottom
      return a.top >= b.top && a.bottom <= b.bottom
    }

    const tick = () => {
      const el = paneRef.current?.querySelector<HTMLElement>(`[data-field="${CSS.escape(focusKey)}"]`)
      if (!el) {
        if (frames++ < 30) raf = requestAnimationFrame(tick)
        return
      }
      if (landed(el)) return
      if (corrections++ >= 5) return
      // `auto`, not `smooth`: a smooth scroll is an animation, and every field that mounts
      // underneath it re-lays out the pane and can cancel it mid-flight — which is one of the two
      // candidate causes of the 0-and-3,804 reading (#336). An instant jump has no flight to
      // cancel. It also re-checks after each jump, so a jump that lands short corrects itself
      // instead of reporting success from having called the API.
      el.scrollIntoView({ block: 'center', behavior: 'auto' })
      raf = requestAnimationFrame(tick)
    }

    raf = requestAnimationFrame(tick)
    return () => cancelAnimationFrame(raf)
    // `columns.length` is in the deps because the fields cannot be found before the columns that
    // render them arrive, and on a cold load they arrive AFTER this effect's first run.
  }, [focusKey, row.id, columns.length])

  return (
    <div ref={paneRef}>
      {(images || imagesError) && (
        <div className={styles.group} style={{ padding: 12, marginBottom: 8 }}>
          {imagesError ? (
            <div className={`${styles.note} ${styles.noteError}`}>
              <span>The images could not be read: {imagesError}. This is not “this record has no images”.</span>
            </div>
          ) : (
            <GalleryStrip images={images ?? NO_IMAGES} inheritedFrom={imagesInheritedFrom} />
          )}
        </div>
      )}

      {groups.map(([group, cols]) => {
        const isOpen = open[group] === true
        const missing = cols.filter((c) => c.requiredBy.length > 0 && !row.values[c.key]?.value).length
        return (
          <section key={group} className={styles.group}>
            {/* A DISCLOSURE, so `expanded` — not `active`. `aria-pressed` here would tell a screen
                reader there is a toggle state where there is a section that opens beneath. */}
            <PressableRow
              className={styles.groupHead}
              expanded={isOpen}
              onClick={() => setOpen((o) => ({ ...o, [group]: !isOpen }))}
              label={
                <span>
                  {isOpen ? <ChevronDown size={13} aria-hidden /> : <ChevronRight size={13} aria-hidden />} {group}
                </span>
              }
            >
              <span className={styles.groupCount}>
                {cols.length} field{cols.length === 1 ? '' : 's'}
                {missing > 0 ? ` · ${missing} required missing` : ''}
              </span>
            </PressableRow>

            {isOpen && (
              <div className={styles.groupBody}>
                {cols.map((col) => (
                  <RecordField
                    key={col.key}
                    column={col}
                    cell={row.values[col.key]}
                    focused={col.key === focusKey}
                    scopeKind={scope.kind}
                    lockedReason={
                      col.scope === 'per_variant' && row.isParent
                        ? 'This field belongs to each variation — edit it on a variation row.'
                        : undefined
                    }
                    issue={issues[col.key]}
                    state={writeStates[col.key]}
                    onWrite={onWrite}
                    onReset={onReset}
                    onHistory={onHistory}
                    rowId={row.id}
                    formulas={formulas}
                    candidates={formulaCandidates}
                    onFormulaSaved={onFormulaSaved}
                    writesRefused={writesRefused}
                  />
                ))}
              </div>
            )}
          </section>
        )
      })}

      {groups.length === 0 && (
        <div className={`${styles.note} ${styles.noteInfo}`}>
          <span>
            No columns for this scope
            {scope.kind === 'channel' ? ` (${scope.channel} ${scope.marketplace})` : ''}. The channel schema has not
            been fetched, or no product type is set on this record — the sheet reports the same gap.
          </span>
        </div>
      )}
    </div>
  )
}

'use client'

import { useCallback, useState } from 'react'
import { FormulaComposer } from '@/design-system/grid/editors/FormulaComposer'
import { exprOf, isFormulaDraft, type FormulaCandidate } from '@/design-system/grid'
import type { DrawerFormulas, SheetColumn } from '../types'

export interface FormulaFieldProps {
  column: SheetColumn
  /** The record this field belongs to — `SheetRow.id`, the id the formula store keys on. */
  rowId: string
  formulas: DrawerFormulas
  /** The expression already stored on this cell, or null when the operator is starting one. */
  storedExpr: string | null
  /** What a `$reference` may name on THIS row, with the value it currently holds. Built once per record. */
  candidates: readonly FormulaCandidate[]
  /** The text the field held when formula mode began — restored on Escape. */
  originalText: string
  disabled?: boolean
  ariaLabel: string
  /**
   * Leave formula mode without saving: Escape, or clearing the leading `=`. The argument is the
   * text to hand back to the ordinary control, so deleting the `=` leaves what was typed after it
   * rather than silently discarding it.
   */
  onExit: (text: string) => void
  /** A formula was stored. The host refetches — the VALUE this produced is the server's to report. */
  onSaved?: () => void
}

export function FormulaField({ column, rowId, formulas, storedExpr, candidates, originalText, disabled, ariaLabel, onExit, onSaved }: FormulaFieldProps) {
  const [text, setText] = useState(storedExpr ? `=${storedExpr}` : originalText)
  const preview = useCallback((expr: string, signal?: AbortSignal) => formulas.preview(rowId, column.key, expr, signal), [formulas.preview, rowId, column.key])
  return <FormulaComposer text={text} onChange={setText} candidates={candidates.filter(c => c.kind !== 'field' || c.name !== column.key)}
    functions={formulas.functions} preview={preview} sourceLabel={formulas.sourceLabel} disabled={disabled || formulas.ready === false}
    allowText={column.kind !== 'number'} ariaLabel={`${ariaLabel} — formula`} saveOnBlur
    onCancel={() => { setText(storedExpr ? `=${storedExpr}` : originalText); onExit(originalText) }}
    onApply={async draft => {
      const result = isFormulaDraft(draft) ? await formulas.save(rowId, column.key, exprOf(draft)) :
        formulas.replace ? await formulas.replace(rowId, column.key, draft) : { ok: false, error: 'Remove the formula before entering a value.' }
      if (result.ok) onSaved?.()
      return result
    }} />
}

/**
 * PES.3 — the channel scope's row model: alias bands and the child SKUs under them.
 *
 * Layout §1: "Rows = one collapsible group per listing alias (①②③…), each with the SAME child SKUs
 * underneath, sharing one stock pool (qty per-channel, never summed)."
 *
 * ── The total that must not exist ───────────────────────────────────────────────────────────────
 * PES.5 §3.2 is explicit: "Quantity is per alias, never summed. Each alias group carries its own qty
 * cell; the family total is not the sum of its aliases. The contract carries no 'total quantity'
 * field precisely so no client can invent one" (reference_oversell_is_per_channel_not_summed).
 *
 * So this module computes NO quantity totals — not per scope, not per alias. Aliases share their
 * children, so any such sum double-counts units that do not exist and invites an operator to publish
 * stock they do not have. Quantity is read from the alias's own qty CELL, one row at a time, and
 * `assertNoQuantitySummation` below is the standing guard on that promise.
 *
 * Pure: no React, no AG import at runtime. Tested beside this file.
 */

import { writeGate as substrateWriteGate } from '@/design-system/grid/editors/writeGate'

import { aliasKeyOf, studioRowId, type AliasGroup, type ChannelSheetRow, type StudioCellValue, type StudioRow } from './types'

/** Keep matching rows and the listing band of each matching variant. Bands can match themselves. */
export function filterRowsWithBands(rows: ChannelSheetRow[], matches: (row: ChannelSheetRow) => boolean): ChannelSheetRow[] {
  const matching = new Set(rows.filter(matches).map(row => row.rowId))
  const aliases = new Set(rows.filter(row => matching.has(row.rowId)).map(row => aliasKeyOf(row.aliasId)))
  return rows.filter(row => matching.has(row.rowId) || (row.rowKind === 'parent' && aliases.has(aliasKeyOf(row.aliasId))))
}

/* 🔴 `aliasBarTone` LIVED HERE and is now the engine's `readyPillTone` (#727), with its four cases
   and two new regression cases beside it in `renderers/readyPillTone.vitest.test.ts`. Deleted only
   after reading that file: for an hour it looked like dead code while the rule it guards was being
   violated by the component that replaced it, and deleting it then would have taken #43's only
   guard with it. The rule moved first; the function went second. */


/**
 * What affordance a cell may offer, from the SERVER's own routing fields (ruling #58).
 *
 * Three rules, and each exists because the honest answer differs from the obvious one:
 *
 * 1. `writable: false` → NOTHING. A row under a non-primary alias has an unproven write path
 *    (PES.5-ii), so it gets no editor and no cascade click. The server's `writeBlockedReason` is
 *    shown verbatim rather than paraphrased into a guess.
 * 2. `writeTarget: 'master'` → **no cascade affordance at all.** `follows` may be TRUE on such a
 *    cell (basePrice is), and it is tempting to offer an un-pin — but this cell can only be written
 *    at master, so "un-pin" would either do nothing or rewrite every channel. Ruled honest, not
 *    contradictory: follows can be SEEN here and not ACTED on. The cell is still editable; the edit
 *    is simply a master edit, which rule 3 makes explicit.
 * 3. `affectsAllChannels: true` → editable, but the operator must be told BEFORE committing that
 *    this changes every channel, not just the one on screen.
 */
export type CellAffordance = 'blocked' | 'masterEdit' | 'cascade'

export function affordanceOf(cell: StudioCellValue | undefined): CellAffordance {
  if (!cell) return 'blocked'
  if (cell.writable === false) return 'blocked'
  if (cell.writeTarget === 'master') return 'masterEdit'
  return 'cascade'
}

/** Only a `cascade` cell may offer the pin/reset click. */
export function offersCascade(cell: StudioCellValue | undefined): boolean {
  return cell?.resettable !== false && affordanceOf(cell) === 'cascade'
}

/** Is this cell editable at all, per the server rather than the column? */
export function isCellEditable(cell: StudioCellValue | undefined): boolean {
  return !!cell && cell.editable !== false && cell.writable !== false
}

/** What a `cellValueChanged` should cause on a CHANNEL scope. */
export type ChannelWriteGate = 'ignore' | 'blocked' | 'acknowledge' | 'write'

export interface ChannelWriteGateInput {
  colId: string | undefined
  /** AG's `source`. */
  source: string | undefined
  /** True while THIS component is putting a declined value back — its own undo, not an edit. */
  selfInflicted: boolean
  cell: StudioCellValue | undefined
  /** Has the operator already been told, for this coordinate, that master writes hit every channel? */
  acknowledged: boolean
}

/**
 * The single decision behind every channel-sheet write, LAYERED over the substrate's.
 *
 * The grid-mechanic conditions — no column, `source: 'data'`, and the self-inflicted revert — belong
 * to PES.2's `writeGate` and are delegated, not copied: they are properties of AG, not of this
 * scope, and two copies of a rule about `setDataValue` re-entrancy is exactly the shape that let the
 * bug exist in the first place.
 *
 * What remains here is genuinely this lane's: PES.5's per-cell routing contract. `writable` gates a
 * cell the server says must not be written at all; `affectsAllChannels` gates a write that would
 * leave this channel and change every other one.
 */
export function channelWriteGate(input: ChannelWriteGateInput): ChannelWriteGate {
  const base = substrateWriteGate({
    colId: input.colId,
    source: input.source,
    selfInflicted: input.selfInflicted,
  })
  if (!base.write) return 'ignore'
  /**
   * 🔴 Gated on the REASON, not only on `writable === false` (#513, SC.1's measurement).
   *
   * Measured across 2,772 cells on both channel scopes: `writable === false` appears **zero**
   * times. The server withholds an edit with `editable: false` instead, which drops the editor
   * before this gate is ever consulted — so the branch that exists to show `writeBlockedReason`
   * verbatim was unreachable, and a cell that could not be edited said nothing about why.
   *
   * ⚠ Inert until PES.5 lands: `writeBlockedReason` is non-null on 0 of those 2,772 cells today.
   * This makes the path CORRECT, it does not make it visible — the visible half arrives with the
   * reasons. Kept `writable === false` alongside it: it costs nothing and is the contract's own
   * stated meaning, so a server that starts sending it still blocks.
   */
  if (!input.cell || input.cell.writable === false || input.cell.writeBlockedReason) return 'blocked'
  if (input.cell.contentAcknowledgement && input.cell.contentAddress === null) return 'acknowledge'
  if (input.cell.affectsAllChannels && !input.cell.contentAcknowledgement && !input.acknowledged) return 'acknowledge'
  return 'write'
}

/**
 * The save-reporter identity for one channel write.
 *
 * 🔴 TWO values, not one (#699). `writeId` is unique per ATTEMPT so overlapping writes count
 * correctly — a fill-down puts forty in flight at once. `subject` is what the write is ABOUT, and
 * the header counts failures per subject: without it a row refused twice reads as "2 changes not
 * saved" when there is one, and a retry that SUCCEEDS never clears the first failure because
 * nothing connects the two attempts. Channel rows also need their account, market and language:
 * the same variant/alias ID can appear in multiple scopes sharing one product save ledger.
 *
 * Extracted rather than left inline in the writer's `commit` closure for the reason `isOperatorEdit`
 * below was: the closure lives in a `.tsx` this suite cannot import, so an inline decision here
 * would be one no test could reach.
 */
export function channelWriteIdentity(rowId: string, seq: number, scope: {
  channel: string; marketplace: string; accountId?: string; locale?: string; instanceId: string
}): { writeId: string; subject: string } {
  const subject = `channel:${JSON.stringify([scope.channel, scope.marketplace, scope.accountId ?? null, scope.locale ?? null, rowId])}`
  // A remounted sheet restarts its counter while earlier requests may still be in flight.
  return { writeId: `${subject}#${scope.instanceId}#${seq}`, subject }
}

/**
 * Is this `cellValueChanged` an OPERATOR edit that should reach the server?
 *
 * 🔴 DENY-list, never an allow-list (PES.2's guard, ruling #53). AG types `source` as
 * `string | undefined` and documents only EXAMPLES (`edit` / `paste` / `undo` / `redo` / `data`), so
 * an allow-list silently drops any edit source nobody predicted — a fill-handle variant, say — and
 * an edit that shows on screen but never reaches the server is exactly the dishonesty this sheet
 * exists to prevent. Saving one source too many is the cheaper mistake.
 *
 * `'data'` is the one source known NOT to be an edit: it is the grid's own data being set. This
 * lane refetches after every cascade pin/reset, so without the guard each refetch would fire a
 * write per cell and the sheet would talk to itself.
 *
 * Extracted rather than left inline so the rule is testable — an inline `if` can be deleted in a
 * refactor and nothing would fail.
 */
export function isOperatorEdit(source: string | undefined): boolean {
  return source !== 'data'
}

/**
 * Attach the grid identity to the server's rows.
 *
 * `StudioRow.id` is the Product id, which is NOT unique across the grid: the same child SKU appears
 * under every alias that lists it. AG's `getRowId` and `getDataPath` need something that is.
 */
export function withRowIdentity(rows: StudioRow[], aliases: AliasGroup[]): ChannelSheetRow[] {
  const positionOf = new Map(aliases.map((a) => [aliasKeyOf(a.id), a.position]))
  return rows.map((r) => ({
    ...r,
    rowId: studioRowId(r.aliasId, r.id),
    aliasPosition: positionOf.get(aliasKeyOf(r.aliasId)) ?? 0,
  }))
}

/**
 * AG `treeData` path: the ALIAS is the group, the child SKU is the leaf.
 *
 * The alias-level row (`rowKind: 'parent'`) IS the group node — it carries the listing's own values,
 * so it is the band rather than a row beneath one.
 */
export function dataPathFor(row: ChannelSheetRow): string[] {
  const key = aliasKeyOf(row.aliasId)
  return row.rowKind === 'parent' ? [key] : [key, row.rowId]
}

export function rowIdOf(row: ChannelSheetRow): string {
  return row.rowId
}

/**
 * Order rows so every alias band is immediately followed by its own children, bands by position
 * (primary, `position: 0`, first). A band separated from its children reads as a bug.
 */
export function orderRows(rows: ChannelSheetRow[]): ChannelSheetRow[] {
  return [...rows].sort((a, b) => {
    if (a.aliasPosition !== b.aliasPosition) return a.aliasPosition - b.aliasPosition
    if (a.rowKind !== b.rowKind) return a.rowKind === 'parent' ? -1 : 1
    return a.sku.localeCompare(b.sku)
  })
}

/** The child rows of one alias group. */
export function variantRowsOf(rows: ChannelSheetRow[], aliasId: string | null): ChannelSheetRow[] {
  const key = aliasKeyOf(aliasId)
  return rows.filter((r) => r.rowKind === 'variant' && aliasKeyOf(r.aliasId) === key)
}

/** The band row of one alias group, when the family root is listed under it. */
export function bandRowOf(rows: ChannelSheetRow[], aliasId: string | null): ChannelSheetRow | undefined {
  const key = aliasKeyOf(aliasId)
  return rows.find((r) => r.rowKind === 'parent' && aliasKeyOf(r.aliasId) === key)
}

/**
 * The DISTINCT child SKUs on this coordinate, however many aliases list them.
 *
 * A count, never a quantity. This is the one cross-alias number that is safe, because a SKU listed
 * three times is still one SKU — whereas its units listed three times are still one pool.
 */
export function distinctVariantCount(rows: ChannelSheetRow[]): number {
  const seen = new Set<string>()
  for (const r of rows) if (r.rowKind === 'variant') seen.add(r.id)
  return seen.size
}

export interface AliasSummary {
  alias: AliasGroup
  /** Child rows drawn under this band. */
  variantRows: number
  /** Distinct child SKUs — equal to `variantRows` unless the server repeated one. */
  variantSkus: number
  /** From `AliasGroup.readiness`, never recomputed here. `null` = nothing to be ready against. */
  percent: number | null
  errors: number
  warnings: number
  rowsMissingRequired: number
  /** True while this alias is still an unadopted `EBAY_LISTING_SHELL`: a real listing with no rows. */
  isUnadoptedShell: boolean
}

export function summariseAlias(rows: ChannelSheetRow[], alias: AliasGroup): AliasSummary {
  const mine = variantRowsOf(rows, alias.id)
  const skus = new Set(mine.map((r) => r.id))
  return {
    alias,
    variantRows: mine.length,
    variantSkus: skus.size,
    percent: clampPct(alias.readiness?.percent),
    errors: alias.readiness?.errors ?? 0,
    warnings: alias.readiness?.warnings ?? 0,
    rowsMissingRequired: alias.readiness?.rowsMissingRequired ?? 0,
    // A live listing (it has a channel id) with nothing under it — the 22 shells measured on prod.
    isUnadoptedShell: mine.length === 0 && !!alias.externalListingId,
  }
}

/**
 * Readiness percentage for the band's bar. Taken from `AliasGroup.readiness.percent` and NOT
 * recomputed: PES.5 owns one readiness definition (§5) so two surfaces cannot disagree about 71%.
 * A missing percent reports 0 rather than inventing 100.
 */
export function aliasReadinessPct(alias: AliasGroup): number | null {
  return clampPct(alias.readiness?.percent)
}

/**
 * 🔴 NULL survives. It does not become 0.
 *
 * The server sends `percent: null` when the schema declares no required field for a coordinate —
 * "nothing to be ready against". Coercing that to 0 draws an empty red bar and tells the operator
 * their listing is 0% ready, which is an invention; coercing to 100 is a more comfortable
 * invention. Both are the same error. Caught by the #129 field-drift scan, having shipped as 0%.
 */
function clampPct(n: number | null | undefined): number | null {
  if (n === null || n === undefined) return null
  if (typeof n !== 'number' || !Number.isFinite(n)) return null
  return Math.max(0, Math.min(100, Math.round(n)))
}

/**
 * The standing guard on §3.2's invariant.
 *
 * Exported and asserted in the tests rather than left as a comment, because "never summed" is the
 * kind of rule a later refactor breaks silently while every screen still looks plausible. If a
 * quantity total is ever needed, it has to come from the server — which deliberately does not
 * provide one.
 */
export function assertNoQuantitySummation(mod: Record<string, unknown>): string[] {
  return Object.keys(mod).filter((k) => /total(quantity|qty|stock|units|pool)/i.test(k.replace(/[^a-z]/gi, '')))
}

/* ── which cell the record was opened FROM (PES.4 §5.4) ───────────────────────────────────── */

/**
 * Re-exported, NOT re-declared (#227/#229). PES.4 lifted this into `drawer/revealCell.ts` beside
 * `isCellCovered` so master and channel share one rule and one `CHROME_COLUMNS` union; keeping a
 * local copy here is how the two sheets would come to disagree about which columns are chrome.
 * A channel-only chrome id goes into THEIR union, never into a set here.
 */
// 🔴 From the MODULE, not the barrel. `../../drawer` re-exports React components, and this file is
// imported by node-env tests that cannot transform JSX — the barrel trap, hit a third time tonight.
export { isRevealAnchor } from '../../drawer/revealCell'

/**
 * Never render a sentence that ends mid-clause.
 *
 * 🔴 Lives HERE, not beside the component that calls it: it is pure, and a node-env test cannot
 * parse the JSX in `AliasPublishControl.tsx`. Fourth time tonight that a pure helper in a `.tsx`
 * made itself untestable — the rule is that pure logic goes in a `.ts` file from the start.
 *
 * Trailing `:` / `,` / `—` / `(` mean the server intended to append something and had nothing to
 * append. Dropping the dangling punctuation leaves a sentence that is true and complete; keeping it
 * asks the operator to look for a list that does not exist.
 */
export function tidyServerMessage(raw: string): string {
  const t = raw.trim().replace(/[\s:,;—-]+$/, '')
  return t.endsWith('.') || t.length === 0 ? t : `${t}.`
}


/* ── the run-level mapping fact, attached where the classifier expects it ─────────────────── */

/**
 * Give a cell the RUN's `productLevelOnly` so `classifyProvenance` can reach `mappedShared`.
 *
 * 🔴 `provenance.ts:146` decides `mappedShared` from a per-cell `mappedProductLevel`, and the wire
 * carries no such field — it carries `meta.mapping.productLevelOnly`, a fact about the RUN. PES.2's
 * framing (#367) is that a run-level fact is the CONSUMER's to supply, and that is this sheet.
 *
 * Measured before the fix, Amazon·IT: 15 cells `mapped`, **0** `mappedShared`, with the run flag
 * `true` — so every cell that should have said "editing one row changes N" said the opposite of
 * what §9.6b intends.
 *
 * Allocates only when the flag is TRUE. It is read per cell per paint inside `cellClassRules`, and
 * when the run is not product-level there is nothing to add, so the common path stays the identity.
 */
export function withMappingRun<T extends object>(cell: T | undefined, productLevelOnly: boolean): T | undefined {
  if (!cell || !productLevelOnly) return cell
  return { ...cell, mappedProductLevel: true }
}

/**
 * What a cell should say about itself on hover — the honesty the sheet owes before an edit (#513).
 *
 * Two things an operator cannot otherwise see:
 *
 *  - **why a cell refuses the editor.** `editable: false` drops the editor silently; the reason the
 *    server gave is the only explanation that exists.
 *  - **where an edit would actually land.** On a channel scope, a cell with `affectsAllChannels`
 *    writes the SHARED master record: 33 of eBay·IT's 35 columns do (`writeTarget: 'master'`), so
 *    an edit made from an eBay tab changes Amazon too. That is the same class as Amazon's shared-EU
 *    quantity, and it must be stated on the cell rather than discovered afterwards.
 *
 * 🔴 Keyed on `affectsAllChannels`, NOT on `writeVerb === 'master'`. eBay·IT's `name` and
 * `description` are `writeVerb: 'master'` yet `writeTarget: 'channelListing'` — genuine per-listing
 * overrides that touch nothing else. Warning on the verb would have put a false cross-market notice
 * on the two fields an operator edits most, which is worse than no notice: it teaches them to
 * ignore it.
 *
 * Returns `null` when there is nothing to say, so a caller renders no tooltip rather than an empty
 * one.
 */
export function cellHoverNote(
  cell: StudioCellValue | undefined,
  scopeLabel: string,
): string | null {
  if (!cell) return null
  if (cell.writeBlockedReason) return cell.writeBlockedReason
  if (cell.editable === false) return null
  if (cell.affectsAllChannels) {
    return `Editing this on ${scopeLabel} changes the shared master record — every channel sees it.`
  }
  return null
}

/**
 * How many of the columns in view write the shared master record — the toolbar's standing notice.
 *
 * A count, not a boolean: "33 of 35 columns" is the fact that makes an operator read the cell
 * notices, and one column behaving this way is a very different surface from thirty-three.
 * Returns 0 when nothing does, so the caller can omit the notice entirely.
 */
export function crossChannelColumnCount(
  row: { values?: Record<string, StudioCellValue> } | undefined,
): number {
  if (!row?.values) return 0
  return Object.values(row.values).filter((c) => c?.affectsAllChannels && c.editable !== false && c.writable !== false).length
}

/**
 * PES.3 — the row model, tested on the shape prod actually has.
 *
 * The fixture mirrors 2026-09-01: GALE-JACKET listed under several eBay·IT aliases over the same
 * child SKUs. The invariant under test is PES.5 §3.2's: nothing in this lane totals a quantity, and
 * the counts that DO cross aliases are counts of SKUs, which do not scale with the alias list.
 */
import { describe, expect, it } from 'vitest'

import * as rowsModule from './rows'
/* 🔴 The DEEP path, never the barrel: `@/design-system/grid` re-exports `.tsx`, and this suite is
   node-only — importing the barrel here dies at PARSE before a single case runs
   (reference_test_scoping_and_hidden_assertions). `readiness.ts` is plain TS. */
import { readyPillTone } from '@/design-system/grid/renderers/readiness'
import {
  affordanceOf,
  isCellEditable,
  isOperatorEdit,
  offersCascade,
  channelWriteGate,
  aliasReadinessPct,
  bandRowOf,
  dataPathFor,
  distinctVariantCount,
  orderRows,
  summariseAlias,
  variantRowsOf,
  isRevealAnchor,
  withMappingRun,
  withRowIdentity,
} from './rows'
import { aliasKeyOf, type AliasGroup, type StudioCellValue, type StudioRow } from './types'

const alias = (id: string | null, position: number, over: Partial<AliasGroup> = {}): AliasGroup => ({
  id,
  label: id === null ? 'Primary' : `Listing ${position}`,
  position,
  status: 'ACTIVE',
  externalListingId: id === null ? '257584954808' : `25656610${position}20`,
  listingStatus: 'ACTIVE',
  isPublished: true,
  readiness: { percent: 100, state: 'ready', errors: 0, warnings: 0, rowsMissingRequired: 0 },
  rowIds: [],
  ...over,
})

const row = (aliasId: string | null, id: string, rowKind: 'parent' | 'variant'): StudioRow => ({
  id,
  sku: id,
  name: null,
  parentId: rowKind === 'variant' ? 'GALE-JACKET' : null,
  isParent: rowKind === 'parent',
  status: 'ACTIVE',
  productType: 'OUTERWEAR',
  version: 1,
  childCount: rowKind === 'parent' ? 3 : 0,
  aliasId,
  rowKind,
  values: {},
  readiness: { state: 'ready', issues: [] },
  basePrice: null,
  listing: null,
  completeness: { overall: { filled: 0, total: 0, pct: 0 }, required: { filled: 0, total: 0, missing: [] }, byGroup: [] },
})

const SKUS = ['GALE-BLACK-M', 'GALE-BLACK-L', 'GALE-YELLOW-M']
const ALIASES = [alias(null, 0), alias('a1', 1), alias('a2', 2)]
const RAW: StudioRow[] = ALIASES.flatMap((a) => [
  row(a.id, 'GALE-JACKET', 'parent'),
  ...SKUS.map((s) => row(a.id, s, 'variant')),
])
const ROWS = withRowIdentity(RAW, ALIASES)

describe('row identity — the same SKU under N aliases is N rows', () => {
  it('gives every row a unique id even though product ids repeat', () => {
    const ids = ROWS.map((r) => r.rowId)
    expect(new Set(ids).size).toBe(ids.length)
    // The product id genuinely repeats: that is why rowId exists.
    expect(new Set(ROWS.map((r) => r.id)).size).toBeLessThan(ids.length)
  })

  it('keys the PRIMARY listing like any other group, with no special case', () => {
    expect(aliasKeyOf(null)).toBe('primary')
    expect(ROWS.some((r) => r.rowId.startsWith('primary:'))).toBe(true)
  })

  it('copies each group position onto its rows', () => {
    expect(ROWS.find((r) => r.aliasId === 'a2')?.aliasPosition).toBe(2)
    expect(ROWS.find((r) => r.aliasId === null)?.aliasPosition).toBe(0)
  })
})

describe('counts that cross aliases are SKU counts, never quantities', () => {
  it('does not scale with the number of aliases', () => {
    expect(distinctVariantCount(ROWS)).toBe(3)
    const withFourth = withRowIdentity(
      [...RAW, row('a3', 'GALE-JACKET', 'parent'), ...SKUS.map((s) => row('a3', s, 'variant'))],
      [...ALIASES, alias('a3', 3)],
    )
    // Twelve visible variant rows, still three SKUs.
    expect(withFourth.filter((r) => r.rowKind === 'variant')).toHaveLength(12)
    expect(distinctVariantCount(withFourth)).toBe(3)
  })

  it('exposes NO quantity/stock total anywhere in the module (PES.5 §3.2)', () => {
    // A standing guard, not a comment: "never summed" is the kind of rule a later refactor breaks
    // silently while every screen still looks plausible.
    expect(rowsModule.assertNoQuantitySummation(rowsModule)).toEqual([])
  })
})

describe('grouping', () => {
  it('paths a leaf under its alias and the band as the group node', () => {
    const band = ROWS.find((r) => r.rowKind === 'parent' && r.aliasId === 'a1')!
    const leaf = ROWS.find((r) => r.rowKind === 'variant' && r.aliasId === 'a1')!
    expect(dataPathFor(band)).toEqual(['a1'])
    expect(dataPathFor(leaf)).toEqual(['a1', leaf.rowId])
  })

  it('finds a group own band and children', () => {
    expect(variantRowsOf(ROWS, 'a1')).toHaveLength(3)
    expect(bandRowOf(ROWS, 'a1')?.rowKind).toBe('parent')
