    expect(withMappingRun(c, false)).toBe(c)
  })

  it('passes undefined through rather than inventing a cell', () => {
    expect(withMappingRun(undefined, true)).toBeUndefined()
  })

  it('does not mutate the wire cell it was given', () => {
