/**
 * PES.3 — the channel scope's own chrome: the alias band and the provenance badge.
 *
 * Page-local, following the convention of `app/fleet/fleet-pages.css` — the GRID's chrome belongs in
 * the engine (feedback_grid_chrome_lives_in_the_engine) and is PES.2's to own, so nothing here
 * restyles a grid part. These rules dress two things this lane invents: the alias group band and the
 * cascade badge. Both are queued as substrate requests to PES.2 in `docs/pes-claims.md`; when the
 * substrate lands, this file shrinks to nothing and the classes come from `design-system/grid/`.
 *
 * Every colour is a `--nds-*` token — an undefined class or a raw hex is the silent kind of wrong
 * (reference_undefined_css_class_is_silent, reference_ds_channel_tokens_used_raw).
 */

/* ── The alias band ──────────────────────────────────────────────────────────────────────────── */

/* The band lives in the 240px pinned identity column (ruling #77c), so every item is sized for
   that budget: the label takes what is left after the fixed pieces, and truncates with the full
   sentence on the cell's own title. */
.nds-alias-band {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  width: 100%;
}

/* ①②③ — the alias's ordinal mark. Tabular so bands line up as the list grows. */
.nds-alias-mark {
  flex: 0 0 auto;
  font-size: var(--nds-font-size-base);
  line-height: 1;
  color: var(--nds-text-2);
  font-variant-numeric: tabular-nums;
}

/* #712 — the variant count beside the alias label. Same line, quieter than the label it follows:
   it is a reference number, not the thing an operator acts on. `font-weight: normal` rather than a
   colour, because the band already spends its colour budget on the status pill and the readiness
   bar (and a dimmed informative value is what the contrast rule refuses). */
.nds-alias-count {
  font-weight: var(--nds-font-weight-normal);
  color: var(--nds-text-2);
}

.nds-alias-label {
  flex: 0 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-weight: var(--nds-font-weight-semibold);
  color: var(--nds-text);
}

/* The channel's own id — monospace, because an ItemID/ASIN is read digit by digit. */
/* The empty-shell marker: one word, always visible. A live listing with nothing behind it is the
   single most important thing this band can say, so it never moves to a hover. */
.nds-alias-shell {
  flex: 0 0 auto;
  padding: 0 5px;
  border-radius: var(--nds-radius-pill);
  background: var(--nds-warning-soft);
  color: var(--nds-warning-text);
  font-size: var(--nds-font-size-xs);
  font-weight: var(--nds-font-weight-semibold);
}

/* Readiness bar. Pushed right so every band's bar starts at the same x and they can be compared
   down the column without reading a single number. */
.nds-alias-readiness {
  flex: 0 0 auto;
  margin-left: auto;
  /* 48px, not 96: at 240px total the bar competes with the listing's NAME, and a name an operator
     cannot read is worse than a bar they read less precisely. Exact % is on the band's title. */
  width: 48px;
  height: 6px;
  border-radius: var(--nds-radius-full);
  background: var(--nds-border-subtle);
  overflow: hidden;
}

.nds-alias-readiness-bar {
  display: block;
  height: 100%;
  border-radius: var(--nds-radius-full);
  transition: width 160ms ease;
}

/* One class per `ReadinessTone` from PES.2's `readinessMeta()` — all five, so an unrecognised
   readiness state (which it reports as `neutral`) still paints instead of vanishing. */
.nds-alias-readiness-success { background: var(--nds-success); }
.nds-alias-readiness-warning { background: var(--nds-warning); }
.nds-alias-readiness-danger  { background: var(--nds-danger); }
.nds-alias-readiness-neutral { background: var(--nds-text-3); }
.nds-alias-readiness-info    { background: var(--nds-text-2); }

.nds-alias-pct {
  flex: 0 0 auto;
  width: 34px;
  text-align: right;
  font-variant-numeric: tabular-nums;
}

/* ── The cascade badge ───────────────────────────────────────────────────────────────────────── */

.nds-cascade {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  width: 100%;
}

.nds-cascade-value {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ── The backend-not-landed notice ───────────────────────────────────────────────────────────── */

/*
 * Shown when PES.5's read is not deployed. Deliberately plain and deliberately NOT an empty grid:
 * "this product has no aliases" and "the endpoint does not exist" look identical to an operator, and
 * only one of them is a fact about the catalogue.
 */
.nds-channel-notice {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 24px;
  border: 1px dashed var(--nds-border);
  border-radius: var(--nds-radius-lg);
  color: var(--nds-text-2);
  font-size: var(--nds-font-size-sm);
}

.nds-channel-notice-title {
  font-weight: var(--nds-font-weight-semibold);
  color: var(--nds-text);
}

.nds-channel-notice code {
  font-family: var(--nds-font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-size: var(--nds-font-size-xs);
  color: var(--nds-text);
}

/* ── The per-alias publish control ───────────────────────────────────────────────────────────── */

.nds-alias-publish {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  min-width: 0;
}

/* Mapping error. The one mapping state visible without hovering: a derived value that would not
   ship. `unmapped` and a clean mapping stay in the tooltip — an icon on every cell of a fully
   mapped sheet tells the operator nothing. */
.nds-cascade-maperr {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 14px;
  height: 14px;
  border-radius: var(--nds-radius-pill);
  background: var(--nds-danger);
  color: var(--nds-text-inverse);
  font-size: 10px;
  font-weight: 700;
  line-height: 1;
}

/* The chip-hit ring lives in the ENGINE now (grid/theme/grid.css) — PES.2 hoisted it verbatim
   after check-ag-grid-import-boundary flagged this file for styling an `.ag-cell`. The rule was
   right; the LOCATION was not. Grid chrome belongs to the engine
   (feedback_grid_chrome_lives_in_the_engine), and the guard is what says so. */

/**
 * The channel toolbar's own layout.
 *
 * The DS prefsbar is a single row, which is right until a preflight answers: its verdict line and
 * the eBay preview-only sentence are long, and on screen they pushed the View chips into
 * overlapping the status text — legible in a screenshot, invisible in a diff
 * (feedback_read_the_screen_not_the_diff). So this lane's toolbar wraps instead of overflowing, and
 * every item keeps its own line box.
 */
.nds-channel-toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 12px;
  min-width: 0;
  row-gap: 8px;
}

.nds-channel-toolbar > * {
  min-width: 0;
}

/* A preflight verdict is a paragraph, not a chip — give it the full row it needs rather than
   letting it squeeze everything else. */
.nds-alias-publish {
  flex: 1 1 100%;
}

/* The `affectsAllChannels` acknowledgement (ruling #58). Full-width and unmissable on purpose: it
   is the one moment the sheet has to correct an assumption the operator has every reason to hold —
   that editing on a channel scope edits that channel. */
.nds-channel-ack {
  flex: 1 1 100%;
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  padding: 8px 12px;
  border: 1px solid var(--nds-warning);
  border-radius: var(--nds-radius-sm);
  background: var(--nds-warning-soft);
  color: var(--nds-text);
  font-size: var(--nds-font-size-sm);
}

/* #513 — the standing cross-market notice in the toolbar descriptor. Warning-toned rather than
   muted: it states that an edit here leaves the channel, which an operator must not read past. */
.cs-cross-channel-note {
  /* 🔴 `--nds-warning-text`, NOT the `--nds-color-warning-fg` I first wrote: that token does not
     exist, and an undefined token resolves to transparent with no error and no guard hit — the
     notice would have been invisible while looking deliberate. Verified against the defined set. */
  color: var(--nds-warning-text);
}

.cs-cell-details {
  display: grid;
  gap: var(--nds-space-16);
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.cs-cell-details p { margin: 0; }

apps/web/src/design-system/grid/renderer.content:
/**
 * GDS — the ONE identity band, in the engine so both sheets draw the same row (#710).
 *
 * 🔴 Why this exists. Master drew identity across THREE pinned columns — `product` (expander + P/C
 * chip + thumbnail), `sku` (180px) and `completeness` (90px) — while the channel scope drew its own
 * `__identity`. Two surfaces, two layouts, and the Owner reading the same product on both:
 * *"It must all be the same exactly, visually and all."* Three columns also meant three widths to
 * keep in step, which is how the chip came to overlap the thumbnail (#709a): each column was sized
 * on its own and none of them was sized on the content.
 *
 * One component, one content-derived width, one row kind. A lane composes it by passing nodes; it
 * does not re-implement the layout, and it cannot drift from the other scope because there is only
 * one of these.
 *
 * The ORDER is fixed here on purpose — expander, role, picture, identity text, state — because that
 * order is the thing being made identical. What each slot CONTAINS is the lane's business: master
 * passes a P/C chip and a product name, a channel passes its alias mark and the axis values.
 */
import { memo, type ReactNode } from 'react'
import { MoreHorizontal } from 'lucide-react'

/* The DS `Thumbnail`, the same one `IdentityCell` draws — not a lookalike. */
import { Menu, Thumbnail, type MenuItemDef } from '../../components'
import { readyPillTone, type RowReadinessState } from './readiness'

export interface IdentityBandProps {
  /**
   * The tree control. A parent gets `ExpandButton`, a leaf gets `ExpandSlot` — never nothing, or
   * the SKUs in a family start on two different x positions and the column reads ragged.
   */
  expand?: ReactNode
  /** Who this row is: `P`/`C` on master, the primary/alias mark on a channel. */
  role?: ReactNode
  image?: string | null
  photoCount?: number
  /**
   * A BAND row carries no picture — an alias header is about the listing, not about one variant, and
   * a thumbnail there claims the band owns an image it does not have.
   */
  noImage?: boolean
  /**
   * A mark ABOUT THE PICTURE, drawn beside it — master's "inherited" glyph when a variation is
   * showing the family's image. It is not part of `role`: `role` says what the ROW is, this says
   * whose the photograph is, and a quarter of children have no image of their own.
   */
  imageMark?: ReactNode
  /** The key, monospace. Never edited here. */
  sku: ReactNode
  /** The second line: the product name on master, the axis values where the family varies. */
  secondary?: ReactNode
  /** Full text for the second line when it truncates. */
  secondaryTitle?: string
  /** Pinned RIGHT: readiness, and any state pill the scope owns. */
  trailing?: ReactNode
  /**
   * The row's verb menu, rendered as the LAST trailing item (#724).
   *
   * 🔴 In the band, not in a column of its own. A 56px `actions` column exists only to hold a `⋯`
   * that is already at the row's identity — and it is the difference between master's pinned set and
   * the channel's, which is the thing #710 exists to remove. The DS `Menu` with an icon Button
   * trigger, the same shape `ActionsCell` uses: one menu convention, not a second.
   */
  menuItems?: MenuItemDef[]
  /** Accessible name for the `⋯` trigger — a menu whose button is unnamed is unreachable by name. */
  menuLabel?: string
}

export const IdentityBand = memo(function IdentityBand({
  expand, role, image, photoCount, noImage, imageMark, sku, secondary, secondaryTitle, trailing,
  menuItems, menuLabel,
}: IdentityBandProps) {
  return (
    <div className="nds-identity-band">
      {expand}
      {role}
      {!noImage && (
        <span className="nds-identity-band-pic">
          <Thumbnail src={image ?? null} photoCount={photoCount} alt="" />
          {imageMark}
        </span>
      )}
      <span className="nds-identity-band-text">
        <span className="nds-identity-band-sku">{sku}</span>
        {secondary != null && secondary !== '' && (
          <span className="nds-identity-band-sub" title={secondaryTitle}>{secondary}</span>
        )}
      </span>
      {(trailing != null || (menuItems && menuItems.length > 0)) && (
        <span className="nds-identity-band-trail">
          {trailing}
          {menuItems && menuItems.length > 0 && (
            <Menu
              label={<MoreHorizontal size={15} />}
              items={menuItems}
              align="right"
              triggerProps={{ className: 'nds-btn sm icon', 'aria-label': menuLabel ?? 'Row actions' }}
            />
          )}
        </span>
      )}
    </div>
  )
})

export interface CompletenessPillProps {
  /** 0–100. `null` renders nothing rather than a confident 0. */
  pct: number | null | undefined
  /**
   * 🔴 The COLOUR comes from here, never from `pct` (ruling #43; regression found by PES.3 on
   * adoption, #727).
   *
   * The first version computed its own tone from the percentage — `100 → full, <40 → low`. That
   * reverses #43: a high percentage does not mean a listing can publish. Measured on Amazon·DE, an
   * alias in state `errors` at 84% painted neutral grey while the pill's own `aria-label` said
   * "Error" — one control making two statements about one listing.
   *
   * The percentage now drives only the bar's LENGTH and the number. `undefined` means "this ratio
   * has no readiness behind it" — master completeness — and paints neutral.
   */
  state?: RowReadinessState | null
  /** The hover sentence — what the number is a ratio OF. */
  tip?: string
}

/**
 * Readiness as a bar AND a number, pinned to the band's right edge.
 *
 * 🔴 Both, not either. The bar alone cannot be read precisely and fails anyone who cannot separate
 * its two colours; the number alone gives no sense of a row's progress against the rows above it,
 * which is the thing an operator scans a column of these for. The pair is also why this replaced a
 * 90px numeric column rather than moving it: the column could show `21%` and nothing else.
 *
 * `aria-label` carries the same sentence as the tooltip, because the bar is a graphic and the
 * percentage beside it is the only text — a screen reader gets the ratio, not a bare "21%".
 */
export const CompletenessPill = memo(function CompletenessPill({ pct, state, tip }: CompletenessPillProps) {
  if (pct == null || Number.isNaN(pct)) return null
  /* Clamp, because this is drawn from a server ratio and a width of `-4%` or `130%` paints outside
     its own track. Rounding once here keeps the bar and the number telling the same story — a bar
     drawn from 20.6 beside a label reading 21 is a small lie that is very hard to see. */
  const value = Math.max(0, Math.min(100, Math.round(pct)))
  const tone = readyPillTone(state)
  return (
    <span
      className={`nds-readypill nds-readypill-${tone}`}
      role="img"
      aria-label={tip ?? `${value}% complete`}
      title={tip}
    >
      <span className="nds-readypill-track">
        <span className="nds-readypill-fill" style={{ width: `${value}%` }} />
      </span>
      <span className="nds-readypill-num">{value}%</span>
    </span>
  )
})

