import { CONTENT_COLUMNS, PRIMARY_CONTENT_LOCALE } from './content-locale.js'
import { normalizeLanguage } from './content-language.js'
import { resolveContent, resolveContentBatch, translationMissing, type ContentListing, type ContentProduct, type Coordinate, type ResolvedContent } from './content-resolver.js'
import type { ResolvedValue } from './attribute-resolver.js'

type Row = Record<string, any>
export function contentLanguages(product: Row, parent?: Row | null): string[] {
  return [...new Set([PRIMARY_CONTENT_LOCALE, ...[product, parent].flatMap(owner => (owner?.translations ?? []).map((row: Row) => normalizeLanguage(row.language)))])]
}
export function contentKeys(product: Row, parent?: Row | null, declared: readonly string[] = []): string[] {
  return [...new Set([...Object.keys(CONTENT_COLUMNS), ...declared, ...[product, parent].flatMap(owner => (owner?.translations ?? []).flatMap((row: Row) => Object.keys(row.attributes ?? {})))])]
}
export function contentListing(product: Row, listing?: Row | null, coordinate?: Coordinate, languages?: readonly string[]): ContentListing | null {
  if (!listing) return null
  const address = coordinate ?? listing.coordinate ?? (listing.channel && (listing.marketplace || listing.region) ? {
    channel: listing.channel, market: !listing.marketplace || listing.marketplace === 'DEFAULT' ? listing.region : listing.marketplace,
    ...(listing.channelConnectionId ? { accountId: listing.channelConnectionId } : {}), ...(listing.aliasId || listing.aliasKey ? { aliasId: listing.aliasId ?? listing.aliasKey } : {}),
  } : undefined)
  const ordered = languages ?? listing.languages
  if (!address || !ordered?.length) throw new Error('Content listing reads require a coordinate and hydrated Marketplace.languages.')
  return { id: listing.id, productId: listing.productId ?? product.id, workspaceId: listing.workspaceId, coordinate: address, languages: ordered,
    translations: listing.translations, title: listing.title, description: listing.description,
    titleOverride: listing.titleOverride, descriptionOverride: listing.descriptionOverride, bulletPointsOverride: listing.bulletPointsOverride,
    followMasterTitle: listing.followMasterTitle, followMasterDescription: listing.followMasterDescription, followMasterBulletPoints: listing.followMasterBulletPoints }
}
/** Existing wire names retained; the resolver supplies their facts once. */
export function contentAttribute(content: ResolvedContent, productId: string, parentId?: string | null): ResolvedValue {
  const source = content.tier === 'pin' ? content.follows ? 'channelSnapshot' : 'channelExplicit'
    : content.tier === 'language' ? parentId ? 'variantLocale' : 'masterLocale' : content.tier === 'source' ? 'masterColumn' : 'default'
  const translationState = translationMissing(content, content.requested) ? 'fallback'
    : content.translation?.outdated ? 'outdated' : content.translation?.reviewedAt ? 'reviewed'
    : content.translation && content.translation.source !== 'manual' ? 'draft' : 'current'
  return { value: content.value, source, inheritedFrom: content.tier === 'pin' ? content.provenance.from : content.ownerId ?? productId,
    requestedLocale: content.requested, effectiveLocale: content.language, language: content.language, requested: content.requested,
    translationState, tier: content.tier, follows: content.follows, drift: content.drift, contentProvenance: content.provenance }
}
export function resolveContentAttributes(input: { product: Row; parent?: Row | null; listing?: Row | null; coordinate?: Coordinate; languages?: readonly string[]; requested: string; localizableKeys?: readonly string[] }): Record<string, ResolvedValue> {
  const listing = contentListing(input.product, input.listing, input.coordinate, input.languages)
  const fields = contentKeys(input.product, input.parent, input.localizableKeys)
  const resolved = resolveContentBatch({ members: [{ product: input.product as ContentProduct, parent: input.parent as ContentProduct,
    listing, localizableKeys: fields }], fields, addresses: [{ requested: input.requested, ...(listing ? { coordinate: listing.coordinate } : input.coordinate ? { coordinate: input.coordinate } : {}) }] })[0].fields
  return Object.fromEntries(Object.entries(resolved).map(([key, value]) => [key, contentAttribute(value, input.product.id, input.product.parentId)]))
}

/** R10: raw resolver absence must not change an established list-shaped sheet/API wire. */
export function contentWireValue(value: unknown, shape?: string): unknown {
  return shape === 'list' && value == null ? [] : value
}

/** Store readers require the same hydrated product and market authority as the sheet. */
export function listingContentState(listing: Row, requested: string, field: string, localizableKeys: readonly string[] = []) {
  if (!listing.product) throw new Error('Listing content requires its hydrated product and translations.')
  const owner = listing.product
  const hydrated = contentListing(owner, listing)!
  return resolveContent({ product: owner, parent: owner.parent, listing: hydrated, localizableKeys,
    field, address: { requested: normalizeLanguage(requested), coordinate: hydrated.coordinate } })
}

apps/api/src/services/pim/attribute-reso.content:
/** Factual attributes keep the parent/variant/channel cascade.
 * Localizable content is overlaid once by resolveContent (pin → language → source → computed).
 * The legacy Product JSON and outbound attribute bags never supply content values.
 */

// ────────────────────────────────────────────────────────────────────
// Types
// ────────────────────────────────────────────────────────────────────

/** Origin of a resolved value. UI uses this to style inheritance. */
import { ALLOWED_MASTER_FIELDS } from './master-field-gate.js'
import { PRIMARY_CONTENT_LOCALE } from './content-locale.js'
import { normalizeLanguage } from './content-language.js'
import { resolveContentAttributes } from './content-read.js'
import type { Coordinate, ResolvedContent } from './content-resolver.js'
import { canonicalVariantAxis } from './variant-attribute-keys.js'

export type ValueSource =
  | 'master'           // came from parent Product.categoryAttributes
  | 'masterLocale'     // shared ProductTranslation row
  | 'masterColumn'     // synthesized from a legacy Product column (A.4 compat layer)
  | 'variant'          // came from variant child Product
  | 'variantLocale'    // variant ProductTranslation row
  | 'channelOverride'  // came from ChannelListing.overrideData
  | 'channelSnapshot' // a following legacy listing value; drift, never an operator pin
  | 'channelExplicit'  // came from titleOverride / priceOverride / etc.
  | 'default'          // none of the above set a value

/** Per-key resolution result. */
export interface ResolvedValue<T = unknown> {
  value: T | null
  source: ValueSource
  /** The Product/ChannelListing id this value came from. Null when
   *  source is 'default'. Used by error→editor deep linking to route
   *  the operator to the right entity. */
  inheritedFrom: string | null
  language?: string
  requested?: string
  tier?: ResolvedContent['tier']
  follows?: boolean
  drift?: boolean
  contentProvenance?: ResolvedContent['provenance']
  warnings?: string[]
  requestedLocale?: string
  effectiveLocale?: string
  translationState?: 'current' | 'fallback' | 'draft' | 'reviewed' | 'outdated' | 'missing'
}

/** Minimal Product shape the resolver needs. Pulled from Prisma but
 *  retyped here so the resolver is independent of generated types. */
export interface ProductLike {
  id: string
  parentId: string | null
  categoryAttributes: Record<string, unknown> | null
  localizedContent: Record<string, Record<string, unknown>> | null
  variantAttributes: Record<string, unknown> | null
  // ── A.4 legacy-column synthesis sources ─────────────────────────
  // Optional because not every loader hydrates them. When `synthesize:
  // true` (default) AND the corresponding JSONB key is missing, the
  // resolver returns these with source='masterColumn'. Removable once
  // all writes populate localizedContent + categoryAttributes.
  translations?: Array<Record<string, unknown>>
  name?: string | null
  description?: string | null
  bulletPoints?: string[]
  keywords?: string[]
  brand?: string | null
  manufacturer?: string | null
  countryOfOrigin?: string | null
  basePrice?: number | string | null
}

/** Minimal ChannelListing shape. All explicit-override fields are
 *  optional because not every listing row has every override. */
export interface ChannelListingLike {
  id: string
  overrideData: Record<string, unknown> | null
  // SSOT toggles + override columns (Phase 20):
  followMasterTitle?: boolean
  followMasterDescription?: boolean
  followMasterPrice?: boolean
  followMasterQuantity?: boolean
  followMasterBulletPoints?: boolean
  followMasterImages?: boolean
  titleOverride?: string | null
  descriptionOverride?: string | null
  priceOverride?: number | string | null
  quantityOverride?: number | null
  bulletPointsOverride?: string[]
  // Direct columns (used when SSOT toggles aren't present — legacy):
  title?: string | null
  description?: string | null
  price?: number | string | null
  quantity?: number | null
}

export interface ResolveInput {
  coordinate?: Coordinate
  marketLanguages?: readonly string[]
  localizableKeys?: string[]
  /** The product (or variant child Product) being resolved. */
  product: ProductLike
  /** Optional parent — required when product.parentId is set, ignored
   *  otherwise. Pass null for top-level products. */
  parent: ProductLike | null
  /** Optional channel listing (channel × marketplace). When omitted,
   *  resolution stops at variant level. */
  channelListing?: ChannelListingLike | null
  /** Requested language; defaults to PRIMARY_CONTENT_LOCALE. */
  locale?: string
  /** A.4 — Fill in missing keys from legacy Product columns
   *  (name → title, description → description, etc.). Default true.
   *  Only fires for the default locale ('en') so non-en queries don't
   *  receive English text mislabeled as the requested locale. Pass
   *  false to get strict JSONB-only behaviour (useful for "what's
   *  ACTUALLY been authored in JSONB" diagnostics). */
  synthesize?: boolean
}

export type ResolvedAttributes = Record<string, ResolvedValue>

// ────────────────────────────────────────────────────────────────────
// Internal helpers
// ────────────────────────────────────────────────────────────────────


/** Mapping of SSOT-tracked field name → its follow-master flag +
 *  override column. Keeps the special-case logic in one table. */
const SSOT_FIELDS = [
  { key: 'title',        followFlag: 'followMasterTitle',        overrideCol: 'titleOverride',        directCol: 'title' },
  { key: 'description',  followFlag: 'followMasterDescription',  overrideCol: 'descriptionOverride',  directCol: 'description' },
  { key: 'price',        followFlag: 'followMasterPrice',        overrideCol: 'priceOverride',        directCol: 'price' },
  { key: 'quantity',     followFlag: 'followMasterQuantity',     overrideCol: 'quantityOverride',     directCol: 'quantity' },
  { key: 'bulletPoints', followFlag: 'followMasterBulletPoints', overrideCol: 'bulletPointsOverride', directCol: null },
] as const

/** A.4 — legacy Product columns the resolver can synthesize into
 *  attribute keys when the JSONB layers don't supply them. Each entry
 *  is (resolver-key → ProductLike column). Only consulted when
 *  synthesize=true AND the query is for the default locale, so non-en
 *  queries don't receive English text mislabeled. Remove an entry
 *  once 100% of writes for that key go through localizedContent. */
const SYNTHESIS_MAP: Array<{
  resolverKey: string
  column: keyof ProductLike
}> = [
  { resolverKey: 'brand',        column: 'brand' },
  { resolverKey: 'manufacturer', column: 'manufacturer' },
  { resolverKey: 'basePrice',    column: 'basePrice' },
]

/** Apply a layer of key/values onto the accumulator. A `null` value in
 *  the layer means "explicit null" (still overrides); `undefined`
 *  means "key absent" (no-op). Caller-controlled source/inheritedFrom. */
function applyLayer(
  acc: ResolvedAttributes,
  layer: Record<string, unknown> | null | undefined,
  source: ValueSource,
  inheritedFrom: string | null,
  locale?: string,
): void {
  if (!layer || typeof layer !== 'object') return
  for (const [key, value] of Object.entries(layer)) {
    if (value === undefined) continue
    if (locale && key.startsWith('_')) continue
    acc[key] = { value, source, inheritedFrom, ...(locale ? { requestedLocale: locale, effectiveLocale: locale, translationState: 'current' as const } : {}) }
  }
}

/** Legacy variation labels remain addressable while supplying the canonical Master axes.
 * An explicit canonical value wins. Conflicting aliases never choose a value by key order. */
function applyVariantLayer(acc: ResolvedAttributes, product: ProductLike): void {
  const variations = product.categoryAttributes?.variations
  const bag = { ...(product.variantAttributes && typeof product.variantAttributes === 'object' ? product.variantAttributes : {}),
    ...(variations && typeof variations === 'object' && !Array.isArray(variations) ? variations : {}) }
  applyLayer(acc, bag, 'variant', product.id)
  if (!bag || typeof bag !== 'object' || Array.isArray(bag)) return
  // Legacy "Body Type" is not a stable identity: imports also use it for gender.
  for (const axis of ['color', 'size', 'style']) {
    if (Object.prototype.hasOwnProperty.call(bag, axis) && bag[axis] !== undefined) continue
    const matches = Object.entries(bag).filter(([key, value]) => canonicalVariantAxis(key) === axis && value !== undefined)
    if (!matches.length) continue
    const conflict = new Set(matches.map(([, value]) => JSON.stringify(value))).size > 1
    acc[axis] = { value: conflict ? null : matches[0][1], source: 'variant', inheritedFrom: product.id,
      ...(conflict ? { warnings: [`Conflicting variant attributes supply ${axis}: ${matches.map(([key]) => key).join(', ')}. Set the canonical ${axis} attribute to resolve the conflict.`] } : {}) }
  }
}

/** A.4 — Apply the legacy-column synthesis layer for one Product.
 *  Lowest-precedence layer for that entity; later JSONB layers from
 *  the same entity overwrite it, and a higher-precedence entity
 *  (variant > parent, channel > variant) overwrites it. inheritedFrom
 *  carries "<productId>:<columnName>" so the UI can link back to the
 *  exact field, not just the entity. */
function applySynthesisLayer(
  acc: ResolvedAttributes,
  source: ProductLike,
  locale: string,
): void {
  for (const { resolverKey, column } of SYNTHESIS_MAP) {
    const value = (source as unknown as Record<string, unknown>)[column as string]
    if (value === undefined || value === null || value === '') continue
    // Empty arrays count as "no data" for synthesis — they'd otherwise
    // mask a real bulletPoints write further up the merge stack.
    if (Array.isArray(value) && value.length === 0) continue
    acc[resolverKey] = {
      value,
      source: 'masterColumn',
      inheritedFrom: `${source.id}:${column as string}`,
      ...(['title', 'description', 'bulletPoints', 'keywords'].includes(resolverKey)
        ? { requestedLocale: locale, effectiveLocale: PRIMARY_CONTENT_LOCALE, translationState: locale === PRIMARY_CONTENT_LOCALE ? 'current' as const : 'fallback' as const } : {}),
    }
  }
}

/** Shared native facts have no content locale. Their canonical column wins over legacy aliases. */
function applyCanonicalFacts(acc: ResolvedAttributes, product: ProductLike): void {
  for (const key of ALLOWED_MASTER_FIELDS) {
    if (['description', 'bulletPoints', 'keywords'].includes(key)) continue
    let value = (product as unknown as Record<string, unknown>)[key]
    if (value === undefined || value === null || value === '' || Array.isArray(value) && value.length === 0) continue
    // Prisma decimal columns must remain numeric in in-process validation, before JSON serialization.
    if (typeof value === 'object' && typeof (value as { toNumber?: unknown }).toNumber === 'function') value = (value as { toNumber(): number }).toNumber()
    acc[key] = { value, source: 'masterColumn', inheritedFrom: product.id }
  }
}

// ────────────────────────────────────────────────────────────────────
// Public API
// ────────────────────────────────────────────────────────────────────

/**
 * Resolve all attributes for the given (product, variant?, channel?,
 * locale?) tuple.
 *
 * Returns a flat map of attribute-key → {value, source, inheritedFrom}.
 * Keys that aren't set anywhere don't appear in the result; the caller
 * decides whether absence means "not applicable" or "use schema default".
 */
export function resolveAttributes(input: ResolveInput): ResolvedAttributes {
  const { product, parent, channelListing, synthesize = true } = input
  const locale = normalizeLanguage(input.locale ?? PRIMARY_CONTENT_LOCALE)
  const acc: ResolvedAttributes = {}
  // Language-independent facts retain their established parent/variant/override rules.
  for (const owner of [parent, product]) {
    if (!owner) continue
    if (synthesize) applySynthesisLayer(acc, owner, locale)
    if (owner === product) applyVariantLayer(acc, product)
    applyLayer(acc, owner.categoryAttributes, owner === product && parent ? 'variant' : 'master', owner.id)
    if (synthesize) applyCanonicalFacts(acc, owner)
    if (owner.countryOfOrigin) applyLayer(acc, { countryOfOrigin: owner.countryOfOrigin, country_of_origin: owner.countryOfOrigin }, 'masterColumn', owner.id)
  }
  if (synthesize) {
    const origin = acc.countryOfOrigin ?? acc.country_of_origin
    if (origin) { acc.countryOfOrigin = origin; acc.country_of_origin = origin }
  }
  if (channelListing) {
    applyLayer(acc, channelListing.overrideData, 'channelOverride', channelListing.id)
    for (const ssot of SSOT_FIELDS.filter(field => ['price', 'quantity'].includes(field.key))) {
      if ((channelListing as any)[ssot.followFlag] !== false) continue
      const value = (channelListing as any)[ssot.overrideCol] ?? (ssot.directCol ? (channelListing as any)[ssot.directCol] : undefined)
      if (value !== undefined) acc[ssot.key] = { value, source: 'channelExplicit', inheritedFrom: channelListing.id }
    }
  }
  // Text has exactly one cascade. It overwrites any historical untagged text aliases in fact bags.
  Object.assign(acc, resolveContentAttributes({ product, parent, listing: channelListing, coordinate: input.coordinate,
    languages: input.marketLanguages, requested: locale, localizableKeys: input.localizableKeys }))
  return acc
}

/** Convenience wrapper: resolve and return a flat key→value map,
 *  discarding provenance. Use this in publish pipelines / payload
 *  generators where you only need the merged data. */
export function resolveAttributesFlat(input: ResolveInput): Record<string, unknown> {
  const resolved = resolveAttributes(input)
  const flat: Record<string, unknown> = {}
  for (const [k, v] of Object.entries(resolved)) {
    flat[k] = v.value
  }
  return flat
}

/** Convenience: return only the keys whose source matches one of the
 *  given origins. Useful for "show me only what this channel overrides". */
export function resolveAttributesBySource(
  input: ResolveInput,
  sources: ValueSource[],
): ResolvedAttributes {
  const resolved = resolveAttributes(input)
  const out: ResolvedAttributes = {}
  const allow = new Set(sources)
  for (const [k, v] of Object.entries(resolved)) {
    if (allow.has(v.source)) out[k] = v
  }
  return out
}

apps/api/src/services/pim/resolve-channe.content:
/**
 * FM.2 — Unified channel-field resolver.
 *
 * The single per-coordinate read-path for "what value should channel
 * field F carry for this (product, channel, marketplace, variant?)",
 * composing the FM.1 catalog mapping rule (source/fallback + transforms)
 * with the FL per-product link groups and per-coordinate overrides, and
 * returning the value + provenance + flags. preview / validate (today)
 * and cascade / sync (FM.5–FM.8) all call this so "what you preview" ==
 * "what ships".
 *
 * This module is the leaf "core": it owns the shared primitives
 * (resolveSourcePath, applyTransforms, isPresent) that publish-validator
 * (D.5) and payload-preview (D.6) previously defined locally. They now
 * import from here, which keeps a single source of truth for path
 * resolution + transforms and avoids an import cycle.
 *
 * Precedence (highest → lowest):
 *   1. missing      source + fallback + default all empty (surfaced so
 *                   validation can block on required fields)
 *   2. locked       identity field pinned to master (GTIN/SKU/brand)
 *   3. override      per-coordinate pin — the rule's source resolved to a
 *                   ChannelListing *Override / overrideData value
 *                   (detected via attribute-resolver provenance)
 *   4. linked        coordinate is a FieldLinkGroup member (value tracks
 *                   master; cross-language TRANSLATE flags needsTranslation)
 *   5. fallback      rule.source empty → rule.fallback supplied the value
 *   6. default       a `default` transform fired on an empty source
 *   7. catalogRule   value mapped from master via rule.source + transforms
 *
 * VALUE INVARIANT (FM.2): the resolved value equals the legacy
 * (resolveSourcePath → applyTransforms) result in every case. The link
 * layer only enriches provenance + needsTranslation; a FieldLinkGroup
 * stores no canonical value (linked members track master, translated at
 * propagation time — FM.5). This is what lets payload-preview's existing
 * `source`/`payload`/`missingRequired` output stay byte-identical while
 * the richer `provenance`/`needsTranslation` ride alongside.
 */

import { contentField, contentPathAddress, resolveContentPath, translationMissing, type ContentProduct } from './content-resolver.js'
import { contentAttribute } from './content-read.js'
import { normalizeLanguage } from './content-language.js'
import type { ResolvedAttributes, ValueSource } from './attribute-resolver.js'
import type { FieldMappingRule, TransformOp } from './schema-mapping.service.js'
import { evaluateExpr, exprDependencies } from './mapping/expr.js'

// ────────────────────────────────────────────────────────────────────
// Shared primitives (moved here from publish-validator / payload-preview)
// ────────────────────────────────────────────────────────────────────

/** Empty = null/undefined, '' (after trim), or []. 0 and false are NOT
 *  empty (a real price/flag value). */
export function isPresent(v: unknown): boolean {
  if (v === null || v === undefined) return false
  if (typeof v === 'string' && v.trim() === '') return false
  if (Array.isArray(v) && v.length === 0) return false
  return true
}

/**
 * Resolve a dotted source path like 'localizedContent.{locale}.title'
 * against the flat resolver output. The resolver already merges every
 * layer into one shape so this is just a key-path walk + {locale}
 * substitution.
 *
 * Supported syntax:
 *   - `title`                              top-level resolver key
 *   - `localizedContent.{locale}.title`    {locale} substituted; the
 *                                          path then walks into the
 *                                          original Product object
 *   - `categoryAttributes.material`        walks into raw Product field
 *   - `variantAttributes.Color`            ditto
 */
export function resolveSourcePath(
  path: string,
  resolved: Record<string, unknown>,
  product: { localizedContent?: unknown; categoryAttributes?: unknown; variantAttributes?: unknown; [key: string]: any },
  locale: string,
): unknown {
  if (!path || typeof path !== 'string') return null
  locale = normalizeLanguage(locale)
  const substituted = path.replace(/\{locale\}/g, locale)
  const field = substituted.startsWith('localizedContent.') ? substituted.split('.')[2] : undefined
  const address = contentPathAddress(path, locale, field ? [field] : [])
  if (address) {
    // The flat map already carries the listing/parent result for this address.
    // An explicit different-language source is resolved afresh from hydrated rows.
    let value: unknown = address.requested === locale && Object.prototype.hasOwnProperty.call(resolved, address.field)
      ? resolved[address.field]
      : resolveContentPath({ product: product as ContentProduct, parent: product.parent, path,
          listing: product.contentListing, localizableKeys: field ? [field] : [], address: { requested: locale, ...(product.contentListing ? { coordinate: product.contentListing.coordinate } : {}) } })?.value ?? null
    if (address.requested === locale && Object.prototype.hasOwnProperty.call(resolved, address.field)) {
      for (const key of address.tail) value = value && typeof value === 'object' ? (value as Record<string, unknown>)[key] ?? null : null
    }
    return value
  }

  // Single-segment paths read straight from the resolved map.
  if (!substituted.includes('.')) {
    return resolved[substituted] ?? null
  }

  // Multi-segment paths walk into the raw Product structure. This lets
  // mapping rules use deep paths even when the resolver didn't lift the
  // key into its top-level shape.
  const segments = substituted.split('.')
  const root = segments[0]
  const rest = segments.slice(1)

  let cursor: unknown
  switch (root) {
    case 'categoryAttributes':
      // Attribute-bag paths still follow the parent/variant cascade. Reading the raw
      // child bag here discarded inherited Master facts for otherwise valid mappings.
      cursor = Object.prototype.hasOwnProperty.call(resolved, rest[0])
        ? { ...(product.categoryAttributes as Record<string, unknown> ?? {}), [rest[0]]: resolved[rest[0]] }
        : product.categoryAttributes
      break
    case 'variantAttributes':
      cursor = Object.prototype.hasOwnProperty.call(resolved, rest[0])
        ? { ...(product.variantAttributes as Record<string, unknown> ?? {}), [rest[0]]: resolved[rest[0]] }
        : product.variantAttributes
      break
    default:
      // Unknown root → try resolved map first (handles `title.foo`
      // style paths where `title` resolved to an object).
      cursor = resolved[root] ?? null
  }

  for (const seg of rest) {
    if (cursor === null || cursor === undefined || typeof cursor !== 'object') return null
    cursor = (cursor as Record<string, unknown>)[seg]
  }
  return cursor ?? null
}

/**
 * Lookup/format context for the FM.3 data-backed transform ops. All
 * fields optional: when absent, valueMap/sizeScale no-op with a warning
 * (the FM.4 store + FM.9 manifest wire them up) and template/channelLimit
 * fall back to their inline inputs.
 */
export interface TransformContext {
  /** Flat resolved attribute values, for {{attr}} template interpolation. */
  values?: Record<string, unknown>
  /** FM.4 — canonical value → channel/market value (e.g. Rosso → Red);
   *  null on a miss. */
  lookupValueMap?: (attribute: string, fromValue: string) => string | null
  /** FM.4 — size across systems (e.g. EU 52 → UK "L"); null on a miss. */
  lookupSizeScale?: (scale: string, from: string, to: string, value: string) => string | null
  /** FM.9 — channel field max length from the manifest, for channelLimit. */
  maxLength?: number
  /** PES.6 — resolve a saved business rule name to its expression body
   *  (`MarketplaceSchemaMapping.expressions`). Absent = `rule("…")` and `ref` both
   *  report "no business rule named …" rather than resolving to nothing. */
  namedExpression?: (name: string) => string | undefined
  /** PES.6 — resolve a dotted `$path` for the expression engine. When absent the
   *  engine falls back to the flat `values` map, which covers single-segment paths
   *  only; the callers that own a Product pass the full path resolver. */
  lookupPath?: (path: string) => unknown
}

// ── FM.3 transform helpers (pure) ───────────────────────────────────

// Unit conversion via a base unit per dimension. Returns null when the
// two units aren't in the same known dimension.
const WEIGHT_TO_GRAMS: Record<string, number> = { mg: 0.001, g: 1, kg: 1000, oz: 28.349523125, lb: 453.59237 }
const LENGTH_TO_MM: Record<string, number> = { mm: 1, cm: 10, m: 1000, in: 25.4, ft: 304.8 }

function convertUnit(value: number, from: string, to: string): number | null {
  const f = from.toLowerCase()
  const t = to.toLowerCase()
  for (const table of [WEIGHT_TO_GRAMS, LENGTH_TO_MM]) {
    if (f in table && t in table) return (value * table[f]) / table[t]
  }
  return null
}

function formatNumber(
  n: number,
  decimals: number | undefined,
  decimalSep: string,
  thousandsSep: string,
): string {
  const fixed = decimals != null ? n.toFixed(decimals) : String(n)
  const [intPart, fracPart] = fixed.split('.')
  const grouped = thousandsSep ? intPart.replace(/\B(?=(\d{3})+(?!\d))/g, thousandsSep) : intPart
  return fracPart != null ? `${grouped}${decimalSep}${fracPart}` : grouped
}

function interpolateTemplate(expr: string, values: Record<string, unknown>): string {
  return expr.replace(/\{\{\s*([\w.]+)\s*\}\}/g, (_m, key) => {
    const v = values[key]
    return v == null ? '' : String(v)
  })
}

/** Apply transforms in order. Each transform mutates the value;
 *  warnings collect anything that's worth surfacing without blocking
 *  (e.g. truncated content). Unknown transform types are skipped with
 *  a warning rather than throwing so a partial rule doesn't sink the
 *  whole preview. */
export function applyTransforms(
  value: unknown,
  transforms: TransformOp[] | undefined,
  warnings: string[],
  ctx?: TransformContext,
): { out: unknown; applied: TransformOp['type'][] } {
  if (!transforms || transforms.length === 0) return { out: value, applied: [] }
  let current: unknown = value
  const applied: TransformOp['type'][] = []
  for (const t of transforms) {
    try {
      switch (t.type) {
        case 'truncate': {
          if (typeof current !== 'string') {
            warnings.push(`truncate skipped — value is not a string`)
            break
          }
          const max = t.max ?? Infinity
          if (current.length > max) {
            warnings.push(`truncated from ${current.length} → ${max}`)
            current = current.slice(0, max)
          }
          applied.push('truncate')
          break
        }
        case 'titleCase':
          if (typeof current !== 'string') {
            warnings.push('titleCase skipped — value is not a string')
            break
          }
          current = current.replace(/\b\w/g, (c) => c.toUpperCase())
          applied.push('titleCase')
          break
        case 'lowerCase':
          if (typeof current !== 'string') {
            warnings.push('lowerCase skipped — value is not a string')
            break
          }
          current = current.toLowerCase()
          applied.push('lowerCase')
          break
        case 'upperCase':
          if (typeof current !== 'string') {
            warnings.push('upperCase skipped — value is not a string')
            break
          }
          current = current.toUpperCase()
          applied.push('upperCase')
          break
        case 'prepend':
          if (typeof current !== 'string') {
            warnings.push('prepend skipped — value is not a string')
            break
          }
          current = String(t.value ?? '') + current
          applied.push('prepend')
          break
        case 'append':
          if (typeof current !== 'string') {
            warnings.push('append skipped — value is not a string')
            break
          }
          current = current + String(t.value ?? '')
          applied.push('append')
          break
        case 'replace':
          if (typeof current !== 'string') {
            warnings.push('replace skipped — value is not a string')
            break
          }
          try {
            const re = new RegExp(t.pattern ?? '', 'g')
            current = current.replace(re, t.replacement ?? '')
            applied.push('replace')
          } catch (e: any) {
            warnings.push(`replace failed — invalid regex: ${e?.message ?? 'unknown'}`)
          }
          break
        case 'default':
          // `default` only fires when the current value is empty.
          if (!isPresent(current)) {
            current = t.value ?? null
            applied.push('default')
          }
          break
        // ── FM.3 ────────────────────────────────────────────────────
        case 'unit': {
          const num = typeof current === 'number' ? current : Number(current)
          if (!Number.isFinite(num)) {
            warnings.push('unit skipped — value is not numeric')
            break
          }
          const converted = convertUnit(num, t.from, t.to)
          if (converted == null) {
            warnings.push(`unit skipped — cannot convert ${t.from}→${t.to}`)
            break
          }
          current = converted
          applied.push('unit')
          break
        }
        case 'numberFormat': {
          const num = typeof current === 'number' ? current : Number(current)
          if (!Number.isFinite(num)) {
            warnings.push('numberFormat skipped — value is not numeric')
            break
          }
          current = formatNumber(num, t.decimals, t.decimalSep ?? '.', t.thousandsSep ?? '')
          applied.push('numberFormat')
          break
        }
        case 'template':
          current = interpolateTemplate(t.expr ?? '', ctx?.values ?? {})
          applied.push('template')
          break
        case 'channelLimit': {
          if (typeof current !== 'string') {
            warnings.push('channelLimit skipped — value is not a string')
            break
          }
          const max = t.max ?? ctx?.maxLength
          if (max != null && current.length > max) {
            if (t.mode === 'flag') {
              warnings.push(`exceeds channel limit ${current.length} > ${max}`)
            } else {
              warnings.push(`channel-limited from ${current.length} → ${max}`)
              current = current.slice(0, max)
            }
          }
          applied.push('channelLimit')
          break
        }
        case 'valueMap': {
          if (!ctx?.lookupValueMap) {
            warnings.push('valueMap skipped — no value-map context (FM.4)')
            break
          }
          if (current == null) break
          const mapped = ctx.lookupValueMap(t.attribute, String(current))
          if (mapped != null) {
            current = mapped
          } else if (t.onMiss === 'null') {
            current = null
          } else if (t.onMiss === 'flag') {
            warnings.push(`valueMap miss — no mapping for ${t.attribute}="${String(current)}"`)
          }
          applied.push('valueMap')
          break
        }
        case 'sizeScale': {
          if (!ctx?.lookupSizeScale) {
            warnings.push('sizeScale skipped — no size-scale context (FM.4)')
            break
          }
          if (current == null) break
          const mapped = ctx.lookupSizeScale(t.scale, t.from, t.to, String(current))
          if (mapped != null) {
            current = mapped
          } else if (t.onMiss === 'null') {
            current = null
          } else if (t.onMiss === 'flag') {
            warnings.push(`sizeScale miss — ${t.scale} ${t.from}→${t.to} "${String(current)}"`)
          }
          applied.push('sizeScale')
          break
        }
        // ── PES.6: the formula engine ───────────────────────────────
        case 'expr': {
          // An expression IGNORES the incoming value and computes from the resolved
          // attributes — an expression field normally has an empty `source`. Failures
          // land in `warnings` and null the value: a broken formula must read as
          // unresolved, never as a legitimately-empty field.
          let body = t.expr
          if (t.ref) {
            body = ctx?.namedExpression?.(t.ref)
            if (body === undefined) {
              warnings.push(`expr skipped — no business rule named "${t.ref}"`)
              current = null
              applied.push('expr')
              break
            }
          }
          if (typeof body !== 'string' || body.trim() === '') {
            warnings.push('expr skipped — the rule has neither a formula nor a business-rule name')
            applied.push('expr')
            break
          }
          const flat = ctx?.values ?? {}
          const res = evaluateExpr(body, {
            // Prefer the caller's full path resolver; fall back to the flat map so the
            // op still works for single-segment paths when no resolver was supplied.
            lookup: (path) =>
              ctx?.lookupPath ? ctx.lookupPath(path) : Object.prototype.hasOwnProperty.call(flat, path) ? flat[path] : undefined,
            namedExpression: ctx?.namedExpression,
          })
          if (res.error) {
            warnings.push(`expr failed — ${res.error}`)
            current = null
          } else {
            for (const w of res.warnings) warnings.push(`expr: ${w}`)
            current = res.value
          }
          applied.push('expr')
          break
        }
        case 'translate':
          // Deferred marker — never mutates the value inline; the resolver
          // forces needsTranslation when this op is present (FM.5 fills it).
          applied.push('translate')
          break
        default:
          warnings.push(`unknown transform type "${(t as { type: string }).type}" skipped`)
      }
    } catch (e: any) {
      warnings.push(`transform "${t.type}" threw — ${e?.message ?? 'unknown'}`)
    }
  }
  return { out: current, applied }
}

// ────────────────────────────────────────────────────────────────────
// Link-group membership
// ────────────────────────────────────────────────────────────────────

export type ChannelFieldSource =
  | 'locked'
  | 'override'
  | 'linked'
  | 'fallback'
  | 'default'
  | 'catalogRule'
  | 'missing'

/** Per-coordinate link membership for one field, derived from the
 *  product's FieldLinkGroups by linkForCoordinate(). Null when the
 *  coordinate isn't a member. */
export interface FieldLinkMembership {
  translatePolicy: 'TRANSLATE' | 'VERBATIM' | 'NONE'
  sourceLanguage: string | null
  /** The coordinate's market language, for the cross-language flag. */
  targetLanguage: string | null
}

/** Minimal FieldLinkGroup shape the resolver needs. Loaded by the caller
 *  (one findMany per product) and passed in, keeping this module pure. */
export interface FieldLinkGroupLike {
  fieldKey: string
  variantId: string | null
  translatePolicy: 'TRANSLATE' | 'VERBATIM' | 'NONE'
  sourceLanguage: string | null
  /** [{ channel, marketplace, variantId? }] — the coordinate model. */
  members: unknown
}

interface MemberCoord {
  channel: string
  marketplace: string
  variantId?: string | null
}

function membersOf(group: FieldLinkGroupLike): MemberCoord[] {
  const raw = group.members
  if (!Array.isArray(raw)) return []
  return raw.filter(
    (m): m is MemberCoord =>
      !!m && typeof m === 'object' && typeof (m as any).channel === 'string' && typeof (m as any).marketplace === 'string',
  )
}

/**
 * Resolve whether (channel, marketplace, variantId?) is a member of a
 * link group for `fieldKey`, returning the translate policy + languages
 * needed to flag cross-language translation. Returns null when not a
 * member. A coordinate belongs to ≤1 group per field (enforced by the FL
 * service layer); the first match wins defensively.
 */
export function linkForCoordinate(
  groups: FieldLinkGroupLike[],
  fieldKey: string,
  channel: string,
  marketplace: string,
  variantId: string | null | undefined,
  targetLanguage: string,
): FieldLinkMembership | null {
  const vid = variantId ?? null
  for (const g of groups) {
    if (g.fieldKey !== fieldKey) continue
    if ((g.variantId ?? null) !== vid) continue
    const isMember = membersOf(g).some(
      (m) => m.channel === channel && m.marketplace === marketplace && (m.variantId ?? null) === vid,
    )
    if (!isMember) continue
    return {
      translatePolicy: g.translatePolicy,
      sourceLanguage: g.sourceLanguage,
      targetLanguage,
    }
  }
  return null
}

// ────────────────────────────────────────────────────────────────────
// resolveChannelField
// ────────────────────────────────────────────────────────────────────

export interface ResolveChannelFieldInput {
  fieldKey: string
  rule: FieldMappingRule
  /** Provenance-carrying resolved attributes (attribute-resolver output).
   *  resolveChannelField flattens this for path resolution and reads the
   *  provenance to detect per-coordinate overrides. */
  resolvedAttrs: ResolvedAttributes
  product: { localizedContent?: unknown; categoryAttributes?: unknown; variantAttributes?: unknown; [key: string]: any }
  locale: string
  /** Link-group membership for this coordinate+field, or null. */
  link?: FieldLinkMembership | null
  /** Identity field pinned to master (GTIN/SKU/brand). */
  locked?: boolean
  /** FM.4 — value-map / size-scale lookups + manifest maxLength for the
   *  data-backed transform ops. resolveChannelField fills ctx.values
   *  (the resolved attributes) itself; the caller supplies the lookups. */
  transformCtx?: Pick<TransformContext, 'lookupValueMap' | 'lookupSizeScale' | 'maxLength' | 'namedExpression' | 'lookupPath'>
}

export interface ResolvedChannelField {
  fieldKey: string
  value: unknown
  source: ChannelFieldSource
  /** rule.source result before transforms (for diff/debug). */
  raw: unknown
  appliedTransforms: TransformOp['type'][]
  warnings: string[]
  required: boolean
  /** Exact legacy D.6 value-origin ('source'|'fallback'|'default'|
   *  'missing'), independent of the enriched provenance — lets
   *  payload-preview keep its byte-identical `source` contract. */
  legacySource: 'source' | 'fallback' | 'default' | 'missing'
  /** Cross-language TRANSLATE member whose translation isn't pinned yet —
   *  the FM.5 propagation step fills it. */
  needsTranslation: boolean
  language?: string
  requested?: string
  follows?: boolean
  drift?: boolean
  requestedLocale?: string
  effectiveLocale?: string
  translationState?: import('./attribute-resolver.js').ResolvedValue['translationState']
}

function flattenResolved(r: ResolvedAttributes): Record<string, unknown> {
  const flat: Record<string, unknown> = {}
  for (const [k, v] of Object.entries(r)) flat[k] = v.value
  return flat
}

/** A.1 provenance values that mean "a per-coordinate channel override
 *  supplied this value" (vs inherited master/variant). */
const OVERRIDE_SOURCES: ReadonlySet<ValueSource> = new Set<ValueSource>([
  'channelOverride',
  'channelExplicit',
])

export function resolveChannelField(input: ResolveChannelFieldInput): ResolvedChannelField {
  const { fieldKey, rule, resolvedAttrs, product, locale, link, locked } = input
  const warnings: string[] = []
  const flat = flattenResolved(resolvedAttrs)

  // 1. rule.source → fallback → transforms (the legacy value formula).
  const sourceRaw = resolveSourcePath(rule.source, flat, product, locale)
  const sourceKey = contentPathAddress(rule.source, locale, Object.keys(resolvedAttrs))?.field ?? rule.source.replace(/^(categoryAttributes|variantAttributes)\./, '').split('.')[0]
  warnings.push(...(resolvedAttrs[sourceKey]?.warnings ?? []))
  let value: unknown = sourceRaw
  let usedFallback = false
  if (value == null && (!Object.prototype.hasOwnProperty.call(resolvedAttrs, sourceKey) || resolvedAttrs[sourceKey]?.source === 'default') && rule.fallback) {
    const fb = resolveSourcePath(rule.fallback, flat, product, locale)
    if (isPresent(fb)) {
      value = fb
      usedFallback = true
    }
  }
  const { out, applied } = applyTransforms(value, rule.transforms, warnings, {
    values: flat,
    // PES.6 — the resolver owns the Product + locale, so it supplies the FULL path
    // resolver to the expression engine here. A caller that only has a flat value map
    // may still override it; nobody has to remember to pass it.
    lookupPath: (path: string) => {
      const subbedPath = path.replace(/\{locale\}/g, locale)
      // `undefined` means "no such attribute" (the engine warns); a known-but-empty
      // attribute must come back as null so isblank() reads true without a warning.
      if (!subbedPath.includes('.') && !(subbedPath in flat)) return undefined
      return resolveSourcePath(path, flat, product, locale)
    },
    ...input.transformCtx,
  })
  value = out
  const defaultFired = applied.includes('default') && !isPresent(sourceRaw)

  // 2. Per-coordinate override detection: when rule.source is a single
  //    segment, its provenance is the resolved attribute's source. A
  //    multi-segment path walks raw product (no override layer), so it
  //    stays unmarked — value is unaffected either way (the override is
  //    already merged into the resolved attribute the path reads).
  const subbed = rule.source.replace(/\{locale\}/g, locale)
  const overrideSource =
    !subbed.includes('.') ? resolvedAttrs[subbed]?.source : undefined
  const isOverride = !!overrideSource && OVERRIDE_SOURCES.has(overrideSource)

  // 3. Cross-language translate flag (linked TRANSLATE, different langs).
  const effectivePath = (usedFallback ? rule.fallback! : rule.source).replace(/\{locale\}/g, locale)
  const address = contentPathAddress(effectivePath, locale, Object.keys(resolvedAttrs).filter(key => resolvedAttrs[key].language))
  const pathHit = address && address.requested !== normalizeLanguage(locale)
    ? resolveContentPath({ product: product as ContentProduct, parent: product.parent, path: effectivePath,
        listing: product.contentListing, localizableKeys: [address.field], address: { requested: locale, ...(product.contentListing ? { coordinate: product.contentListing.coordinate } : {}) } }) : null
  const resolvedSource = pathHit ? contentAttribute(pathHit, product.id, product.parentId)
    : resolvedAttrs[address?.field ?? effectivePath.replace(/^(categoryAttributes|variantAttributes)\./, '').split('.')[0]]
  let effectiveLocale = resolvedSource?.language
  let translationState = effectiveLocale && translationMissing({ language: effectiveLocale }, locale) ? 'fallback' : resolvedSource?.translationState
  const dependencies = new Set<string>()
  const visited = new Set<string>()
  const collect = (expression: string) => {
    if (visited.has(expression)) return
    visited.add(expression)
    const parsed = exprDependencies(expression)
    for (const key of parsed?.attributes ?? []) dependencies.add(key)
    for (const name of parsed?.rules ?? []) { const nested = input.transformCtx?.namedExpression?.(name); if (nested) collect(nested) }
  }
  for (const transform of rule.transforms ?? []) {
    if (transform.type === 'expr') collect(transform.expr ?? input.transformCtx?.namedExpression?.(transform.ref ?? '') ?? '')
    if (transform.type === 'template') for (const match of (transform.expr ?? '').matchAll(/\{\{\s*([^{}\s]+)\s*\}\}/g)) dependencies.add(match[1])
  }
  for (const dependency of dependencies) {
    const hit = resolvedAttrs[dependency.replace(/^(categoryAttributes|variantAttributes)\./, '').replace(/^localizedContent\.[^.]+\./, '')]
    if (hit?.translationState === 'fallback' || hit?.translationState === 'outdated') {
      effectiveLocale = hit.effectiveLocale; translationState = hit.translationState
      warnings.push(`Mapping uses ${dependency} with ${hit.translationState} content for ${locale}.`)
    }
  }
  // Missing translation is a language fact, independent of value emptiness or review state.
  // Links/transforms do not relabel untranslated source text as the destination language.
  const needsTranslation = !!effectiveLocale && translationMissing({ language: effectiveLocale }, locale)

  // 4. Provenance precedence (does not change the value).
  let source: ChannelFieldSource
  if (!isPresent(value)) source = 'missing'
  else if (locked) source = 'locked'
  else if (isOverride) source = 'override'
  else if (link) source = 'linked'
  else if (usedFallback) source = 'fallback'
  else if (defaultFired) source = 'default'
  else source = 'catalogRule'

  // Legacy D.6 value-origin — exact reproduction of the pre-FM.2 preview
  // `source` field, independent of the enriched provenance above (a field
  // can be both a link member AND fallback/default-filled).
  let legacySource: 'source' | 'fallback' | 'default' | 'missing'
  if (!isPresent(value)) legacySource = 'missing'
  else if (usedFallback) legacySource = 'fallback'
  else if (defaultFired) legacySource = 'default'
  else legacySource = 'source'

  return {
    fieldKey,
    value: value ?? null,
    source,
    raw: sourceRaw,
    appliedTransforms: applied,
    warnings,
    required: rule.required === true,
    legacySource,
    needsTranslation,
    ...(effectiveLocale ? { language: effectiveLocale, requested: normalizeLanguage(locale), follows: resolvedSource?.follows, drift: resolvedSource?.drift, requestedLocale: normalizeLanguage(locale), effectiveLocale, translationState: translationState ?? 'current' } : {}),
  }
}

