import { contentListing, resolveContentAttributes, contentWireValue } from '../content-read.js'
import { contentField, translationMissing } from '../content-resolver.js'
import { normalizeLanguage } from '../content-language.js'
import { PRIMARY_CONTENT_LOCALE, CONTENT_COLUMNS } from '../content-locale.js'
import { marketLanguages } from '../market-languages.js'
import { presentationContexts } from './presentation-context.js'
import { effectivePresentationRule, resolvePresentationOrder } from './presentation-rules.js'
import { primaryConnectionIds } from '../../connection-resolver.service.js'
import { isBlankValue, projectCellValue } from '../sheet-values.js'
import { normalizeEbayListingValue } from '../ebay-listing-values.js'
import { storedChannelState } from '../channel-value-mutation.js'
import { validateChannelValue } from './validate-channel-value.js'
import { masterDefaultRule } from './master-default-rule.js'
import { exprDependenciesDeep } from './expr.js'
import { evaluateSchemaRequirements } from './schema-requirements.js'
/**
 * PES.6.2 — the batched channel-field resolver. THE seam.
 *
 * One endpoint answers "what does channel field F resolve to for these N products?" for the
 * mapping editor's Preview Value column AND for the product sheet's 🔗 derived channel cells.
 * There is deliberately ONE implementation: a preview must RUN the engine
 * (reference_preview_must_run_the_engine), and a sheet that re-derived values in the browser
 * would drift from what publishes the moment a transform changed.
 *
 * It is `payload-preview` widened on two axes and nothing else:
 *   - N products instead of 1, with each per-product load done ONCE (product + parent +
 *     listing + link groups) and each per-template load done once (rules, value maps, size
 *     scales, business rules). `previewPayload` in a loop would be ~6 queries per product.
 *   - the full field CATALOGUE instead of `Object.keys(rules)`, so an unmapped field comes back
 *     as a row with `status: 'unmapped'` rather than not coming back at all.
 *
 * Every value still goes through `resolveChannelField`, so provenance, warnings, applied
 * transforms and the value itself are the same objects publish will use.
 *
 * AUTO-CORRECTION is reported, never performed silently. When the schema closes a field's value
 * list and the resolved value differs only by case/whitespace from a legal option, the corrected
 * value is what would ship, and `autoCorrected` carries the before → after so the cell can say
 * so (Rithum's magenta chip). When it matches nothing, that is an ERROR, not a correction.
 */

import prisma from '../../../db.js'
import { resolveAttributes } from '../attribute-resolver.js'
import { getMappingForMarketplace, getRulesFor, type FieldMappingRule, type MarketplaceSchemaMapping } from '../schema-mapping.service.js'
import {
  resolveChannelField, isPresent, linkForCoordinate, type FieldLinkGroupLike,
} from '../resolve-channel-field.js'
import { getFieldCatalogue, type CatalogueField, type FieldCatalogue } from './field-catalogue.service.js'
import { categoryForListing, resolveCategoriesForProducts, type ResolvedCategory, type MappingRow } from './category-mapping.service.js'

export interface ResolvedCell {
  sourceOwner?: CatalogueField['sourceOwner']

  label?: string
  sourceDependencies?: string[]
  ruleOrigin?: 'master' | 'default' | 'category' | null
  fieldKey: string
  supplyingRule?: { id: string; name: string; version: number; href: string }
  rule?: FieldMappingRule | null
  raw?: unknown
  legacySource?: 'source' | 'fallback' | 'default' | 'missing'
  needsTranslation?: boolean
  language?: string
  requested?: string
  follows?: boolean
  drift?: boolean
  requestedLocale?: string
  effectiveLocale?: string
  translationState?: import('../attribute-resolver.js').ResolvedValue['translationState']
  /** The value that would ship, AFTER any enum auto-correction. */
  value: unknown
  status: 'mapped' | 'unmapped'
  /** FM.2 provenance — locked / override / linked / fallback / default / catalogRule / missing. */
  provenance: string | null
  appliedTransforms: string[]
  warnings: string[]
  /** Blocking problems for this cell. A required field with no value; a value outside a closed
   *  list. Distinct from `warnings`, and distinct from `status` — Rithum shows a field that is
   *  Mapped AND errored, and so do we. */
  errors: string[]
  /** Errors in an authored rule or its populated result; missing data is separate. */
  mappingErrors?: string[]
  /** Set when a closed-list value was normalised to the schema's own spelling. */
  autoCorrected: { from: string; to: string } | null
  required: boolean
  requirementReasons?: Array<{ message: string; schemaPath: string }>
  /** Length limits actually exceeded, reported not enforced. */
  overLimit: { chars?: number; bytes?: number } | null
}

export interface ResolvedProduct {
  validationContext?: { schema: FieldCatalogue['schema']; mappingVersion: number }
  readiness?: { state: 'blocked' | 'locally-valid'; populated: number; total: number; invalid: number; translationPending: number; listingOwnerFields?: number; schemaValidation: 'evaluated' | 'missing' | 'unavailable'; channelValidation: 'not-checked' }
  productId: string
  sku: string
  name: string | null
  /** Which channel category (and how it was found) drove the rule set for this product. */
  category: ResolvedCategory
  cells: Record<string, ResolvedCell>
  presentationContext?: import('./presentation-rules.js').PresentationContext
  presentationOrder?: ReturnType<typeof resolvePresentationOrder>
  counts: { mapped: number; unmapped: number; errors: number; requiredMissing: number }
}

export interface ResolveBatchResult {
  channel: string
  marketplace: string
  locale: string
  /** The catalogue the cells were resolved against — the UI needs its priorities + groups
   *  anyway, so returning it saves a second round trip. Omitted when `includeCatalogue` is
   *  false (the sheet already has its columns). */
  catalogue: FieldCatalogue | null
  products: ResolvedProduct[]
  /** Products asked for but not found. Named rather than silently dropped. */
  missingProductIds: string[]
}

/**
 * Link groups for MANY products in ONE query.
 *
 * `payload-preview.loadFieldLinkGroups` is per product, so calling it in a loop cost one SELECT
 * per row — 21 identical-shaped queries for a 21-SKU family, scaling with the batch. It is also
 * the module whose import chain reaches the Redis-backed event bus
 * (payload-preview → value-map.service → value-translate → … → lib/queue), which made merely
 * IMPORTING this file block when Redis was unreachable. Doing the query here fixes both: one
 * round trip, and nothing heavy in the import graph.
 */
async function loadLinkGroupsForProducts(
  productIds: string[],
): Promise<Map<string, FieldLinkGroupLike[]>> {
  const out = new Map<string, FieldLinkGroupLike[]>()
  for (const id of productIds) out.set(id, [])
  if (productIds.length === 0) return out
  const rows = await prisma.fieldLinkGroup.findMany({
    where: { productId: { in: productIds } },
    select: {
      productId: true, fieldKey: true, variantId: true,
      translatePolicy: true, sourceLanguage: true, members: true,
    },
  })
  for (const r of rows) {
    out.get(r.productId)?.push({
      fieldKey: r.fieldKey,
      variantId: r.variantId,
      translatePolicy: r.translatePolicy as FieldLinkGroupLike['translatePolicy'],
      sourceLanguage: r.sourceLanguage,
      members: r.members,
    })
  }
  return out
}

export async function resolveBatch(input: {
  /** Explicit account for catalog transfers; absent preserves the Studio's primary account. */
  channelConnectionId?: string | null
  /** Exact listing projection. An absent key selects the primary listing. */
  aliasKey?: string
  channel: string
  marketplace: string
  productIds: string[]
  /** Restrict to these fields. Omit for the whole catalogue. */
  fieldKeys?: string[]
  locale?: string
  /** Force one category's rule set for every product (the editor pins the category it is
   *  editing); omit to resolve each product's own category. */
  productType?: string | null
  /** Internal review filter: match actual account/alias category before loading field schemas. */
  categoryFilter?: string | null
  includeCatalogue?: boolean
  /** Read-only draft simulation. Never persisted or used as a separate resolver. */
  mappingSnapshot?: MarketplaceSchemaMapping
  categoryMappingSnapshot?: MappingRow[]
  includePresentation?: boolean
  /** Internal, read-only simulation used by propagation. Listing overrides still win. */
  masterChangesByProduct?: Record<string, Record<string, unknown>>
  /** Internal import review: apply the canonical planner's storage patches in memory only. */
  productChangesByProduct?: Record<string, Record<string, unknown>>
  listingChangesByProduct?: Record<string, Record<string, unknown>>
  /** Reconciliation baseline; category and listing-owned fields keep their real context. */
  inheritMappedFields?: boolean
}): Promise<ResolveBatchResult> {
  const channel = input.channel.toUpperCase()
  const { marketplace } = input
  const languages = await marketLanguages(channel, marketplace)
  const locale = normalizeLanguage(input.locale ?? languages[0])
  // Listing ownership alone does not exempt an Information field. Only these
  // workflow-owned values are assembled later; Shopify validates its projected
  // remote/draft owners after the common mapping pass.
  const deferred = (field: CatalogueField | undefined) => !!field?.sourceOwner && (channel === 'SHOPIFY'
    || ['Pricing', 'Inventory', 'Media', 'Product media', 'Channel-reported data'].includes(field.sourceOwner.label))
  const productIds = [...new Set(input.productIds)].filter(Boolean)
  const includeCatalogue = input.includeCatalogue !== false

  // ── per-template loads: once, not per product ────────────────────
  const mapping = input.mappingSnapshot ?? await getMappingForMarketplace(channel, marketplace)
  const namedExpression = (name: string) => mapping.expressions?.[name]
  // Loaded lazily: `value-map.service`'s import chain reaches the Redis-backed event bus, and a
  // static import made this whole module unimportable while Redis was down. Nothing here needs
  // it until a resolve actually runs.
  const { loadValueMapLookup, loadSizeScaleLookup } = await import('../value-map.service.js')
  const [lookupValueMap, lookupSizeScale] = await Promise.all([
    loadValueMapLookup(channel, marketplace, { fresh: !!input.mappingSnapshot }),
    loadSizeScaleLookup({ fresh: !!input.mappingSnapshot }),
  ])

  const products = await prisma.product.findMany({
    where: { id: { in: productIds } },
    select: {
      id: true, sku: true, name: true, parentId: true, productType: true,
      localizedContent: true, translations: true, categoryAttributes: true, variantAttributes: true,
    },
  })
  const found = new Set(products.map((p) => p.id))
  const missingProductIds = productIds.filter((id) => !found.has(id))
  if (products.length === 0) {
    return {
      channel, marketplace, locale,
      catalogue: includeCatalogue
        ? await getFieldCatalogue({ locale, channel, marketplace, accountId: input.channelConnectionId, productType: input.productType, mappingSnapshot: mapping })
        : null,
      products: [],
      missingProductIds,
    }
  }

  const connectionId = input.channelConnectionId !== undefined ? input.channelConnectionId : (await primaryConnectionIds([channel])).get(channel) ?? null
  const parentIds = [...new Set(products.map((p) => p.parentId).filter(Boolean) as string[])]
  const [parents, listings, categories] = await Promise.all([
    parentIds.length
      ? prisma.product.findMany({ where: { id: { in: parentIds } }, include: { translations: true } })
      : Promise.resolve([]),
    prisma.channelListing.findMany({ include: { translations: true },
      where: { productId: { in: [...found] }, channel, marketplace, aliasKey: input.aliasKey ?? '', channelConnectionId: connectionId },
      orderBy: { id: 'asc' },
    }),
    resolveCategoriesForProducts({ productIds: [...found], channel, marketplace, mappingSnapshot: input.categoryMappingSnapshot }),
  ])
  const parentById = new Map(parents.map((p) => [p.id, { ...p, ...input.productChangesByProduct?.[p.id] }]))
  const listingByProduct = new Map(listings.slice().reverse().map((l) => [l.productId, { ...l, ...input.listingChangesByProduct?.[l.productId] }]))
  for (const product of products) {
    categories[product.id] = categoryForListing(categories[product.id], channel, listingByProduct.get(product.id)?.platformAttributes)
  }
  const matchingIds = [...found].filter(id => !input.categoryFilter || categories[id]?.channelCategoryId === input.categoryFilter)
  if (!matchingIds.length) return { channel, marketplace, locale, catalogue: null, products: [], missingProductIds }

  const linkGroupsByProduct = await loadLinkGroupsForProducts(matchingIds)

  // The full product rows the resolver needs (findMany above selected a subset for speed;
  // resolveAttributes wants the whole row).
  const fullProducts = await prisma.product.findMany({ where: { id: { in: matchingIds } }, include: { translations: true } })
  const fullById = new Map(fullProducts.map((p) => [p.id, { ...p, ...input.productChangesByProduct?.[p.id] }]))
  const presentation = channel === 'EBAY' && (input.includePresentation || mapping.presentationRules?.length) ? await presentationContexts(prisma, fullProducts, parents, categories, connectionId) : null

  // ── one catalogue per DISTINCT category in the batch ─────────────
  // The editor pins a category, so this is normally one. A sheet page can span several.
  const pinned = input.productType?.trim() || null
  const categoryFor = (productId: string): string | null =>
    channel === 'SHOPIFY' ? null : pinned ?? categories[productId]?.channelCategoryId ?? null

  const distinctCategories = [...new Set(matchingIds.map((id) => categoryFor(id)))]
  const catalogueByCategory = new Map<string | null, FieldCatalogue>()
  for (const cat of distinctCategories) {
    catalogueByCategory.set(cat, await getFieldCatalogue({ locale, channel, marketplace, accountId: connectionId, productType: cat, mappingSnapshot: mapping }))
  }

  const wanted = input.fieldKeys && input.fieldKeys.length > 0 ? new Set(input.fieldKeys) : null

  const out: ResolvedProduct[] = []
  for (const p of products) {
    let full = fullById.get(p.id)
    if (!full) continue
    const changes = { ...input.masterChangesByProduct?.[p.id] }
    if ('title' in changes) changes.name = changes.title
    else if ('name' in changes) changes.title = changes.name
    if (Object.keys(changes).length) {
      const copy = Object.fromEntries(Object.entries(CONTENT_COLUMNS).filter(([key]) => key in changes).map(([key, column]) => [column, changes[key]]))
      full = locale === PRIMARY_CONTENT_LOCALE ? { ...full, ...copy } : { ...full, translations: [
        ...(full.translations ?? []).filter(row => normalizeLanguage(row.language) !== locale),
        { ...(full.translations ?? []).find(row => normalizeLanguage(row.language) === locale), productId: full.id, language: locale, ...copy } as any,
      ] }
    }
    const cat = categoryFor(p.id)
    const catalogue = catalogueByCategory.get(cat)!
    const rules = getRulesFor(mapping, cat)
    const linkGroups = linkGroupsByProduct.get(p.id) ?? []

    const resolvedAttrs = resolveAttributes({
      localizableKeys: catalogue.masterLocalizableKeys,
      product: full as any,
      parent: (full.parentId ? parentById.get(full.parentId) : null) as any,
      // Sources are shared Master/variant facts. The destination's explicit override is
      // applied below; feeding another listing field's override into a rule creates a loop
      // and makes the source picker, mapping preview and sheet disagree.
      locale,
    })
    for (const key of catalogue.masterSourceKeys ?? []) {
      resolvedAttrs[key] ??= { value: null, source: 'default', inheritedFrom: null }
    }
    for (const [key, value] of Object.entries(changes)) {
      resolvedAttrs[key] = { ...resolvedAttrs[key], value, source: 'master', inheritedFrom: null }
    }

    const parent = full.parentId ? parentById.get(full.parentId) : null
    const content = resolveContentAttributes({ product: full, parent, listing: listingByProduct.get(p.id), languages,
      requested: locale, localizableKeys: catalogue.masterLocalizableKeys })

    // Conditions can depend on a field outside the requested projection.
    const fields: CatalogueField[] = catalogue.fields

    const cells: Record<string, ResolvedCell> = {}
    let mapped = 0, unmapped = 0, errorCount = 0, requiredMissing = 0

    for (const field of fields) {
      // A removed or retyped definition cannot keep resolving an old authored mapping.
      if (channel === 'SHOPIFY' && field.schemaKnown === false) continue
      // Historical Master facts remain usable before their keys are added to the family dictionary.
      // Only exact declared semantic matches qualify; an existing operator mapping keeps precedence.
      const rule: FieldMappingRule | null = rules[field.fieldKey] ?? field.rule ?? (field.sourceOwner ? null : masterDefaultRule({
        key: field.fieldKey, masterKey: field.sheetKey, channelStore: field.channelStore,
      }, new Set(Object.keys(resolvedAttrs))))
      const listing = listingByProduct.get(p.id)
      const store = field.channelStore
      const contentHit = content[contentField(field.sheetKey ?? field.fieldKey)]
      const storedState = contentHit ? { state: 'inherited' as const } : storedChannelState(listing as unknown as Record<string, unknown> ?? {}, store, [...new Set([field.sheetKey ?? field.fieldKey, field.fieldKey])])
      const stored = !contentHit && storedState.state === 'stored' && !(input.inheritMappedFields && rule && !field.sourceOwner)
        ? storedState.value : undefined
      const systemValue = channel === 'AMAZON' && field.fieldKey === 'parentage_level'
        ? full.isParent ? 'parent' : full.parentId ? 'child' : undefined
        : channel === 'AMAZON' && field.fieldKey === 'child_parent_sku_relationship__parent_sku' && full.parentId
          ? parentById.get(full.parentId)?.sku : undefined
      const effectiveStored = isBlankValue(stored) && ((channel === 'AMAZON' && field.fieldKey === 'productType') || (channel === 'EBAY' && field.fieldKey === 'categoryId'))
        ? categories[p.id]?.channelCategoryId : stored === undefined ? systemValue : stored
      // A deliberately cleared override is still an override; it must not revive Master.
      const hasStored = effectiveStored !== undefined
      const directRaw = channel === 'EBAY' ? normalizeEbayListingValue(field.sheetKey ?? field.fieldKey, effectiveStored) : effectiveStored
      const directValue = projectCellValue({ shape: field.shape }, directRaw)

      if (!contentHit && !hasStored && !rule) {
        const errors: string[] = []
        if (!deferred(field) && (field.priority === 'required' && field.requiredInParent !== false)) {
          errors.push(`Field '${field.label}' is required.`)
          requiredMissing++
          errorCount++
        }
        cells[field.fieldKey] = {
          fieldKey: field.fieldKey, label: field.label, sourceOwner: field.sourceOwner, value: null, status: 'unmapped', provenance: null,
          rule, raw: null, legacySource: 'missing', needsTranslation: false,
          appliedTransforms: [], warnings: [], errors, mappingErrors: [], autoCorrected: null,
          required: !deferred(field) && (field.priority === 'required' && field.requiredInParent !== false), overLimit: null,
        }
        unmapped++
        continue
      }

      const link = linkForCoordinate(linkGroups, field.fieldKey, channel, marketplace, null, locale)
      const r: import('../resolve-channel-field.js').ResolvedChannelField = contentHit && (contentHit.tier === 'pin' || !rule)
        ? { fieldKey: field.fieldKey, value: contentHit.value, raw: contentHit.value, source: contentHit.tier === 'pin' && !contentHit.follows ? 'override' : 'catalogRule',
            legacySource: 'source', required: rule?.required === true, language: contentHit.language, requested: locale,
            requestedLocale: locale, effectiveLocale: contentHit.language, translationState: contentHit.translationState,
            follows: contentHit.follows, drift: contentHit.drift, needsTranslation: translationMissing(contentHit, locale), warnings: [], appliedTransforms: [] }
        : hasStored ? { fieldKey: field.fieldKey, required: rule?.required === true, value: directValue, raw: directValue, source: stored === undefined ? 'default' : 'override', legacySource: 'source', needsTranslation: false, warnings: [], appliedTransforms: [] } : resolveChannelField({
        fieldKey: field.fieldKey,
        rule: rule!,
        resolvedAttrs,
        product: { ...full, parent, contentListing: contentListing(full, listing, undefined, languages) } as any,
        locale,
        link,
        transformCtx: {
          lookupValueMap,
          lookupSizeScale,
          maxLength: field.maxLength ?? undefined,
          namedExpression,
        },
      })

      const projected = contentWireValue(field.shape === 'list' ? projectCellValue({ shape: 'list' }, r.value) : r.value, field.shape)
      const { value, errors, autoCorrected, overLimit } = validateChannelValue(field, projected)
      errors.push(...r.warnings.filter(warning => /^(expr (?:failed|skipped)|Conflicting variant attributes)/.test(warning)))
      const mappingErrors = !hasStored && rule ? [...errors] : []

      // Required-but-empty is the error the whole editor exists to surface.
      const isRequired = !deferred(field) && ((field.priority === 'required' && field.requiredInParent !== false) || rule?.required === true)
      if (!isPresent(value) && isRequired) {
        errors.push(`Field '${field.label}' is required.`)
        requiredMissing++
      }
      if (r.requested && translationMissing(r, r.requested)) {
        const message = r.effectiveLocale
          ? `Showing ${r.effectiveLocale} fallback; ${locale} content ${r.translationState === 'outdated' ? 'is outdated' : 'is missing'}.`
          : `Translation into ${locale} is pending.`
        r.warnings.push(message)
        if (isRequired) errors.push(message)
      }

      if (errors.length > 0) errorCount++
      mapped++
      cells[field.fieldKey] = {
        fieldKey: field.fieldKey,
        label: field.label,
        ruleOrigin: rules[field.fieldKey] ? (mapping.byProductType?.[cat ?? '']?.[field.fieldKey] ? 'category' : 'default') : rule ? 'master' : null,
        sourceDependencies: [...new Set([rule?.source, rule?.fallback, ...(rule?.transforms ?? []).flatMap(op =>
          op.type === 'expr' ? exprDependenciesDeep(op.expr ?? `rule(${JSON.stringify(op.ref)})`, mapping.expressions ?? {})?.attributes ?? []
          : op.type === 'template' ? [...(op.expr ?? '').matchAll(/\{\{\s*([^{}\s]+)\s*\}\}/g)].map(match => match[1]) : []),
        ].filter((key): key is string => !!key).map(key => key.replace(/^(categoryAttributes|variantAttributes)\./, '').replace(/^localizedContent\.[^.]+\./, '').replace(/^name$/, 'title')))],
        rule, raw: r.raw, legacySource: r.legacySource, needsTranslation: r.needsTranslation,
        ...(r.effectiveLocale ? { language: r.language, requested: r.requested, follows: r.follows, drift: r.drift, requestedLocale: r.requestedLocale, effectiveLocale: r.effectiveLocale, translationState: r.translationState } : {}),
        value: contentWireValue(value ?? null, field.shape),
        status: 'mapped',
        sourceOwner: rule ? null : field.sourceOwner,
        provenance: r.source,
        appliedTransforms: r.appliedTransforms,
        warnings: r.warnings,
        errors,
        mappingErrors,
        autoCorrected,
        required: isRequired,
        overLimit,
      }
    }

    const requirements = evaluateSchemaRequirements(catalogue, Object.fromEntries(Object.values(cells).map(c => [c.fieldKey, c.value])))
    for (const key of requirements.requiredFields ?? []) {
      if (cells[key] && !deferred(fields.find(f => f.fieldKey === key))) cells[key].required = true
    }
    for (const issue of requirements.issues) {
      const cell = cells[issue.fieldKey]
      if (!cell) continue
      // Pricing, stock and media may be assembled only by their owning publisher.
      // An absent preview value is not evidence that its outgoing value is missing.
      if (deferred(fields.find(f => f.fieldKey === issue.fieldKey)) && !isPresent(cell.value)) continue
      cell.required ||= issue.required
      cell.requirementReasons ??= []
      cell.requirementReasons.push({ message: issue.message, schemaPath: issue.schemaPath })
      if (!(issue.required && !isPresent(cell.value) && cell.errors.some(e => e.includes('is required.'))) && !cell.errors.includes(issue.message)) cell.errors.push(issue.message)
      if (!issue.required && isPresent(cell.value) && cell.rule && !['override', 'locked'].includes(cell.provenance ?? '')) cell.mappingErrors?.push(issue.message)
    }
    if (requirements.unavailable) {
      for (const cell of Object.values(cells)) cell.errors.push(`Category requirement validation is unavailable: ${requirements.unavailable}`)
    }

    const context = presentation?.get(p.id)
    const themeCell = cells.descriptionThemeId
    if (context && themeCell && !['override', 'locked'].includes(themeCell.provenance ?? '')) {
      const theme = effectivePresentationRule(mapping.presentationRules ?? [], context, 'themeId')
      if (theme.rule) {
        themeCell.value = theme.value ?? null; themeCell.provenance = 'catalogRule'; themeCell.status = 'mapped'
        themeCell.raw = themeCell.value
        themeCell.errors = validateChannelValue(fields.find(f => f.fieldKey === 'descriptionThemeId')!, themeCell.value).errors
        themeCell.supplyingRule = { id: theme.rule.id, name: theme.rule.name, version: theme.rule.version, href: `/channels/ebay/variation-order-rules?market=${encodeURIComponent(marketplace)}&rule=${encodeURIComponent(theme.rule.id)}` }
      }
      if (theme.conflicts.length) themeCell.errors.push(`Conflicting presentation rules: ${theme.conflicts.join('; ')}`)
    }
    if (categories[p.id]?.conflicts?.length) {
      for (const cell of Object.values(cells)) cell.errors.push(`Conflicting shared categories: ${categories[p.id].conflicts!.join('; ')}. Choose a primary shared category or an explicit listing category.`)
    }
    for (const field of fields) if (field.schemaKnown === false && cells[field.fieldKey]?.rule) {
      const message = 'This rule targets a field absent from the selected category schema. Review the rule or refresh the schema.'
      cells[field.fieldKey].errors.push(message)
      cells[field.fieldKey].mappingErrors?.push(message)
    }
    const completeCells = Object.values(cells)
    const invalid = completeCells.filter(c => c.errors.length).length
    const translationPending = completeCells.filter(c => c.requested && translationMissing(c, c.requested)).length
    const schemaValidation = requirements.unavailable ? 'unavailable' as const : catalogue.schema?.present ? 'evaluated' as const : 'missing' as const
    const readiness: NonNullable<ResolvedProduct['readiness']> = {
      state: invalid || translationPending || schemaValidation !== 'evaluated' ? 'blocked' : 'locally-valid',
      populated: completeCells.filter(c => isPresent(c.value)).length, total: completeCells.length, invalid, translationPending,
      schemaValidation, channelValidation: 'not-checked', listingOwnerFields: fields.filter(f => f.sourceOwner).length,
    }
    if (wanted) for (const key of Object.keys(cells)) if (!wanted.has(key)) delete cells[key]
    out.push({
      productId: p.id,
      sku: p.sku,
      name: p.name ?? null,
      category: categories[p.id] ?? {
        channelCategoryId: null, channelCategoryPath: null, browseNodeId: null,
        source: 'none', categoryId: null, categoryName: null, reviewed: false,
      },
      cells,
      readiness,
      validationContext: { schema: catalogue.schema, mappingVersion: catalogue.mappingVersion },
      ...(context ? { presentationContext: context, presentationOrder: resolvePresentationOrder(mapping.presentationRules ?? [], context, (listingByProduct.get(p.id)?.platformAttributes ?? {}) as Record<string, unknown>) } : {}),
      counts: {
        mapped: Object.values(cells).filter(c => c.status === 'mapped').length,
        unmapped: Object.values(cells).filter(c => c.status === 'unmapped').length,
        errors: Object.values(cells).filter(c => c.errors.length > 0).length,
        requiredMissing: Object.values(cells).filter(c => c.required && !isPresent(c.value)).length,
      },
    })
  }

  return {
    channel,
    marketplace,
    locale,
    catalogue: includeCatalogue ? (catalogueByCategory.get(pinned ?? distinctCategories[0]) ?? null) : null,
    products: out,
    missingProductIds,
  }
}

apps/web/src/app/products/[id]/edit/_stu.content:
'use client'

/** The resolved channel value and its source. Source controls open details before any change. */
import { memo } from 'react'
import { CellAction } from '@/design-system/components'
import { SourceIndicator } from '@/design-system/components/SourceIndicator'

import type { ICellRendererParams } from '@/design-system/grid'
import { EmptyValue, LongTextCell, RequiredValue, ShapeValue, classifyProvenance, isEmptyShape, isShaped, SelectChevron } from '@/design-system/grid'

import { hasValue } from './provenance'
import { withMappingRun } from './rows'
import { isReferenceField } from '../referenceOptions'
import { describeValueSource } from './value-source'
import { columnRequiredByAny, isProductRelationshipColumn } from '@nexus/shared/master-sheet'
import type { ChannelSheetRow, SheetColumn } from './types'

export interface CascadeCellParams {
  formattedPreview?: boolean
  openEditor?: (row: ChannelSheetRow, column: SheetColumn, anchor: HTMLElement | null) => void
  column: SheetColumn
  /**
   * Whether this mapping RUN was product-grain (`meta.mapping.productLevelOnly`).
   *
   * Supplied by the sheet rather than read from the cell, because the wire carries it once per run
   * and `classifyProvenance` expects it per cell — the consumer bridges the two (#379).
   */
  productLevelOnly?: boolean
  /**
   * #780 — reads the SERVER'S reason this cell's formula produced nothing, or `null`.
   *
   * A FUNCTION read at paint time, not a value: the refusal arrives with the formula batch after
   * first paint, and a value here would either freeze the first load's answer or rebuild the column
   * model to change it — the same discipline `exprFor` already follows on both sheets.
   */
  refusedReasonFor?: (productId: string, fieldKey: string) => string | null
  /** Inspecting a source never changes its value. Pin/reset are labelled actions in the details. */
  onDetails: (row: ChannelSheetRow, column: SheetColumn) => void
}

export const CascadeCell = memo(function CascadeCell(
  p: ICellRendererParams<ChannelSheetRow> & CascadeCellParams,
) {
  const row = p.data
  const { column, onDetails, productLevelOnly } = p

  const cell = row?.values?.[column.key]
  /* A list or a measure is "present" by its own rule — an empty array is not a value. */
  const present = column.shape === 'list' || column.shape === 'measure' ? !isEmptyShape(column.shape, cell?.value) : hasValue(cell?.value)

  if (!row) return null
  if (isProductRelationshipColumn(column.key)) return present ? <>{String(cell?.value)}</> : <EmptyValue />

  // A channel scope is never the master layer, so the classifier is told so. The run-level mapping
  // fact rides with the cell (`withMappingRun`) — without it `mappedShared` cannot be reached and
  // a product-grain derivation renders as an ordinary per-row `mapped`.
  /* #780 — the refusal rides with the cell into the ONE classifier, exactly as the mapping run
     does. Merged here rather than in `withMappingRun` because it comes from a different source (the
     formula batch, not the sheet payload) and folding it in there would imply the wire carries it. */
  /* `row.id`, the bare product id the formula map is keyed on — NOT `row.rowId`, this scope's grid
     identity. See the note on `refusedReasonFor` in ChannelSheet. */
  const refusedReason = p.refusedReasonFor && row ? p.refusedReasonFor(row.rowId, column.key) : null
  const provenance = classifyProvenance(
    { ...withMappingRun(cell, productLevelOnly ?? false), refusedReason },
    'channel',
  )
  // Blocking mapping errors remain visible beside the source; details come from the resolver.
  const mapped = cell?.mapped ?? null
  const mappingNote = mapped
    ? mapped.errors.length > 0
      ? `${(mapped.mappingErrors ?? mapped.errors).length ? 'Mapping error' : 'Field validation'}: ${mapped.errors.join(' · ')}`
      : mapped.warnings.length > 0
          ? `Mapped, with warnings: ${mapped.warnings.join(' · ')}`
          : null
    : null

  const source = describeValueSource(cell, provenance, refusedReason)
  const description = source.kind === 'warning' ? source.description
    : [source.description, mappingNote, cell?.writeBlockedReason]
      .filter((part): part is string => !!part).map(part => part.trim().replace(/\.+$/, '')).join('. ')

  return (
    <span className="nds-cascade nds-reveal-row">
      <span className="nds-cascade-value">
        {/* `valueFormatted` first: a closed-list column maps its code to a label on the column
            (#669), and the renderer must show what the formatter resolved or the cell contradicts
            the dropdown that set it. Falls back to the raw value for every column that has no
            formatter, which is most of them. */}
        {present ? (
          p.formattedPreview ? String(p.valueFormatted ?? p.value ?? '') : column.shape === 'list' || column.shape === 'measure' ? (
            /* AM.1 §A.3 — the engine's cell for the shape, the same one master's `withMark` wraps. */
            <ShapeValue shape={column.shape} value={p.value ?? cell?.value} optionLabels={column.optionLabels} />
          ) : column.kind === 'longtext' ? (
            /* master's long-text renderer — the text with its length mark — so a capped field reads the
               same on every scope (2026-09-04). `required` is never reached here (`present` is true);
               the required treatment of an EMPTY cell stays this renderer's below. */
            <LongTextCell {...p} maxLength={column.maxLength} maxBytes={column.maxBytes} capFrom={column.capFrom} required={column.requiredBy.length > 0} />
          ) : (
            String(p.valueFormatted ?? p.value ?? cell?.value ?? '')
          )
        ) : (
          /* `⚠ required`, by the SHARED rule master applies (`columnRequiredByAny`: the column applies
             to this row AND a channel requires it for this product type) — this scope drew `—` for the
             same state until 2026-09-04. */
          columnRequiredByAny(column, row) ? <RequiredValue /> : <EmptyValue />
        )}
      </span>
      {/**
        * 🔴 D13's closed-list affordance, on this scope at last (#710). The class was already here
        * — `ChannelSheet.tsx` applies `SELECT_CELL_CLASS` by KIND from the engine's own constant —
        * but the class is the cursor and the glyph is a NODE, so 63 select cells on this scope
        * rendered no chevron at all while master rendered one (measured by PES.2). A closed list
        * and a free-text cell looked identical at rest here, which is the exact defect the
        * affordance exists to remove: the capability was there and nothing on screen said so.
        *
        * `SelectChevron` is the engine's (`grid/editors/SelectCellEditor.tsx`), the same component
        * and the same lucide glyph master renders — never a second chevron with its own size.
        *
        * A SIBLING of `.nds-cascade-value`, never inside it: that span is the ellipsizing box
        * (`overflow:hidden; text-overflow:ellipsis`), and PES.2's #707 measured what happens to an
        * icon placed in there — it becomes inline content of a truncating block rather than a flex
        * item, and falls to a second line. `.nds-cascade` is `inline-flex` with `gap: 6px` and the
        * value is `flex: 1 1 auto`, so as a sibling the value truncates before the glyph moves.
        */}
      {(column.kind === 'select' || column.kind === 'boolean' || isReferenceField(column.key)) && !isShaped(column) && <SelectChevron />}
      {mapped && mapped.errors.length > 0 && (
        <span className="nds-cascade-maperr" aria-label={mappingNote ?? 'Mapping error'}>!</span>
      )}
      {p.openEditor && <CellAction label={`${p.api.getColumn(column.key)?.isCellEditable(p.node) ? 'Edit' : 'Details'}: ${row.sku}, ${column.label}`} description={cell?.writeBlockedReason ?? 'Enter or F2 opens the editor.'}
        onFocusCell={() => { if (p.node.rowIndex != null) { p.api.setFocusedCell(p.node.rowIndex, column.key); p.api.clearCellSelection(); p.api.addCellRange({ rowStartIndex: p.node.rowIndex, rowEndIndex: p.node.rowIndex, columns: [column.key] }) } }}
        onActivate={anchor => p.openEditor?.(row, column, anchor)} />}
      <SourceIndicator
        kind={source.kind}
        label={source.label}
        description={description}
        tooltip={refusedReason ?? undefined}
        actionLabel={`Show cell details: ${row.sku}, ${column.label}`}
        onAction={() => onDetails(row, column)}
      />
    </span>
  )
})

import type { ValueSourceKind } from '@/design-system/components/SourceIndicator'
import type { CellProvenance } from '@/design-system/grid/renderers/provenance'
import type { StudioCellValue } from './types'

export interface ValueSourceDescription {
  kind: ValueSourceKind
  label: string
  description: string
}

/** Explain the resolver's winner. A master-layer pin is not a listing override. */
export function describeValueSource(cell: StudioCellValue | undefined, provenance: CellProvenance, refusedReason?: string | null): ValueSourceDescription {
  const source = (kind: ValueSourceKind, label: string, description: string): ValueSourceDescription => ({ kind, label, description })
  if (provenance === 'refused') return source('warning', 'Formula needs attention', refusedReason ?? 'The formula could not produce a value')
  if (provenance === 'formula') return source('formula', 'Cell formula', 'Calculated by this cell’s formula; edit the formula to change how it works')
  if (provenance === 'ai' || provenance === 'aiStale') return source('ai', provenance === 'aiStale' ? 'Outdated AI draft' : 'AI draft', 'Review this suggestion before accepting it')
  if (!cell) return source('missing', 'No value', 'No source information is available')
  const localized = cell.mapped?.effectiveLocale ? cell.mapped : cell
  if (localized.needsTranslation || localized.translationState === 'fallback') return source('warning',
    localized.translationState === 'outdated' ? 'Outdated translation' : 'Language fallback',
    `Showing ${localized.effectiveLocale ?? 'source'} content. ${localized.requestedLocale ?? 'Selected language'} ${localized.translationState === 'outdated' ? 'needs review after a source change' : 'content is missing'}. This value does not count as translated content`)
  if (cell.nexusDraft) return source('override', 'Saved Nexus draft', 'Saved for this account, listing and field owner. Review synchronization to send these changes to Shopify')
  if (localized.translationState === 'draft' || localized.translationState === 'reviewed') return source('master',
    localized.translationState === 'draft' ? 'Translation draft' : 'Reviewed translation',
    `${localized.effectiveLocale} content${localized.translationState === 'draft' ? ' is saved and awaiting review' : ' has been reviewed'}`)
  const mapped = cell.mapped
  if (mapped?.provenance === 'override' || (!mapped && ['channel', 'alias', 'aliasVariant'].includes(cell.layer) && cell.pinned && !cell.inherited)) {
    return source('override', 'Listing override', 'Stored for this SKU and listing on this channel and market; changes to Master do not replace it')
  }
  if (mapped?.sourceOwner) return source('channel', mapped.sourceOwner.label, 'This attribute uses its own channel or listing value. A Master mapping is not required')
  if (mapped?.status === 'unmapped') return source('missing', 'No mapping', 'No rule connects this channel attribute to Master; configure a mapping or enter a listing value')
  if (mapped?.provenance === 'default') return source('default', 'Channel default', 'Supplied by the channel’s category mapping or a configured default')
  if (mapped?.provenance === 'linked' || cell.linkGroupId || cell.layer === 'linked') return source('linked', 'Linked field', 'Follows a shared field link; its configured source determines the value')
  if (provenance === 'inheritedOverride') return source('linked', 'Inherited override', 'The server reports a value inherited from another listing layer')
  if (mapped) {
    if (mapped.supplyingRule) return source('rule', 'Shared rule', `Supplied by ${mapped.supplyingRule.name} · v${mapped.supplyingRule.version}. Editing this reusable rule can affect other matching products`)
    const path = mapped.legacySource === 'fallback' ? mapped.fallbackPath : mapped.sourcePath
    if (path && !mapped.usesExpression) {
      return source('master', 'Follows Master', [
        `Uses Master’s ${path}${mapped.legacySource === 'fallback' ? ' fallback' : ''} for this product and content language`,
        mapped.provenance === 'missing' ? 'The configured source currently produces no value' : null,
        mapped.appliedTransforms.length ? `Channel adjustments: ${mapped.appliedTransforms.join(', ')}` : null,
      ].filter(Boolean).join('. '))
    }
    return source('rule', 'Mapping rule', mapped.usesExpression
      ? 'Calculated by a channel mapping expression; its inputs determine whether Master changes affect it'
      : mapped.provenance === 'missing'
        ? 'A mapping exists, but it currently produces no value'
        : 'Supplied by the configured channel mapping')
  }
  if (['master', 'variant'].includes(cell.layer)) return source('master', cell.writeTarget === 'master' ? 'Master value' : 'Follows Master', cell.affectsAllChannels
    ? 'Shared Master field; editing it affects every channel that follows it'
    : 'Uses the resolved Master value for this product and content language')
  return source(cell.value == null ? 'missing' : 'channel', cell.value == null ? 'No value' : 'Channel value', 'No Master source is reported for this cell')
}

/** Reset removes the override. Only a declared Master input warrants promising Master. */
export function resetSourceLabel(cell: StudioCellValue): string {
  return cell.mapped?.sourcePath && !cell.mapped.usesExpression && !cell.mapped.supplyingRule
    ? 'follow Master'
    : 'use the configured mapping or default; the field may become empty if none is configured'
}

import { describe, expect, it } from 'vitest'
import { classifyProvenance } from '@/design-system/grid/renderers/provenance'
import { describeValueSource, resetSourceLabel } from './value-source'
import type { MappedCell, StudioCellValue } from './types'

const mapping = (over: Partial<MappedCell> = {}): MappedCell => ({
  value: 'Xavia', status: 'mapped', provenance: 'catalogRule', sourcePath: 'brand',
  appliedTransforms: [], warnings: [], errors: [], autoCorrected: null, requiredByRule: false, overLimit: null, ...over,
})
const cell = (over: Partial<StudioCellValue> = {}): StudioCellValue => ({
  value: 'Xavia', source: 'master', inheritedFrom: null, inherited: false,
  layer: 'master', pinned: false, follows: null, editable: true, linkGroupId: null,
  mapped: mapping(), writeField: 'attr_brand', writeTarget: 'channelListing',
  writeVerb: 'channel', affectsAllChannels: false, writable: true, ...over,
})
const describeCell = (c: StudioCellValue) => describeValueSource(c, classifyProvenance(c, 'channel'))

describe('channel value sources', () => {
  it('explains a supplying presentation rule instead of the superseded shared source path', () => {
    const mapped = mapping({ supplyingRule: { id: 'jackets', name: 'Jackets presentation', version: 4, href: '/channels/ebay/variation-order-rules?rule=jackets' } })
    const inherited = cell({ mapped })
    expect(describeCell(inherited)).toMatchObject({ kind: 'rule', label: 'Shared rule' })
    expect(describeCell(inherited).description).toContain('Jackets presentation')
    expect(describeCell(inherited).description).toContain('v4')
    expect(resetSourceLabel(inherited)).toContain('configured mapping or default')
    expect(describeCell(cell({ mapped: { ...mapped, provenance: 'override' } })).kind).toBe('override')
  })
  it('shows Master for a mapped input, even when Master stores a variant override', () => {
    expect(describeCell(cell()).kind).toBe('master')
    expect(describeCell(cell({ layer: 'variant', pinned: true })).kind).toBe('master')
  })
  it('names fallback and channel adjustments without claiming the untransformed value is used', () => {
    const result = describeCell(cell({ mapped: mapping({ legacySource: 'fallback', fallbackPath: 'name', appliedTransforms: ['truncate'] }) }))
    expect(result.kind).toBe('master')
    expect(result.description).toContain('name fallback')
    expect(result.description).toContain('truncate')
  })
  it.each([null, '', false, 0, []])('keeps a stored override for %j distinct from inheritance', value => {
    expect(describeCell(cell({ value, layer: 'channel', pinned: true, mapped: mapping({ provenance: 'override', value }) })).kind).toBe('override')
  })
  it('distinguishes a missing Master value from a missing mapping', () => {
    const emptyMaster = describeCell(cell({ value: null, mapped: mapping({ value: null, provenance: 'missing' }) }))
    expect(emptyMaster.kind).toBe('master')
    expect(emptyMaster.description).toContain('currently produces no value')
    expect(describeCell(cell({ mapped: mapping({ status: 'unmapped', sourcePath: null, provenance: null }) })).label).toBe('No mapping')
  })
  it('does not label constants, category defaults, expressions or shared links as Master', () => {
    expect(describeCell(cell({ mapped: mapping({ provenance: 'default' }) })).kind).toBe('default')
    expect(describeCell(cell({ mapped: mapping({ sourcePath: '' }) })).kind).toBe('rule')
    expect(describeCell(cell({ mapped: mapping({ usesExpression: true }) })).kind).toBe('rule')
    expect(describeCell(cell({ mapped: mapping({ provenance: 'linked' }) })).kind).toBe('linked')
  })
  it('uses a conservative label when an older server omits source details', () => {
    expect(describeCell(cell({ mapped: mapping({ sourcePath: undefined }) })).kind).toBe('rule')
  })
  it('keeps formula and draft states above stored mapping metadata', () => {
    expect(describeValueSource(cell(), 'formula').kind).toBe('formula')
    expect(describeValueSource(cell(), 'refused', 'Invalid option').description).toBe('Invalid option')
    expect(describeValueSource(cell(), 'aiStale').label).toBe('Outdated AI draft')
  })
  it('does not promise Master after reset without a declared source', () => {
    expect(resetSourceLabel(cell())).toBe('follow Master')
    expect(resetSourceLabel(cell({ mapped: mapping({ sourcePath: null }) }))).toContain('may become empty')
    expect(resetSourceLabel(cell({ mapped: mapping({ usesExpression: true }) }))).toContain('configured mapping')
  })
  it('identifies shared Master edits and channel-owned values separately', () => {
    const shared = describeCell(cell({ mapped: null, writeTarget: 'master', affectsAllChannels: true }))
    expect(shared.label).toBe('Master value')
    expect(shared.description).toContain('every channel')
    expect(describeCell(cell({ mapped: null, layer: 'default' })).kind).toBe('channel')
  })
})

it('explains a store-owned empty field without claiming that its Master mapping is missing', () => {
  const owned = cell({ value: null, mapped: mapping({ value: null, status: 'unmapped', sourcePath: null,
    sourceOwner: { kind: 'listing', label: 'Listing settings', path: 'listing.platformAttributes.metafields.PRODUCT.custom.features' } }) })
  expect(describeCell(owned)).toMatchObject({ kind: 'channel', label: 'Listing settings' })
  expect(describeCell(owned).description).toContain('A Master mapping is not required')
})
